(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("isocrates-orations-2-e", [{"sp": "HDR", "t": "Λόγοι, τόμος Βʹ"}, {"sp": "HDR", "t": "Ἀρεοπαγιτικός", "st": "7"}, {"sp": "N", "t": "πολλοὺς ὑμῶν οἶμαι θαυμάζειν ἥντινά ποτε γνώμην ἔχων περὶ σωτηρίας τὴν πρόσοδον ἐποιησάμην, ὥσπερ τῆς πόλεως ἐν κινδύνοις οὔσης ἢ σφαλερῶς αὐτῇ τῶν πραγμάτων καθεστηκότων, ἀλλ’ οὐ πλείους μὲν τριήρεις ἢ διακοσίας κεκτημένης, εἰρήνην δὲ καὶ τὰ περὶ τὴν χώραν ἀγούσης, καὶ τῶν κατὰ θάλατταν ἀρχούσης,", "st": "7.1"}, {"sp": "N", "t": "ἔτι δὲ συμμάχους ἐχούσης πολλοὺς μὲν τοὺς ἑτοίμως ἡμῖν, ἤν τι δέῃ, βοηθήσοντας, πολὺ δὲ πλείους τοὺς τὰς συντάξεις ὑποτελοῦντας καὶ τὸ προσταττόμενον ποιοῦντας· ὧν ὑπαρχόντων ἡμᾶς μὲν ἄν τις φήσειεν ἐικὸς εἶναι θαρρεῖν ὡς πόρρω τῶν κινδύνων ὄντας, τοῖς δ’ ἐχθροῖς τοῖς ἡμετέροις προσήκειν δεδιέναι καὶ βουλεύεσθαι περὶ τῆς αὑτῶν σωτηρίας.", "st": "7.2"}, {"sp": "N", "t": "ὑμεῖς μὲν οὖν οἶδ’ ὅτι τούτῳ χρώμενοι τῷ λογισμῷ καὶ τῆς ἐμῆς προσόδου καταφθονεῖτε, καὶ πᾶσαν ἐλπίζετε τὴν Ἑλλάδα ταύτῃ τῇ δυνάμει κατασχήσειν· ἐγὼ δὲ δι’ αὐτὰ ταῦτα τυγχάνω δεδιώς. ὁρῶ γὰρ τῶν πόλεων τὰς ἄριστα πράττειν οἰομένας κάκιστα βουλευομένας καὶ τὰς μάλιστα θαρρούσας εἰς πλείστους κινδύνους καθισταμένας. αἴτιον δὲ τούτων ἐστίν,", "st": "7.3"}, {"sp": "N", "t": "ὅτι τῶν ἀγαθῶν καὶ τῶν κακῶν οὐδὲν αὐτὸ καθ’ αὑτὸ παραγίγνεται τοῖς ἀνθρώποις, ἀλλὰ συντέτακται καὶ συνακολουθεῖ τοῖς μὲν πλούτοις καὶ ταῖς δυναστείαις ἄνοια καὶ μετὰ ταύτης ἀκολασία, ταῖς δ’ ἐνδείαις καὶ ταῖς ταπεινότησι σωφροσύνη καὶ πολλὴ μετριότης,", "st": "7.4"}, {"sp": "N", "t": "ὥστε χαλεπὸν εἶναι διαγνῶναι ποτέραν ἄν τις δέξαιτο τῶν μερίδων τούτων τοῖς παισὶ τοῖς αὑτοῦ καταλιπεῖν. ἴδοιμεν γὰρ ἂν ἐκ μὲν τῆς φαυλοτέρας εἶναι δοκούσης ἐπὶ τὸ βέλτιον ὡς ἐπὶ τὸ πολὺ τὰς πράξεις ἐπιδιδούσας, ἐκ δὲ τῆς κρείττονος φαινομένης ἐπὶ τὸ χεῖρον εἰθισμένας μεταπίπτειν.", "st": "7.5"}, {"sp": "N", "t": "καὶ τούτων ἐνεγκεῖν ἔχω παραδείγματα πλεῖστα μὲν ἐκ τῶν ἰδιωτικῶν πραγμάτων, πυκνοτάτας γὰρ ταῦτα λαμβάνει τὰς μεταβολάς, οὐ μὴν ἀλλὰ μείζω γε καὶ φανερώτερα τοῖς ἀκούουσιν ἐκ τῶν ἡμῖν καὶ Λακεδαιμονίοις συμβάντων. ἡμεῖς τε γὰρ ἀναστάτου μὲν τῆς πόλεως ὑπὸ τῶν βαρβάρων γεγενημένης διὰ τὸ δεδιέναι καὶ προσέχειν τὸν νοῦν τοῖς πράγμασιν ἐπρωτεύσαμεν τῶν Ἑλλήνων, ἐπειδὴ δ’ ἀνυπέρβλητον ᾠήθημεν τὴν δύναμιν ἔχειν, παρὰ μικρὸν ἤλθομεν ἐξανδραποδισθῆναι·", "st": "7.6"}, {"sp": "N", "t": "Λακεδαιμόνιοί τε τὸ μὲν παλαιὸν ἐκ φαύλων καὶ ταπεινῶν πόλεων ὁρμηθέντες διὰ τὸ σωφρόνως ζῆν καὶ στρατιωτικῶς κατέσχον Πελοπόννησον, μετὰ δὲ ταῦτα μεῖζον φρονήσαντες τοῦ δέοντος, καὶ λαβόντες καὶ τὴν κατὰ γῆν καὶ τὴν κατὰ θάλατταν ἀρχήν, εἰς τοὺς αὐτοὺς κινδύνους κατέστησαν ἡμῖν.", "st": "7.7"}, {"sp": "N", "t": "ὅστις οὖν εἰδὼς τοσαύτας μεταβολὰς γεγενημένας καὶ τηλικαύτας δυνάμεις οὕτω ταχέως ἀναιρεθείσας πιστεύει τοῖς παροῦσι, λίαν ἀνόητός ἐστιν, ἄλλως τε καὶ τῆς μὲν πόλεως ἡμῶν πολὺ καταδεέστερον νῦν πραττούσης ἢ κατ’ ἐκεῖνον τὸν χρόνον, τοῦ δὲ μίσους τοῦ τῶν Ἑλλήνων καὶ τῆς ἔχθρας τῆς πρὸς βασιλέα πάλιν ἀνακεκαινισμένης, ἃ τότε κατεπολέμησεν ἡμᾶς.", "st": "7.8"}, {"sp": "N", "t": "ἀπορῶ δὲ πότερον ὑπολάβω μηδὲν μέλειν ὑμῖν τῶν κοινῶν πραγμάτων ἢ φροντίζειν μὲν αὐτῶν, εἰς τοῦτο δ’ ἀναισθησίας ἥκειν ὥστε λανθάνειν ὑμᾶς εἰς ὅσην ταραχὴν ἡ πόλις καθέστηκεν. ἐοίκατε γὰρ οὕτω διακειμένοις ἀνθρώποις, οἵτινες ἁπάσας μὲν τὰς πόλεις τὰς ἐπὶ Θρᾴκης ἀπολωλεκότες, πλείω δ’ ἢ χίλια τάλαντα μάτην εἰς τοὺς ξένους ἀνηλωκότες,", "st": "7.9"}, {"sp": "N", "t": "πρὸς δὲ τοὺς Ἕλληνας διαβεβλημένοι καὶ τῷ βαρβάρῳ πολέμιοι γεγονότες, ἔτι δὲ τοὺς μὲν Θηβαίων φίλους σώζειν ἠναγκασμένοι, τοὺς δ’ ἡμετέρους αὐτῶν συμμάχους ἀπολωλεκότες, ἐπὶ τοιαύταις πράξεσιν εὐαγγέλια μὲν δὶς ἤδη τεθύκαμεν, ῥᾳθυμότερον δὲ περὶ αὐτῶν ἐκκλησιάζομεν τῶν πάντα τὰ δέοντα πραττόντων.", "st": "7.10"}, {"sp": "N", "t": "καὶ ταῦτ’ εἰκότως καὶ ποιοῦμεν καὶ πάσχομεν· οὐδὲν γὰρ οἷόν τε γίγνεσθαι κατὰ τρόπον τοῖς μὴ καλῶς περὶ ὅλης τῆς διοικήσεως βεβουλευμένοις, ἀλλ’ ἐὰν καὶ κατορθώσωσι περί τινας τῶν πράξεων ἢ διὰ τύχην ἢ δι’ ἀνδρὸς ἀρετήν, μικρὸν διαλιπόντες πάλιν εἰς τὰς αὐτὰς ἀπορίας κατέστησαν. καὶ ταῦτα γνοίη τις ἂν ἐκ τῶν περὶ ἡμᾶς γεγενημένων·", "st": "7.11"}, {"sp": "N", "t": "ἁπάσης γὰρ τῆς Ἑλλάδος ὑπὸ τὴν πόλιν ἡμῶν ὑποπεσούσης καὶ μετὰ τὴν Κόνωνος ναυμαχίαν καὶ μετὰ τὴν Τιμοθέου στρατηγίαν, οὐδένα χρόνον τὰς εὐτυχίας κατασχεῖν ἠδυνήθημεν, ἀλλὰ ταχέως διεσκαριφησάμεθα καὶ διελύσαμεν αὐτάς. πολιτείαν γὰρ τὴν ὀρθῶς ἂν τοῖς πράγμασι χρησαμένην οὔτ’ ἔχομεν οὔτε καλῶς ζητοῦμεν.", "st": "7.12"}, {"sp": "N", "t": "καίτοι τὰς εὐπραγίας ἅπαντες ἴσμεν καὶ παραγιγνομένας καὶ παραμενούσας οὐ τοῖς τὰ τείχη κάλλιστα καὶ μέγιστα περιβεβλημένοις, οὐδὲ τοῖς μετὰ πλείστων ἀνθρώπων εἰς τὸν αὐτὸν τόπον συνηθροισμένοις, ἀλλὰ τοῖς ἄριστα καὶ σωφρονέστατα τὴν αὑτῶν πόλιν διοικοῦσιν.", "st": "7.13"}, {"sp": "N", "t": "ἔστι γὰρ ψυχὴ πόλεως οὐδὲν ἔτερον ἢ πολιτεία, τοσαύτην ἔχουσα δύναμιν ὅσην περ ἐν σώματι φρόνησις. αὕτη γάρ ἐστιν ἡ βουλευομένη περὶ ἁπάντων, καὶ τὰ μὲν ἀγαθὰ διαφυλάττουσα, τὰς δὲ συμφορὰς διαφεύγουσα. ταύτῃ καὶ τοὺς νόμους καὶ τοὺς ῥήτορας καὶ τοὺς ἰδιώτας ἀναγκαῖόν ἐστιν ὁμοιοῦσθαι, καὶ πράττειν οὕτως ἑκάστους οἵαν περ ἂν ταύτην ἔχωσιν.", "st": "7.14"}, {"sp": "N", "t": "ἧς ἡμεῖς διεφθαρμένης οὐδὲν φροντίζομεν, οὐδὲ σκοποῦμεν ὅπως ἐπανορθώσομεν αὐτήν· ἀλλ’ ἐπὶ μὲν τῶν ἐργαστηρίων καθίζοντες κατηγοροῦμεν τῶν καθεστώτων, καὶ λέγομεν ὡς οὐδέποτ’ ἐν δημοκρατίᾳ κάκιον ἐπολιτεύθημεν, ἐν δὲ τοῖς πράγμασι καὶ ταῖς διανοίαις αἷς ἔχομεν μᾶλλον αὐτὴν ἀγαπῶμεν τῆς ὑπὸ τῶν προγόνων καταλειφθείσης. ὑπὲρ ἧς ἐγὼ καὶ τοὺς λόγους μέλλω ποιεῖσθαι καὶ τὴν πρόσοδον ἀπεγραψάμην.", "st": "7.15"}, {"sp": "N", "t": "εὑρίσκω γὰρ ταύτην μόνην ἂν γενομένην καὶ τῶν μελλόντων κινδύνων ἀποτροπὴν καὶ τῶν παρόντων κακῶν ἀπαλλαγήν, ἢν ἐθελήσωμεν ἐκείνην τὴν δημοκρατίαν ἀναλαβεῖν, ἢν Σόλων μὲν ὁ δημοτικώτατος γενόμενος ἐνομοθέτησε, Κλεισθένης δὲ ὁ τοὺς τυράννους ἐκβαλὼν καὶ τὸν δῆμον καταγαγὼν πάλιν ἐξ ἀρχῆς κατέστησεν.", "st": "7.16"}, {"sp": "N", "t": "ἧς οὐκ ἂν εὕροιμεν οὔτε δημοτικωτέραν οὔτε τῇ πόλει μᾶλλον συμφέρουσαν. τεκμήριον δὲ μέγιστον· οἱ μὲν γὰρ ἐκείνῃ χρώμενοι, πολλὰ καὶ καλὰ διαπραξάμενοι καὶ παρὰ πᾶσιν ἀνθρώποις εὐδοκιμήσαντες, παρ’ ἑκόντων τῶν Ἑλλήνων τὴν ἡγεμονίαν ἔλαβον, οἱ δὲ τῆς νῦν παρούσης ἐπιθυμήσαντες, ὑπὸ πάντων μισηθέντες καὶ πολλὰ καὶ δεινὰ παθόντες, μικρὸν ἀπέλιπον τοῦ μὴ ταῖς ἐσχάταις συμφοραῖς περιπεσεῖν.", "st": "7.17"}, {"sp": "N", "t": "καίτοι πῶς χρὴ ταύτην τὴν πολιτείαν ἐπαινεῖν ἢ στέργειν τὴν τοσούτων μὲν κακῶν αἰτίαν πρότερον γενομένην, νῦν δὲ καθ’ ἕκαστον τὸν ἐνιαυτὸν ἐπὶ τὸ χεῖρον φερομένην; πῶς δ’ οὐ χρὴ δεδιέναι μὴ τοιαύτης ἐπιδόσεως γιγνομένης τελευτῶντες εἰς τραχύτερα πράγματα τῶν τότε γενομένων ἐξοκείλωμεν;", "st": "7.18"}, {"sp": "N", "t": "ἵνα δὲ μὴ συλλήβδην μόνον ἀκηκοότες, ἀλλ’ ἀκριβῶς εἰδότες ποιῆσθε καὶ τὴν αἵρεσιν καὶ τὴν κρίσιν αὐτῶν, ὑμέτερον μὲν ἔργον ἐστὶ παρασχεῖν ὑμᾶς αὐτοὺς προσέχοντας τὸν νοῦν τοῖς ὑπ’ ἐμοῦ λεγομένοις, ἐγὼ δ’ ὡς ἂν δύνωμαι συντομώτατα περὶ ἀμφοτέρων τούτων πειράσομαι διελθεῖν πρὸς ὑμᾶς.", "st": "7.19"}, {"sp": "N", "t": "οἱ γὰρ κατ’ ἐκεῖνον τὸν χρόνον τὴν πόλιν διοικοῦντες κατεστήσαντο πολιτείαν οὐκ ὀνόματι μὲν τῷ κοινοτάτῳ καὶ πραοτάτῳ προσαγορευομένην, ἐπὶ δὲ τῶν πράξεων οὐ τοιαύτην τοῖς ἐντυγχάνουσι φαινομένην, οὐδ’ ἣ τοῦτον τὸν τρόπον ἐπαίδευε τοὺς πολίτας ὥσθ’ ἡγεῖσθαι τὴν μὲν ἀκολασίαν δημοκρατίαν, τὴν δὲ παρανομίαν ἐλευθερίαν, τὴν δὲ παρρησίαν ἰσονομίαν, τὴν δ’ ἐξουσίαν τοῦ πάντα ποιεῖν εὐδαιμονίαν, ἀλλὰ μισοῦσα καὶ κολάζουσα τοὺς τοιούτους βελτίους καὶ σωφρονεστέρους ἅπαντας τοὺς πολίτας ἐποίησεν.", "st": "7.20"}, {"sp": "N", "t": "μέγιστον δ’ αὐτοῖς συνεβάλετο πρὸς τὸ καλῶς οἰκεῖν τὴν πόλιν, ὅτι δυοῖν ἰσοτήτοιν νομιζομέναιν εἶναι, καὶ τῆς μὲν ταὐτὸν ἅπασιν ἀπονεμούσης τῆς δὲ τὸ προσῆκον ἑκάστοις, οὐκ ἠγνόουν τὴν χρησιμωτέραν, ἀλλὰ τὴν μὲν τῶν αὐτῶν ἀξιοῦσαν τοὺς χρηστοὺς καὶ τοὺς πονηροὺς ἀπεδοκίμαζον ὡς οὐ δικαίαν οὖσαν,", "st": "7.21"}, {"sp": "N", "t": "τὴν δὲ κατὰ τὴν ἀξίαν ἕκαστον τιμῶσαν καὶ κολάζουσαν προῃροῦντο, καὶ διὰ ταύτης ᾤκουν τὴν πόλιν, οὐκ ἐξ ἁπάντων τὰς ἀρχὰς κληροῦντες, ἀλλὰ τοὺς βελτίστους καὶ τοὺς ἱκανωτάτους ἐφ’ ἕκαστον τῶν ἔργων προκρίνοντες. τοιούτους γὰρ ἤλπιζον ἔσεσθαι καὶ τοὺς ἄλλους, οἷοί περ ἂν ὦσιν οἱ τῶν πραγμάτων ἐπιστατοῦντες.", "st": "7.22"}, {"sp": "N", "t": "ἔπειτα καὶ δημοτικωτέραν ἐνόμιζον εἶναι ταύτην τὴν κατάστασιν ἢ τὴν διὰ τοῦ λαγχάνειν γιγνομένην ἐν μὲν γὰρ τῇ κληρώσει τὴν τύχην βραβεύσειν, καὶ πολλάκις λήψεσθαι τὰς ἀρχὰς τοὺς ὀλιγαρχίας ἐπιθυμοῦντας, ἐν δὲ τῷ προκρίνειν τοὺς ἐπιεικεστάτους τὸν δῆμον ἔσεσθαι κύριον ἑλέσθαι τοὺς ἀγαπῶντας μάλιστα τὴν καθεστῶσαν πολιτείαν.", "st": "7.23"}, {"sp": "N", "t": "αἴτιον δ’ ἦν τοῦ ταῦτα τοῖς πολλοῖς ἀρέσκειν καὶ μὴ περιμαχήτους εἶναι τὰς ἀρχάς, ὅτι μεμαθηκότες ἦσαν ἐργάζεσθαι καὶ φείδεσθαι, καὶ μὴ τῶν μὲν οἰκείων ἀμελεῖν τοῖς δ’ ἀλλοτρίοις ἐπιβουλεύειν, μηδ’ ἐκ τῶν δημοσίων τὰ σφέτερ’ αὐτῶν διοικεῖν, ἀλλ’ ἐκ τῶν ἑκάστοις ὑπαρχόντων, εἴ ποτε δεήσειε, τοῖς κοινοῖς ἐπαρκεῖν, μηδ’ ἀκριβέστερον εἰδέναι τὰς ἐκ τῶν ἀρχείων προσόδους ἢ τὰς ἐκ τῶν ἰδίων γιγνομένας αὑτοῖς. οὕτω δ’ ἀπείχοντο σφόδρα τῶν τῆς πόλεως,", "st": "7.24"}, {"sp": "N", "t": "ὥστε χαλεπώτερον ἦν ἐν ἐκείνοις τοῖς χρόνοις εὑρεῖν τοὺς βουλομένους ἄρχειν ἢ νῦν τοὺς μηδὲν δεομένους· οὐ γὰρ ἐμπορίαν ἀλλὰ λειτουργίαν ἐνόμιζον εἶναι τὴν τῶν κοινῶν ἐπιμέλειαν, οὐδ’ ἀπὸ τῆς πρώτης ἡμέρας ἐσκόπουν ἐλθόντες εἴ τι λῆμμα παραλελοίπασιν οἱ πρότερον ἄρχοντες, ἀλλὰ πολὺ μᾶλλον εἴ τινος πράγματος κατημελήκασι τῶν τέλος ἔχειν κατεπειγόντων.", "st": "7.25"}, {"sp": "N", "t": "ὡς δὲ συντόμως εἰπεῖν, ἐκεῖνοι διεγνωκότες ἦσαν ὅτι δεῖ τὸν μὲν δῆμον ὥσπερ τύραννον καθιστάναι τὰς ἀρχὰς καὶ κολάζειν τοὺς ἐξαμαρτάνοντας καὶ κρίνειν περὶ τῶν ἀμφισβητουμένων, τοὺς δὲ σχολὴν ἄγειν δυναμένους καὶ βίον ἱκανὸν κεκτημένους ἐπιμελεῖσθαι τῶν κοινῶν ὥσπερ οἰκέτας,", "st": "7.26"}, {"sp": "N", "t": "καὶ δικαίους μὲν γενομένους ἐπαινεῖσθαι καὶ στέργειν ταύτῃ τῇ τιμῇ, κακῶς δὲ διοικήσαντας μηδεμιᾶς συγγνώμης τυγχάνειν ἀλλὰ ταῖς μεγίσταις ζημίαις περιπίπτειν. καίτοι πῶς ἄν τις εὕροι ταύτης βεβαιοτέραν ἢ δικαιοτέραν δημοκρατίαν, τῆς τοὺς μὲν δυνατωτάτους ἐπὶ τὰς πράξεις καθιστάσης, αὐτῶν δὲ τούτων τὸν δῆμον κύριον ποιούσης;", "st": "7.27"}, {"sp": "N", "t": "τὸ μὲν οὖν σύνταγμα τῆς πολιτείας τοιοῦτον ἦν αὐτοῖς· ῥᾴδιον δ’ ἐκ τούτων καταμαθεῖν ὡς καὶ τὰ καθ’ ἡμέραν ἑκάστην ὀρθῶς καὶ νομίμως πράττοντες διετέλεσαν. ἀνάγκη γὰρ τοῖς περὶ ὅλων τῶν πραγμάτων καλὰς τὰς ὑποθέσεις πεποιημένοις καὶ τὰ μέρη τὸν αὐτὸν τρόπον ἔχειν ἐκείνοις.", "st": "7.28"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τὰ περὶ τοὺς θεούς, ἐντεῦθεν γὰρ ἄρχεσθαι δίκαιον, οὐκ ἀνωμάλως οὐδ’ ἀτάκτως οὔτ’ ἐθεράπευον οὔτ’ ὠργίαζον· οὐδ’ ὁπότε μὲν δόξειεν αὐτοῖς, τριακοσίους βοῦς ἔπεμπον, ὁπότε δὲ τύχοιεν, τὰς πατρίους θυσίας ἐξέλειπον· οὐδὲ τὰς μὲν ἐπιθέτους ἑορτάς, αἷς ἑστίασίς τις προσείη, μεγαλοπρεπῶς ἦγον, ἐν δὲ τοῖς ἁγιωτάτοις τῶν ἱερῶν ἀπὸ μισθωμάτων ἔθυον·", "st": "7.29"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνο μόνον ἐτήρουν, ὅπως μηδὲν μήτε τῶν πατρίων καταλύσουσι μήτ’ ἔξω τῶν νομιζομένων προσθήσουσιν· οὐ γὰρ ἐν ταῖς πολυτελείαις ἐνόμιζον εἶναι τὴν εὐσέβειαν, ἀλλ’ ἐν τῷ μηδὲν κινεῖν ὧν αὐτοῖς οἱ πρόγονοι παρέδοσαν. καὶ γάρ τοι καὶ τὰ παρὰ τῶν θεῶν οὐκ ἐμπλήκτως οὐδὲ ταραχωδῶς αὐτοῖς συνέβαινεν, ἀλλ’ εὐκαίρως καὶ πρὸς τὴν ἐργασίαν τῆς χώρας καὶ πρὸς τὴν συγκομιδὴν τῶν καρπῶν.", "st": "7.30"}, {"sp": "N", "t": "παραπλησίως δὲ τοῖς εἰρημένοις καὶ τὰ πρὸς σφᾶς αὐτοὺς διῴκουν. οὐ γὰρ μόνον μερὶ τῶν κοινῶν ὡμονόουν, ἀλλὰ καὶ περὶ τὸν ἴδιον βίον τοσαύτην ἐποιοῦντο πρόνοιαν ἀλλήλων, ὅσην περ χρὴ τοὺς εὖ φρονοῦντας καὶ πατρίδος κοινωνοῦντας. οἵ τε γὰρ πενέστεροι τῶν πολιτῶν τοσοῦτον ἀπεῖχον τοῦ φθονεῖν τοῖς πλείω κεκτημένοις,", "st": "7.31"}, {"sp": "N", "t": "ὥσθ’ ὁμοίως ἐκήδοντο τῶν οἴκων τῶν μεγάλων ὥσπερ τῶν σφετέρων αὐτῶν, ἡγούμενοι τὴν ἐκείνων εὐδαιμονίαν αὑτοῖς εὐπορίαν ὑπάρχειν· οἵ τε τὰς οὐσίας ἔχοντες οὐχ ὅπως ὑπερεώρων τοὺς καταδεέστερον πράττοντας, ἀλλ’ ὑπολαμβάνοντες αἰσχύνην αὑτοῖς εἶναι τὴν τῶν πολιτῶν ἀπορίαν ἐπήμυνον ταῖς ἐνδείαις, τοῖς μὲν γεωργίας ἐπὶ μετρίαις μισθώσεσι παραδιδόντες, τοὺς δὲ κατ’ ἐμπορίαν ἐκπέμποντες, τοῖς δ’ εἰς τὰς ἄλλας ἐργασίας ἀφορμὴν παρέχοντες.", "st": "7.32"}, {"sp": "N", "t": "οὐ γὰρ ἐδεδίεσαν μὴ δυοῖν θάτερον πάθοιεν, ἢ πάντων στερηθεῖεν, ἢ πολλὰ πράγματα σχόντες μέρος τι κομίσαιντο τῶν προεθέντων· ἀλλ’ ὁμοίως ἐθάρρουν περὶ τῶν ἔξω δεδομένων ὥσπερ περὶ τῶν ἔνδον κειμένων. ἑώρων γὰρ τοὺς περὶ τῶν συμβολαίων κρίνοντας οὐ ταῖς ἐπιεικείαις χρωμένους, ἀλλὰ τοῖς νόμοις πειθομένους,", "st": "7.33"}, {"sp": "N", "t": "οὐδ’ ἐν τοῖς τῶν ἄλλων ἀγῶσιν αὑτοῖς ἀδικεῖν ἐξουσίαν παρασκευάζοντας, ἀλλὰ μᾶλλον ὀργιζομένους τοῖς ἀποστεροῦσιν αὐτῶν τῶν ἀδικουμένων, καὶ νομίζοντας διὰ τοὺς ἄπιστα τὰ συμβόλαια ποιοῦντας μείζω βλάπτεσθαι τοὺς πένητας τῶν πολλὰ κεκτημένων· τοὺς μὲν γάρ, ἢν παύσωνται προϊέμενοι, μικρῶν προσόδων ἀποστερηθήσεσθαι, τοὺς δ’, ἢν ἀπορήσωσι τῶν ἐπαρκούντων, εἰς τὴν ἐσχάτην ἔνδειαν καταστήσεσθαι.", "st": "7.34"}, {"sp": "N", "t": "καὶ γάρ τοι διὰ τὴν γνώμην ταύτην οὐδεὶς οὔτ’ ἀπεκρύπτετο τὴν οὐσίαν οὔτ’ ὤκνει συμβάλλειν, ἀλλ’ ἥδιον ἑώρων τοὺς δανειζομένους ἢ τοὺς ἀποδιδόντας. ἀμφότερα γὰρ αὐτοῖς συνέβαινεν, ἅπερ ἂν βουληθεῖεν ἄνθρωποι νοῦν ἔχοντες· ἅμα γὰρ τούς τε πολίτας ὠφέλουν καὶ τὰ σφέτερ’ αὐτῶν ἐνεργὰ καθίστασαν. κεφάλαιον δὲ τοῦ καλῶς ἀλλήλοις ὁμιλεῖν· αἱ μὲν γὰρ κτήσεις ἀσφαλεῖς ἦσαν, οἷσπερ κατὰ τὸ δίκαιον ὑπῆρχον, αἱ δὲ χρήσεις κοιναὶ πᾶσι τοῖς δεομένοις τῶν πολιτῶν.", "st": "7.35"}, {"sp": "N", "t": "ἴσως ἂν οὖν τις ἐπιτιμήσειε τοῖς εἰρημένοις, ὅτι τὰς μὲν πράξεις ἐπαινῶ τὰς ἐν ἐκείνοις τοῖς χρόνοις γεγενημένας, τὰς δ’ αἰτίας οὐ φράζω, δι’ ἃς οὕτω καλῶς καὶ τὰ πρὸς σφᾶς αὐτοὺς εἶχον καὶ τὴν πόλιν διῴκουν. ἐγὼ δ’ οἶμαι μὲν εἰρηκέναι τι καὶ τοιοῦτον, οὐ μὴν ἀλλ’ ἔτι πλείω καὶ σαφέστερον πειράσομαι διαλεχθῆναι περὶ αὐτῶν.", "st": "7.36"}, {"sp": "N", "t": "ἐκεῖνοι γὰρ οὐκ ἐν μὲν ταῖς παιδείαις πολλοὺς τοὺς ἐπιστατοῦντας εἶχον, ἐπειδὴ δ’ εἰς ἄνδρας δοκιμασθεῖεν, ἐξῆν αὐτοῖς ποιεῖν ὅ τι βουληθεῖεν, ἀλλ’ ἐν αὐταῖς ταῖς ἀκμαῖς πλέονος ἐπιμελείας ἐτύγχανον ἢ παῖδες ὄντες. οὕτω γὰρ ἡμῶν οἱ πρόγονοι σφόδρα περὶ τὴν σωφροσύνην ἐσπούδαζον, ὥστε τὴν ἐξ Ἀρείου πάγου βουλὴν ἐπέστησαν ἐπιμελεῖσθαι τῆς εὐκοσμίας, ἧς οὐχ οἷόν τ’ ἦν μετασχεῖν πλὴν τοῖς καλῶς γεγονόσι καὶ πολλὴν ἀρετὴν ἐν τῷ βίω καὶ σωφροσύνην ἐνδεδειγμένοις, ὥστ’ εἰκότως αὐτὴν διενεγκεῖν τῶν ἐν τοῖς Ἕλλησι συνεδρίων.", "st": "7.37"}, {"sp": "N", "t": "σημείοις δ’ ἄν τις χρήσαιτο περὶ τῶν τότε καθεστώτων καὶ τοῖς ἐν τῷ παρόντι γιγνομένοις· ἔτι γὰρ καὶ νῦν ἁπάντων τῶν περὶ τὴν αἵρεσιν καὶ τὴν δοκιμασίαν κατημελημένων ἴδοιμεν ἂν τοὺς ἐν τοῖς ἄλλοις πράγμασιν οὐκ ἀνεκτοὺς ὄντας, ἐπειδὰν εἰς Ἄρειον πάγον ἀναβῶσιν, ὀκνοῦντας τῇ φύσει χρῆσθαι καὶ μᾶλλον τοῖς ἐκεῖ νομίμοις ἢ ταῖς αὑτῶν κακίαις ἐμμένοντας. τοσοῦτον φόβον ἐκεῖνοι τοῖς πονηροῖς ἐνειργάσαντο, καὶ τοιοῦτο μνημεῖον ἐν τῷ τόπῳ τῆς αὑτῶν ἀρετῆς καὶ σωφροσύνης ἐγκατέλιπον.", "st": "7.38"}, {"sp": "N", "t": "τὴν δὴ τοιαύτην, ὥσπερ εἶπον, κυρίαν ἐποίησαν τῆς εὐταξίας ἐπιμελεῖσθαι, ἣ τοὺς μὲν οἰομένους ἐνταῦθα βελτίστους ἄνδρας γίγνεσθαι, παρ’ οἷς οἱ νόμοι μετὰ πλείστης ἀκριβείας κείμενοι τυγχάνουσιν, ἀγνοεῖν ἐνόμιζεν· οὐδὲν γὰρ ἂν κωλύειν ὁμοίους ἅπαντας εἶναι τοὺς Ἕλληνας ἕνεκά γε τοῦ ῥᾴδιον εἶναι τὰ γράμματα λαβεῖν παρ’ ἀλλήλων.", "st": "7.39"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἐκ τούτων τὴν ἐπίδοσιν εἶναι τῆς ἀρετῆς, ἀλλ’ ἐκ τῶν καθ’ ἑκάστην τὴν ἡμέραν ἐπιτηδευμάτων· τοὺς γὰρ πολλοὺς ὁμοίους τοῖς ἤθεσιν ἀποβαίνειν, ἐν οἷς ἂν ἕκαστοι παιδευθῶσιν. ἔπειτα τά γε πλήθη καὶ τὰς ἀκριβείας τῶν νόμων σημεῖον εἶναι τοῦ κακῶς οἰκεῖσθαι τὴν πόλιν ταύτην· ἐμφράγματα γὰρ αὐτοὺς ποιουμένους τῶν ἁμαρτημάτων πολλοὺς τίθεσθαι τοὺς νόμους ἀναγκάζεσθαι.", "st": "7.40"}, {"sp": "N", "t": "δεῖν δὲ τοὺς ὀρθῶς πολιτευομένους οὐ τὰς στοὰς ἐμπιπλάναι γραμμάτων, ἀλλ’ ἐν ταῖς ψυχαῖς ἔχειν τὸ δίκαιον· οὐ γὰρ τοῖς ψηφίσμασιν ἀλλὰ τοῖς ἤθεσι καλῶς οἰκεῖσθαι τὰς πόλεις, καὶ τοὺς μὲν κακῶς τεθραμμένους καὶ τοὺς ἀκριβῶς τῶν νόμων ἀναγεγραμμένους τολμήσειν παραβαίνειν, τοὺς δὲ καλῶς πεπαιδευμένους καὶ τοῖς ἁπλῶς κειμένοις ἐθελήσειν ἐμμένειν.", "st": "7.41"}, {"sp": "N", "t": "ταῦτα διανοηθέντες οὐ τοῦτο πρῶτον ἐσκόπουν, δι’ ὧν κολάσουσι τοὺς ἀκοσμοῦντας, ἀλλ’ ἐξ ὧν παρασκευάσουσι μηδὲν αὐτοὺς ἄξιον ζημίας ἐξαμαρτάνειν· ἡγοῦντο γὰρ τοῦτο μὲν αὑτῶν ἔργον εἶναι, τὸ δὲ περὶ τὰς τιμωρίας σπουδάζειν τοῖς ἐχθροῖς προσήκειν.", "st": "7.42"}, {"sp": "N", "t": "ἁπάντων μὲν οὖν ἐφρόντιζον τῶν πολιτῶν, μάλιστα δὲ τῶν νεωτέρων. ἑώρων γὰρ τοὺς τηλικούτους ταραχωδέστατα διακειμένους καὶ πλείστων γέμοντας ἐπιθυμιῶν, καὶ τὰς ψυχὰς αὐτῶν μάλιστα δαμασθῆναι δεομένας ἐπιμελείαις καλῶν ἐπιτηδευμάτων καὶ πόνοις ἡδονὰς ἔχουσιν· ἐν μόνοις γὰρ ἂν τούτοις ἐμμεῖναι τοὺς ἐλευθέρως τεθραμμένους καὶ μεγαλοφρονεῖν εἰθισμένους.", "st": "7.43"}, {"sp": "N", "t": "ἅπαντας μὲν οὖν ἐπὶ τὰς αὐτὰς ἄγειν διατριβὰς οὐχ οἷόν τ’ ἦν, ἀνωμάλως τὰ περὶ τὸν βίον ἔχοντας· ὡς δὲ πρὸς τὴν οὐσίαν ἥρμοττεν, οὕτως ἑκάστοις προσέταττον. τοὺς μὲν γὰρ ὑποδεέστερον πράττοντας ἐπὶ τὰς γεωργίας καὶ τὰς ἐμπορίας ἔτρεπον, εἰδότες τὰς ἀπορίας μὲν διὰ τὰς ἀργίας γιγνομένας,", "st": "7.44"}, {"sp": "N", "t": "τὰς δὲ κακουργίας διὰ τὰς ἀπορίας· ἀπορίας· ἀναιροῦντες οὖν τὴν ἀρχὴν τῶν κακῶν ἀπαλλάξειν ᾤοντο καὶ τῶν ἄλλων ἁμαρτημάτων τῶν μετ’ ἐκείνην γιγνομένων. τοὺς δὲ βίον ἱκανὸν κεκτημένους περὶ τὴν ἱππικὴν καὶ τὰ γυμνάσια καὶ τὰ κυνηγέσια καὶ τὴν φιλοσοφίαν ἠνάγκασαν διατρίβειν, ὁρῶντες ἐκ τούτων τοὺς μὲν διαφέροντας γιγνομένους, τοὺς δὲ τῶν πλείστων κακῶν ἀπεχομένους.", "st": "7.45"}, {"sp": "N", "t": "καὶ ταῦτα νομοθετήσαντες οὐδὲ τὸν λοιπὸν χρόνον ὠλιγώρουν, ἀλλὰ διελόμενοι τὴν μὲν πόλιν κατὰ κώμας τὴν δὲ χώραν κατὰ δήμους ἐθεώρουν τὸν βίον τὸν ἑκάστου, καὶ τοὺς ἀκοσμοῦντας ἀνῆγον εἰς τὴν βουλήν. ἡ δὲ τοὺς μὲν ἐνουθέτει, τοῖς δ’ ἠπείλει, τοὺς δ’ ὡς προσῆκεν ἐκόλαζεν. ἠπίσταντο γὰρ ὅτι δύο τρόποι τυγχάνουσιν ὄντες οἱ καὶ προτρέποντες ἐπὶ τὰς ἀδικίας καὶ παύοντες τῶν πονηριῶν·", "st": "7.46"}, {"sp": "N", "t": "παρ’ οἷς μὲν γὰρ μήτε φυλακὴ μηδεμία τῶν τοιούτων καθέστηκε μήθ’ αἱ κρίσεις ἀκριβεῖς εἰσι, παρὰ τούτοις μὲν διαφθείρεσθαι καὶ τὰς ἐπιεικεῖς τῶν φύσεων, ὅπου δὲ μήτε λαθεῖν τοῖς ἀδικοῦσι ῥᾴδιόν ἐστι μήτε φανεροῖς γενομένοις συγγνώμης τυχεῖν, ἐνταῦθα δ’ ἐξιτήλους γίγνεσθαι τὰς κακοηθείας. ἅπερ ἐκεῖνοι γιγνώσκοντες ἀμφοτέροις κατεῖχον τοὺς πολίτας, καὶ ταῖς τιμωρίαις καὶ ταῖς ἐπιμελείαις· τοσούτου γὰρ ἔδεον αὐτοὺς λανθάνειν οἱ κακόν τι δεδρακότες, ὥστε καὶ τοὺς ἐπιδόξους ἁμαρτήσεσθαί τι προῃσθάνοντο.", "st": "7.47"}, {"sp": "N", "t": "τοιγαροῦν οὐκ ἐν τοῖς σκιραφείοις οἱ νεώτεροι διέτριβον, οὐδ’ ἐν ταῖς αὐλητρίσιν, οὐδ’ ἐν τοῖς τοιούτοις συλλόγοις ἐν οἷς νῦν διημερεύουσιν· ἀλλ’ ἐν τοῖς ἐπιτηδεύμασιν ἔμενον ἐν οἷς ἐτάχθησαν, θαυμάζοντες καὶ ζηλοῦντες τοὺς ἐν τούτοις πρωτεύοντας. οὕτω δ’ ἔφευγον τὴν ἀγοράν, ὥστ’ εἰ καί ποτε διελθεῖν ἀναγκασθεῖεν, μετὰ πολλῆς αἰδοῦς καὶ σωφροσύνης ἐφαίνοντο τοῦτο ποιοῦντες.", "st": "7.48"}, {"sp": "N", "t": "ἀντειπεῖν δὲ τοῖς πρεσβυτέροις ἢ λοιδορήσασθαι δεινότερον ἐνόμιζον ἢ νῦν περὶ τοὺς γονέας ἐξαμαρτεῖν. ἐν καπηλείῳ δὲ φαγεῖν ἢ πιεῖν οὐδεὶς οὐδ’ ἂν οἰκέτης ἐπιεικὴς ἐτόλμησεν· σεμνύνεσθαι γὰρ ἐμελέτων, ἀλλ’ οὐ βωμολοχεύεσθαι. καὶ τοὺς εὐτραπέλους δὲ καὶ τοὺς σκώπτειν δυναμένους, οὓς νῦν εὐφυεῖς προσαγορεύουσιν, ἐκεῖνοι δυστυχεῖς ἐνόμιζον.", "st": "7.49"}, {"sp": "N", "t": "καὶ μηδεὶς οἰέσθω με δυσκόλως διακεῖσθαι πρὸς τοὺς ταύτην ἔχοντας τὴν ἡλικίαν. οὔτε γὰρ ἡγοῦμαι τούτους αἰτίους εἶναι τῶν γιγνομένων, σύνοιδά τε τοῖς πλείστοις αὐτῶν ἥκιστα χαίρουσι ταύτῃ τῇ καταστάσει, δι’ ἣν ἔξεστιν αὐτοῖς ἐν ταῖς ἀκολασίαις ταύταις διατρίβειν· ὥστ’ οὐκ ἂν εἰκότως τούτοις ἐπιτιμῴην, ἀλλὰ πολὺ δικαιότερον τοῖς ὀλίγῳ πρὸ ἡμῶν τὴν πόλιν διοικήσασιν.", "st": "7.50"}, {"sp": "N", "t": "ἐκεῖνοι γὰρ ἦσαν οἱ προτρέψαντες ἐπὶ ταύτας τὰς ὀλιγωρίας καὶ καταλύσαντες τῆς βουλῆς δύναμιν. ἧς ἐπιστατούσης οὐ δικῶν οὐδ’ ἐγκλημάτων οὐδ’ εἰσφορῶν οὐδὲ πενίας οὐδὲ πολέμων ἡ πόλις ἔγεμεν, ἀλλὰ καὶ πρὸς ἀλλήλους ἡσυχίαν εἶχον καὶ πρὸς τοὺς ἄλλους ἅπαντας εἰρήνην ἦγον. παρεῖχον γὰρ σφᾶς αὐτοὺς τοῖς μὲν Ἕλλησι πιστούς,", "st": "7.51"}, {"sp": "N", "t": "τοῖς δὲ βαρβάροις φοβερούς· τοὺς μὲν γὰρ σεσωκότες ἦσαν, παρὰ δὲ τῶν δίκην τηλικαύτην εἰληφότες, ὥστ’ ἀγαπᾶν ἐκείνους εἰ μηδὲν ἔτι κακὸν πάσχοιεν. τοιγάρτοι διὰ ταῦτα μετὰ τοσαύτης ἀσφαλείας διῆγον, ὥστε καλλίους εἶναι καὶ πολυτελεστέρας τὰς οἰκήσεις καὶ τὰς κατασκευὰς τὰς ἐπὶ τῶν ἀγρῶν ἢ τὰς ἐντὸς τείχους, καὶ πολλοὺς τῶν πολιτῶν μηδ’ εἰς τὰς ἑορτὰς εἰς ἄστυ καταβαίνειν, ἀλλ’ αἱρεῖσθαι μένειν ἐπὶ τοῖς ἰδίοις ἀγαθοῖς μᾶλλον ἢ τῶν κοινῶν ἀπολαύειν.", "st": "7.52"}, {"sp": "N", "t": "οὐδὲ γὰρ τὰ περὶ τὰς θεωρίας, ὧν ἕνεκ’ ἄν τις ἦλθεν, ἀσελγῶς οὐδ’ ὑπερηφάνως ἀλλὰ νοῦν ἐχόντως ἐποίουν. οὐ γὰρ ἐκ τῶν πομπῶν οὐδ’ ἐκ τῶν περὶ τὰς χορηγίας φιλονεικιῶν οὐδ’ ἐκ τῶν τοιούτων ἀλαζονειῶν τὴν εὐδαιμονίαν ἐδοκίμαζον, ἀλλ’ ἐκ τοῦ σωφρόνως οἰκεῖν καὶ τοῦ βίου τοῦ καθ’ ἡμέραν καὶ τοῦ μηδένα τῶν πολιτῶν ἀπορεῖν τῶν ἐπιτηδείων. ἐξ ὧνπερ χρὴ κρίνειν τοὺς ὡς ἀληθῶς εὖ πράττοντας καὶ μὴ φορτικῶς πολιτευομένους·", "st": "7.53"}, {"sp": "N", "t": "ἐπεὶ νῦν γε τίς οὐκ ἂν ἐπὶ τοῖς γιγνομένοις τῶν εὖ φρονούντων ἀλγήσειεν, ὅταν ἴδῃ πολλοὺς τῶν πολιτῶν αὐτοὺς μὲν περὶ τῶν ἀναγκαίων, εἴθ’ ἕξουσιν εἴτε μή, πρὸ τῶν δικαστηρίων κληρουμένους, τῶν δ’ Ἑλλήνων τοὺς ἐλαύνειν τὰς ναῦς βουλομένους τρέφειν ἀξιοῦντας, καὶ χορεύοντας μὲν ἐν χρυσοῖς ἱματίοις, χειμάζοντας δ’ ἐν τοιούτοις ἐν οἷς οὐ βούλομαι λέγειν, καὶ τοιαύτας ἄλλας ἐναντιώσεις περὶ τὴν διοίκησιν γιγνομένας, αἳ μεγάλην αἰσχύνην τῇ πόλει ποιοῦσιν;", "st": "7.54"}, {"sp": "N", "t": "ὧν οὐδὲν ἦν ἐπ’ ἐκείνης τῆς βουλῆς· ἀπήλλαξε γὰρ τοὺς μὲν πένητας τῶν ἀποριῶν ταῖς ἐργασίαις καὶ ταῖς παρὰ τῶν ἐχόντων ὠφελίαις, τοὺς δὲ νεωτέρους τῶν ἀκολασιῶν τοῖς ἐπιτηδεύμασι καὶ ταῖς αὐτῶν ἐπιμελείαις, τοὺς δὲ πολιτευομένους τῶν πλεονεξιῶν ταῖς τιμωρίαις καὶ τῷ μὴ λανθάνειν τοὺς ἀδικοῦντας, τοὺς δὲ πρεσβυτέρους τῶν ἀθυμιῶν ταῖς τιμαῖς ταῖς πολιτικαῖς καὶ ταῖς παρὰ τῶν νεωτέρων θεραπείαις. καίτοι πῶς ἂν γένοιτο ταύτης πλείονος ἀξία πολιτεία, τῆς οὕτω καλῶς ἁπάντων τῶν πραγμάτων ἐπιμεληθείσης;", "st": "7.55"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ποτὲ καθεστώτων τὰ μὲν πλεῖστα διεληλύθαμεν· ὅσα δὲ παραλελοίπαμεν, ἐκ τῶν εἰρημένων, ὅτι κἀκεῖνα τὸν αὐτὸν τρόπον εἶχε τούτοις, ῥᾴδιόν ἐστι καταμαθεῖν. ἤδη δέ τινες ἀκούσαντές μου ταῦτα διεξιόντος ἐπῄνεσαν μὲν ὡς οἷόν τε μάλιστα, καὶ τοὺς προγόνους ἐμακάρισαν ὅτι τὸν τρόπον τοῦτον τὴν πόλιν διῴκουν,", "st": "7.56"}, {"sp": "N", "t": "οὐ μὴν ὑμᾶς γε ᾤοντο πεισθήσεσθαι χρῆσθαι τούτοις, ἀλλ’ αἱρήσεσθαι διὰ τὴν συνήθειαν ἐν τοῖς καθεστηκόσι πράγμασι κακοπαθεῖν μᾶλλον ἢ μετὰ πολιτείας ἀκριβεστέρας ἄμεινον τὸν βίον διάγειν. εἶναι δ’ ἔφασαν ἐμοὶ καὶ κίνδυνον, μὴ τὰ βέλτιστα συμβουλεύων μισόδημος εἶναι δόξω καὶ τὴν πόλιν ζητεῖν εἰς ὀλιγαρχίαν ἐμβαλεῖν.", "st": "7.57"}, {"sp": "N", "t": "ἐγὼ δ’ εἰ μὲν περὶ πραγμάτων ἀγνοουμένων καὶ μὴ κοινῶν τοὺς λόγους ἐποιούμην, καὶ περὶ τούτων ἐκέλευον ὑμᾶς ἑλέσθαι συνέδρους ἢ συγγραφέας, δι’ ὧν ὁ δῆμος κατελύθη τὸ πρότερον, εἰκότως ἂν εἶχον ταύτην τὴν αἰτίαν· νῦν δ’ οὐδὲν εἴρηκα τοιοῦτον, ἀλλὰ διείλεγμαι περὶ διοικήσεως οὐκ ἀποκεκρυμμένης ἀλλὰ πᾶσι φανερᾶς,", "st": "7.58"}, {"sp": "N", "t": "ἣν πάντες ἴστε καὶ πατρίαν ἡμῖν οὖσαν καὶ πλείστων ἀγαθῶν καὶ τῇ πόλει καὶ τοῖς ἄλλοις Ἕλλησιν αἰτίαν γεγενημένην, πρὸς δὲ τούτοις ὑπὸ τοιούτων ἀνδρῶν νομοθετηθεῖσαν καὶ κατασταθεῖσαν, οὓς οὐδεὶς ὅστις οὐκ ἂν ὁμολογήσειε δημοτικωτάτους γεγενῆσθαι τῶν πολιτῶν. ὥστε πάντων ἄν μοι συμβαίη δεινότατον, εἰ τοιαύτην πολιτείαν εἰσηγούμενος νεωτέρων δόξαιμι πραγμάτων ἐπιθυμεῖν.", "st": "7.59"}, {"sp": "N", "t": "ἔπειτα κἀκεῖθεν ῥᾴδιον γνῶναι τὴν ἐμὴν διάνοιαν· ἐν γὰρ τοῖς πλείστοις τῶν λόγων τῶν εἰρημένων ὑπ’ ἐμοῦ φανήσομαι ταῖς μὲν ὀλιγαρχίαις καὶ ταῖς πλεονεξίαις ἐπιτιμῶν, τὰς δ’ ἰσότητας καὶ τὰς δημοκρατίας ἐπαινῶν, οὐ πάσας, ἀλλὰ τὰς καλῶς καθεστηκυίας, οὐδ’ ὡς ἔτυχον, ἀλλὰ δικαίως καὶ λόγον ἐχόντως.", "st": "7.60"}, {"sp": "N", "t": "οἶδα γὰρ τούς τε προγόνους τοὺς ἡμετέρους ἐν ταύτῃ τῇ καταστάσει πολὺ τῶν ἄλλων διενεγκόντας, καὶ Λακεδαιμονίους διὰ τοῦτο κάλλιστα πολιτευομένους, ὅτι μάλιστα δημοκρατούμενοι τυγχάνουσιν. ἐν γὰρ τῇ τῶν ἀρχῶν αἱρέσει καὶ τῷ βίῳ τῷ καθ’ ἡμέραν καὶ τοῖς ἄλλοις ἐπιτηδεύμασιν ἴδοιμεν ἂν παρ’ αὐτοῖς τὰς ἰσότητας καὶ τὰς ὁμοιότητας μᾶλλον ἢ παρὰ τοῖς ἄλλοις ἰσχυούσας· οἷς αἱ μὲν ὀλιγαρχίαι πολεμοῦσιν, οἱ δὲ καλῶς δημοκρατούμενοι χρώμενοι διατελοῦσιν.", "st": "7.61"}, {"sp": "N", "t": "τῶν τοίνυν ἄλλων πόλεων ταῖς ἐπιφανεστάταις καὶ μεγίσταις, ἢν ἐξετάζειν βουληθῶμεν, εὑρήσομεν τὰς δημοκρατίας μᾶλλον ἢ τὰς ὀλιγαρχίας συμφερούσας· ἐπεὶ καὶ τὴν ἡμετέραν πολιτείαν, ᾗ πάντες ἐπιτιμῶσιν, ἢν παραβάλωμεν αὐτὴν μὴ πρὸς τὴν ὑπ’ ἐμοῦ ῥηθεῖσαν ἀλλὰ πρὸς τὴν ὑπὸ τῶν τριάκοντα καταστᾶσαν, οὐδεὶς ὅστις οὐκ ἂν θεοποίητον εἶναι νομίσειεν.", "st": "7.62"}, {"sp": "N", "t": "βούλομαι δ’, εἰ καί τινές με φήσουσιν ἔξω τῆς ὑποθέσεως λέγειν, δηλῶσαι καὶ διελθεῖν ὅσον αὕτη τῆς τότε διήνεγκεν, ἵνα μηδεὶς οἴηταί με τὰ μὲν ἁμαρτήματα τοῦ δήμου λίαν ἀκριβῶς ἐξετάζειν, εἰ δέ τι καλὸν ἢ σεμνὸν διαπέπρακται, ταῦτα δὲ παραλείπειν. ἔσται δ’ ὁ λόγος οὔτε μακρὸς οὔτ’ ἀνωφελὴς τοῖς ἀκούουσιν.", "st": "7.63"}, {"sp": "N", "t": "ἐπειδὴ γὰρ τὰς ναῦς τὰς περὶ Ἑλλήσποντον ἀπωλέσαμεν καὶ ταῖς συμφοραῖς ἐκείναις ἡ πόλις περιέπεσε, τίς οὐκ οἶδε τῶν πρεσβυτέρων τοὺς μὲν δημοτικοὺς καλουμένους ἑτοίμους ὄντας ὁτιοῦν πάσχειν ὑπὲρ τοῦ μὴ ποιεῖν τὸ προσταττόμενον, καὶ δεινὸν ἡγουμένους εἴ τις ὄψεται τὴν πόλιν τὴν τῶν Ἑλλήνων ἄρξασαν, ταύτην ὑφ’ ἑτέροις οὖσαν, τοὺς δὲ τῆς ὀλιγαρχίας ἐπιθυμήσαντας ἑτοίμως καὶ τὰ τείχη καθαιροῦντας καὶ τὴν δουλείαν ὑπομένοντας;", "st": "7.64"}, {"sp": "N", "t": "καὶ τότε μέν, ὅτε τὸ πλῆθος ἦν κύριον τῶν πραγμάτων, ἡμᾶς τὰς τῶν ἄλλων ἀκροπόλεις φρουροῦντας, ἐπειδὴ δ’ οἱ τριάκοντα παρέλαβον τὴν πολιτείαν, τοὺς πολεμίους τὴν ἡμετέραν ἔχοντας; καὶ κατὰ μὲν ἐκεῖνον τὸν χρόνον δεσπότας ἡμῶν ὄντας Λακεδαιμονίους, ἐπειδὴ δ’ οἱ φεύγοντες κατελθόντες πολεμεῖν ὑπὲρ τῆς ἐλευθερίας ἐτόλμησαν καὶ Κόνων ναυμαχῶν ἐνίκησε, πρέσβεις ἐλθόντας παρ’ αὐτῶν καὶ διδόντας τῇ πόλει τὴν ἀρχὴν τὴν τῆς θαλάττης;", "st": "7.65"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ τάδε τίς οὐ μνημονεύει τῶν ἡλικιωτῶν τῶν ἐμῶν, τὴν μὲν δημοκρατίαν οὕτω κοσμήσασαν τὴν πόλιν καὶ τοῖς ἱεροῖς καὶ τοῖς ὁσίοις, ὥστ’ ἔτι καὶ νῦν τοὺς ἀφικνουμένους νομίζειν αὐτὴν ἀξίαν εἶναι μὴ μόνον τῶν Ἑλλήνων ἄρχειν ἀλλὰ καὶ τῶν ἄλλων ἁπάντων, τοὺς δὲ τριάκοντα τῶν μὲν ἀμελήσαντας, τὰ δὲ συλήσαντας, τοὺς δὲ νεωσοίκους ἐπὶ καθαιρέσει τριῶν ταλάντων ἀποδομένους, εἰς οὓς ἡ πόλις ἀνήλωσεν οὐκ ἐλάττω χιλίων ταλάντων;", "st": "7.66"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδὲ τὴν πραότητα δικαίως ἄν τις ἐπαινέσειε τὴν ἐκείνων μᾶλλον ἢ τὴν τοῦ δήμου. οἱ μὲν γὰρ ψηφίσματι παραλαβόντες τὴν πόλιν πεντακοσίους μὲν καὶ χιλίους τῶν πολιτῶν ἀκρίτους ἀπέκτειναν, εἰς δὲ τὸν Πειραιᾶ φυγεῖν πλείους ἢ πεντακισχιλίους ἠνάγκασαν· οἱ δὲ κρατήσαντες καὶ μεθ’ ὅπλων κατιόντες, αὐτοὺς τοὺς αἰτιωτάτους τῶν κακῶν ἀνελόντες, οὕτω τὰ πρὸς τοὺς ἄλλους καλῶς καὶ νομίμως διῴκησαν, ὥστε μηδὲν ἔλαττον ἔχειν τοὺς ἐκβαλόντας τῶν κατελθόντων.", "st": "7.67"}, {"sp": "N", "t": "ὃ δὲ πάντων κάλλιστον καὶ μέγιστον τεκμήριον τῆς ἐπιεικείας τοῦ δήμου· δανεισαμένων γὰρ τῶν ἐν ἄστει μεινάντων ἑκατὸν τάλαντα παρὰ Λακεδαιμονίων εἰς τὴν πολιορκίαν τῶν τὸν Πειραιᾶ κατασχόντων, ἐκκλησίας γενομένης περὶ ἀποδόσεως τῶν χρημάτων, καὶ λεγόντων πολλῶν ὡς δίκαιόν ἐστι διαλύειν τὰ πρὸς Λακεδαιμονίους μὴ τοὺς πολιορκουμένους ἀλλὰ τοὺς δανεισαμένους, ἔδοξε τῷ δήμῳ κοινὴν ποιήσασθαι τὴν ἀπόδοσιν.", "st": "7.68"}, {"sp": "N", "t": "καὶ γάρ τοι διὰ ταύτην τὴν γνώμην εἰς τοιαύτην ἡμᾶς ὁμόνοιαν κατέστησαν καὶ τοσοῦτον ἐπιδοῦναι τὴν πόλιν ἐποίησαν, ὥστε Λακεδαιμονίους, τοὺς ἐπὶ τῆς ὀλιγαρχίας ὀλίγου δεῖν καθ’ ἑκάστην τὴν ἡμέραν προστάττοντας ἡμῖν, ἐλθεῖν ἐπὶ τῆς δημοκρατίας ἱκετεύσοντας καὶ δεησομένους μὴ περιιδεῖν αὐτοὺς ἀναστάτους γενομένους. τὸ δ’ οὖν κεφάλαιον τῆς ἑκατέρων διανοίας τοιοῦτον ἦν· οἱ μὲν γὰρ ἠξίουν τῶν μὲν πολιτῶν ἄρχειν, τοῖς δὲ πολεμίοις δουλεύειν, οἱ δὲ τῶν μὲν ἄλλων ἄρχειν, τοῖς δὲ πολίταις ἴσον ἔχειν.", "st": "7.69"}, {"sp": "N", "t": "ταῦτα δὲ διῆλθον δυοῖν ἕνεκα, πρῶτον μὲν ἐμαυτὸν ἐπιδεῖξαι βουλόμενος οὐκ ὀλιγαρχιῶν οὐδὲ πλεονεξιῶν ἀλλὰ δικαίας καὶ κοσμίας ἐπιθυμοῦντα πολιτείας, ἔπειτα τὰς δημοκρατίας τάς τε κακῶς καθεστηκυίας ἐλαττόνων συμφορῶν αἰτίας γιγνομένας, τὰς τε καλῶς πολιτευομένας προεχούσας τῷ δικαιοτέρας εἶναι καὶ κοινοτέρας καὶ τοῖς χρωμένοις ἡδίους.", "st": "7.70"}, {"sp": "N", "t": "τάχ’ οὖν ἄν τις θαυμάσειε, τί βουλόμενος ἀντὶ τῆς πολιτείας τῆς οὕτω πολλὰ καὶ καλὰ διαπεπραγμένης ἑτέραν ὑμᾶς πείθω μεταλαβεῖν, καὶ τίνος ἕνεκα νῦν μὲν οὕτω καλῶς ἐγκεκωμίακα τὴν δημοκρατίαν, ὅταν δὲ τύχω, πάλιν μεταβαλὼν ἐπιτιμῶ καὶ κατηγορῶ τῶν καθεστώτων.", "st": "7.71"}, {"sp": "N", "t": "ἐγὼ δὲ καὶ τῶν ἰδιωτῶν τοὺς ὀλίγα μὲν κατορθοῦντας πολλὰ δ’ ἐξαμαρτάνοντας μέμφομαι καὶ νομίζω φαυλοτέρους εἶναι τοῦ δέοντος, καὶ πρός γε τούτοις τοὺς γεγονότας ἐκ καλῶν κἀγαθῶν ἀνδρῶν, καὶ μικρῷ μὲν ὄντας ἐπιεικεστέρους τῶν ὑπερβαλλόντων ταῖς πονηρίαις, πολὺ δὲ χείρους τῶν πατέρων, λοιδορῶ, καὶ συμβουλεύσαιμ’ ἂν αὐτοῖς παύσασθαι τοιούτοις οὖσιν.", "st": "7.72"}, {"sp": "N", "t": "τὴν αὐτὴν οὖν γνώμην ἔχω καὶ περὶ τῶν κοινῶν· ἡγοῦμαι γὰρ δεῖν ἡμᾶς οὐ μέγα φρονεῖν οὐδ’ ἀγαπᾶν, εἰ κακοδαιμονησάντων καὶ μανέντων ἀνθρώπων νομιμώτεροι γεγόναμεν, ἀλλὰ πολὺ μᾶλλον ἀγανακτεῖν καὶ βαρέως φέρειν, εἰ χείρους τῶν προγόνων τυγχάνοιμεν ὄντες· πρὸς γὰρ τὴν ἐκείνων ἀρετὴν ἀλλ’ οὐ πρὸς τὴν τῶν τριάκοντα πονηρίαν ἁμιλλητέον ἡμῖν ἐστιν, ἄλλως τε καὶ προσῆκον ἡμῖν βελτίστοις ἁπάντων ἀνθρώπων εἶναι.", "st": "7.73"}, {"sp": "N", "t": "καὶ τοῦτον εἴρηκα τὸν λόγον οὐ νῦν πρῶτον, ἀλλὰ πολλάκις ἤδη καὶ πρὸς πολλούς. ἐπίσταμαι γὰρ ἐν μὲν τοῖς ἄλλοις τόποις φύσεις ἐγγιγνομένας καρπῶν καὶ δένδρων καὶ ζώων ἰδίας ἐν ἑκάστοις καὶ πολὺ τῶν ἄλλων διαφερούσας, τὴν δ’ ἡμετέραν χώραν ἄνδρας φέρειν καὶ τρέφειν δυναμένην οὐ μόνον πρὸς τὰς τέχνας καὶ τὰς πράξεις καὶ τοὺς λόγους εὐφυεστάτους, ἀλλὰ καὶ πρὸς ἀνδρίαν καὶ πρὸς ἀρετὴν πολὺ διαφέροντας.", "st": "7.74"}, {"sp": "N", "t": "τεκμαίρεσθαι δὲ δίκαιόν ἐστι τοῖς τε παλαιοῖς ἀγῶσιν, οὓς ἐποιήσαντο πρὸς Ἀμαζόνας καὶ Θρᾷκας καὶ Πελοποννησίους ἅπαντας, καὶ τοῖς κινδύνοις τοῖς περὶ τὰ Περσικὰ γενομένοις, ἐν οἷς καὶ μόνοι καὶ μετὰ Πελοποννησίων, καὶ πεζομαχοῦντες καὶ ναυμαχοῦντες, νικήσαντες τοὺς βαρβάρους ἀριστείων ἠξιώθησαν· ὧν οὐδὲν ἂν ἔπραξαν, εἰ μὴ πολὺ τὴν φύσιν διήνεγκαν.", "st": "7.75"}, {"sp": "N", "t": "καὶ μηδεὶς οἰέσθω ταύτην τὴν εὐλογίαν ἡμῖν προσήκειν τοῖς νῦν πολιτευομένοις, ἀλλὰ πολὺ τοὐναντίον. εἰσὶ γὰρ οἱ τοιοῦτοι τῶν λόγων ἔπαινος μὲν τῶν ἀξίους σφᾶς αὐτοὺς τῆς τῶν προγόνων ἀρετῆς παρεχόντων, κατηγορία δὲ τῶν τὰς εὐγενείας ταῖς αὑτῶν ῥᾳθυμίαις καὶ κακίαις καταισχυνόντων. ὅπερ ἡμεῖς ποιοῦμεν· εἰρήσεται γὰρ τἀληθές. τοιαύτης γὰρ ἡμῖν τῆς φύσεως ὑπαρχούσης, οὐ διεφυλάξαμεν αὐτήν, ἀλλ’ ἐμπεπτώκαμεν εἰς ἄνοιαν καὶ ταραχὴν καὶ πονηρῶν πραγμάτων ἐπιθυμίαν.", "st": "7.76"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἢν ἐπακολουθῶ τοῖς ἐνοῦσιν ἐπιτιμῆσαι καὶ κατηγορῆσαι τῶν ἐνεστώτων πραγμάτων, δέδοικα μὴ πόρρω λίαν τῆς ὑποθέσεως ἀποπλανηθῶ. περὶ μὲν οὖν τούτων καὶ πρότερον εἰρήκαμεν, καὶ πάλιν ἐροῦμεν, ἢν μὴ πείσωμεν ὑμᾶς παύσασθαι τοιαῦτ’ ἐξαμαρτάνοντας· περὶ δ’ ὧν ἐξ ἀρχῆς τὸν λόγον κατεστησάμην, βραχέα διαλεχθεὶς παραχωρῶ τοῖς βουλομένοις ἔτι συμβουλεύειν περὶ τούτων.", "st": "7.77"}, {"sp": "N", "t": "ἡμεῖς γὰρ ἢν μὲν οὕτως οἰκῶμεν τὴν πόλιν ὥσπερ νῦν, οὐκ ἔστιν ὅπως οὐ καὶ βουλευσόμεθα καὶ πολεμήσομεν καὶ βιωσόμεθα καὶ σχεδὸν ἅπαντα καὶ πεισόμεθα καὶ πράξομεν, ἅπερ ἐν τῷ παρόντι καιρῷ καὶ τοῖς παρελθοῦσι χρόνοις· ἢν δὲ μεταβάλωμεν τὴν πολιτείαν, δῆλον ὅτι κατὰ τὸν αὐτὸν λόγον, οἷά περ ἦν τοῖς προγόνοις τὰ πράγματα, τοιαῦτ’ ἔσται καὶ περὶ ἡμᾶς· ἀνάγκη γὰρ ἐκ τῶν αὐτῶν πολιτευμάτων καὶ τὰς πράξεις ὁμοίας ἀεὶ καὶ παραπλησίας ἀποβαίνειν.", "st": "7.78"}, {"sp": "N", "t": "δεῖ δὲ τὰς μεγίστας αὐτῶν παρ’ ἀλλήλας θέντας βουλεύσασθαι, ποτέρας ἡμῖν αἱρετέον ἐστίν. καὶ πρῶτον μὲν σκεψώμεθα τοὺς Ἕλληνας καὶ τοὺς βαρβάρους, πῶς πρὸς ἐκείνην τὴν πολιτείαν διέκειντο καὶ πῶς νῦν ἔχουσι πρὸς ἡμᾶς. οὐ γὰρ ἐλάχιστον μέρος τὰ γένη ταῦτα συμβάλλεται πρὸς εὐδαιμονίαν,", "st": "7.79"}, {"sp": "N", "t": "ὅταν ἔχῃ κατὰ τρόπον ἡμῖν. οἱ μὲν τοίνυν Ἕλληνες οὕτως ἐπίστευον τοῖς κατ’ ἐκεῖνον τὸν χρόνον πολιτευομένοις, ὥστε τοὺς πλείστους αὐτῶν ἑκόντας ἐγχειρίσαι τῇ πόλει σφᾶς αὐτούς· οἱ δὲ βάρβαροι τοσοῦτον ἀπεῖχον τοῦ πολυπραγμονεῖν περὶ τῶν Ἑλληνικῶν πραγμάτων, ὥστε οὔτε μακροῖς πλοίοις ἐπὶ τάδε Φασήλιδος ἔπλεον οὔτε στρατοπέδοις ἐντὸς Ἅλυος ποταμοῦ κατέβαινον,", "st": "7.80"}, {"sp": "N", "t": "ἀλλὰ πολλὴν ἡσυχίαν ἦγον. νῦν δ’ εἰς τοῦτο τὰ πράγματα περιέστηκεν, ὥσθ’ οἱ μὲν μισοῦσι τὴν πόλιν, οἱ δὲ καταφρονοῦσιν ἡμῶν· καὶ περὶ μὲν τοῦ μίσους τῶν Ἑλλήνων αὐτῶν ἀκηκόατε τῶν στρατηγῶν· ὡς δὲ βασιλεὺς ἔχει πρὸς ἡμᾶς, ἐκ τῶν ἐπιστολῶν ὧν ἔπεμψεν ἐδήλωσεν.", "st": "7.81"}, {"sp": "N", "t": "ἔτι πρὸς τούτοις ὑπὸ μὲν ἐκείνης τῆς εὐταξίας οὕτως ἐπαιδεύθησαν οἱ πολῖται πρὸς ἀρετήν, ὥστε σφᾶς μὲν αὐτοὺς μὴ λυπεῖν, τοὺς δ’ εἰς τὴν χώραν εἰσβάλλοντας ἅπαντας μαχόμενοι νικᾶν. ἡμεῖς δὲ τοὐναντίον· ἀλλήλοις μὲν γὰρ κακὰ παρέχοντες οὐδεμίαν ἡμέραν διαλείπομεν, τῶν δὲ περὶ τὸν πόλεμον οὕτω κατημελήκαμεν, ὥστ’ οὐδ’ εἰς ἐξετάσεις ἰέναι τολμῶμεν ἢν μὴ λαμβάνωμεν ἀργύριον.", "st": "7.82"}, {"sp": "N", "t": "τὸ δὲ μέγιστον· τότε μὲν οὐδεὶς ἦν τῶν πολιτῶν ἐνδεὴς τῶν ἀναγκαίων, οὐδὲ προσαιτῶν τοὺς ἐντυγχάνοντας τὴν πόλιν κατῄσχυνε, νῦν δὲ πλείους εἰσὶν οἱ σπανίζοντες τῶν ἐχόντων· οἷς ἄξιόν ἐστι πολλὴν συγγνώμην ἔχειν, εἰ μηδὲν τῶν κοινῶν φροντίζουσιν, ἀλλὰ τοῦτο σκοποῦσιν ὁπόθεν τὴν ἀεὶ παροῦσαν ἡμέραν διάξουσιν.", "st": "7.83"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ἡγούμενος, ἢν μιμησώμεθα τοὺς προγόνους, καὶ τῶν κακῶν ἡμᾶς τούτων ἀπαλλαγήσεσθαι καὶ σωτῆρας οὐ μόνον τῆς πόλεως ἀλλὰ καὶ τῶν Ἐλλήνων ἁπάντων γενήσεσθαι, τήν τε πρόσοδον ἐποιησάμην καὶ τοὺς λόγους εἴρηκα τούτους· ὑμεῖς δὲ πάντα λογισάμενοι ταῦτα χειροτονεῖθ’ ὅ τι ἂν ὑμῖν δοκῇ μάλιστα συμφέρειν τῇ πόλει.", "st": "7.84"}, {"sp": "HDR", "t": "Κατὰ τῶν σοφιστῶν", "st": "13"}, {"sp": "N", "t": "εἰ πάντες ἤθελον οἱ παιδεύειν ἐπιχειροῦντες ἀληθῆ λέγειν, καὶ μὴ μείζους ποιεῖσθαι τὰς ὑποσχέσεις ὧν ἔμελλον ἐπιτελεῖν, οὐκ ἂν κακῶς ἤκουον ὑπὸ τῶν ἰδιωτῶν· νῦν δ’ οἱ τολμῶντες λίαν ἀπερισκέπτως ἀλαζονεύεσθαι πεποιήκασιν ὥστε δοκεῖν ἄμεινον βουλεύεσθαι τοὺς ῥᾳθυμεῖν αἱρουμένους τῶν περὶ τὴν φιλοσοφίαν διατριβόντων. τίς γὰρ οὐκ ἃν μισήσειεν ἅμα καὶ καταφρονήσειε πρῶτον μὲν τῶν περὶ τὰς ἔριδας διατριβόντων, οἳ προσποιοῦνται μὲν τὴν ἀλήθειαν ζητεῖν, εὐθὺς δ’ ἐν ἀρχῇ τῶν ἐπαγγελμάτων ψευδῆ λέγειν ἐπιχειροῦσιν;", "st": "13.1"}, {"sp": "N", "t": "οἶμαι γὰρ ἅπασιν εἶναι φανερὸν ὅτι τὰ μέλλοντα προγιγνώσκειν οὐ τῆς ἡμετέρας φύσεώς ἐστιν, ἀλλὰ τοσοῦτον ἀπέχομεν ταύτης τῆς φρονήσεως, ὥσθ’ Ὅμηρος ὁ μεγίστην ἐπὶ σοφίᾳ δόξαν εἰληφὼς καὶ τοὺς θεοὺς πεποίηκεν ἔστιν ὅτε βουλευομένους ὑπὲρ αὐτῶν, οὐ τὴν ἐκείνων γνώμην εἰδώς, ἀλλ’ ἡμῖν ἐνδείξασθαι βουλόμενος ὅτι τοῖς ἀνθρώποις ἓν τοῦτο τῶν ἀδυνάτων ἐστίν.", "st": "13.2"}, {"sp": "N", "t": "οὗτοι τοίνυν εἰς τοῦτο τόλμης ἐληλύθασιν, ὥστε πειρῶνται πείθειν τοὺς νεωτέρους ὡς, ἢν αὐτοῖς πλησιάζωσιν, ἅ τε πρακτέον ἐστὶν εἴσονται καὶ διὰ ταύτης τῆς ἐπιστήμης εὐδαίμονες γενήσονται. καὶ τηλικούτων ἀγαθῶν αὑτοὺς διδασκάλους καὶ κυρίους καταστήσαντες, οὐκ αἰσχύνονται τρεῖς ἢ τέτταρας μνᾶς ὑπὲρ τούτων αἰτοῦντες.", "st": "13.3"}, {"sp": "N", "t": "ἀλλ’ εἰ μέν τι τῶν ἄλλων κτημάτων πολλοστοῦ μέρους τῆς ἀξίας ἐπώλουν, οὐκ ἂν ἠμφεσβήτησαν ὡς εὖ φρονοῦντες τυγχάνουσι, σύμπασαν δὲ τὴν ἀρετὴν καὶ τὴν εὐδαιμονίαν οὕτως ὀλίγου τιμῶντες, ὡς νοῦν ἔχοντες διδάσκαλοι τῶν ἄλλων ἀξιοῦσι γίγνεσθαι. καὶ λέγουσι μὲν ὡς οὐδὲν δέονται χρημάτων, ἀργυρίδιον καὶ χρυσίδιον τὸν πλοῦτον ἀποκαλοῦντες, μικροῦ δὲ κέρδους ὀρεγόμενοι μόνον οὐκ ἀθανάτους ὑπισχνοῦνται τοὺς συνόντας ποιήσειν.", "st": "13.4"}, {"sp": "N", "t": "ὃ δὲ πάντων καταγελαστότατον, ὅτι παρὰ μὲν ὧν δεῖ λαβεῖν αὐτούς, τούτοις μὲν ἀπιστοῦσιν, οἷς μέλλουσι τὴν δικαιοσύνην παραδώσειν, ὧν δ’ οὐδεπώποτε διδάσκαλοι γεγόνασι, παρὰ τούτοις τὰ παρὰ τῶν μαθητῶν μεσεγγυοῦνται, πρὸς μὲν τὴν ἀσφάλειαν εὖ βουλευόμενοι, τῷ δ’ ἐπαγγέλματι τἀναντία πράττοντες.", "st": "13.5"}, {"sp": "N", "t": "τοὺς μὲν γὰρ ἄλλο τι παιδεύοντας προσήκει διακριβοῦσθαι περὶ τῶν διαφερόντων, οὐδὲν γὰρ κωλύει τοὺς περὶ ἕτερα δεινοὺς γενομένους μὴ χρηστοὺς εἶναι περὶ τὰ συμβόλαια· τοὺς δὲ τὴν ἀρετὴν καὶ τὴν σωφροσύνην ἐνεργαζομένους πῶς οὐκ ἄλογόν ἐστι μὴ τοῖς μαθηταῖς μάλιστα πιστεύειν; οὐ γὰρ δή που περὶ τοὺς ἄλλους ὄντες καλοὶ κἀγαθοὶ καὶ δίκαιοι περὶ τούτους ἐξαμαρτήσονται, δι’ οὓς τοιοῦτοι γεγόνασιν.", "st": "13.6"}, {"sp": "N", "t": "ἐπειδὰν οὖν τῶν ἰδιωτῶν τινες, ἅπαντα ταῦτα συλλογισάμενοι, κατίδωσι τοὺς τὴν σοφίαν διδάσκοντας καὶ τὴν εὐδαιμονίαν παραδιδόντας αὐτούς τε πολλῶν δεομένους καὶ τοὺς μαθητὰς μικρὸν πραττομένους, καὶ τὰς ἐναντιώσεις ἐπὶ μὲν τῶν λόγων τηροῦντας, ἐπὶ δὲ τῶν ἔργων μὴ καθορῶντας, ἔτι δὲ περὶ μὲν τῶν μελλόντων εἰδέναι προσποιουμένους,", "st": "13.7"}, {"sp": "N", "t": "περὶ δὲ τῶν παρόντων μηδὲν τῶν δεόντων μήτ’ εἰπεῖν μήτε συμβουλεῦσαι δυναμένους, ἀλλὰ μᾶλλον ὁμονοοῦντας καὶ πλείω κατορθοῦντας τοὺς ταῖς δόξαις χρωμένους ἢ τοὺς τὴν ἐπιστήμην ἔχειν ἐπαγγελλομένους, εἰκότως οἶμαι καταφρονοῦσι, καὶ νομίζουσιν ἀδολεσχίαν καὶ μικρολογίαν ἀλλ’ οὐ τῆς ψυχῆς ἐπιμέλειαν εἶναι τὰς τοιαύτας διατριβάς.", "st": "13.8"}, {"sp": "N", "t": "οὐ μόνον δὲ τούτοις ἀλλὰ καὶ τοῖς τοὺς πολιτικοὺς λόγους ὑπισχνουμένοις ἄξιον ἐπιτιμῆσαι καὶ γὰρ ἐκεῖνοι τῆς μὲν ἀληθείας οὐδὲν φροντίζουσιν, ἡγοῦνται δὲ τοῦτ’ εἶναι τὴν τέχνην, ἢν ὡς πλείστους τῇ μικρότητι τῶν μισθῶν καὶ τῷ μεγέθει τῶν ἐπαγγελμάτων προσαγάγωνται καὶ λαβεῖν τι παρ’ αὐτῶν δυνηθῶσιν· οὕτω δ’ ἀναισθήτως αὐτοί τε διάκεινται καὶ τοὺς ἄλλους ἔχειν ὑπειλήφασιν, ὥστε χεῖρον γράφοντες τοὺς λόγους ἢ τῶν ἰδιωτῶν τινες αὐτοσχεδιάζουσιν, ὅμως ὑπισχνοῦνται τοιούτους ῥήτορας τοὺς συνόντας ποιήσειν ὥστε μηδὲν τῶν ἐνόντων ἐν τοῖς πράγμασι παραλιπεῖν.", "st": "13.9"}, {"sp": "N", "t": "καὶ ταύτης τῆς δυνάμεως οὐδὲν οὔτε ταῖς ἐμπειρίαις οὔτε τῇ φύσει τῇ τοῦ μαθητοῦ μεταδιδόασιν, ἀλλά φασιν ὁμοίως τὴν τῶν λόγων ἐπιστήμην ὥσπερ τὴν τῶν γραμμάτων παραδώσειν, ὡς μὲν ἔχει τούτων ἑκάτερον, οὐκ ἐξετάσαντες, οἰόμενοι δὲ διὰ τὰς ὑπερβολὰς τῶν ἐπαγγελμάτων αὐτοί τε θαυμασθήσεσθαι καὶ τὴν παίδευσιν τὴν τῶν λόγων πλέονος ἀξίαν δόξειν εἶναι, κακῶς εἰδότες ὅτι μεγάλας ποιοῦσι τὰς τέχνας οὐχ οἱ τολμῶντες ἀλαζονεύεσθαι περὶ αὐτῶν, ἀλλ’ οἵτινες ἄν, ὅσον ἔνεστιν ἐν ἑκάστῃ, τοῦτ’ ἐξευρεῖν δυνηθῶσιν.", "st": "13.10"}, {"sp": "N", "t": "ἐγὼ δὲ πρὸ πολλῶν μὲν ἂν χρημάτων ἐτιμησάμην τηλικοῦτον δύνασθαι τὴν φιλοσοφίαν, ὅσον οὗτοι λέγουσιν, ἴσως γὰρ οὐκ ἂν ἡμεῖς πλεῖστον ἀπελείφθημεν, οὐδ’ ἂν ἐλάχιστον μέρος ἀπελαύσαμεν αὐτῆς· ἐπειδὴ δ’ οὐχ οὕτως ἔχει, βουλοίμην ἂν παύσασθαι τοὺς φλυαροῦντας· ὁρῶ γὰρ οὐ μόνον περὶ τοὺς ἐξαμαρτάνοντας τὰς βλασφημίας γιγνομένας, ἀλλὰ καὶ τοὺς ἄλλους ἅπαντας συνδιαβαλλομένους τοὺς περὶ τὴν αὐτὴν διατριβὴν ὄντας.", "st": "13.11"}, {"sp": "N", "t": "θαυμάζω δ’ ὅταν ἴδω τούτους μαθητῶν ἀξιουμένους, οἳ ποιητικοῦ πράγματος τεταγμένην τέχνην παράδειγμα φέροντες λελήθασι σφᾶς αὐτούς. τίς γὰρ οὐκ οἶδε πλὴν τούτων ὅτι τὸ μὲν τῶν γραμμάτων ἀκινήτως ἔχει καὶ μένει κατὰ ταὐτόν, ὥστε τοῖς αὐτοῖς ἀεὶ περὶ τῶν αὐτῶν χρώμενοι διατελοῦμεν, τὸ δὲ τῶν λόγων πᾶν τοὐναντίον πέπονθεν· τὸ γὰρ ὑφ’ ἑτέρου ῥηθὲν τῷ λέγοντι μετ’ ἐκεῖνον οὐχ ὁμοίως χρήσιμόν ἐστιν, ἀλλ’ οὗτος εἶναι δοκεῖ τεχνικώτατος, ὅς τις ἂν ἀξίως μὲν λέγῃ τῶν πραγμάτων, μηδὲν δὲ τῶν αὐτῶν τοῖς ἄλλοις εὑρίσκειν δύνηται.", "st": "13.12"}, {"sp": "N", "t": "μέγιστον δὲ σημεῖον τῆς ἀνομοιότητος αὐτῶν· τοὺς μὲν γὰρ λόγους οὐχ οἷόν τε καλῶς ἔχειν, ἢν μὴ τῶν καιρῶν καὶ τοῦ πρεπόντως καὶ τοῦ καινῶς ἔχειν μετάσχωσιν, τοῖς δὲ γράμμασιν οὐδενὸς τούτων προσεδέησεν. ὥσθ’ οἱ χρώμενοι τοῖς τοιούτοις παραδείγμασι πολὺ ἂν δικαιότερον ἀποτίνοιεν ἢ λαμβάνοιεν ἀργύριον, ὅτι πολλῆς ἐπιμελείας αὐτοὶ δεόμενοι παιδεύειν τοὺς ἄλλους ἐπιχειροῦσιν.", "st": "13.13"}, {"sp": "N", "t": "εἰ δὲ δεῖ μὴ κατηγορεῖν τῶν ἄλλων ἀλλὰ καὶ τὴν ἐμαυτοῦ δηλῶσαι διάνοιαν, ἡγοῦμαι πάντας ἄν μοι τοὺς εὖ φρονοῦντας συνειπεῖν ὅτι πολλοὶ μὲν τῶν φιλοσοφησάντων ἰδιῶται διετέλεσαν ὄντες, ἄλλοι δέ τινες οὐδενὶ πώποτε συγγενόμενοι τῶν σοφιστῶν καὶ λέγειν καὶ πολιτεύεσθαι δεινοὶ γεγόνασιν. αἱ μὲν γὰρ δυνάμεις καὶ τῶν λόγων καὶ τῶν ἄλλων ἔργων ἁπάντων ἐν τοῖς εὐφυέσιν ἐγγίγνονται καὶ τοῖς περὶ τὰς ἐμπειρίας γεγυμνασμένοις·", "st": "13.14"}, {"sp": "N", "t": "ἡ δὲ παίδευσις τοὺς μὲν τοιούτους τεχνικωτέρους καὶ πρὸς τὸ ζητεῖν εὐπορωτέρους ἐποίησεν, οἷς γὰρ νῦν ἐντυγχάνουσι πλανώμενοι, ταῦτ’ ἐξ ἑτοιμοτέρου λαμβάνειν αὐτοὺς ἐδίδαξεν, τοὺς δὲ καταδεεστέραν τὴν φύσιν ἔχοντας ἀγωνιστὰς μὲν ἀγαθοὺς ἢ λόγων ποιητὰς οὐκ ἂν ἀποτελέσειεν, αὐτοὺς δ’ ἂν αὑτῶν προαγάγοι καὶ πρὸς πολλὰ φρονιμωτέρως διακεῖσθαι ποιήσειεν.", "st": "13.15"}, {"sp": "N", "t": "βούλομαι δ’, ἐπειδή περ εἰς τοῦτο προῆλθον, ἔτι σαφέστερον εἰπεῖν περὶ αὐτῶν. φημὶ γὰρ ἐγὼ τῶν μὲν ἰδεῶν, ἐξ ὧν τοὺς λόγους ἅπαντας καὶ λέγομεν καὶ συντίθεμεν, λαβεῖν τὴν ἐπιστήμην οὐκ εἶναι τῶν πάνυ χαλεπῶν, ἤν τις αὑτὸν παραδῷ μὴ τοῖς ῥᾳδίως ὑπισχνουμένοις ἀλλὰ τοῖς εἰδόσι τι περὶ αὐτῶν· τὸ δὲ τούτων ἐφ’ ἑκάστῳ τῶν πραγμάτων ἃς δεῖ προελέσθαι καὶ μῖξαι πρὸς ἀλλήλας καὶ τάξαι κατὰ τρόπον, ἔτι δὲ τῶν καιρῶν μὴ διαμαρτεῖν, ἀλλὰ καὶ τοῖς ἐνθυμήμασι πρεπόντως ὅλον τὸν λόγον καταποικῖλαι καὶ τοῖς ὀνόμασιν εὐρύθμως καὶ μουσικῶς εἰπεῖν,", "st": "13.16"}, {"sp": "N", "t": "ταῦτα δὲ πολλῆς ἐπιμελείας δεῖσθαι καὶ ψυχῆς ἀνδρικῆς καὶ δοξαστικῆς ἔργον εἶναι, καὶ δεῖν τὸν μὲν μαθητὴν πρὸς τῷ τὴν φύσιν ἔχειν οἵαν χρὴ τὰ μὲν εἴδη τὰ τῶν λόγων μαθεῖν, περὶ δὲ τὰς χρήσεις αὐτῶν γυμνασθῆναι, τὸν δὲ διδάσκαλον τὰ μὲν οὕτως ἀκριβῶς οἷόν τ’ εἶναι διελθεῖν ὥστε μηδὲν τῶν διδακτῶν παραλιπεῖν, περὶ δὲ τῶν λοιπῶν τοιοῦτον αὑτὸν παράδειγμα παρασχεῖν,", "st": "13.17"}, {"sp": "N", "t": "ὥστε τοὺς ἐκτυπωθέντας καὶ μιμήσασθαι δυναμένους εὐθὺς ἀνθηρότερον καὶ χαριέστερον τῶν ἄλλων φαίνεσθαι λέγοντας. καὶ τούτων μὲν ἁπάντων συμπεσόντων τελείως ἕξουσιν οἱ φιλοσοφοῦντες· καθ’ ὃ δ’ ἂν ἐλλειφθῇ τι τῶν εἰρημένων, ἀνάγκη ταύτῃ χεῖρον διακεῖσθαι τοὺς πλησιάζοντας.", "st": "13.18"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄρτι τῶν σοφιστῶν ἀναφυόμενοι καὶ νεωστὶ προσπεπτωκότες ταῖς ἀλαζονείαις, εἰ καὶ νῦν πλεονάζουσιν, εὖ οἶδ’ ὅτι πάντες ἐπὶ ταύτην κατενεχθήσονται τὴν ὑπόθεσιν. λοιποὶ δ’ ἡμῖν εἰσιν οἱ πρὸ ἡμῶν γενόμενοι καὶ τὰς καλουμένας τέχνας γράψαι τολμήσαντες, οὓς οὐκ ἀφετέον ἀνεπιτιμήτους· οἵ τινες ὑπέσχοντο δικάζεσθαι διδάξειν, ἐκλεξάμενοι τὸ δυσχερέστατον τῶν ὀνομάτων, ὃ τῶν φθονούντων ἔργον ἦν λέγειν, ἀλλ’ οὐ τῶν προεστώτων τῆς τοιαύτης παιδεύσεως, καὶ ταῦτα τοῦ πράγματος,", "st": "13.19"}, {"sp": "N", "t": "καθ’ ὅσον ἐστὶ διδακτόν, οὐδὲν μᾶλλον πρὸς τοὺς δικανικοὺς λόγους ἢ πρὸς τοὺς ἄλλους ἅπαντας ὠφελεῖν δυναμένου. τοσούτῳ δὲ χείρους ἐγένοντο τῶν περὶ τὰς ἔριδας καλινδουμένων, ὅσον οὗτοι μὲν τοιαῦτα λογίδια διεξιόντες, οἷς εἴ τις ἐπὶ τῶν πράξεων ἐμμείνειεν εὐθὺς ἂν ἐν πᾶσιν εἴη κακοῖς, ὅμως ἀρετὴν ἐπηγγείλαντο καὶ σωφροσύνην περὶ αὐτῶν, ἐκεῖνοι δ’ ἐπὶ τοὺς πολιτικοὺς λόγους, παρακαλοῦντες, ἀμελήσαντες τῶν ἄλλων τῶν προσόντων αὐτοῖς ἀγαθῶν, πολυπραγμοσύνης καὶ πλεονεξίας ὑπέστησαν εἶναι διδάσκαλοι.", "st": "13.20"}, {"sp": "N", "t": "καίτοι τοὺς βουλομένους πειθαρχεῖν τοῖς ὑπὸ τῆς φιλοσοφίας ταύτης προσταττομένοις πολὺ ἂν θᾶττον πρὸς ἐπιείκειαν ἢ πρὸς ῥητορείαν ὠφελήσειεν. καὶ μηδεὶς οἰέσθω με λέγειν ὡς ἔστι δικαιοσύνη διδακτόν· ὅλως μὲν γὰρ οὐδεμίαν ἡγοῦμαι τοιαύτην εἶναι τέχνην, ἥτις τοῖς κακῶς πεφυκόσι πρὸς ἀρετὴν σωφροσύνην ἂν καὶ δικαιοσύνην ἐμποιήσειεν· οὐ μὴν ἀλλὰ συμπαρακελεύσασθαί γε καὶ συνασκῆσαι μάλιστ’ ἃ οἶμαι τὴν τῶν λόγων τῶν πολιτικῶν ἐπιμέλειαν.", "st": "13.21"}, {"sp": "N", "t": "ἵνα δὲ μὴ δοκῶ τὰς μὲν τῶν ἄλλων ὑποσχέσεις διαλύειν, αὐτὸς δὲ μείζω λέγειν τῶν ἐνόντων, ἐξ ὧνπερ αὐτὸς ἐπείσθην οὕτω ταῦτ’ ἔχειν, ῥᾳδίως οἶμαι καὶ τοῖς ἄλλοις φανερὸν καταστήσειν.", "st": "13.22"}, {"sp": "HDR", "t": "Περὶ ἀντιδόσεως", "st": "15"}, {"sp": "N", "t": "εἰ μὲν ὅμοιος ἦν ὁ λόγος ὁ μέλλων ἀναγνωσθήσεσθαι τοῖς ἢ πρὸς τοὺς ἀγῶνας ἢ πρὸς τὰς ἐπιδείξεις γιγνομένοις, οὐδὲν ἂν οἶμαι προδιαλεχθῆναι περὶ αὐτοῦ· νῦν δὲ διὰ τὴν καινότητα καὶ τὴν διαφορὰν ἀναγκαῖόν ἐστι προειπεῖν τὰς αἰτίας, δι’ ἃς οὕτως ἀνόμοιον αὐτὸν ὄντα τοῖς ἄλλοις γράφειν προειλόμην· μὴ γὰρ τούτων δηλωθεισῶν πολλοῖς ἂν ἴσως ἄτοπος εἶναι δόξειεν.", "st": "15.1"}, {"sp": "N", "t": "ἐγὼ γὰρ εἰδὼς ἐνίους τῶν σοφιστῶν βλασφημοῦντας περὶ τῆς ἐμῆς διατριβῆς, καὶ λέγοντας ὡς ἔστι περὶ δικογραφίαν, καὶ παραπλήσιον ποιοῦντας ὥσπερ ἂν εἴ τις Φειδίαν τὸν τὸ τῆς Ἀθηνᾶς ἕδος ἐργασάμενον τολμῴη καλεῖν κοροπλάθον, ἢ Ζεῦξιν καὶ Παρράσιον τὴν αὐτὴν ἔχειν φαίη τέχνην τοῖς τὰ πινάκια γράφουσιν, ὅμως οὐδὲ πώποτε τὴν μικρολογίαν ταύτην ἠμυνάμην αὐτῶν,", "st": "15.2"}, {"sp": "N", "t": "ἡγούμενος τὰς μὲν ἐκείνων φλυαρίας οὐδεμίαν δύναμιν ἔχειν, αὐτὸς δὲ πᾶσι τοῦτο πεποιηκέναι φανερόν, ὅτι προῄρημαι καὶ λέγειν καὶ γράφειν οὐ περὶ τῶν ἰδίων συμβολαίων, ἀλλ’ ὑπὲρ τηλικούτων τὸ μέγεθος καὶ τοιούτων πραγμάτων, ὑπὲρ ὧν οὐδεὶς ἂν ἄλλος ἐπιχειρήσειε, πλὴν τῶν ἐμοὶ πεπλησιακότων ἢ τῶν τούτους μιμεῖσθαι βουλομένων.", "st": "15.3"}, {"sp": "N", "t": "μέχρι μὲν οὖν πόρρω τῆς ἡλικίας ᾠόμην καὶ διὰ τὴν προαίρεσιν ταύτην καὶ διὰ τὴν ἄλλην ἀπραγμοσύνην ἐπιεικῶς ἔχειν πρὸς ἅπαντας τοὺς ἰδιώτας· ἤδη δ’ ὑπογυίου μοι τῆς τοῦ βίου τελευτῆς οὔσης, ἀντιδόσεως γενομένης περὶ τριηραρχίας καὶ περὶ ταύτης ἀγῶνος ἔγνων καὶ τούτων τινὰς οὐχ οὕτω πρός με διακειμένους ὥσπερ ἤλπιζον, ἀλλὰ τοὺς μὲν πολὺ διεψευσμένους τῶν ἐμῶν ἐπιτηδευμάτων καὶ ῥέποντας ἐπὶ τὸ πείθεσθαι τοῖς ἀνεπιτήδειόν τι λέγουσι, τοὺς δὲ σαφῶς μὲν εἰδότας περὶ ἃ τυγχάνω διατρίβων, φθονοῦντας δὲ καὶ ταὐτὸν πεπονθότας τοῖς σοφισταῖς καὶ χαίροντας ἐπὶ τοῖς Ψευδῆ περί μου δόξαν ἔχουσιν.", "st": "15.4"}, {"sp": "N", "t": "ἐδήλωσαν δ’ οὕτω διακείμενοι· τοῦ γὰρ ἀντιδίκου περὶ μὲν ὧν ἡ κρίσις ἦν οὐδὲν λέγοντος δίκαιον, διαβάλλοντος δὲ τὴν τῶν λόγων τῶν ἐμῶν δύναμιν καὶ καταλαζονευομένου περί τε τοῦ πλούτου καὶ τοῦ πλήθους τῶν μαθητῶν, ἔγνωσαν ἐμὴν εἶναι τὴν λειτουργίαν. τὴν μὲν οὖν δαπάνην οὕτως ἠνέγκαμεν, ὥσπερ προσήκει τοὺς μήτε λίαν ὑπὸ τῶν τοιούτων ἐκταραττομένους μήτε παντάπασιν ἀσώτως μηδ’ ὀλιγώρως πρὸς χρήματα διακειμένους·", "st": "15.5"}, {"sp": "N", "t": "ᾐσθημένος δ’ ὥσπερ εἶπον πλείους ὄντας ὧν ᾠόμην τοὺς οὐκ ὀρθῶς περί μου γιγνώσκοντας, ἐνεθυμούμην πῶς ἂν δηλώσαιμι καὶ τούτοις καὶ τοῖς ἐπιγιγνομένοις καὶ τὸν τρόπον ὃν ἔχω καὶ τὸν βίον ὃν ζῶ καὶ τὴν παιδείαν περὶ ἣν διατρίβω, καὶ μὴ περιίδοιμι περὶ τῶν τοιούτων ἄκριτον ἐμαυτὸν ὄντα, μηδ’ ἐπὶ τοῖς βλασφημεῖν εἰθισμένοις ὥσπερ νῦν γενόμενον.", "st": "15.6"}, {"sp": "N", "t": "σκοπούμενος οὖν εὕρισκον οὐδαμῶς ἂν ἄλλως τοῦτο διαπραξόμενος, πλὴν εἰ γραφείη λόγος ὥσπερ εἰκὼν τῆς ἐμῆς διανοίας καὶ τῶν ἄλλων τῶν ἐμοὶ βεβιωμένων· διὰ τούτου γὰρ ἤλπιζον καὶ τὰ περὶ ἐμὲ μάλιστα γνωσθήσεσθαι, καὶ τὸν αὐτὸν τοῦτον μνημεῖόν μου καταλειφθήσεσθαι πολὺ κάλλιον τῶν χαλκῶν ἀναθημάτων.", "st": "15.7"}, {"sp": "N", "t": "εἰ μὲν οὖν ἐπαινεῖν ἐμαυτὸν ἐπιχειροίην, ἑώρων οὔτε περιλαβεῖν ἅπαντα περὶ ὧν διελθεῖν προῃρούμην οἷός τε γενησόμενος, οὔτ’ ἐπιχαρίτως οὐδ’ ἀνεπιφθόνως εἰπεῖν περὶ αὐτῶν δυνησόμενος· εἰ δ’ ὑποθείμην ἀγῶνα μὲν καὶ κίνδυνόν τινα περὶ ἐμὲ γιγνόμενον, συκοφάντην δ’ ὄντα τὸν γεγραμμένον καὶ τὸν πράγματά μοι παρέχοντα, κἀκεῖνον μὲν ταῖς διαβολαῖς χρώμενον ταῖς ἐπὶ τῆς ἀντιδόσεως ῥηθείσαις, ἐμαυτὸν δ’ ἐν ἀπολογίας σχήματι τοὺς λόγους ποιούμενον, οὕτως ἂν ἐκγενέσθαι μοι μάλιστα διαλεχθῆναι περὶ ἁπάντων ὧν τυγχάνω βουλόμενος.", "st": "15.8"}, {"sp": "N", "t": "ταῦτα δὲ διανοηθεὶς ἔγραφον τὸν λόγον τοῦτον, οὐκ ἀκμάζων, ἀλλ’ ἔτη γεγονὼς δύο καὶ ὀγδοήκοντα. διόπερ χρὴ συγγνώμην ἔχειν, ἢν μαλακώτερος ὢν φαίνηται τῶν παρ’ ἐμοῦ πρότερον ἐκδεδομένων. καὶ γὰρ οὐδὲ ῥᾴδιος ἦν οὐδ’ ἁπλοῦς, ἀλλὰ πολλὴν ἔχων πραγματείαν.", "st": "15.9"}, {"sp": "N", "t": "ἔστι γὰρ τῶν γεγραμμένων ἔνια μὲν ἐν δικαστηρίῳ πρέποντα ῥηθῆναι, τὰ δὲ πρὸς μὲν τοὺς τοιούτους ἀγῶνας οὐχ ἁρμόττοντα, περὶ δὲ φιλοσοφίας πεπαρρησιασμένα καὶ δεδηλωκότα τὴν δύναμιν αὐτῆς· ἔστι δέ τι καὶ τοιοῦτον ὃ τῶν νεωτέρων τοῖς ἐπὶ τὰ μαθήματα καὶ τὴν παιδείαν ὁρμῶσιν ἀκούσασιν ἂν συνενέγκοι, πολλὰ δὲ καὶ τῶν ὑπ’ ἐμοῦ πάλαι γεγραμμένων ἐγκαταμεμιγμένα τοῖς νῦν λεγομένοις οὐκ ἀλόγως οὐδ’ ἀκαίρως, ἀλλὰ προσηκόντως τοῖς ὑποκειμένοις.", "st": "15.10"}, {"sp": "N", "t": "τοσοῦτον οὖν μῆκος λόγου συνιδεῖν, καὶ τοσαύτας ἰδέας καὶ τοσοῦτον ἀλλήλων ἀφεστώσας συναρμόσαι καὶ συναγαγεῖν, καὶ τὰς ἐπιφερομένας οἰκειῶσαι ταῖς προειρημέναις, καὶ πάσας ποιῆσαι σφίσιν αὐταῖς ὁμολογουμένας, οὐ πάνυ μικρὸν ἦν ἔργον. ὅμως δ’ οὐκ ἀπέστην, καίπερ τηλικοῦτος ὤν. πρὶν αὐτὸν ἀπετέλεσα, μετὰ πολλῆς μὲν ἀληθείας εἰρημένον, τὰ δ’ ἄλλα τοιοῦτον οἷος ἂν εἶναι δόξη τοῖς ἀκροωμένοις.", "st": "15.11"}, {"sp": "N", "t": "χρὴ δὲ τοὺς διεξιόντας αὐτὸν πρῶτον μὲν ὡς ὄντος μικτοῦ τοῦ λόγου καὶ πρὸς ἁπάσας τὰς ὑποθέσεις ταύτας γεγραμμένου ποιεῖσθαι τὴν ἀκρόασιν, ἔπειτα προσέχειν τὸν νοῦν ἔτι μᾶλλον τοῖς λέγεσθαι μέλλουσιν ἢ τοῖς ἤδη προειρημένοις, πρὸς δὲ τούτοις μὴ ζητεῖν εὐθὺς ἐπελθόντας ὅλον αὐτὸν διελθεῖν, ἀλλὰ τοσοῦτον μέρος ὅσον μὴ λυπήσει τοὺς παρόντας. ἐὰν γὰρ ἐμμείνητε τούτοις, μᾶλλον δυνήσεσθε κατιδεῖν εἴ τι τυγχάνομεν λέγοντες ἄξιον ἡμῶν αὐτῶν.", "st": "15.12"}, {"sp": "N", "t": "ἃ μὲν οὖν ἀναγκαῖον ἦν προειπεῖν, ταῦτ’ ἐστίν· ἤδη δ’ ἀναγιγνώσκετε τὴν ἀπολογίαν τὴν προσποιουμένην μὲν περὶ κρίσεως γεγράφθαι, βουλομένην δὲ περὶ ἐμοῦ δηλῶσαι τὴν ἀλήθειαν, καὶ τοὺς μὲν ἀγνοοῦντας εἰδέναι ποιῆσαι, τοὺς δὲ φθονοῦντας ἔτι μᾶλλον ὑπὸ τῆς νόσου ταύτης λυπεῖσθαι· μείζω γὰρ δίκην οὐκ ἂν δυναίμην λαβεῖν παρ’ αὐτῶν.", "st": "15.13"}, {"sp": "N", "t": "πάντων ἡγοῦμαι πονηροτάτους εἶναι καὶ μεγίστης ζημίας ἀξίους, οἵτινες οἷς αὐτοὶ τυγχάνουσιν ὄντες ἔνοχοι, ταῦτα τῶν ἄλλων τολμῶσι κατηγορεῖν· ὅπερ Λυσίμαχος πεποίηκεν. οὗτος γὰρ αὐτὸς συγγεγραμμένα λέγων περὶ τῶν ἐμῶν συγγραμμάτων πλείω πεποίηται λόγον ἢ περὶ τῶν ἄλλων ἁπάντων, ὅμοιον ἐργαζόμενος ὥσπερ ἂν εἴ τις ἱεροσυλίας ἕτερον διώκων αὐτὸς τὰ τῶν θεῶν ἐν τοῖν χεροῖν ἔχων φανείη.", "st": "15.14"}, {"sp": "N", "t": "πρὸ πολλοῦ δ’ ἂν ἐποιησάμην οὕτως αὐτὸν νομίζειν εἶναί με δεινόν, ὥσπερ ἐν ὑμῖν εἴρηκεν· οὐ γὰρ ἄν ποτέ μοι πράγματα ποιεῖν ἐπεχείρησε. νῦν δὲ λέγει μὲν ὡς ἐγὼ τοὺς ἥττους λόγους κρείττους δύναμαι ποιεῖν, τοσοῦτον δέ μου καταπεφρόνηκεν, ὥστε αὐτὸς ψευδόμενος ἐμοῦ τἀληθῆ λέγοντος ἐλπίζει ῥᾳδίως ἐπικρατήσειν.", "st": "15.15"}, {"sp": "N", "t": "οὕτω δέ μοι δυσκόλως ἅπαντα συμβέβηκεν, ὥσθ’ οἱ μὲν ἄλλοι τοῖς λόγοις διαλύονται τὰς διαβολάς, ἐμοῦ δὲ Λυσίμαχος αὐτοὺς τοὺς λόγους μάλιστα διαβέβληκεν, ἵν’ ἢν μὲν ἱκανῶς δόξω λέγειν, ἔνοχος ὢν φανῶ τοῖς ὑπὸ τούτου περὶ τῆς δεινότητος τῆς ἐμῆς προειρημένοις, ἢν δ’ ἐνδεέστερον τύχω διαλεχθεὶς ὧν οὗτος ὑμᾶς προσδοκᾶν πεποίηκε, τὰς πράξεις ἡγῆσθέ μου χείρους εἶναι.", "st": "15.16"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν μήτε πιστεύειν πω μήτ’ ἀπιστεῖν τοῖς εἰρημένοις, πρὶν ἂν διὰ τέλους ἀκούσητε καὶ τὰ παρ’ ἡμῶν, ἐνθυμουμένους ὅτι οὐδὲν ἂν ἔδει δίδοσθαι τοῖς φεύγουσιν ἀπολογίαν, εἴπερ οἷόν τ’ ἦν ἐκ τῶν τοῦ διώκοντος λόγων ἐψηφίσθαι τὰ δίκαια. νῦν δ’ εἰ μὲν εὖ τυγχάνει κατηγορηκὼς ἢ κακῶς, οὐδεὶς ἂν τῶν παρόντων ἀγνοήσειεν· εἰ δ’ ἀληθέσι κέχρηται τοῖς λόγοις, οὐκέτι τοῦτο τοῖς κρίνουσι γνῶναι ῥᾴδιον ἐξ ὧν ὁ πρότερος εἴρηκεν, ἀλλ’ ἀγαπητὸν ἢν ἐξ ἀμφοτέρων τῶν λόγων ἐκλαβεῖν δυνηθῶσι τὸ δίκαιον.", "st": "15.17"}, {"sp": "N", "t": "οὐ θαυμάζω δὲ τῶν πλείω χρόνον διατριβόντων ἐπὶ ταῖς τῶν ἐξαπατώντων κατηγορίαις ἢ ταῖς ὑπὲρ αὑτῶν ἀπολογίαις, οὐδὲ τῶν λεγόντων ὡς ἔστι μέγιστον κακὸν διαβολή· τί γὰρ ἂν γένοιτο ταύτης κακουργότερον, ἣ ποιεῖ τοὺς μὲν ψευδομένους εὐδοκιμεῖν, τοὺς δὲ δικάζοντας ἐπιορκεῖν, ὅλως δὲ τὴν μὲν ἀλήθειαν ἀφανίζει, ψευδῆ δὲ δόξαν παραστήσασα τοῖς ἀκούουσιν ὃν ἂν τύχῃ τῶν πολιτῶν ἀδίκως ἀπόλλυσιν;", "st": "15.18"}, {"sp": "N", "t": "ἃ φυλακτέον ἐστίν, ὅπως μηδὲν ὑμῖν συμβήσεται τοιοῦτον, μηδ’ ἃ τοῖς ἄλλοις ἂν ἐπιτιμήσαιτε τούτοις αὐτοὶ φανήσεσθε περιπίπτοντες. οἶμαι δ’ ὑμᾶς οὐκ ἀγνοεῖν ὅτι τῇ πόλει πολλάκις οὕτως ἤδη μετεμέλησε τῶν κρίσεων τῶν μετ’ ὀργῆς καὶ μὴ μετ’ ἐλέγχου γενομένων, ὥστ’ οὐ πολὺν χρόνον διαλιποῦσα παρὰ μὲν τῶν ἐξαπατησάντων δίκην λαβεῖν ἐπεθύμησε, τοὺς δὲ διαβληθέντας ἡδέως ἂν εἶδεν ἄμεινον ἢ πρότερον πράττοντας.", "st": "15.19"}, {"sp": "N", "t": "ὧν χρὴ μεμνημένους μὴ προπετῶς πιστεύειν τοῖς τῶν κατηγόρων λόγοις, μηδὲ μετὰ θορύβου καὶ χαλεπότητος ἀκροᾶσθαι τῶν ἀπολογουμένων. καὶ γὰρ αἰσχρὸν ἐπὶ μὲν τῶν ἄλλων πραγμάτων ἐλεημονεστάτους ὁμολογεῖσθαι καὶ πραοτάτους ἁπάντων εἶναι τῶν Ἑλλήνων, ἐπὶ δὲ τοῖς ἀγῶσι τοῖς ἐνθάδε γιγνομένοις τἀναντία τῇ δόξῃ ταύτῃ φαίνεσθαι πράττοντας·", "st": "15.20"}, {"sp": "N", "t": "καὶ παρ’ ἑτέροις μὲν ἐπειδὰν περὶ ψυχῆς ἀνθρώπου δικάζωσι, μέρος τι τῶν ψήφων ὑποβάλλεσθαι τοῖς φεύγουσι, παρ’ ὑμῖν δὲ μηδὲ τῶν ἴσων τυγχάνειν τοὺς κινδυνεύοντας τοῖς συκοφαντοῦσιν, ἀλλ’ ὀμνύναι μὲν καθ’ ἕκαστον τὸν ἐνιαυτὸν ἦ μὴν ὁμοίως ἀκροάσεσθαι τῶν κατηγορούντων καὶ τῶν ἀπολογουμένων,", "st": "15.21"}, {"sp": "N", "t": "τοσοῦτον δὲ τὸ μεταξὺ ποιεῖν, ὥστε τῶν μὲν αἰτιωμένων ὅ τι ἂν λέγωσιν ἀποδέχεσθαι, τῶν δὲ τούτους ἐξελέγχειν πειρωμένων ἐνίοτε μηδὲ τὴν φωνὴν ἀκούοντας ἀνέχεσθαι, καὶ νομίζειν μὲν ἀοικήτους εἶναι ταύτας τῶν πόλεων ἐν αἷς ἄκριτοί τινες ἀπόλλυνται τῶν πολιτῶν, ἀγνοεῖν δ’ ὅτι τοῦτο ποιοῦσιν οἱ μὴ κοινὴν τὴν εὔνοιαν τοῖς ἀγωνιζομένοις παρέχοντες.", "st": "15.22"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὅταν τις αὐτὸς μὲν κινδυνεύων κατηγορῇ τῶν διαβαλλόντων, ἑτέρῳ δὲ δικάζων μὴ τὴν αὐτὴν ἔχῃ γνώμην περὶ αὐτῶν. καίτοι χρὴ τοὺς νοῦν ἔχοντας τοιούτους εἶναι κριτὰς τοῖς ἄλλοις, οἵων περ ἂν αὐτοὶ τυγχάνειν ἀξιώσαιεν, λογιζομένους ὅτι διὰ τοὺς συκοφαντεῖν τολμῶντας ἄδηλον ὅστις εἰς κίνδυνον καταστὰς ἀναγκασθήσεται λέγειν ἅπερ ἐγὼ νῦν πρὸς τοὺς μέλλοντας περὶ αὐτοῦ τὴν ψῆφον διοίσειν.", "st": "15.23"}, {"sp": "N", "t": "οὐ γὰρ δὴ τῷ γε κοσμίως ζῆν ἄξιον πιστεύειν ὡς ἀδεῶς ἐξέσται τὴν πόλιν οἰκεῖν· οἱ γὰρ προῃρημένοι τῶν μὲν ἰδίων ἀμελεῖν τοῖς δ’ ἀλλοτρίοις ἐπιβουλεύειν οὐ τῶν μὲν σωφρόνως πολιτευομένων ἀπέχονται, τοὺς δὲ κακόν τι δρῶντας εἰς ὑμᾶς εἰσάγουσιν, ἀλλ’ ἐν τοῖς μηδὲν ἀδικοῦσιν ἐπιδειξάμενοι τὰς αὑτῶν δυνάμεις παρὰ τῶν φανερῶς ἐξημαρτηκότων πλέον λαμβάνουσιν ἀργύριον.", "st": "15.24"}, {"sp": "N", "t": "ἅπερ Λυσίμαχος διανοηθεὶς εἰς τουτονὶ τὸν κίνδυνόν με κατέστησεν, ἡγούμενος τὸν ἀγῶνα τὸν πρὸς ἐμὲ παρ’ ἑτέρων αὑτῷ χρηματισμὸν ποιήσειν, καὶ προσδοκῶν, ἢν ἐμοῦ περιγένηται τοῖς λόγοις, ὅν φησι διδάσκαλον εἶναι τῶν ἄλλων, ἀνυπόστατον τὴν αὑτοῦ δύναμιν ἅπασιν εἶναι δόξειν.", "st": "15.25"}, {"sp": "N", "t": "ἐλπίζει δὲ ῥᾳδίως τοῦτο ποιήσειν· ὁρᾷ γὰρ ὑμᾶς μὲν λίαν ταχέως ἀποδεχομένους τὰς αἰτίας καὶ τὰς διαβολάς, ἐμὲ δ’ ὑπὲρ αὐτῶν οὐ δυνησόμενον ἀξίως τῆς δόξης ἀπολογήσασθαι καὶ διὰ τὸ γῆρας καὶ διὰ τὴν ἀπειρίαν τῶν τοιούτων ἀγώνων.", "st": "15.26"}, {"sp": "N", "t": "οὕτω γὰρ βεβίωκα τὸν παρελθόντα χρόνον, ὥστε μηδένα μοι πώποτε μήτ’ ἐν ὀλιγαρχία μήτ’ ἐν δημοκρατία μήθ’ ὕβριν μήτ’ ἀδικίαν ἐγκαλέσαι, μηδ’ εἶναι μήτε διαιτητὴν μήτε δικαστὴν ὅστις περὶ τῶν ἐμοὶ πεπραγμένων φανήσεται κριτὴς γεγενημένος· ἠπιστάμην γὰρ αὐτὸς μὲν εἰς τοὺς ἄλλους μηδὲν ἐξαμαρτάνειν, ἀδικούμενος δὲ μὴ μετὰ δικαστηρίου ποιεῖσθαι τὰς τιμωρίας, ἀλλ’ ἐν τοῖς φίλοις τοῖς ἐκείνων διαλύεσθαι περὶ τῶν ἀμφισβητουμένων. ὧν οὐδέν μοι πλέον γέγονεν,", "st": "15.27"}, {"sp": "N", "t": "ἀλλ’ ἀνεγκλητεὶ μέχρι ταυτησὶ τῆς ἡλικίας βεβιωκὼς εἰς τὸν αὐτὸν καθέστηκα κίνδυνον, εἰς ὅνπερ ἂν εἰ πάντας ἐτύγχανον ἠδικηκώς. οὐ μὴν παντάπασιν ἀθυμῶ διὰ τὸ μέγεθος τοῦ τιμήματος, ἀλλ’ ἐάν περ ἐθελήσητε μετ’ εὐνοίας ἀκροάσασθαι, πολλὰς ἐλπίδας ἔχω τοὺς μὲν διεψευσμένους τῶν ἐμῶν ἐπιτηδευμάτων καὶ πεπεισμένους ὑπὸ τῶν βουλομένων βλασφημεῖν ταχέως μεταπεισθήσεσθαι περὶ αὐτῶν, τοὺς δὲ τοιοῦτον εἶναί με νομίζοντας οἷός περ εἰμί, βεβαιότερον ἔτι ταύτην ἕξειν τὴν διάνοιαν.", "st": "15.28"}, {"sp": "N", "t": "ἵνα δὲ μὴ λίαν ἐνοχλῶ πολλὰ πρὸ τοῦ πράγματος λέγων, ἀφέμενος τούτων, περὶ ὧν οἴσετε τὴν ψῆφον, ἤδη πειράσομαι διδάσκειν ὑμᾶς. καί μοι ἀνάγνωθι τὴν γραφήν.", "st": "15.29"}, {"sp": "N", "t": "<em>Γραφή<\/em>", "st": "15.29"}, {"sp": "N", "t": "ἐκ μὲν τοίνυν τῆς γραφῆς πειρᾶταί με διαβάλλειν ὁ κατήγορος ὡς διαφθείρω τοὺς νεωτέρους λέγειν διδάσκων καὶ παρὰ τὸ δίκαιον ἐν τοῖς ἀγῶσι πλεονεκτεῖν, ἐκ δὲ τῶν ἄλλων λόγων ποιεῖ με τηλικοῦτον, ὅσος οὐδεὶς πώποτε γέγονεν οὔτε τῶν περὶ τὰ δικαστήρια καλινδουμένων οὔτε τῶν περὶ τὴν φιλοσοφίαν διατριψάντων· οὐ γὰρ μόνον ἰδιώτας φησί μου γεγενῆσθαι μαθητάς, ἀλλὰ καὶ ῥήτορας καὶ στρατηγοὺς καὶ βασιλέας καὶ τυράννους, καὶ χρήματα παρ’ αὐτῶν παμπληθῆ τὰ μὲν εἰληφέναι τὰ δ’ ἔτι καὶ νῦν λαμβάνειν.", "st": "15.30"}, {"sp": "N", "t": "τοῦτον δὲ τὸν τρόπον πεποίηται τὴν κατηγορίαν, ἡγούμενος ἐκ μὲν ὧν καταλαζονεύεται περί μου καὶ τοῦ πλούτου καὶ τοῦ πλήθους τῶν μαθητῶν φθόνον ἅπασι τοῖς ἀκούουσιν ἐμποιήσειν, ἐκ δὲ τῆς περὶ τὰ δικαστήρια πραγματείας εἰς ὀργὴν καὶ μῖσος ὑμᾶς καταστήσειν· ἅπερ ὅταν πάθωσιν οἱ κρίνοντες, χαλεπώτατοι τοῖς ἀγωνιζομένοις εἰσίν. ὡς οὖν τὰ μὲν μείζω τοῦ προσήκοντος εἴρηκε, τὰ δ’ ὅλως ψεύδεται, ῥᾳδίως οἶμαι φανερὸν ποιήσειν.", "st": "15.31"}, {"sp": "N", "t": "ἀξιῶ δ’ ὑμᾶς τοῖς μὲν λόγοις οἷς πρότερον ἀκηκόατε περί μου τῶν βλασφημεῖν καὶ διαβάλλειν βουλομένων, μὴ προσέχειν τὸν νοῦν, μηδὲ πιστεύειν τοῖς μήτε μετ’ ἐλέγχου μήτε μετὰ κρίσεως εἰρημένοις, μηδὲ ταῖς δόξαις χρῆσθαι ταῖς ἀδίκως ὑπ’ ἐκείνων ὑμῖν ἐγγεγενημέναις, ἀλλ’ ὁποῖός τις ἂν ἐκ τῆς κατηγορίας τῆς νῦν καὶ τῆς ἀπολογίας φαίνωμαι, τοιοῦτον εἶναί με νομίζειν· οὕτω γὰρ γιγνώσκοντες αὐτοί τε δόξετε καλῶς κρίνειν καὶ νομίμως, ἐγώ τε τεύξομαι πάντων τῶν δικαίων.", "st": "15.32"}, {"sp": "N", "t": "ὅτι μὲν οὖν οὐδεὶς οὔθ’ ὑπὸ τῆς δεινότητος τῆς ἐμῆς οὔθ’ ὑπὸ τῶν συγγραμμάτων βέβλαπται τῶν πολιτῶν, τὸν ἐνεστῶτα κίνδυνον ἡγοῦμαι μέγιστον εἶναι τεκμήριον. εἰ γάρ τις ἦν ἠδικημένος, εἰ καὶ τὸν ἄλλον χρόνον ἡσυχίαν εἶχεν, οὐκ ἂν ἠμέλησε τοῦ καιροῦ τοῦ παρόντος, ἀλλ’ ἦλθεν ἂν ἤτοι κατηγορήσων ἢ καταμαρτυρήσων. ὅπου γὰρ ὁ μηδ’ ἀκηκοὼς μηδὲν πώποτε φλαῦρον εἰς ἀγῶνά με τηλικουτονὶ κατέστησεν, ἦ που σφόδρ’ ἂν οἱ κακῶς πεπονθότες ἐπειρῶντ’ ἂν δίκην παρ’ ἐμοῦ λαμβάνειν.", "st": "15.33"}, {"sp": "N", "t": "οὐ γὰρ δὴ τοῦτό γ’ ἐστὶν οὔτ’ εἰκὸς οὔτε δυνατόν, ἐμὲ μὲν περὶ πολλοὺς ἡμαρτηκέναι, τοὺς δὲ ταῖς συμφοραῖς δι’ ἐμὲ περιπεπτωκότας ἡσυχίαν ἔχειν καὶ μὴ τολμᾶν ἐγκαλεῖν, ἀλλὰ πραοτέρους ἐν τοῖς ἐμοῖς εἶναι κινδύνοις τῶν μηδὲν ἠδικημένων, ἐξὸν αὐτοῖς δηλώσασιν ἃ πεπόνθασι τὴν μεγίστην παρ’ ἐμοῦ λαβεῖν τιμωρίαν.", "st": "15.34"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὔτε πρότερον οὔτε νῦν οὐδείς μοι φανήσεται τοιοῦτον οὐδὲν ἐγκαλέσας. ὥστ’ εἰ συγχωρήσαιμι τῷ κατηγόρῳ καὶ προσομολογήσαιμι πάντων ἀνθρώπων εἶναι δεινότατος, καὶ συγγραφεὺς τῶν λόγων τῶν λυπούντων ὑμᾶς τοιοῦτος οἷος οὐδεὶς ἄλλος γέγονε, πολὺ ἂν δικαιότερον ἐπιεικὴς εἶναι δοκοίην ἢ ζημιωθείην.", "st": "15.35"}, {"sp": "N", "t": "τοῦ μὲν γὰρ γενέσθαι προέχοντα τῶν ἄλλων ἢ περὶ τοὺς λόγους ἢ περὶ τὰς πράξεις εἰκότως ἄν τις τὴν τύχην αἰτιάσαιτο, τοῦ δὲ καλῶς καὶ μετρίως κεχρῆσθαι τῇ φύσει δικαίως ἂν ἅπαντες τὸν τρόπον τὸν ἐμὸν ἐπαινέσειαν. οὐ μὴν οὐδ’ εἰ ταῦτ’ ἔχων περὶ ἐμαυτοῦ λέγειν, οὐδ’ οὕτω φανήσομαι περὶ τοὺς λόγους τοὺς τοιούτους γεγενημένος.", "st": "15.36"}, {"sp": "N", "t": "γνώσεσθε δ’ ἐκ τῶν ἐπιτηδευμάτων τῶν ἐμῶν, ἐξ ὧνπερ οἷόν τ’ ἐστὶν εἰδέναι τὴν ἀλήθειαν πολὺ μᾶλλον ἢ παρὰ τῶν διαβαλλόντων. οἶμαι γὰρ οὐδένα τοῦτ’ ἀγνοεῖν, ὅτι πάντες ἄνθρωποι περὶ τὸν τόπον τοῦτον εἰώθασι διατρίβειν, ὅθεν ἂν προέλωνται τὸν βίον πορίζεσθαι.", "st": "15.37"}, {"sp": "N", "t": "τοὺς μὲν τοίνυν ἀπὸ τῶν συμβολαίων τῶν ὑμετέρων ζῶντας καὶ τῆς περὶ ταῦτα πραγματείας ἴδοιτ’ ἂν μόνον οὐκ ἐν τοῖς δικαστηρίοις οἰκοῦντας, ἐμὲ δ’ οὐδεὶς πώποθ’ ἑώρακεν οὔτ’ ἐν τοῖς συνεδρίοις οὔτε περὶ τὰς ἀνακρίσεις οὔτ’ ἐπὶ τοῖς δικαστηρίοις οὔτε πρὸς τοῖς διαιτηταῖς, ἀλλ’ οὕτως ἀπέχομαι τούτων ἁπάντων ὡς οὐδεὶς ἄλλος τῶν πολιτῶν.", "st": "15.38"}, {"sp": "N", "t": "ἔπειτ’ ἐκείνους μὲν ἂν εὕροιτε παρ’ ὑμῖν μόνοις χρηματίζεσθαι δυναμένους, εἰ δ’ ἄλλοσέ ποι πλεύσειαν, ἐνδεεῖς ἂν ὄντας τῶν καθ’ ἡμέραν, ἐμοὶ δὲ τὰς εὐπορίας, περὶ ὧν οὗτος μειζόνως εἴρηκεν, ἔξωθεν ἁπάσας γεγενημένας· ἔτι δὲ τοῖς μὲν πλησιάζοντας ἢ τοὺς ἐν κακοῖς αὐτοὺς ὄντας ἢ τοὺς ἑτέροις πράγματα παρέχειν βουλομένους, ἐμοὶ δὲ τοὺς πλείστην σχολὴν τῶν Ἑλλήνων ἄγοντας.", "st": "15.39"}, {"sp": "N", "t": "ἠκούσατε δὲ καὶ τοῦ κατηγόρου λέγοντος ὅτι παρὰ Νικοκλέους τοῦ Σαλαμινίων βασιλέως πολλὰς ἔλαβον καὶ μεγάλας δωρεάς. καίτοι τίνι πιστὸν ὑμῶν ἐστιν ὡς Νικοκλῆς ἔδωκέ μοι ταύτας, ἵνα δίκας μανθάνῃ λέγειν, ὃς καὶ τοῖς ἄλλοις περὶ τῶν ἀμφισβητουμένων ὥσπερ δεσπότης ἐδίκαζεν; ὥστ’ ἐξ ὧν αὐτὸς οὗτος εἴρηκε, ῥᾴδιον καταμαθεῖν ὅτι πόρρω τῶν πραγματειῶν εἰμι τῶν περὶ τὰ συμβόλαια γιγνομένων.", "st": "15.40"}, {"sp": "N", "t": "ἀλλὰ μὴν κἀκεῖνο πᾶσι φανερόν ἐστιν ὅτι παμπληθεῖς εἰσιν οἱ παρασκευάζοντες τοὺς λόγους τοῖς ἐν τοῖς δικαστηρίοις ἀγωνιζομένοις. τούτων μὲν τοίνυν τοσούτων ὄντων οὐδεὶς πώποτε φανήσεται μαθητῶν ἠξιωμένος, ἐγὼ δὲ πλείους εἰληφώς, ὥς φησιν ὁ κατήγορος, ἢ σύμπαντες οἱ περὶ τὴν φιλοσοφίαν διατρίβοντες. καίτοι πῶς εἰκὸς τοὺς τοσοῦτον τοῖς ἐπιτηδεύμασιν ἀλλήλων ἀφεστῶτας περὶ τὰς αὐτὰς πράξεις ἡγεῖσθαι διατρίβειν;", "st": "15.41"}, {"sp": "N", "t": "ἔχων δὲ πολλὰς εἰπεῖν διαφορὰς περὶ τοῦ βίου τοῦ τ’ ἐμοῦ καὶ τῶν περὶ τὰς δίκας, ἐκείνως ὑμᾶς ἡγοῦμαι τάχιστ’ ἂν ἀφέσθαι τῆς δόξης ταύτης, εἴ τις ὑμῖν ἐπιδείξειε μὴ τούτων τῶν πραγμάτων μαθητάς μου γιγνομένους ὧν ὁ κατήγορος εἴρηκε, μηδὲ περὶ τοὺς λόγους ὄντα με δεινὸν τοὺς περὶ τῶν ἰδίων συμβολαίων.", "st": "15.42"}, {"sp": "N", "t": "οἶμαι γὰρ ὑμᾶς, ἐξελεγχομένης τῆς αἰτίας ἧς εἶχον πρότερον, ζητεῖν ἑτέραν μεταλαβεῖν διάνοιαν, καὶ ποθεῖν ἀκοῦσαι περὶ ποίους ἄλλους λόγους γεγενημένος τηλικαύτην δόξαν ἔλαβον. εἰ μὲν οὖν μοι συνοίσει κατειπόντι τὴν ἀλήθειαν, οὐκ οἶδα· χαλεπὸν γὰρ στοχάζεσθαι τῆς ὑμετέρας διανοίας· οὐ μὴν ἀλλὰ παρρησιάσομαί γε πρὸς ὑμᾶς.", "st": "15.43"}, {"sp": "N", "t": "καὶ γὰρ ἂν αἰσχυνθείην τοὺς πλησιάσαντας, εἰ πολλάκις εἰρηκὼς ὅτι δεξαίμην ἂν ἅπαντας εἰδέναι τοὺς πολίτας καὶ τὸν βίον ὃν ζῶ καὶ τοὺς λόγους οὓς λέγω, νῦν μὴ δηλοίην ὑμῖν αὐτοὺς ἀλλ’ ἀποκρυπτόμενος φανείην. ὡς οὖν ἀκουσόμενοι τὴν ἀλήθειαν, οὕτω προσέχετε τὸν νοῦν.", "st": "15.44"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐκεῖνο δεῖ μαθεῖν ὑμᾶς, ὅτι τρόποι τῶν λόγων εἰσὶν οὐκ ἐλάττους ἢ τῶν μετὰ μέτρου ποιημάτων. οἱ μὲν γὰρ τὰ γένη τὰ τῶν ἡμιθέων ἀναζητοῦντες τὸν βίον τὸν αὑτῶν κατέτριψαν, οἱ δὲ περὶ τοὺς ποιητὰς ἐφιλοσόφησαν, ἕτεροι δὲ τὰς πράξεις τὰς ἐν τοῖς πολέμοις συναγαγεῖν ἐβουλήθησαν, ἄλλοι δέ τινες περὶ τὰς ἐρωτήσεις καὶ τὰς ἀποκρίσεις γεγόνασιν, οὓς ἀντιλογικοὺς καλοῦσιν.", "st": "15.45"}, {"sp": "N", "t": "εἴη δ’ ἂν οὐ μικρὸν ἔργον, εἰ πάσας τις τὰς ἰδέας τὰς τῶν λόγων ἐξαριθμεῖν ἐπιχειρήσειεν· ἧς δ’ οὖν ἐμοὶ προσήκει, ταύτης μνησθεὶς ἐάσω τὰς ἄλλας. εἰσὶ γάρ τινες οἳ τῶν μὲν προειρημένων οὐκ ἀπείρως ἔχουσι, γράφειν δὲ προῄρηνται λόγους οὐ περὶ τῶν ἰδίων συμβολαίων, ἀλλ’ Ἑλληνικοὺς καὶ πολιτικοὺς καὶ πανηγυρικούς, οὓς ἅπαντες ἂν φήσαιεν ὁμοιοτέρους εἶναι τοῖς μετὰ μουσικῆς καὶ ῥυθμῶν πεποιημένοις ἢ τοῖς ἐν δικαστηρίῳ λεγομένοις.", "st": "15.46"}, {"sp": "N", "t": "καὶ γὰρ τῇ λέξει ποιητικωτέρᾳ καὶ ποικιλωτέρᾳ τὰς πράξεις δηλοῦσι, καὶ τοῖς ἐνθυμήμασιν ὀγκωδεστέροις καὶ καινοτέροις χρῆσθαι ζητοῦσιν, ἔτι δὲ ταῖς ἄλλαις ἰδέαις ἐπιφανεστέραις καὶ πλείοσιν ὅλον τὸν λόγον διοικοῦσιν. ὧν ἅπαντες μὲν ἀκούοντες χαίρουσιν οὐδὲν ἧττον ἢ τῶν ἐν τοῖς μέτροις πεποιημένων, πολλοὶ δὲ καὶ μαθηταὶ γίγνεσθαι βούλονται, νομίζοντες τοὺς ἐν τούτοις πρωτεύοντας πολὺ σοφωτέρους καὶ βελτίους καὶ μᾶλλον ὠφελεῖν δυναμένους εἶναι τῶν τὰς δίκας εὖ λεγόντων.", "st": "15.47"}, {"sp": "N", "t": "συνίσασι γὰρ τοῖς μὲν διὰ πολυπραγμοσύνην ἠπείροις τῶν ἀγώνων γεγενημένοις, τοὺς δ’ ἐκ φιλοσοφίας ἐκείνων τῶν λόγων ὧν ἄρτι προεῖπον τὴν δύναμιν εἰληφότας, καὶ τοὺς μὲν δικανικοὺς δοκοῦντας εἶναι ταύτην τὴν ἡμέραν μόνην ἀνεκτοὺς ὄντας ἐν ᾗ περ ἂν ἀγωνιζόμενοι τυγχάνωσι, τοὺς δ’ ἐν ἁπάσαις ταῖς ὁμιλίαις καὶ παρὰ πάντα τὸν χρόνον ἐντίμους ὄντας καὶ δόξης ἐπιεικοῦς τυγχάνοντας· ἔτι δὲ τοὺς μέν,", "st": "15.48"}, {"sp": "N", "t": "ἢν ὀφθῶσι δὶς ἢ τρὶς ἐπὶ τῶν δικαστηρίων, μισουμένους καὶ διαβαλλομένους, τοὺς δ’ ὅσῳ περ ἂν πλείοσι καὶ πλεονάκις συγγίγνωνται, τοσούτῳ μᾶλλον θαυμαζομένους· πρὸς δὲ τούτοις τοὺς μὲν περὶ τὰς δίκας δεινοὺς πόρρω τῶν λόγων ἐκείνων ὄντας, τοὺς δ’ εἰ βουληθεῖεν ταχέως ἂν ἑλεῖν καὶ τοὺτους δυνηθέντας.", "st": "15.49"}, {"sp": "N", "t": "ταῦτα λογιζόμενοι καὶ πολὺ κρείττω νομίζοντες εἶναι τὴν αἵρεσιν, βούλονται μετασχεῖν τῆς παιδείας ταύτης, ἧς οὐδ’ ἂν ἐγὼ φανείην ἀπεληλαμένος, ἀλλὰ πολλῷ χαριεστέραν δόξαν εἰληφώς. περὶ μὲν οὖν τῆς ἐμῆς εἴτε βούλεσθε καλεῖν δυνάμεως εἴτε φιλοσοφίας εἴτε διατριβῆς, ἀκηκόατε πᾶσαν τὴν ἀλήθειαν.", "st": "15.50"}, {"sp": "N", "t": "βούλομαι δὲ περὶ ἐμαυτοῦ καὶ νόμον θεῖναι χαλεπώτερον ἢ περὶ τῶν ἄλλων, καὶ λόγον εἰπεῖν θρασύτερον ἢ κατὰ τὴν ἐμὴν ἡλικίαν. ἀξιῶ γὰρ οὐ μόνον, εἰ βλαβεροῖς χρῶμαι τοῖς λόγοις, μηδεμιᾶς συγγνώμης τυγχάνειν παρ’ ὑμῶν, ἀλλ’ εἰ μὴ τοιούτοις, οἵοις οὐδεὶς ἄλλος, τὴν μεγίστην ὑποσχεῖν τιμωρίαν. οὐχ οὕτω δ’ ἂν τολμηρὰν ἐποιησάμην τὴν ὑπόσχεσιν, εἰ μὴ καὶ δείξειν ἤμελλον ὑμῖν καὶ ῥᾳδίαν ποιήσειν τὴν διάγνωσιν αὐτῶν.", "st": "15.51"}, {"sp": "N", "t": "ἔχει γὰρ οὕτως· ἐγὼ καλλίστην ἡγοῦμαι καὶ δικαιοτάτην εἶναι τὴν τοιαύτην ἀπολογίαν, ἥτις εἰδέναι ποιεῖ τοὺς δικάζοντας ὡς δυνατὸν μάλιστα, περὶ ὧν τὴν ψῆφον οἴσουσι, καὶ μὴ πλανᾶσθαι τῇ διανοίᾳ μηδ’ ἀμφιγνοεῖν τοὺς τἀληθῆ λέγοντας.", "st": "15.52"}, {"sp": "N", "t": "εἰ μὲν τοίνυν ἠγωνιζόμην ὡς περὶ πράξεις τινὰς ἡμαρτηκώς, οὐκ ἂν οἷός τ’ ἦν ἰδεῖν ὑμῖν αὐτὰς παρασχεῖν, ἀλλ’ ἀναγκαίως εἶχεν εἰκάζοντας ὑμᾶς ἐκ τῶν εἰρημένων διαγιγνώσκειν ὅπως ἐτύχετε περὶ τῶν πεπραγμένων· ἐπειδὴ δὲ περὶ τοὺς λόγους ἔχω τὴν αἰτίαν, οἶμαι μᾶλλον ὑμῖν ἐμφανιεῖν τὴν ἀλήθειαν.", "st": "15.53"}, {"sp": "N", "t": "αὐτοὺς γὰρ ὑμῖν δείξω τοὺς εἰρημένους ὑπ’ ἐμοῦ καὶ γεγραμμένους, ὥστ’ οὐ δοξάσαντες ἀλλὰ σαφῶς εἰδότες ὁποῖοί τινές εἰσι τὴν ψῆφον οἴσετε περὶ αὐτῶν. ἅπαντας μὲν οὖν διὰ τέλους εἰπεῖν οὐκ ἂν δυναίμην· ὁ γὰρ χρόνος ὁ δεδομένος ἡμῖν ὀλίγος ἐστίν· ὥσπερ δὲ τῶν καρπῶν, ἐξενεγκεῖν ἑκάστου δεῖγμα πειράσομαι. μικρὸν γὰρ μέρος ἀκούσαντες ῥᾳδίως τό τ’ ἐμὸν ἦθος γνωριεῖτε καὶ τῶν λόγων τὴν δύναμιν ἁπάντων μαθήσεσθε.", "st": "15.54"}, {"sp": "N", "t": "δέομαι δὲ τῶν πολλάκις ἀνεγνωκότων τὰ μέλλοντα ῥηθήσεσθαι μὴ ζητεῖν ἐν τῷ παρόντι παρ’ ἐμοῦ καινοὺς λόγους, μηδ’ ὀχληρόν με νομίζειν, ὅτι λέγω τοὺς πάλαι παρ’ ὑμῖν διατεθρυλημένους. εἰ μὲν γὰρ ἐπίδειξιν ποιούμενος ἔλεγον αὐτούς, εἰκότως ἂν εἶχον τὴν αἰτίαν ταύτην· νῦν δὲ κρινόμενος καὶ κινδυνεύων ἀναγκάζομαι χρῆσθαι τοῦτον τὸν τρόπον αὐτοῖς.", "st": "15.55"}, {"sp": "N", "t": "καὶ γὰρ ἂν πάντων εἴην καταγελαστότατος, εἰ τοῦ κατηγόρου διαβάλλοντος ὅτι τοιούτους γράφω λόγους οἳ καὶ τὴν πόλιν βλάπτουσι καὶ τοὺς νεωτέρους διαφθείρουσι, δι’ ἑτέρων ποιοίμην τὴν ἀπολογίαν, ἐξὸν αὐτοὺς δείξαντι τούτους ἀπολύσασθαι τὴν διαβολὴν τὴν λεγομένην περὶ ἡμῶν. ὑμᾶς μὲν οὖν ἀξιῶ μοι διὰ ταῦτα συγγνώμην ἔχειν καὶ συναγωνιστὰς γίγνεσθαι, τοῖς δὲ ἄλλοις ἤδη περαίνειν ἐπιχειρήσω, μικρὸν ἔτι προειπών, ἵνα ῥᾷον ἐπακολουθῶσι τοῖς λεγομένοις.", "st": "15.56"}, {"sp": "N", "t": "ὁ μὲν γὰρ λόγος ὁ μέλλων πρῶτος ὑμῖν δειχθήσεσθαι κατ’ ἐκείνους ἐγράφη τοὺς χρόνους, ὅτε Λακεδαιμόνιοι μὲν ἦρχον τῶν Ἑλλήνων, ἡμεῖς δὲ ταπεινῶς ἐπράττομεν. ἔστι δὲ τοὺς μὲν Ἕλληνας παρακαλῶν ἐπὶ τὴν τῶν βαρβάρων στρατείαν, Λακεδαιμονίοις δὲ περὶ τῆς ἡγεμονίας ἀμφισβητῶν. τοιαύτην δὲ τὴν ὑπόθεσιν ποιησάμενος,", "st": "15.57"}, {"sp": "N", "t": "ἀποφαίνω τὴν πόλιν ἁπάντων τῶν ὑπαρχόντων τοῖς Ἕλλησιν ἀγαθῶν αἰτίαν γεγενημένην. ἀφορισάμενος δὲ τὸν λόγον τὸν περὶ τῶν τοιούτων εὐεργεσιῶν, καὶ βουλόμενος τὴν ἡγεμονίαν ἔτι σαφέστερον ἀποφαίνειν ὡς ἔστι τῆς πόλεως, ἐνθένδε ποθὲν ἐπιχειρῶ διδάσκειν περὶ τούτων, ὡς τῇ πόλει τιμᾶσθαι προσήκει πολὺ μᾶλλον ἐκ τῶν περὶ τὸν πόλεμον κινδύνων ἢ τῶν ἄλλων εὐεργεσιῶν.", "st": "15.58"}, {"sp": "N", "t": "ὤιμην μὲν οὖν αὐτὸς δυνήσεσθαι διελθεῖν περὶ αὐτῶν· νῦν δέ με τὸ γῆρας ἐμποδίζει καὶ ποιεῖ προαπαγορεύειν. ἵν’ οὖν μὴ παντάπασιν ἐκλυθῶ πολλῶν ἔτι μοι λεκτέων ὄντων, ἀρξάμενος ἀπὸ τῆς παραγραφῆς ἀνάγνωθι τὰ περὶ τῆς ἡγεμονίας αὐτοῖς. [Ἐκ τοῦ Πανηγυρικοῦ, 51–99.]", "st": "15.59"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς ἡγεμονίας, ὡς δικαίως ἂν εἴη τῆς πόλεως, ῥᾴδιον ἐκ τῶν εἰρημένων καταμαθεῖν. ἐνθυμήθητε δὲ πρὸς ὑμᾶς αὐτούς, εἰ δοκῶ τοῖς λόγοις διαφθείρειν τοὺς νεωτέρους, ἀλλὰ μὴ προτρέπειν ἐπ’ ἀρετὴν καὶ τοὺς ὑπὲρ τῆς πόλεως κινδύνους, ἢ δικαίως ἂν δοῦναι δίκην ὑπὲρ τῶν εἰρημένων, ἀλλ’ οὐκ ἂν χάριν κομίσασθαι παρ’ ὑμῶν τὴν μεγίστην,", "st": "15.60"}, {"sp": "N", "t": "ὃς οὕτως ἐγκεκωμίακα τὴν πόλιν καὶ τοὺς προγόνους καὶ τοὺς κινδύνους τοὺς ἐν ἐκείνοις τοῖς χρόνοις γεγενημένους, ὥστε τούς τε πρότερον γράψαντας περὶ τὴν ὑπόθεσιν ταύτην ἅπαντας ἠφανικέναι τοὺς λόγους, αἰσχυνομένους ὑπὲρ τῶν εἰρημένων αὑτοῖς, τούς τε νῦν δοκοῦντας εἶναι δεινοὺς μὴ τολμᾶν ἔτι λέγειν περὶ τούτων, ἀλλὰ καταμέμφεσθαι τὴν δύναμιν τὴν σφετέραν αὐτῶν.", "st": "15.61"}, {"sp": "N", "t": "ἀλλ’ ὅμως, τούτων οὕτως ἐχόντων, φανήσονταί τινες τῶν εὑρεῖν μὲν οὐδὲν οὐδ’ εἰπεῖν ἄξιον λόγου δυναμένων, ἐπιτιμᾶν δὲ καὶ βασκαίνειν τὰ τῶν ἄλλων μεμελετηκότων, οἳ χαριέντως μὲν εἰρῆσθαι ταῦτα φήσουσι (τὸ γὰρ εὖ φθονήσουσιν εἰπεῖν), πολὺ μέντοι χρησιμωτέρους εἶναι τῶν λόγων καὶ κρείττους τοὺς ἐπιπλήττοντας τοῖς νῦν ἁμαρτανομένοις ἢ τοὺς τὰ πεπραγμένα πρότερον ἐπαινοῦντας, καὶ τοὺς ὑπὲρ ὧν δεῖ πράττειν συμβουλεύοντας ἢ τοὺς τὰ παλαιὰ τῶν ἔργων διεξιόντας.", "st": "15.62"}, {"sp": "N", "t": "ἵν’ οὖν μηδὲ ταῦτ’ ἔχωσιν εἰπεῖν, ἀφέμενος τοῦ βοηθεῖν τοῖς εἰρημένοις πειράσομαι μέρος ἑτέρου λόγου τοσοῦτον, ὅσον περ ἄρτι, διελθεῖν ὑμῖν, ἐν ᾧ φανήσομαι περὶ τούτων ἁπάντων πολλὴν ἐπιμέλειαν πεποιημένος. ἔστι δὲ τὰ μὲν ἐν ἀρχῇ λεγόμενα περὶ τῆς εἰρήνης τῆς πρὸς Χίους καὶ Ῥοδίους καὶ Βυζαντίους,", "st": "15.63"}, {"sp": "N", "t": "ἐπιδείξας δ’ ὡς συμφέρει τῇ πόλει διαλύσασθαι τὸν πόλεμον, κατηγορῶ τῆς δυναστείας τῆς ἐν τοῖς Ἕλλησι καὶ τῆς ἀρχῆς τῆς κατὰ θάλατταν, ἀποφαίνων αὐτὴν οὐδὲν διαφέρουσαν οὔτε ταῖς πράξεσιν οὔτε τοῖς πάθεσι τῶν μοναρχιῶν· ἀναμιμνήσκω δὲ καὶ τὰ συμβάντα δι’ αὐτὴν τῇ πόλει καὶ Λακεδαιμονίοις καὶ τοῖς ἄλλοις ἅπασι. διαλεχθεὶς δὲ περὶ τούτων,", "st": "15.64"}, {"sp": "N", "t": "καὶ τὰς τῆς Ἑλλάδος συμφορὰς ὀδυράμενος, καὶ τῇ πόλει παραινέσας ὡς χρὴ μὴ περιορᾶν αὐτὴν οὕτω πράττουσαν, ἐπὶ τελευτῆς ἐπί τε τὴν δικαιοσύνην παρακαλῶ καὶ τοῖς ἁμαρτανομένοις ἐπιπλήττω καὶ περὶ τῶν μελλόντων συμβουλεύω. λαβὼν οὖν ἀρχὴν ταύτην ὅθεν διαλέγομαι περὶ αὐτῶν, ἀνάγνωθι καὶ τοῦτο τὸ μέρος αὐτοῖς.", "st": "15.65"}, {"sp": "N", "t": "[Ἐκ τοῦ Περὶ τῆς εἰρήνης, 25–56, 132–145.]", "st": "15.66"}, {"sp": "N", "t": "δυοῖν μὲν τοίνυν λόγοιν ἀκηκόατε· βούλομαι δὲ καὶ τοῦ τρίτου μικρὰ διελθεῖν, ἵν’ ὑμῖν ἔτι μᾶλλον γένηται καταφανὲς ὅτι πάντες οἱ λόγοι πρὸς ἀρετὴν καὶ δικαιοσύνην συντείνουσιν. ἔστι δ’ ὁ μέλλων δειχθήσεσθαι Νικοκλεῖ τῷ Κυπρίῳ, τῷ κατ’ ἐκεῖνον τὸν χρόνον βασιλεύοντι, συμβουλεύων ὡς δεῖ τῶν πολιτῶν ἄρχειν· οὐχ ὁμοίως δὲ γέγραπται τοῖς ἀνεγνωσμένοις.", "st": "15.67"}, {"sp": "N", "t": "οὗτοι μὲν γὰρ τὸ λεγόμενον ὁμολογούμενον ἀεὶ τῷ προειρημένῳ καὶ συγκεκλειμένον ἔχουσιν, ἐν δὲ τούτῳ τοὐναντίον· ἀπολύσας γὰρ ἀπὸ τοῦ προτέρου καὶ χωρίς, ὥσπερ τὰ καλούμενα κεφάλαια, ποιήσας, πειρῶμαι διὰ βραχέων ἕκαστον ὧν συμβουλεύω φράζειν. τούτου δ’ ἕνεκα ταύτην ἐποιησάμην τὴν ὑπόθεσιν,", "st": "15.68"}, {"sp": "N", "t": "ἡγούμενος ἐκ τοῦ παραινεῖν τήν τε διάνοιαν τὴν ἐκείνου μάλιστ’ ὠφελήσειν καὶ τὸν τρόπον τὸν ἐμαυτοῦ τάχιστα δηλώσειν. διὰ τὴν αὐτὴν δὲ ταύτην πρόφασιν καὶ νῦν αὐτὸν αὐτὸν ὑμῖν δεῖξαι προειλόμην, οὐχ ὡς ἄριστα τῶν λοιπῶν γεγραμμένον, ἀλλ’ ὡς ἐκ τούτου μάλιστα φανερὸς γενησόμενος, ὃν τρόπον εἴθισμαι καὶ τοῖς ἰδιώταις καὶ τοῖς δυνάσταις πλησιάζειν·", "st": "15.69"}, {"sp": "N", "t": "φανήσομαι γὰρ πρὸς αὐτὸν ἐλευθέρως καὶ τῆς πόλεως ἀξίως διειλεγμένος, καὶ οὐ τὸν ἐκείνου πλοῦτον οὐδὲ τὴν δύναμιν θεραπεύων ἀλλὰ τοῖς ἀρχομένοις ἐπαμύνων, καὶ παρασκευάζων καθ’ ὅσον ἠδυνάμην τὴν πολιτείαν αὐτοῖς ὡς οἷόν τε πραοτάτην. ὅπου δὲ βασιλεῖ διαλεψόμενος ὑπὲρ τοῦ δήμου τοὺς λόγους ἐποιούμην, ἦπου τοῖς ἐν δημοκρατία πολιτευομένοις σφόδρ’ ἃ παρακελευσαίμην τὸ πλῆθος θεραπεύειν.", "st": "15.70"}, {"sp": "N", "t": "ἐν μὲν οὖν τῷ προοιμίῳ καὶ τοῖς πρώτοις λεγομένοις ἐπιτιμῶ ταῖς μοναρχίαις, ὅτι δέον αὐτοὺς τὴν φρόνησιν ἀσκεῖν μᾶλλον τῶν ἄλλων, οἱ δὲ χεῖρον παιδεύονται τῶν ἰδιωτῶν. διαλεχθεὶς δὲ περὶ τούτων, παραινῶ τῷ Νικοκλεῖ μὴ ῥᾳθυμεῖν μηδ’, ὥς περ ἱερωσύνην εἰληφότα τὴν βασιλείαν, οὕτω τὴν γνώμην ἔχειν, ἀλλὰ τῶν ἡδονῶν ἀμελήσαντα προσέχειν τὸν νοῦν τοῖς πράγμασιν.", "st": "15.71"}, {"sp": "N", "t": "ἐπιχειρῶ δὲ καὶ τοῦτο πείθειν αὐτόν, ὡς χρὴ δεινὸν νομίζειν, ὅταν ὁρᾷ τοὺς μὲν χείρους τῶν βελτιόνων ἄρχοντας καὶ τοὺς ἀνοητοτέρους τοῖς φρονιμωτέροις προστάττοντας, λέγων ὡς ὅσῳ περ ἂν ἐρρωμενέστερον τὴν τῶν ἄλλων ἄνοιαν ἀτιμάσῃ, τοσούτῳ μᾶλλον τὴν ἑαυτοῦ διάνοιαν ἀσκήσει. ποιησάμενος οὖν ἀρχὴν ἣν ἐγὼ τελευτήν, ἀνάγνωθι καὶ τούτου τοῦ λόγου τὸ λοιπὸν μέρος αὐτοῖς.", "st": "15.72"}, {"sp": "N", "t": "[Ἐκ τοῦ Πρὸς Νικοκλέα, 14–39.]", "st": "15.73"}, {"sp": "N", "t": "τῶν μὲν τοίνυν λόγων ἅλις ἡμῖν ἔστω τῶν ἀναγιγνωσκομένων καὶ τηλικοῦτο μῆκος ἐχόντων· ἐπεὶ μικροῦ γε μέρους τῶν πάλαι γεγραμμένων οὐκ ἂν ἀποσχοίμην, ἀλλ’ εἴποιμ’ ἂν εἴ τί μοι δόξειε πρέπον εἶναι τῶ παρόντι καιρῷ· καὶ γὰρ ἂν ἄτοπος εἴην, εἰ τοὺς ἄλλους ὁρῶν τοῖς ἐμοῖς χρωμένους ἐγὼ μόνος ἀπεχοίμην τῶν ὑπ’ ἐμοῦ πρότερον εἰρημένων, ἄλλως τε καὶ νῦν ὅτ’ οὐ μόνον μικροῖς μέρεσιν ἀλλ’ ὅλοις εἴδεσι προειλόμην χρῆσθαι πρὸς ὑμᾶς. ταῦτα μὲν οὖν, ὅπως ἂν ἡμῖν συμπίπτῃ, ποιήσομεν.", "st": "15.74"}, {"sp": "N", "t": "εἶπον δέ που, πρὶν ἀναγιγνώσκεσθαι τούτους, ὡς ἄξιος εἴην οὐ μόνον, εἰ βλαβεροῖς χρῶμαι τοῖς λόγοις, δοῦναι δίκην ὑμῖν, ἀλλ’ εἰ μὴ τοιούτοις οἵοις οὐδεὶς ἄλλος, τῆς μεγίστης τυχεῖν τιμωρίας. εἴ τινες οὖν ὑμῶν ὑπέλαβον τότε λίαν ἀλαζονικὸν εἶναι καὶ μέγα τὸ ῥηθέν, οὐκ ἂν δικαίως ἔτι τὴν γνώμην ταύτην ἔχοιεν· οἶμαι γὰρ ἀποδεδωκέναι τὴν ὑπόσχεσιν καὶ τοιούτους εἶναι τοὺς λόγους τοὺς ἀναγνωσθέντας οἵους περ ἐξ ἀρχῆς ὑπεθέμην.", "st": "15.75"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν διὰ βραχέων ἀπολογήσασθαι περὶ ἑκάστου, καὶ ποιῆσαι μᾶλλον ἔτι καταφανὲς ὡς ἀληθῆ καὶ τότε προεῖπον καὶ νῦν λέγω περὶ αὐτῶν. καὶ πρῶτον μὲν ποῖος γένοιτ’ ἂν λόγος ὁσιώτερος ἢ δικαιότερος τοῦ τοὺς προγόνους ἐγκωμιάζοντος ἀξίως τῆς ἀρετῆς τῆς ἐκείνων καὶ τῶν ἔργων τῶν πεπραγμένων αὐτοῖς;", "st": "15.76"}, {"sp": "N", "t": "ἔπειτα τίς ἂν πολιτικώτερος καὶ μᾶλλον πρέπων τῇ πόλει τοῦ τὴν ἡγεμονίαν ἀποφαίνοντος ἔκ τε τῶν ἄλλων εὐεργεσιῶν καὶ τῶν κινδύνων ἡμετέραν οὖσαν μᾶλλον ἢ Λακεδαιμονίων; ἔτι δὲ τίς ἂν περὶ καλλιόνων καὶ μειζόνων πραγμάτων τοῦ τοὺς Ἕλληνας ἐπί τε τὴν τῶν βαρβάρων στρατείαν παρακαλοῦντος καὶ περὶ τῆς πρὸς ἀλλήλους ὁμονοίας συμβουλεύοντος;", "st": "15.77"}, {"sp": "N", "t": "ἐν μὲν τοίνυν τῷ πρώτῳ λόγῳ περὶ τούτων τυγχάνω διειλεγμένος, ἐν δὲ τοῖς ὑστέροις περὶ ἐλαττόνων μὲν ἢ τηλικούτων, οὐ μὴν περὶ ἀχρηστοτέρων οὐδ’ ἧττον τῇ πόλει συμφερόντων. γνώσεσθε δὲ τὴν δύναμιν αὐτῶν, ἢν παραβάλλητε πρὸς ἕτερα τῶν εὐδοκιμούντων καὶ τῶν ὠφελίμων εἶναι δοκούντων.", "st": "15.78"}, {"sp": "N", "t": "οἶμαι δὴ πάντας ἂν ὁμολογῆσαι τοὺς νόμους πλείστων καὶ μεγίστων ἀγαθῶν αἰτίους εἶναι τῷ βίῳ τῶν ἀνθρώπων· ἀλλ’ ἡ μὲν τούτων χρῆσις τοῦτ’ ὠφελεῖν μόνον πέφυκε, τὰ κατὰ τὴν πόλιν καὶ τὰ συμβόλαια τὰ γιγνόμενα πρὸς ἡμᾶς αὐτούς· εἰ δὲ τοῖς λόγοις πείθοισθε τοῖς ἐμοῖς, ὅλην τὴν Ἑλλάδα καλῶς ἂν διοικοῖτε καὶ δικαίως καὶ τῇ πόλει συμφερόντως.", "st": "15.79"}, {"sp": "N", "t": "χρὴ δὲ τοὺς νοῦν ἔχοντας περὶ ἀμφότερα μὲν ταῦτα σπουδάζειν, αὐτοῖν δὲ τούτοιν τὸ μεῖζον καὶ τὸ πλέονος ἄξιον προτιμᾶν, ἔπειτα κἀκεῖνο γιγνώσκειν, ὅτι νόμους μὲν θεῖναι μυρίοι καὶ τῶν ἄλλων Ἑλλήνων καὶ τῶν βαρβάρων ἱκανοὶ γεγόνασιν, εἰπεῖν δὲ περὶ τῶν συμφερόντων ἀξίως τῆς πόλεως καὶ τῆς Ἑλλάδος οὐκ ἂν πολλοὶ δυνηθεῖεν.", "st": "15.80"}, {"sp": "N", "t": "ὧν ἕνεκα τοὺς ἔργον ποιουμένους τοὺς τοιούτους λόγους εὑρίσκειν τοσούτῳ χρὴ περὶ πλείονος ποιεῖσθαι τῶν τοὺς νόμους τιθέντων καὶ γραφόντων, ὅσῳ πέρ εἰσι σπανιώτεροι καὶ χαλεπώτεροι καὶ ψυχῆς φρονιμωτέρας δεόμενοι τυγχάνουσιν, ἄλλως τε δὴ καὶ νῦν.", "st": "15.81"}, {"sp": "N", "t": "ὅτε μὲν γὰρ ἤρχετο τὸ γένος τὸ τῶν ἀνθρώπων γίγνεσθαι καὶ συνοικίζεσθαι κατὰ πόλεις, εἰκὸς ἦν παραπλησίαν εἶναι τὴν ζήτησιν αὐτῶν· ἐπειδὴ δ’ ἐνταῦθα προεληλύθαμεν ὥστε καὶ τοὺς λόγους τοὺς εἰρημένους καὶ τοὺς νόμους τοὺς κειμένους ἀναριθμήτους εἶναι, καὶ τῶν μὲν νόμων ἐπαινεῖσθαι τοὺς ἀρχαιοτάτους τῶν δὲ λόγων τοὺς καινοτάτους, οὐκέτι τῆς αὐτῆς διανοίας ἔργον ἐστίν,", "st": "15.82"}, {"sp": "N", "t": "ἀλλὰ τοῖς μὲν τοὺς νόμους τιθέναι προαιρουμένοις προὔργου γέγονε τὸ πλῆθος τῶν κειμένων (οὐδὲν γὰρ αὐτοὺς δεῖ ζητεῖν ἑτέρους, ἀλλὰ τοὺς παρὰ τοῖς ἄλλοις εὐδοκιμοῦντας πειραθῆναι συναγαγεῖν, ὃ ῥᾳδίως ὅστις ἂν οὖν βουληθεὶς ποιήσειε), τοῖς δὲ περὶ τοὺς λόγους πραγματευομένοις διὰ τὸ προκατειλῆφθαι τὰ πλεῖστα τοὐναντίον συμβέβηκε· λέγοντες μὲν γὰρ ταὐτὰ τοῖς πρότερον εἰρημένοις ἀναισχυντεῖν καὶ ληρεῖν δόξουσι, καινὰ δὲ ζητοῦντες ἐπιπόνως εὑρήσουσι. διόπερ ἔφασκον ἀμφοτέροις μὲν ἐπαινεῖσθαι προσήκειν, πολὺ δὲ μᾶλλον τοῖς τὸ χαλεπώτερον ἐξεργάζεσθαι δυναμένοις.", "st": "15.83"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τῶν ἐπὶ τὴν σωφροσύνην καὶ τὴν δικαιοσύνην προσποιουμένων προτρέπειν ἡμεῖς ἂν ἀληθέστεροι καὶ χρησιμώτεροι φανεῖμεν ὄντες. οἱ μὲν γὰρ παρακαλοῦσιν ἐπὶ τὴν ἀρετὴν καὶ τὴν φρόνησιν τὴν ὑπὸ τῶν ἄλλων μὲν ἀγνοουμένην, ὑπ’ αὐτῶν δὲ τούτων ἀντιλεγομένην, ἐγὼ δ’ ἐπὶ τὴν ὑπὸ πάντων ὁμολογουμένην.", "st": "15.84"}, {"sp": "N", "t": "κἀκείνοις μὲν ἀπόχρη τοσοῦτον, ἢν ἐπαγαγέσθαι τινὰς τῇ δόξῃ τῇ τῶν ὀνομάτων δυνηθῶσιν εἰς τὴν αὑτῶν ὁμιλίαν, ἐγὼ δὲ τῶν μὲν ἰδιωτῶν οὐδένα πώποτε φανήσομαι παρακαλέσας ἐπ’ ἐμαυτόν, τὴν δὲ πόλιν ὅλην πειρῶμαι πείθειν τοιούτοις πράγμασιν ἐπιχειρεῖν, ἐξ ὧν αὐτοί τε εὐδαιμονήσουσι καὶ τοὺς ἄλλους Ἕλληνας τῶν παρόντων κακῶν ἀπαλλάξουσι.", "st": "15.85"}, {"sp": "N", "t": "καί τοι τὸν πάντας τοὺς πολίτας προτρέπειν προθυμούμενον πρὸς τὸ βέλτιον καὶ δικαιότερον προστῆναι τῶν Ἑλλήνων, πῶς εἰκὸς τοῦτον τοὺς συνόντας διαφθείρειν; τίς δὲ τοιούτους λόγους εὑρίσκειν δυνάμενος πονηροὺς ἂν καὶ περὶ πονηρῶν πραγμάτων ζητεῖν ἐπιχειρήσειεν, ἄλλως τε καὶ διαπεπραγμένος ἀπ’ αὐτῶν ἅπερ ἐγώ;", "st": "15.86"}, {"sp": "N", "t": "τούτων γὰρ γραφέντων καὶ διαδοθέντων καὶ δόξαν ἔσχον παρὰ πολλοῖς καὶ μαθητὰς πολλοὺς ἔλαβον, ὧν οὐδεὶς ἂν παρέμεινεν, εἰ μὴ τοιοῦτον ὄντα με κατέλαβον οἷόν περ προσεδόκησαν· νῦν δὲ τοσούτων γεγενημένων, καὶ τῶν μὲν ἔτη τρία τῶν δὲ τέτταρα συνδιαιτηθέντων, οὐδεὶς οὐδὲν φανήσεται τῶν παρ’ ἐμοὶ μεμψάμενος,", "st": "15.87"}, {"sp": "N", "t": "ἀλλ’ ἐπὶ τελευτῆς, ὅτ’ ἤδη μέλλοιεν ἀποπλεῖν ὡς τοὺς γονέας καὶ τοὺς φίλους τοὺς ἑαυτῶν, οὕτως ἠγάπων τὴν διατριβὴν ὥστε μετὰ πόθου καὶ δακρύων ποιεῖσθαι τὴν ἀπαλλαγήν. καὶ τοι πότερα χρὴ πιστεύειν ὑμᾶς τοῖς σαφῶς ἐπισταμένοις καὶ τοὺς λόγους καὶ τὸν τρόπον τὸν ἐμόν, ἢ τῷ μηδὲν μὲν εἰδότι τῶν ἐμῶν, προῃρημένῳ δὲ συκοφαντεῖν; ὃς εἰς τοσοῦτο πονηρίας καὶ τόλμης ἐλήλυθεν,", "st": "15.88"}, {"sp": "N", "t": "ὥστε γραψάμενος ὡς λόγους διδάσκω δι’ ὧν πλεονεκτήσουσι παρὰ τὸ δίκαιον ἀπόδειξιν μὲν οὐδεμίαν τούτων ἤνεγκε, λέγων δὲ διατετέλεκεν ὡς δεινόν ἐστι διαφθείρεσθαι τοὺς τηλικούτους, ὥσπερ ἀντιλέγοντός τινος περὶ τούτων, ἢ τοῦτο δέον αὐτὸν ἀποφαίνειν ὃ πάντες ὁμολογοῦσιν, ἀλλ’ οὐκ ἐκεῖνο μόνον διδάσκειν ὡς ἐγὼ τυγχάνω ταῦτα διαπραττόμενος.", "st": "15.89"}, {"sp": "N", "t": "καὶ εἰ μέν τις τοῦτον ἀπαγαγὼν ἀνδραποδιστὴν καὶ κλέπτην καὶ λωποδύτην μηδὲν μὲν αὐτὸν ἀποφαίνοι τούτων εἰργασμένον, διεξίοι δ’ ὡς δεινὸν ἕκαστόν ἐστι τῶν κακουργημάτων, ληρεῖν ἂν φαίη καὶ μαίνεσθαι τὸν κατήγορον, αὐτὸς δὲ τοιούτοις λόγοις κεχρημένος οἴεται λανθάνειν ὑμᾶς.", "st": "15.90"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι τοῦτό γε καὶ τοὺς ἀμαθεστάτους γιγνώσκειν, ὅτι δεῖ πιστὰς εἶναι καὶ μέγα δυναμένας τῶν κατηγοριῶν οὐχ αἷς ἔξεστι χρήσασθαι καὶ περὶ τῶν μηδὲν ἠδικηκότων, ἀλλ’ ἃς οὐχ οἷόν τ’ εἰπεῖν ἀλλ’ ἤ κατὰ τῶν ἡμαρτηκότων· ὧν αὐτὸς ὀλιγωρήσας οὐδὲν προσήκοντας τῇ γραφῇ λόγους εἴρηκεν·", "st": "15.91"}, {"sp": "N", "t": "ἔδει γὰρ αὐτὸν καὶ τοὺς λόγους δεικνύναι τοὺς ἐμούς, οἷς διαφθείρω τοὺς συνόντας, καὶ τοὺς μαθητὰς φράζειν τοὺς χείρους διὰ τὴν συνουσίαν τὴν ἐμὴν γεγενημένους· νῦν δὲ τούτων μὲν οὐδέτερον πεποίηκε, παραλιπὼν δὲ τὴν δικαιοτάτην τῶν κατηγοριῶν ἐξαπατᾶν ὑμᾶς ἐπεχείρησεν. ἐγὼ δ’ ἐξ αὐτῶν τούτων ἐξ ὧν περ προσήκει καὶ δίκαιόν ἐστι, ποιήσομαι τὴν ἀπολογίαν.", "st": "15.92"}, {"sp": "N", "t": "καὶ τοὺς μὲν λόγους ὀλίγῳ πρότερον ἀνέγνωμεν ὑμῖν, τοὺς δὲ κεχρημένους ἐκ μειρακίων μοι μέχρι γήρως δηλώσω, καὶ μάρτυρας ὑμῶν αὐτῶν παρέξομαι περὶ ὧν ἂν λέγω τοὺς κατὰ τὴν ἡλικίαν τὴν ἐμὴν γεγενημένους. ἤρξαντο μὲν οὖν ἐν πρώτοις Εὔνομός μοι καὶ Λυσιθείδης καὶ Κάλλιππος πλησιάζειν, μετὰ δὲ τούτους Ὀνήτωρ, Ἀντικλῆς, Φιλωνίδης, Φιλόμηλος,", "st": "15.93"}, {"sp": "N", "t": "Χαρμαντίδης. τούτους ἅπαντας ἡ πόλις χρυσοῖς στεφάνοις ἐστεφάνωσεν, οὐχ ὡς τῶν ἀλλοτρίων ἐφιεμένους, ἀλλ’ ὡς ἄνδρας ἀγαθοὺς ὄντας καὶ πολλὰ τῶν ἰδίων εἰς τὴν πόλιν ἀνηλωκότας. πρὸς οὓς ὅπως βούλεσθε θέτε με διακεῖσθαι· πρὸς γὰρ τὸ παρὸν πανταχῶς ἕξει μοι καλῶς.", "st": "15.94"}, {"sp": "N", "t": "ἤν τε γὰρ ὑπολάβητε σύμβουλον εἶναί με καὶ διδάσκαλον τούτων, δικαίως ἂν ἔχοιτέ μοι πλείω χάριν ἢ τοῖς δι’ ἀρετὴν ἐν πρυτανείῳ σιτουμένοις· τούτων μὲν γὰρ ἕκαστος αὑτὸν μόνον παρέσχε καλὸν κἀγαθόν, ἐγὼ δὲ τοσούτους τὸ πλῆθος ὅσους ὀλίγῳ πρότερον διῆλθον ὑμῖν.", "st": "15.95"}, {"sp": "N", "t": "εἴ τε τῶν μὲν πεπραγμένων ἐκείνοις μηδὲν συναίτιος ἐγενόμην, ὡς ἑταίροις δὲ καὶ φίλοις αὐτοῖς ἐχρώμην, ἱκανὴν ὑπὲρ ὧν φεύγω τὴν γραφὴν ἡγοῦμαι καὶ ταύτην εἶναι τὴν ἀπολογίαν· εἰ γὰρ τοῖς μὲν δι’ ἀρετὴν δωρεὰς εἰληφόσιν ἤρεσκον, τῷ δὲ συκοφάντῃ μὴ τὴν αὐτὴν ἔχω γνώμην, πῶς ἂν εἰκότως γνωσθείην τοὺς συνόντας διαφθείρειν;", "st": "15.96"}, {"sp": "N", "t": "ἢ πάντων γ’ ἂν εἴην δυστυχέστατος, εἰ τῶν ἄλλων ἀνθρώπων ἔκ τε τῶν ἐπιτηδευμάτων καὶ τῶν συνουσιῶν τῶν μὲν χείρω τῶν δὲ βελτίω δόξαν λαμβανόντων ἐγὼ μόνος μὴ τύχοιμι τῆς δοκιμασίας ταύτης, ἀλλὰ τοιούτοις μὲν ἀνδράσι συμβεβιωκώς, ἀνέγκλητον δ’ ἐμαυτὸν μέχρι ταυτησὶ τῆς ἡλικίας παρεσχηκώς, ὅμοιος εἶναι δόξαιμι τοῖς ἔκ τε τῶν ἐπιτηδευμάτων καὶ τῶν ἄλλων συνουσιῶν διαβεβλημένοις. ἡδέως δ’ ἂν εἰδείην τί ποτ’ ἂν ἔπαθον, εἴ τίς μοι τοιοῦτος ἦν συγγεγενημένος οἷός πέρ ἐστιν ὁ κατήγορος, ὃς μισῶν ἅπαντας τοὺς τοιούτους καὶ μισούμενος εἰς τουτονὶ καθέστηκα τὸν κίνδυνον.", "st": "15.97"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνος ὁ λόγος δικαίως ἄν με βλάψειεν, ὃν ἴσως ἄν τινες τολμήσαιεν εἰπεῖν τῶν παντάπασι πρός με δυσκόλως διακειμένων, ὡς τούτοις μὲν οἷς εἴρηκα τοσοῦτον μόνον ἐχρώμην ὅσον ὀφθῆναι διαλεγόμενος, ἕτεροι δέ τινές μοι πολλοὶ καὶ πολυπράγμονες μαθηταὶ γεγόνασιν, οὓς ἀποκρύπτομαι πρὸς ὑμᾶς. ἔχω γὰρ λόγον ὃς ἐξελέγξει καὶ διαλύσει πάσας τὰς τοιάσδε βλασφημίας· ἀξιῶ γάρ,", "st": "15.98"}, {"sp": "N", "t": "εἰ μέν τινες τῶν ἐμοὶ συγγεγενημένων ἄνδρες ἀγαθοὶ γεγόνασι περὶ τὴν πόλιν καὶ τοὺς φίλους καὶ τὸν ἴδιον οἶκον, ἐκείνους ὑμᾶς ἐπαινεῖν, ἐμοὶ δὲ μηδεμίαν ὑπὲρ τούτων χάριν ἔχειν, εἰ δὲ πονηροὶ καὶ τοιοῦτοι τὰς φύσεις οἷοι φαίνειν καὶ γράφεσθαι καὶ τῶν ἀλλοτρίων ἐπιθυμεῖν,", "st": "15.99"}, {"sp": "N", "t": "παρ’ ἐμοῦ δίκην λαμβάνειν. καίτοι τίς ἂν πρόκλησις γένοιτο ταύτης ἀνεπιφθονωτέρα, καὶ δικαιοτέρα τῆς τῶν μὲν καλῶν κἀγαθῶν οὐκ ἀμφισβητούσης, εἰ δέ τινες πονηροὶ γεγόνασιν, ὑπὲρ τούτων δίκην ὑποσχεῖν ἐθελούσης; καὶ ταῦτ’ οὐ λόγος μάτην εἰρημένος ἐστίν, ἀλλὰ παραχωρῶ καὶ τῷ κατηγόρῳ καὶ τῷ βουλομένῳ τῶν ἄλλων, εἴ τις ἔχει τινὰ φράσαι τοιοῦτον, οὐχ ὡς οὐχ ἡδέως ἄν τινών μου καταψευσαμένων, ἀλλ’ ὡς εὐθὺς φανερῶν ἐσομένων ὑμῖν καὶ τῆς ζημίας ἐκείνοις ἀλλ’ οὐκ ἐμοὶ γενησομένης.", "st": "15.100"}, {"sp": "N", "t": "περὶ μὲν οὖν ὧν φεύγω τὴν γραφὴν καὶ τοῦ μὴ διαφθείρειν τοὺς συνόντας, οὐκ οἶδ’ ὅπως ἂν σαφέστερον ἐπιδεῖξαι δυνηθείην. ἐμνήσθη δὲ καὶ τῆς πρὸς Τιμόθεόν μοι φιλίας γεγενημένης, καὶ διαβάλλειν ἡμᾶς ἀμφοτέρους ἐπεχείρησε, καὶ οὐκ ᾐσχύνθη περὶ ἀνδρὸς τετελευτηκότος καὶ πολλῶν ἀγαθῶν αἰτίου τῇ πόλει βλασφήμους καὶ λίαν ἀσελγεῖς λόγους εἰπών. ἐγὼ δ’ ᾤμην μέν,", "st": "15.101"}, {"sp": "N", "t": "εἰ καὶ φανερῶς ἐξηλεγχόμην ἀδικῶν, διὰ τὴν πρὸς ἐκεῖνον φιλίαν σώζεσθαί μοι προσήκειν· ἐπειδὴ δὲ Λυσίμαχος καὶ τοῖς τοιούτοις ἐπιχειρεῖ με βλάπτειν ἐξ ὧν δικαίως ἂν ὠφελοίμην, ἀναγκαίως ἔχει διαλεχθῆναι περὶ αὐτῶν. διὰ τοῦτο δ’ οὐχ ἅμα περὶ τούτου καὶ τῶν ἄλλων ἐπιτηδείων ἐποιησάμην τὴν μνείαν, ὅτι πολὺ τὰ πράγματα διέφερεν αὐτῶν.", "st": "15.102"}, {"sp": "N", "t": "περὶ μὲν γὰρ ἐκείνων οὐδὲν φλαῦρον εἰπεῖν ὁ κατήγορος ἐτόλμησε, περὶ δὲ τὴν Τιμοθέου κατηγορίαν μᾶλλον ἐσπούδασεν ἢ περὶ ὧν ἀπήνεγκε τὴν γραφήν· ἔπειθ’ οἱ μὲν ὀλίγων ἐπεστάτησαν, τῶν δ’ ἑκάστῳ προσταχθέντων οὕτως ἐπεμελήθησαν ὥστε τυχεῖν τῆς τιμῆς τῆς ὀλίγῳ πρότερον ὑπ’ ἐμοῦ λεχθείσης, ὁ δὲ πολλῶν καὶ μεγάλων πραγμάτων καὶ πολὺν χρόνον κατέστη κύριος. ὥστ’ οὐκ ἂν ἥρμοσεν ἅμα περὶ τούτου καὶ τῶν ἄλλων χρήσασθαι τοῖς λόγοις, ἀλλ’ ἀναγκαίως εἶχεν οὕτω διελέσθαι καὶ διατάξασθαι περὶ αὐτῶν.", "st": "15.103"}, {"sp": "N", "t": "χρὴ δὲ τὸν ὑπὲρ ἐκείνου λόγον οὐκ ἀλλότριον εἶναι νομίζειν τοῖς ἐνεστῶσι πράγμασιν, οὐδ’ ἐμὲ λέγειν ἔξω τῆς γραφῆς· τοῖς μὲν γὰρ ἰδιώταις ὑπὲρ ὧν ἕκαστος ἔπραξε προσήκει διαλεχθεῖσι καταβαίνειν ἢ δοκεῖν περιεργάζεσθαι, τοῖς δ’ ὑπολαμβανομένοις συμβούλοις εἶναι καὶ διδασκάλοις ὁμοίως ὑπὲρ τῶν συγγεγενημένων ὥσπερ ὑπὲρ αὑτῶν ἀναγκαῖον ποιεῖσθαι τὴν ἀπολογίαν, ἄλλως τ’ ἢν καὶ τύχῃ τις διὰ τὴν αἰτίαν ταύτην κρινόμενος· ὅ περ ἐμοὶ συμβέβηκεν.", "st": "15.104"}, {"sp": "N", "t": "ἑτέρῳ μὲν οὖν ἀπέχρησεν ἂν τοῦτ’ εἰπεῖν, ὡς οὐ δίκαιόν ἐστι μετέχειν εἴ τι Τιμόθεος πράττων μὴ κατώρθωσεν· οὐδὲ γὰρ τῶν δωρεῶν οὐδὲ τῶν τιμῶν οὐδεὶς αὐτῷ μετέδωκε τῶν ἐκείνῳ ψηφισθεισῶν, ἀλλ’ οὐδ’ ἐπαινέσαι τῶν ῥητόρων οὐδεὶς ἠξίωσεν ὡς σύμβουλον γεγενημένον· εἶναι δὲ δίκαιον ἢ καὶ τῶν ἀγαθῶν κοινωνεῖν ἢ μηδὲ τῶν ἀτυχιῶν ἀπολαύειν.", "st": "15.105"}, {"sp": "N", "t": "ἐγὼ δὲ ταῦτα μὲν αἰσχυνθείην ἂν εἰπεῖν, τὴν αὐτὴν δὲ ποιοῦμαι πρόκλησιν ἥν περ καὶ περὶ τῶν ἄλλων· ἀξιῶ γάρ, εἰ μὲν κακὸς ἀνὴρ γέγονε Τιμόθεος καὶ πολλὰ περὶ ὑμᾶς ἐξήμαρτε, μετέχειν καὶ δίκην διδόναι καὶ πάσχειν ὅμοια τοῖς ἀδικοῦσιν· ἢν δ’ ἐπιδειχθῇ καὶ πολίτης ὢν ἀγαθὸς καὶ στρατηγὸς τοιοῦτος οἷος οὐδεὶς ἄλλος ὧν ἡμεῖς ἴσμεν, ἐκεῖνον μὲν οἶμαι δεῖν ὑμᾶς ἐπαινεῖν καὶ χάριν ἔχειν αὐτῷ, περὶ δὲ ταυτησὶ τῆς γραφῆς ἐκ τῶν ἐμοὶ πεπραγμένων, ὅ τι ἂν ὑμῖν δίκαιον εἶναι δοκῇ, τοῦτο γιγνώσκειν.", "st": "15.106"}, {"sp": "N", "t": "ἀθροώτατον μὲν οὖν τοῦτ’ εἰπεῖν ἔχω περὶ Τιμοθέου καὶ μάλιστα καθ’ ἁπάντων, ὅτι τοσαύτας ᾕρηκε πόλεις κατὰ κράτος ὅσας οὐδεὶς πώποτε τῶν ἐστρατηγηκότων, οὔτε τῶν ἐκ ταύτης τῆς πόλεως οὔτε τῶν ἐκ τῆς ἄλλης Ἑλλάδος, καὶ τούτων ἐνίας, ὧν ληφθεισῶν ἅπας ὁ τόπος ὁ περιέχων οἰκεῖος ἠναγκάσθη τῇ πόλει γενέσθαι· τηλικαύτην ἑκάστη δύναμιν εἶχε.", "st": "15.107"}, {"sp": "N", "t": "τίς γὰρ οὐκ οἶδε Κόρκυραν μὲν ἐν ἐπικαιροτάτῳ καὶ κάλλιστα κειμένην τῶν περὶ Πελοπόννησον, Σάμον δὲ τῶν ἐν Ἰωνίᾳ, Σηστὸν δὲ καὶ Κριθώτην τῶν ἐν Ἑλλησπόντῳ, πόντῳ, Ποτίδαιαν δὲ καὶ Τορώνην τῶν ἐπὶ Θρᾴκης; ἃς ἐκεῖνος ἁπάσας κτησάμενος παρέδωκεν ὑμῖν, οὐ δαπάναις μεγάλαις, οὐδὲ τοὺς ὑπάρχοντας συμμάχους λυμηνάμενος, οὐδὲ πολλὰς ὑμᾶς εἰσφορὰς ἀναγκάσας εἰσενεγκεῖν,", "st": "15.108"}, {"sp": "N", "t": "ἀλλ’ εἰς μὲν τὸν περίπλουν τὸν περὶ Πελοπόννησον τρία καὶ δέκα μόνον τάλαντα δούσης αὐτῷ τῆς πόλεως καὶ τριήρεις πεντήκοντα Κόρκυραν εἷλε, πόλιν ὀγδοήκοντα τριήρεις κεκτημένην, καὶ περὶ τὸν αὐτὸν χρόνον Λακεδαιμονίους ἐνίκησε ναυμαχῶν, καὶ ταύτην αὐτοὺς ἠνάγκασε συνθέσθαι τὴν εἰρήνην, ἣ τοσαύτην μεταβολὴν ἑκατέρᾳ τῶν πόλεων ἐποίησεν,", "st": "15.109"}, {"sp": "N", "t": "ὥσθ’ ἡμᾶς μὲν ἀπ’ ἐκείνης τῆς ἡμέρας θύειν αὐτῇ καθ’ ἕκαστον τὸν ἐνιαυτὸν ὡς οὐδεμιᾶς ἄλλης οὕτω τῇ πόλει συνενεγκούσης, Λακεδαιμονίων δὲ μετ’ ἐκεῖνον τὸν χρόνον μηδ’ ὑφ’ ἑνὸς ἑωρᾶσθαι μήτε ναυτικὸν ἐντὸς Μαλέας περιπλέον μήτε πεζὸν στρατόπεδον διὰ τοῦ Ἰσθμοῦ πορευόμενον, ὅπερ αὐτοῖς τῆς περὶ Λεῦκτρα συμφορᾶς εὕροι τις ἂν αἴτιον γεγενημένον.", "st": "15.110"}, {"sp": "N", "t": "μετὰ δὲ ταύτας τὰς πράξεις ἐπὶ Σάμον στρατεύσας, ἣν Περικλῆς ὁ μεγίστην ἐπὶ σοφίᾳ καὶ δικαιοσύνῃ καὶ σωφροσύνῃ δόξαν εἰληφὼς ἀπὸ διακοσίων νεῶν καὶ χιλίων ταλάντων κατεπολέμησε, ταύτην οὔτε πλέον οὔτ’ ἔλαττον παρ’ ὑμῶν λαβὼν οὔτε παρὰ τῶν συμμάχων ἐκλέξας, ἐν δέκα μησὶν ἐξεπολιόρκησεν ὀκτακισχιλίοις πελτασταῖς καὶ τριήρεσι τριάκοντα, καὶ τούτοις ἅπασιν ἐκ τῆς πολεμίας τὸν μισθὸν ἀπέδωκε.", "st": "15.111"}, {"sp": "N", "t": "καί τοι τοιοῦτον ἔργον ἄν τις ἄλλος φανῇ πεποιηκώς, ὁμολογῶ ληρεῖν, ὅτι διαφερόντως ἐπαινεῖν ἐπιχειρῶ τὸν οὐδὲν περιττότερον τῶν ἄλλων διαπεπραγμένον. ἐντεῦθεν τοίνυν ἀναπλεύσας Σηστὸν καὶ Κριθώτην ἔλαβε, καὶ τὸν ἄλλον χρόνον ἀμελουμένης Χερρονήσου προσέχειν ὑμᾶς αὐτῇ τὸν νοῦν ἐποίησε. τὸ δὲ τελευταῖον Ποτίδαιαν,", "st": "15.112"}, {"sp": "N", "t": "εἰς ἣν ἡ πόλις τετρακόσια καὶ δισχίλια τάλαντα τὸ πρότερον ἀνήλωσε, ταύτην εἷλεν ἀπὸ τῶν χρημάτων ὧν αὐτὸς ἐπόρισε καὶ τῶν συντάξεων τῶν ἀπὸ Θρᾴκης· καὶ προσέτι Χαλκιδεῖς ἅπαντας κατεπολέμησεν. εἰ δὲ δεῖ μὴ καθ’ ἕκαστον ἀλλὰ διὰ βραχέων εἰπεῖν, τεττάρων καὶ εἴκοσι πόλεων κυρίους ὑμᾶς ἐποίησεν ἐλάττω δαπανήσας ὧν οἱ πατέρες ἡμῶν εἰς τὴν Μηλίων πολιορκίαν ἀνήλωσαν.", "st": "15.113"}, {"sp": "N", "t": "ἠβουλόμην δ’ ἄν,ὥσπερ ἐξαριθμῆσαι τὰς πράξεις ῥᾴδιον γέγονεν, οὕτως οἷόν τ’ εἶναι συντόμως δηλῶσαι τοὺς καιροὺς ἐν οἷς ἕκαστα τούτων ἐπράχθη, καὶ τὰ τῆς πόλεως ὡς εἶχε, καὶ τὴν τῶν πολεμίων δύναμιν· πολὺ γὰρ ἂν ὑμῖν αἵ τ’ εὐεργεσίαι μείζους κἀκεῖνος πλείονος ἄξιος ἔδοξεν εἶναι. νῦν δὲ ταῦτα μὲν ἐάσω διὰ τὸ πλῆθος.", "st": "15.114"}, {"sp": "N", "t": "ἡγοῦμαι δ’ ὑμᾶς ἡδέως ἂν ἀκοῦσαι διὰ τί ποτε τῶν μὲν εὐδοκιμούντων ἀνδρῶν παρ’ ὑμῖν καὶ πολεμικῶν εἶναι δοκούντων οὐδὲ κώμην ἔνιοι λαβεῖν ἠδυνήθησαν, Τιμόθεος δ’ οὔτε τὴν τοῦ σώματος φύσιν ἔχων ἐρρωμένην οὔτ’ ἐν τοῖς στρατοπέδοις τοῖς πλανωμένοις κατατετριμμένος, ἀλλ’ ὁ μεθ’ ὑμῶν πολιτευόμενος τηλικαῦτα διεπράξατο τὸ μέγεθος. ἔστι δ’ ὁ λόγος ὁ περὶ τούτων φιλαπεχθήμων μέν, ῥηθῆναι δ’ οὐκ ἀσύμφορος. ἐκεῖνος γὰρ τούτῳ τῶν ἄλλων διήνεγκεν,", "st": "15.115"}, {"sp": "N", "t": "ὅτι περὶ τῶν Ἑλληνικῶν καὶ συμμαχικῶν πραγμάτων καὶ τῆς ἐπιμελείας τῆς τούτων οὐ τὴν αὐτὴν ὑμῖν γνώμην εἶχεν. ὑμεῖς μὲν γὰρ χειροτονεῖτε στρατηγοὺς τοὺς εὐρωστοτάτους τοῖς σώμασι καὶ πολλάκις ἐν τοῖς ξενικοῖς στρατεύμασι γεγενημένους, ὡς διὰ τούτων διαπραξόμενοί τι τῶν δεόντων. ὁ δὲ τοῖς μὲν τοιούτοις λοχαγοῖς ἐχρῆτο καὶ ταξιάρχοις,", "st": "15.116"}, {"sp": "N", "t": "αὐτὸς δὲ περὶ ταῦτα δεινὸς ἦν, περὶ ἅπερ χρὴ φρόνιμον εἶναι τὸν στρατηγὸν τὸν ἀγαθόν. Ἔστι δὲ ταῦτα τίνα δύναμιν ἔχοντα; δεῖ γὰρ οὐχ ἁπλῶς εἰπεῖν, ἀλλὰ σαφῶς φράσαι περὶ αὐτῶν. πρῶτον μὲν δύνασθαι γνῶναι πρὸς τίνας πολεμητέον καὶ τίνας συμμάχους ποιητέον· ἀρχὴ γὰρ αὕτη στρατηγίας ἐστίν, ἧς ἢν διαμάρτῃ τις, ἀνάγκη τὸν πόλεμον ἀσύμφορον καὶ χαλεπὸν καὶ περίεργον εἶναι.", "st": "15.117"}, {"sp": "N", "t": "περὶ τοίνυν τὴν τοιαύτην προαίρεσιν οὐ μόνον οὐδεὶς τοιοῦτος γέγονεν, ἀλλ’ οὐδὲ παραπλήσιος. ῥᾴδιον δ’ ἐξ αὐτῶν τῶν ἔργων γνῶναι· πλείστους γὰρ πολέμους ἄνευ τῆς πόλεως ἀνελόμενος, ἅπαντας τούτους κατώρθωσε καὶ δικαίως ἅπασι τοῖς Ἕλλησιν ἔδοξεν αὐτοὺς ποιήσασθαι. καί τοι τοῦ καλῶς βουλεύσασθαι τίς ἂν ἀπόδειξιν ἔχοι σαφεστέραν καὶ μείζω ταύτης παρασχέσθαι;", "st": "15.118"}, {"sp": "N", "t": "δεύτερον τί προσήκει τὸν στρατηγὸν τὸν ἀγαθόν; στρατόπεδον συναγαγεῖν ἁρμόττον τῷ πολέμῳ τῷ παρόντι, καὶ τοῦτο συντάξαι καὶ χρήσασθαι συμφερόντως. ὡς μὲν τοίνυν ἠπίστατο χρῆσθαι καλῶς, αἱ πράξεις αὐταὶ δεδηλώκασιν· ὡς δὲ καὶ πρὸς τὸ παρασκευάσασθαι μεγαλοπρεπῶς καὶ τῆς πόλεως ἀξίως ἁπάντων διήνεγκεν, οὐδὲ τῶν ἐχθρῶν οὐδεὶς ἂν ἄλλως εἰπεῖν τολμήσειεν.", "st": "15.119"}, {"sp": "N", "t": "ἔτι τοίνυν πρὸς τούτοις ἀπορίας ἐνεγκεῖν στρατοπέδου καὶ πενίας, καὶ πάλιν εὐπορίας εὑρεῖν, τίς οὐκ ἂν τῶν συνεστρατευμένων πρὸς ἀμφότερα ταῦτα διαφέρειν ἐκεῖνον προκρίνειεν; συνίσασι γὰρ αὐτῷ κατὰ μὲν ἀρχὰς τῶν πολέμων διὰ τὸ μηδὲν παρὰ τῆς πόλεως λαμβάνειν εἰς τὰς ἐσχάτας ἐνδείας καθιστάμενον, ἐκ δὲ τούτων εἰς τοῦτο τὰ πράγματα περιιστάναι δυνάμενον, ὥστε καὶ τῶν πολεμίων περιγίγνεσθαι καὶ τοῖς στρατιώταις ἐντελεῖς ἀποδιδόναι τοὺς μισθούς.", "st": "15.120"}, {"sp": "N", "t": "οὕτω τοίνυν τούτων μεγάλων ὄντων καὶ σφόδρα κατεπειγόντων, ἐπὶ τοῖς ἐχομένοις δικαίως ἄν τις αὐτὸν ἔτι μᾶλλον ἐπαινέσειεν. ὁρῶν γὰρ ὑμᾶς τούτους μόνους ἄνδρας νομίζοντας, τοὺς ἀπειλοῦντας καὶ τοὺς ἐκφοβοῦντας τὰς ἄλλας πόλεις καὶ τοὺς ἀεί τι νεωτερίζοντας ἐν τοῖς συμμάχοις, οὐκ ἐπηκολούθησε ταῖς ὑμετέραις γνώμαις, οὐδ’ ἠβουλήθη βλάπτων τὴν πόλιν εὐδοκιμεῖν, ἀλλὰ τοῦτ’ ἐφιλοσόφει καὶ τοῦτ’ ἔπραττεν, ὅπως μηδεμία τῶν πόλεων αὐτὸν φοβήσεται τῶν Ἑλληνίδων, ἀλλὰ πᾶσαι θαρρήσουσι πλὴν τῶν ἀδικουσῶν.", "st": "15.121"}, {"sp": "N", "t": "ἠπίστατο γὰρ τούς τε δεδιότας ὅτι μισοῦσι δι’ οὓς ἂν τοῦτο πεπονθότες τυγχάνωσι, τήν τε πόλιν διὰ μὲν τὴν φιλίαν τὴν τῶν ἄλλων εὐδαιμονεστάτην καὶ μεγίστην γενομένην, διὰ δὲ τὸ μῖσος μικρὸν ἀπολιποῦσαν τοῦ μὴ ταῖς ἐσχάταις συμφοραῖς περιπεσεῖν. ὧν ἐνθυμούμενος τῇ μὲν δυνάμει τῇ τῆς πόλεως τοὺς πολεμίους κατεστρέφετο, τῷ δ’ ἤθει τῷ αὑτοῦ τὴν εὔνοιαν τὴν τῶν ἄλλων προσήγετο, νομίζων τοῦτο στρατήγημα μεῖζον εἶναι καὶ κάλλιον ἢ πολλὰς πόλεις ἑλεῖν καὶ πολλάκις νικῆσαι μαχόμενος.", "st": "15.122"}, {"sp": "N", "t": "οὕτω δ’ ἐσπούδαζε περὶ τὸ μηδεμίαν τῶν πόλεων μηδὲ μικρὰν ὑποψίαν περὶ αὐτοῦ λαβεῖν ὡς ἐπιβουλεύοντος, ὥσθ’ ὁπότε ὁπότε μέλλοι τινὰ παραπλεῖν τῶν μὴ τὰς συντάξεις διδουσῶν, πέμψας προηγόρευε τοῖς ἄρχουσιν, ἵνα μὴ πρὸ τῶν λιμένων ἐξαίφνης ὀφθεὶς εἰς θόρυβον καὶ ταραχὴν αὐτοὺς καταστήσειεν.", "st": "15.123"}, {"sp": "N", "t": "εἰ δὲ τύχοι καθορμισθεὶς πρὸς τὴν χώραν, οὐκ ἂν ἐφῆκε τοῖς στρατιώταις ἁρπάζειν καὶ κλέπτειν καὶ πορθεῖν τὰς οἰκίας, ἀλλὰ τοσαύτην εἶχεν ἐπιμέλειαν ὑπὲρ τοῦ μηδὲν γίγνεσθαι τοιοῦτον, ὅσην περ οἱ δεσπόται τῶν χρημάτων· οὐ γὰρ τούτῳ προσεῖχε τὸν νοῦν, ὅπως ἐκ τῶν τοιούτων αὐτὸς εὐδοκιμήσει παρὰ τοῖς στρατιώταις, ἀλλ’ ὅπως ἡ πόλις παρὰ τοῖς Ἕλλησιν.", "st": "15.124"}, {"sp": "N", "t": "πρὸς δὲ τούτοις τὰς δοριαλώτους τῶν πόλεων οὕτω πράως διῴκει καὶ νομίμως ὡς οὐδεὶς ἄλλος τὰς συμμαχίδας, ἡγούμενος, εἰ τοιοῦτος ὢν φαίνοιτο περὶ τοὺς πολεμήσαντας, τὴν μεγίστην πίστιν ἔσεσθαι δεδωκὼς ὡς οὐδέποτ’ ἂν περί γε τοὺς ἄλλους ἐξαμαρτεῖν τολμήσειεν.", "st": "15.125"}, {"sp": "N", "t": "τοιγάρτοι διὰ τὴν δόξαν τὴν ἐκ τούτων γιγνομένην πολλαὶ τῶν πόλεων τῶν πρὸς ὑμᾶς δυσκόλως ἐχουσῶν ἀναπεπταμέναις αὐτὸν ἐδέχοντο ταῖς πύλαις· ἐν αἷς ἐκεῖνος οὐδεμίαν ταραχὴν ἐποίησεν, ἀλλ’ ὥσπερ οἰκουμένας αὐτὰς εἰσιὼν κατέλαβεν, οὕτως ἐξιὼν κατέλειπεν.", "st": "15.126"}, {"sp": "N", "t": "κεφάλαιον δὲ πάντων τούτων· εἰθισμένων γὰρ τὸν ἄλλον χρόνον πολλῶν γίγνεσθαι καὶ δεινῶν ἐν τοῖς Ἕλλησιν, ἐπὶ τῆς ἐκείνου στρατηγίας οὐδεὶς ἂν οὔτ’ ἀναστάσεις εὕροι γεγενημένας οὔτε πολιτειῶν μεταβολὰς οὔτε σφαγὰς καὶ φυγὰς οὕτως ἄλλ’ οὐδὲν τῶν κακῶν τῶν ἀνηκέστων, ἀλλ’ οὕτως αἱ τοιαῦται συμφοραὶ κατ’ ἐκεῖνον τὸν χρόνον ἐλώφησαν, ὥστε μόνος ὧν ἡμεῖς μνημονεύομεν ἀνέγκλητον τὴν πόλιν τοῖς Ἕλλησι παρέσχε.", "st": "15.127"}, {"sp": "N", "t": "καί τοι χρὴ στρατηγὸν ἄριστον νομίζειν οὐκ εἴ τις μιᾷ τύχῃ τηλικοῦτόν τι κατώρθωσεν ὥσπερ Λύσανδρος, ὃ μηδενὶ τῶν ἄλλων διαπράξασθαι συμβέβηκεν, ἀλλ’ ὅστις ἐπὶ πολλῶν καὶ παντοδαπῶν καὶ δυσκόλων πραγμάτων ὀρθῶς ἀεὶ πράττων καὶ νοῦν ἐχόντως διατετέλεκεν· ὅπερ Τιμοθέῳ συμβέβηκεν.", "st": "15.128"}, {"sp": "N", "t": "οἶμαι οὖν ὑμῶν τοὺς πολλοὺς θαυμάζειν τὰ λεγόμενα καὶ νομίζειν τὸν ἔπαινον τὸν ἐκείνου κατηγορίαν εἶναι τῆς πόλεως, εἰ τοσαύτας μὲν πόλεις ἑλόντα μηδεμίαν δ’ ἀπολέσαντα περὶ προδοσίας ἔκρινε, καὶ πάλιν εἰ διδόντος εὐθύνας αὐτοῦ, καὶ τὰς μὲν πράξεις Ἰφικράτους ἀναδεχομένου, τὸν δ’ ὑπὲρ τῶν χρημάτων λόγον Μενεσθέως, τούτους μὲν ἀπέλυσε, Τιμόθεον δὲ τοσούτοις ἐζημίωσε χρήμασιν ὅσοις οὐδένα πώποτε τῶν προγεγενημένων.", "st": "15.129"}, {"sp": "N", "t": "ἔχει δ’ οὕτως· βούλομαι γὰρ καὶ τὸν ὑπὲρ τῆς πόλεως λόγον εἰπεῖν. εἰ μὲν ὑμεῖς πρὸς αὐτὸ τὸ δίκαιον ἀποβλέποντες σκέψεσθε περὶ τούτων, οὐκ ἔστιν ὅπως οὐ δεινὰ καὶ σχέτλια πᾶσιν εἶναι δόξει τὰ πεπραγμένα περὶ Τιμόθεον· ἢν δ’ ἀναλογίσησθε τὴν ἄγνοιαν ὅσην ἔχομεν πάντες ἄνθρωποι, καὶ τοὺς φθόνους τοὺς ἐπιγιγνομένους ἡμῖν, ἔτι δὲ τὰς ταραχὰς καὶ τὴν τύρβην ἐν ᾗ ζῶμεν, οὐδὲν τούτων ἀλόγως οὐδ’ ἔξω τῆς ἀνθρωπίνης φύσεως εὑρεθήσεται γεγενημένον, ἀλλὰ καὶ Τιμόθεος μέρος τι συμβεβλημένος τοῦ μὴ κατὰ τρόπον γνωσθῆναι περὶ αὐτῶν.", "st": "15.130"}, {"sp": "N", "t": "ἐκεῖνος γὰρ οὔτε μισόδημος ὢν οὔτε μισάνθρωπος οὔθ’ ὑπερήφανος, οὔτ’ ἄλλ’ οὐδὲν ἔχων τῶν τοιούτων κακῶν, διὰ τὴν μεγαλοφροσύνην τὴν τῇ στρατηγίᾳ μὲν συμφέρουσαν, πρὸς δὲ τὰς χρείας τῶν ἀεὶ προσπιπτόντων οὐχ ἁρμόττουσαν, ἅπασιν ἔδοξεν ἔνοχος εἶναι τοῖς προειρημένοις· οὕτω γὰρ ἀφυὴς ἦν πρὸς τὴν τῶν ἀνθρώπων θεραπείαν ὥσπερ δεινὸς περὶ τὴν τῶν πραγμάτων ἐπιμέλειαν.", "st": "15.131"}, {"sp": "N", "t": "καί τοι πολλάκις καὶ παρ’ ἐμοῦ τοιούτους λόγους ἤκουσεν, ὡς χρὴ τοὺς πολιτευομένους καὶ βουλομένους ἀρέσκειν προαιρεῖσθαι μὲν τῶν τε πράξεων τὰς ὠφελιμωτάτας καὶ βελτίστας καὶ τῶν λόγων τοὺς ἀληθεστάτους καὶ δικαιοτάτους, οὐ μὴν ἀλλὰ κἀκεῖνο παρατηρεῖν καὶ σκοπεῖν, ὅπως ἐπιχαρίτως καὶ φιλανθρώπως ἅπαντα φανήσονται καὶ λέγοντες καὶ πράττοντες, ὡς οἱ τούτων ὀλιγωροῦντες ἐπαχθέστεροι καὶ βαρύτεροι δοκοῦσιν εἶναι τοῖς συμπολιτευομένοις.", "st": "15.132"}, {"sp": "N", "t": "“ὁρᾷς δὲ τὴν φύσιν τὴν τῶν πολλῶν ὡς διάκειται πρὸς τὰς ἡδονάς, καὶ διότι μᾶλλον φιλοῦσι τοὺς πρὸς χάριν ὁμιλοῦντας ἢ τοὺς εὖ ποιοῦντας, καὶ τοὺς μετὰ φαιδρότητος καὶ φιλανθρωπίας φενακίζοντας ἢ τοὺς μετ’ ὄγκου καὶ σεμνότητος ὠφελοῦντας. ὧν οὐδέν σοι μεμέληκεν, ἀλλ’ ἢν ἐπιεικῶς τῶν ἔξω πραγμάτων ἐπιμεληθῇς, οἴει σοι καὶ τοὺς ἐνθάδε πολιτευομένους καλῶς ἕξειν.", "st": "15.133"}, {"sp": "N", "t": "τὸ δ’ οὐχ οὕτως ἀλλὰ τοὐναντίον φιλεῖ συμβαίνειν. ἢν γὰρ τούτοις ἀρέσκῃς, ἅπαν ὅ τι ἂν πράξῃς οὐ πρὸς τὴν ἀλήθειαν κρινοῦσιν ἀλλὰ πρὸς τὸ σοὶ συμφέρον ὑπολήψονται, καὶ τὰ μὲν ἁμαρτανόμενα παρόψονται, τὸ δὲ κατορθωθὲν οὐρανόμηκες ποιήσουσιν· ἡ γὰρ εὔνοια πάντας οὕτω διατίθησιν.", "st": "15.134"}, {"sp": "N", "t": "“ἣν σὺ τῇ μὲν πόλει παρὰ τῶν ἄλλων ἐκ παντὸς τρόπου κτήσασθαι ζητεῖς, ἡγούμενος μέγιστον εἶναι τῶν ἀγαθῶν, αὐτὸς δὲ σαυτῷ παρὰ τῆς πόλεως οὐκ οἴει δεῖν τὴν αὐτὴν ταύτην παρασκευάζειν, ἀλλὰ πλείστων ἀγαθῶν αἴτιος γεγενημένος χεῖρον διάκεισαι τῶν οὐδὲν ἄξιον λόγου διαπεπραγμένων.", "st": "15.135"}, {"sp": "N", "t": "“εἰκότως· οἱ μὲν γὰρ τοὺς ῥήτορας καὶ τοὺς ἐν τοῖς ἰδίοις συλλόγοις λογοποιεῖν δυναμένους καὶ πάντα προσποιουμένους εἰδέναι θεραπεύουσι, σὺ δ’ οὐ μόνον ἀμελεῖς, ἀλλὰ καὶ πολεμεῖς τοῖς μέγιστον ἀεὶ δυναμένοις αὐτῶν. “καί τοι πόσους οἴει διὰ τὰς τούτων ψευδολογίας τοὺς μὲν συμφοραῖς περιπεπτωκέναι, τοὺς δ’ ἀτίμους εἶναι; πόσους δὲ τῶν προγεγενημένων ἀνωνύμους εἶναι; πολὺ σπουδαιοτέρους καὶ πλέονος ἀξίους γεγενημένους τῶν ᾀδομένων καὶ τραγῳδουμένων;", "st": "15.136"}, {"sp": "N", "t": "ἀλλ’ οἱ μέν, οἶμαι, ποιητῶν ἔτυχον καὶ λογοποιῶν, οἱ δ’ οὐκ ἔσχον τοὺς ὑμνήσοντας. ἢν οὖν ἐμοὶ πείθῃ καὶ νοῦν ἔχῃς, οὐ καταφρονήσεις τῶν ἀνδρῶν τούτων, οἷς τὸ πλῆθος εἴθισται πιστεύειν οὐ μόνον περὶ ἑνὸς ἑκάστου τῶν πολιτῶν ἀλλὰ καὶ περὶ ὅλων τῶν πραγμάτων, ἀλλ’ ἐπιμέλειάν τινα ποιήσει καὶ θεραπείαν αὐτῶν, ἵν’ εὐδοκιμήσῃς δι’ ἀμφότερα, καὶ διὰ τὰς σαυτοῦ πράξεις καὶ διὰ τοὺς τούτων λόγους.”", "st": "15.137"}, {"sp": "N", "t": "ταῦτα δ’ ἀκούων ὀρθῶς μὲν ἔφασκέ με λέγειν, οὐ μὴν οἷός τ’ ἦν τὴν φύσιν μεταβαλεῖν, ἀλλ’ ἦν μὲν καλὸς κἀγαθὸς ἀνὴρ καὶ τῆς πόλεως καὶ τῆς Ἑλλάδος ἄξιος, οὐ μὴν σύμμετρός γε τοῖς τοιούτοις τῶν ἀνθρώπων, ὅσοι τοῖς ὑπὲρ αὑτοὺς πεφυκόσιν ἀχθόμενοι τυγχάνουσι. τοιγαροῦν οἱ μὲν ῥήτορες ἔργον εἶχον αἰτίας περὶ αὐτοῦ πολλὰς καὶ ψευδεῖς πλάττειν, τὸ δὲ πλῆθος ἀποδέχεσθαι τὰς ὑπὸ τούτων λεγομένας.", "st": "15.138"}, {"sp": "N", "t": "περὶ ὧν ἡδέως ἂν ἀπελογησάμην, εἰ καιρὸν εἶχον· οἶμαι γὰρ ἂν ὑμᾶς ἀκούσαντας μισῆσαι τούς τε προαγαγόντας τὴν πόλιν ἐπὶ τὴν ὀργὴν τὴν πρὸς ἐκεῖνον καὶ τοὺς φλαῦρόν τι περὶ αὐτοῦ λέγειν τολμῶντας. νῦν δὲ ταῦτα μὲν ἐάσω, περὶ ἐμαυτοῦ δὲ καὶ τῶν ἐνεστώτων πραγμάτων πάλιν ποιήσομαι τοὺς λόγους.", "st": "15.139"}, {"sp": "N", "t": "ἀπορῶ δ’ ὅ τι χρήσομαι τοῖς ὑπολοίποις, καὶ τίνος πρώτου μνησθῶ καὶ ποίου δευτέρου· τὸ γὰρ ἐφεξῆς με λέγειν διαπέφευγεν. ἴσως μὲν οὖν ἀναγκαῖόν ἐστιν, ὡς ἂν ἕκαστον τύχῃ προσπεσόν, οὕτως εἰπεῖν περὶ αὐτῶν· ἃ δ’ οὖν μοι νῦν ἐπελήλυθε, καὶ περὶ ὧν ἐγὼ μὲν ἐνόμιζον εἶναι δηλωτέον, ἄλλος δέ τίς μοι συνεβούλευε μὴ λέγειν, οὐκ ἀποκρύψομαι πρὸς ὑμᾶς.", "st": "15.140"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἀπήνεγκε τὴν γραφήν, ἐσκόπουν περὶ αὐτῶν τούτων ὥσπερ ἂν ὑμῶν ἕκαστος, καὶ τόν τε βίον τὸν ἐμαυτοῦ καὶ τὰς πράξεις ἐξήταζον, καὶ πλεῖστον χρόνον περὶ τὰς τοιαύτας διέτριβον ἐφ’ αἷς ᾠόμην ἐπαινεῖσθαί με προσήκειν. ἀκροώμενος δέ τις τῶν ἐπιτηδείων ἐτόλμησεν εἰπεῖν πρός με λόγον πάντων σχετλιώτατον, ὡς ἄξια μὲν εἴη τὰ λεγόμενα φιλοτιμίας, οὐ μὴν ἀλλ’ αὐτός γε δεδιέναι ταῦτα μάλιστα, μὴ πολλοὺς λυπήσῃ τῶν ἀκουόντων.", "st": "15.141"}, {"sp": "N", "t": "“οὕτω γάρ” ἔφη “τινὲς ὑπὸ τοῦ φθόνου καὶ τῶν ἀποριῶν ἐξηγρίωνται καὶ δυσμενῶς ἔχουσιν, ὥστ’ οὐ ταῖς πονηρίαις ἀλλὰ ταῖς εὐπραγίαις πολεμοῦσι, καὶ μισοῦσιν οὐ μόνον τῶν ἀνθρώπων τοὺς ἐπιεικεστάτους, ἀλλὰ καὶ τῶν ἐπιτηδευμάτων τὰ βέλτιστα, καὶ πρὸς τοῖς ἄλλοις κακοῖς τοῖς μὲν ἀδικοῦσι συναγωνίζονται καὶ συγγνώμην ἔχουσιν, οἷς δ’ ἂν φθονήσωσιν ἀπολλύουσιν, ἤν περ δυνηθῶσι.", "st": "15.142"}, {"sp": "N", "t": "ταῦτα δὲ δρῶντες οὐκ ἀγνοοῦσι περὶ ὧν τὴν ψῆφον οἴσουσιν, ἀλλ’ ἀδικήσειν μὲν ἐλπίζοντες, ὀφθήσεσθαι δ’ οὐ προσδοκῶντες· σώζοντες οὖν τοὺς ὁμοίους σφίσιν αὐτοῖς βοηθεῖν νομίζουσι. “τούτου δ’ ἕνεκά σοι ταῦτα διῆλθον, ἵνα προειδὼς ἄμεινον προσφέρῃ καὶ τοῖς λόγοις ἀσφαλεστέροις χρῇ πρὸς αὐτούς, ἐπεὶ νῦν γε τίνα χρὴ προσδοκᾶν γνώμην ἕξειν τοὺς τοιούτους, ὅταν τόν τε βίον τὸν σαυτοῦ καὶ τὰς πράξεις διεξίῃς μηδὲ κατὰ μικρὸν ὁμοίας οὔσας ταῖς τούτων, ἀλλ’ οἵας περ πρὸς ἐμὲ λέγειν ἐπιχειρεῖς;", "st": "15.143"}, {"sp": "N", "t": "ἀποφαίνεις γὰρ τούς τε λόγους οὓς γέγραφας οὐ μέμψεως ἀλλὰ χάριτος τῆς μεγίστης ἀξίους ὄντας, τῶν τε πεπλησιακότων σοι τοὺς μὲν οὐδὲν ἠδικηκότας οὐδ’ ἡμαρτηκότας, τοὺς δὲ δι’ ἀρετὴν ὑπὸ τῆς πόλεως ἐστεφανωμένους, τά τε καθ’ ἡμέραν οὕτω κοσμίως καὶ τεταγμένως βεβιωκότα σαυτὸν ὡς οὐκ οἶδ’ εἴ τις ἄλλος τῶν πολιτῶν, ἔτι δὲ μήτε δεδικασμένον μηδενὶ μήτε πεφευγότα πλὴν περὶ ἀντιδόσεως, μήθ’ ἑτέροις συνηγωνισμένον μήτε μεμαρτυρηκότα, μήτ’ ἄλλο πεποιηκότα μηδέν, ἐν οἷς ἅπαντες πολιτευόμενοι τυγχάνουσι.", "st": "15.144"}, {"sp": "N", "t": "πρὸς δὲ τούτοις οὕτως ἰδίοις οὖσι καὶ περιττοῖς κἀκεῖνο λέγεις, ὡς τῶν μὲν ἀρχῶν καὶ τῶν ὠφελιῶν τῶν ἐντεῦθεν γιγνομένων καὶ τῶν ἄλλων ἁπάντων τῶν κοινῶν ἐξέστηκας, εἰς δὲ τοὺς διακοσίους καὶ χιλίους τοὺς εἰσφέροντας καὶ λειτουργοῦντας οὐ μόνον αὑτὸν παρέχεις ἀλλὰ καὶ τὸν υἱόν, καὶ τρὶς μὲν ἤδη τετριηραρχήκατε, τὰς δ’ ἄλλας λειτουργίας πολυτελέστερον λελειτουργήκατε καὶ κάλλιον ὧν οἱ νόμοι προστάττουσι.", "st": "15.145"}, {"sp": "N", "t": "“ταῦτ’ ἀκούοντας τοὺς τἀναντία πᾶσι τοῖς προειρημένοις ἐπιτετηδευκότας οὐκ οἴει βαρέως οἴσειν καὶ νομιεῖν ἐλέγχεσθαι τὸν βίον τὸν αὑτῶν οὐ σπουδαῖον ὄντα; καὶ γὰρ εἰ μὲν μετὰ πόνου καὶ ταλαιπωρίας ᾐσθάνοντό σε ποριζόμενον εἴς τε τὰς λειτουργίας καὶ περὶ τὴν ἄλλην διοίκησιν, οὐκ ἂν ὁμοίως ἔμελεν αὐτοῖς· νῦν δὲ τά τε παρὰ τῶν ξένων σοι γιγνόμενα πολὺ πλείω νομίζουσιν εἶναι τῶν διδομένων,", "st": "15.146"}, {"sp": "N", "t": "αὐτόν τε σὲ ῥᾳθυμότερον ἡγοῦνται ζῆν οὐ μόνον τῶν ἄλλων ἀλλὰ καὶ τῶν περὶ τὴν φιλοσοφίαν καὶ τὴν αὐτὴν σοι πραγματείαν ὄντων. “ὁρῶσι γὰρ ἐκείνων μὲν τοὺς πλείστους, πλὴν τῶν τὸν σὸν βίον καὶ τὸν τρόπον ἠγαπηκότων, ἔν τε ταῖς πανηγύρεσι καὶ τοῖς ἰδίοις συλλόγοις ἐπιδείξεις ποιουμένους, διαγωνιζομένους πρὸς ἀλλήλους, καθ’ ὑπερβολὴν ὑπισχνουμένους, ἐρίζοντας, λοιδορουμένους,", "st": "15.147"}, {"sp": "N", "t": "οὐδὲν ἀπολείποντας κακῶν, ἀλλὰ σφίσι μὲν αὐτοῖς πράγματα παρέχοντας, τοῖς δ’ ἀκροωμένοις ἐξουσίαν παραδιδόντας τοῖς μὲν καταγελάσαι τῶν λεγομένων, ἐνίοις δ’ ἐπαινέσαι, τοῖς δὲ πλείστοις μισῆσαι, τοῖς δ’ ὅπως ἕκαστοι βούλονται διατεθῆναι πρὸς αὐτούς· σὲ δ’ οὐδενὸς μετέχοντα τούτων, ἀλλ’ ἀνομοίως ζῶντα καὶ τοῖς σοφισταῖς καὶ τοῖς ἰδιώταις, καὶ τοῖς πολλὰ κεκτημένοις καὶ τοῖς ἀπόρως διακειμένοις.", "st": "15.148"}, {"sp": "N", "t": "ἐφ’ οἷς οἱ μὲν λογίζεσθαι δυνάμενοι καὶ νοῦν ἔχοντες ἴσως ἄν σε ζηλώσειαν, οἱ δὲ καταδεέστερον πράττοντες καὶ λυπεῖσθαι μᾶλλον εἰωθότες ἐπὶ ταῖς τῶν ἄλλων ἐπιεικείαις ἢ ταῖς ἑαυτῶν ἀτυχίαις οὐκ ἔστιν ὅπως οὐ δυσκολανοῦσι καὶ χαλεπῶς οἴσουσιν. ὡς οὖν οὕτως αὐτῶν διατεθησομένων σκόπει τί σοι λεκτέον τούτων καὶ τί παραλειπτέον ἐστίν.”", "st": "15.149"}, {"sp": "N", "t": "ἐγὼ δὲ κἀκείνου τότε ταῦτα λέγοντος καὶ νῦν ἡγοῦμαι πάντων ἀνθρώπων ἀτοπωτάτους εἶναι καὶ σχετλιωτάτους, οἵτινες βαρέως ἂν ἀκούοιεν εἰ λειτουργοῦντα μὲν ἐμαυτὸν τῇ πόλει παρέχω καὶ ποιοῦντα τὸ προσταττόμενον, μηδὲν δὲ δέομαι μήτε κληροῦσθαι τῶν ἀρχῶν ἕνεκα, μήτε λαμβάνειν ἃ τοῖς ἄλλοις ἡ πόλις δίδωσι, μήτ’ αὖ φεύγειν δίκας μήτε διώκειν.", "st": "15.150"}, {"sp": "N", "t": "ταῦτα γὰρ συνεταξάμην οὐ διὰ πλοῦτον οὐδὲ δι’ ὑπερηφανίαν, οὐδὲ καταφρονῶν τῶν μὴ τὸν αὐτὸν τρόπον ἐμοὶ ζώντων, ἀλλὰ τὴν μὲν ἡσυχίαν καὶ τὴν ἀπραγμοσύνην ἀγαπῶν, μάλιστα δ’ ὁρῶν τοὺς τοιούτους καὶ παρ’ ὑμῖν καὶ παρὰ τοῖς ἄλλοις εὐδοκιμοῦντας, ἔπειτα τὸν βίον ἡδίω νομίσας εἶναι τοῦτον ἢ τὸν τῶν πολλὰ πραττόντων, ἔτι δὲ ταῖς διατριβαῖς ταῖς ἐμαῖς πρεπωδέστερον, αἷς ἐξ ἀρχῆς κατεστησάμην.", "st": "15.151"}, {"sp": "N", "t": "τούτων μὲν ἕνεκα τοῦτον τὸν τρόπον ζῆν προειλόμην· τῶν δὲ λημμάτων τῶν παρὰ τῆς πόλεως ἀπεσχόμην δεινὸν ἡγησάμενος, εἰ δυνάμενος ἐκ τῶν ἰδίων τρέφειν ἐμαυτὸν ἐμποδών τῳ γενήσομαι τῶν ἐντεῦθεν ζῆν ἠναγκασμένων, καὶ διὰ τὴν ἐμὴν παρουσίαν ἐνδεής τις γενήσεται τῶν ἀναγκαίων. ὑπὲρ ὧν ἐπαίνου τυγχάνειν ἄξιος ἦν μᾶλλον ἢ διαβολῆς.", "st": "15.152"}, {"sp": "N", "t": "νῦν δ’ εἰς πολλὴν ἀπορίαν καθέστηκα, τί δρῶν ἀρέσαι δυνηθείην ἂν τοῖς τοιούτοις. εἰ γὰρ ἅπαντα τὸν χρόνον ἔργον ποιούμενος ὅπως μηδένα μήτ’ ἀδικήσω μήτ’ ἐνοχλήσω μήτε λυπήσω, δι’ αὐτὰ ταῦτα λυπῶ τινας, τί ποιῶν ἂν χαριζοίμην; ἢ τί λοιπόν ἐστι πλὴν ἐμὲ μὲν ἀτυχῆ, τοὺς δὲ τοιούτους ἀμαθεῖς δοκεῖν εἶναι καὶ δυσκόλους τοῖς συμπολιτευομένοις;", "st": "15.153"}, {"sp": "N", "t": "πρὸς μὲν οὖν τοὺς μηδὲν τῶν αὐτῶν τοῖς ἄλλοις γιγνώσκοντας, ἀλλὰ χαλεπωτέρους ὄντας τοῖς μὴ κακῶς πράττουσιν ἢ τοῖς ἀδικοῦσι, μωρόν ἐστιν ἀπολογίαν ζητεῖν· ὅσω γὰρ ἄν τις ἐπιεικέστερον αὑτὸν ἐπιδείξῃ, δῆλον ὅτι τοσούτω χεῖρον ἀγωνιεῖται παρ’ αὐτοῖς· πρὸς δὲ τοὺς ἄλλους, περὶ ὧν Λυσίμαχος διέβαλεν, ὡς παμπληθῆ κεκτήμεθα τὴν οὐσίαν, ἀναγκαῖόν ἐστιν εἰπεῖν, ἵνα μὴ πιστευθεὶς ὁ λόγος εἰς μείζους καὶ πλείους ἡμᾶς ἐμβάλῃ λειτουργίας ὧν ὑπενεγκεῖν ἂν δυνηθεῖμεν.", "st": "15.154"}, {"sp": "N", "t": "ὅλως μὲν οὖν οὐδεὶς εὑρεθήσεται τῶν καλουμένων σοφιστῶν πολλὰ χρήματα συλλεξάμενος, ἀλλ’ οἱ μὲν ἐν ὀλίγοις οἱ δ’ ἐν πάνυ μετρίοις τὸν βίον διαγαγόντες· ὁ δὲ πλεῖστα κτησάμενος ὦν ἡμεῖς μνημονεύομεν, Γοργίας ὁ Λεοντῖνος, οὗτος διατρίψας μὲν περὶ Θετταλίαν, ὅτ’ εὐδαιμονέστατοι τῶν Ἑλλήνων ἦσαν, πλεῖστον δὲ χρόνον βιοὺς καὶ περὶ τὸν χρηματισμὸν τοῦτον γενόμενος,", "st": "15.155"}, {"sp": "N", "t": "πόλιν δ’ οὐδεμίαν καταπαγίως οἰκήσας οὐδὲ περὶ τὰ κοινὰ δαπανηθεὶς οὐδ’ εἰσφορὰν εἰσενεγκεῖν ἀναγκασθείς, ἔτι δὲ πρὸς τούτοις οὔτε γυναῖκα γήμας οὔτε παῖδας ποιησάμενος, ἀλλ’ ἀτελὴς γενόμενος καὶ ταύτης τῆς λειτουργίας τῆς ἐνδελεχεστάτης καὶ πολυτελεστάτης, τοσοῦτον προλαβὼν πρὸς τὸ πλείω κτήσασθαι τῶν ἄλλων, χιλίους μόνους στατῆρας κατέλιπε.", "st": "15.156"}, {"sp": "N", "t": "καί τοι χρὴ περὶ τῆς οὐσίας τῆς ἀλλήλων μὴ τοῖς αἰτιωμένοις εἰκῇ πιστεύειν, μηδὲ τὰς ἐργασίας ἴσας νομίζειν τάς τε τῶν σοφιστῶν καὶ τὰς τῶν ὑποκριτῶν, ἀλλὰ τοὺς ἐν ταῖς αὐταῖς τέχναις ὄντας πρὸς ἀλλήλους κρίνειν, καὶ τοὺς ὁμοίαν ἐν ἑκάστῃ δύναμιν λαβόντας παραπλησίαν καὶ τὴν οὐσίαν ἔχειν νομίζειν.", "st": "15.157"}, {"sp": "N", "t": "ἢν οὖν ἐξισώσητέ με τῷ πλεῖστον ἐξειργασμένῳ καὶ θῆτε πρὸς ἐκεῖνον, οὔθ’ ὑμεῖς παντάπασιν ἀσκέπτως εἰκάζειν δόξετε περὶ τῶν τοιούτων, οὔθ’ ἡμεῖς εὑρεθεῖμεν ἂν οὔτε τὰ περὶ τὴν πόλιν οὔτε τὰ περὶ ἡμᾶς αὐτοὺς κακῶς διῳκηκότες, ἀλλ’ ἀπ’ ἐλαττόνων ζῶντες ὧν εἰς τὰς λειτουργίας ἀνηλώκαμεν. καί τοι τοὺς εὐτελεστέρους ἐν τοῖς ἰδίοις ἢ τοῖς κοινοῖς ὄντας δίκαιόν ἐστιν ἐπαινεῖν.", "st": "15.158"}, {"sp": "N", "t": "ἐνθυμοῦμαι δὲ μεταξὺ λέγων, ὅσον τὰ τῆς πόλεως μεταπέπτωκε, καὶ τὰς διανοίας ὡς οὐδὲν ὁμοίας περὶ τῶν πραγμάτων οἱ νῦν τοῖς πρότερον πεπολιτευμένοις ἔχουσιν. ὅτε μὲν γὰρ ἐγὼ παῖς ἦν, οὕτως ἐνομίζετο τὸ πλουτεῖν ἀσφαλὲς εἶναι καὶ σεμνὸν ὥστ’ ὀλίγου δεῖν πάντες προσεποιοῦντο πλείω κεκτῆσθαι τὴν οὐσίαν ἧς ἔχοντες ἐτύγχανον,", "st": "15.159"}, {"sp": "N", "t": "βουλόμενοι μετασχεῖν τῆς δόξης ταύτης· νῦν δ’ ὑπὲρ τοῦ μὴ πλουτεῖν ὥσπερ τῶν μεγίστων ἀδικημάτων ἀπολογίαν δεῖ παρασκευάζεσθαι καὶ σκοπεῖν, εἰ μέλλει τις σωθήσεσθαι. πολὺ γὰρ δεινότερον καθέστηκε τὸ δοκεῖν εὐπορεῖν ἢ τὸ φανερῶς ἀδικεῖν· οἱ μὲν γὰρ ἢ συγγνώμης ἔτυχον ἢ μικροῖς ἐζημιώθησαν, οἱ δ’ ἄρδην ἀπόλλυνται, καὶ πλείους ἂν εὕροιμεν τοὺς ἐκ τῶν ὄντων ἐκπεπτωκότας ἢ τοὺς δίκην ὑπὲρ τῶν ἁμαρτημάτων δεδωκότας.", "st": "15.160"}, {"sp": "N", "t": "καὶ τί δεῖ λέγειν περὶ τῶν κοινῶν; αὐτὸς γὰρ οὐ μικρὸν διήμαρτον διὰ ταύτην τὴν μεταβολὴν τῶν ἐμαυτοῦ πραγμάτων. ὅτε γὰρ ἐπαμύνειν ἠρχόμην τοῖς ἰδίοις, ἀπολομένων ἐν τῷ πολέμῳ τῷ πρὸς Λακεδαιμονίους ἁπάντων τῶν ὑπαρχόντων ἡμῖν, ἀφ’ ὧν ὁ πατὴρ ἅμα τῇ τε πόλει χρήσιμον αὑτὸν παρεῖχεν, ἡμᾶς θ’ οὕτως ἐπιμελῶς ἐπαίδευσεν ὥστ’ ἐπιφανέστερον εἶναί με τότε καὶ γνωριμώτερον ἐν τοῖς ἡλικιώταις καὶ συμπαιδευομένοις ἢ νῦν ἐν τοῖς συμπολιτευομένοις—", "st": "15.161"}, {"sp": "N", "t": "ὅτε δ’ οὖν, ὥσπερ εἶπον, ἠρχόμην πλησιάζειν τισίν, ᾠόμην, εἰ δυνηθείην πλείω κτήσασθαι καὶ περιποιήσασθαι τῶν ἐπὶ τὸν αὐτὸν βίον ὁρμησάντων, ἀμφότερα δόξειν, καὶ περὶ τὴν φιλοσοφίαν διαφέρειν καὶ κοσμιώτερον βεβιωκέναι τῶν ἄλλων. ἐμοὶ δὲ τοὐναντίον ἀποβέβηκεν.", "st": "15.162"}, {"sp": "N", "t": "εἰ μὲν γὰρ μήτ’ ἄξιος μηδενὸς ἐγενόμην μήτε περιεποιησάμην μηδέν, οὐδεὶς ἄν μοι πράγματα παρεῖχεν, ἀλλὰ φανερῶς ἀδικῶν ἀσφαλῶς ἂν ἔζων ἕνεκά γε τῶν συκοφαντῶν· νῦν δ’ ἀντὶ τῆς δόξης ἧς προσεδόκων ἀγῶνες περί με καὶ κίνδυνοι καὶ φθόνοι καὶ διαβολαὶ γεγόνασιν.", "st": "15.163"}, {"sp": "N", "t": "οὕτω γὰρ ἡ πόλις ἐν τῷ παρόντι χαίρει τοὺς μὲν ἐπιεικεῖς πιέζουσα καὶ ταπεινοὺς ποιοῦσα, τοῖς δὲ πονηροῖς ἐξουσίαν διδοῦσα καὶ λέγειν καὶ ποιεῖν ὅ τι ἂν βουληθῶσιν, ὥστε Λυσίμαχος μὲν ὁ προῃρημένος ζῆν ἐκ τοῦ συκοφαντεῖν καὶ κακῶς ἀεί τινα ποιεῖν τῶν πολιτῶν κατηγορήσων ἡμῶν ἀναβέβηκεν, ἐγὼ δ’ ὃς οὐδὲ περὶ ἕνα πότ’ ἐξήμαρτον, ἀλλὰ τῶν μὲν ἐνθένδε λημμάτων ἀπεσχόμην, παρὰ ξένων δὲ καὶ νομιζόντων εὖ πάσχειν ἐπορισάμην τὰς ὠφελίας, ὡς δεινὰ ποιῶν εἰς τηλικουτονὶ καθέστηκα κίνδυνον.", "st": "15.164"}, {"sp": "N", "t": "καί τοι προσῆκε τοὺς εὖ φρονοῦντας εὔχεσθαι τοῖς θεοῖς ὡς πλείστοις τῶν πολιτῶν παραγενέσθαι τὴν δύναμιν ταύτην, δι’ ἣν ἔμελλον παρ’ ἑτέρων λαμβάνοντες χρησίμους αὑτούς, ὥσπερ ἐγώ, τῇ πόλει παρέξειν. πολλῆς δ’ ἀλογίας περί με γεγενημένης πάντων ἂν συμβαίη δεινότατον, εἰ οἱ μὲν δεδωκότες μοι χρήματα τοσαύτην ἔχοιεν χάριν, ὥστ’ ἔτι καὶ νῦν με θεραπεύειν,", "st": "15.165"}, {"sp": "N", "t": "ὑμεῖς δ’, εἰς οὓς ἀνήλωκα τἀμαυτοῦ, δίκην ἐπιθυμήσαιτε παρ’ ἐμοῦ λαβεῖν. ἔτι δὲ δεινότερον, εἰ Πίνδαρον μὲν τὸν ποιητὴν οἱ πρὸ ἡμῶν γεγονότες ὑπὲρ ἑνὸς μόνον ῥήματος, ὅτι τὴν πόλιν ἔρεισμα τῆς Ἑλλάδος ὠνόμασεν, οὕτως ἐτίμησαν ὥστε καὶ πρόξενον ποιήσασθαι καὶ δωρεὰν μυρίας αὐτῷ δοῦναι δραχμάς, ἐμοὶ δὲ πολὺ πλείω καὶ κάλλιον ἐγκεκωμιακότι καὶ τὴν πόλιν καὶ τοὺς προγόνους μηδ’ ἀσφαλῶς ἐγγένοιτο ἐπιβιῶναι τὸν ἐπίλοιπον χρόνον.", "st": "15.166"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων καὶ τῶν ἄλλων τῶν κατηγορηθέντων ἱκανὴν εἶναι νομίζω τὴν εἰρημένην ἀπολογίαν· οὐκ ὀκνήσω δὲ πρὸς ὑμᾶς οὔθ’ ὡς ἔχω νῦν πρὸς τὸν ἐνεστῶτα κίνδυνον κατειπεῖν τὴν ἀλήθειαν, οὔθ’ ὡς τὸ πρῶτον διετέθην πρὸς αὐτόν. ἐγὼ γὰρ ὑπὲρ μὲν τῶν ἰδίων πολλὰς ἐλπίδας εἶχον καλῶς ἀγωνιεῖσθαι·", "st": "15.167"}, {"sp": "N", "t": "καὶ γὰρ τοῖς βεβιωμένοις καὶ τοῖς πεπραγμένοις ἐπίστευον, καὶ πολλοὺς λόγους καὶ δικαίους ᾤμην ἔχειν ὑπὲρ αὐτῶν· ὁρῶν δ’ οὐ μόνον δυσκόλως διακειμένους περὶ τὴν τῶν λόγων παιδείαν τοὺς εἰθισμένους ἅπασι χαλεπαίνειν, ἀλλὰ καὶ τῶν ἄλλων πολιτῶν πολλοὺς τραχέως πρὸς αὐτὴν διακειμένους, ἐφοβούμην μὴ τὰ μὲν ἴδιά μου παραμεληθῇ, τῆς δὲ κοινῆς τῆς περὶ τοὺς σοφιστὰς διαβολῆς ἀπολαύσω τι φλαῦρον.", "st": "15.168"}, {"sp": "N", "t": "ἐπειδὴ δὲ χρόνων ἐγγιγνομένων εἰσέπεσον εἰς τὸ λογίζεσθαι καὶ σκοπεῖν τί χρήσομαι τοῖς παροῦσιν, ἐπαυσάμην τοῦ δέους καὶ τῆς ταραχῆς ταύτης, οὐκ ἀλόγως, ἀλλ’ ἐκ τῶν εἰκότων λογισάμενος καὶ παραμυθησάμενος ἐμαυτόν·", "st": "15.169"}, {"sp": "N", "t": "τούς τε γὰρ ἐπιεικεῖς ὑμῶν, πρὸς οὕς περ ἐγὼ ποιήσομαι τοὺς λόγους, ἠπιστάμην οὐκ ἐμμένοντας ταῖς δόξαις ταῖς ἀδίκως ἐγγεγενημέναις, ἀλλ’ ἐπακολουθοῦντας ταῖς ἀληθείαις καὶ μεταπειθομένους ὑπὸ τῶν λεγόντων τὰ δίκαια, τήν τε φιλοσοφίαν ἐκ πολλῶν ἐνόμιζον ἐπιδείξειν ἀδίκως διαβεβλημένην, καὶ πολὺ ἂν δικαιοτέρως ἀγαπωμένην αὐτὴν ἢ μισουμένην. ἔχω δὲ καὶ νῦν ἔτι ταύτην τὴν γνώμην.", "st": "15.170"}, {"sp": "N", "t": "οὐκ ἄξιον δὲ θαυμάζειν εἴ τι τῶν καλῶν ἐπιτηδευμάτων ἠγνόηται καὶ διαλέληθεν, οὐδ’ εἰ διεψευσμένοι τινὲς αὐτοῦ τυγχάνουσι· καὶ γὰρ περὶ ἡμῶν αὐτῶν καὶ περὶ ἄλλων πραγμάτων ἀναριθμήτων οὕτως ἔχοντες ἂν εὑρεθεῖμεν. ἡ γὰρ πόλις ἡμῶν πολλῶν ἀγαθῶν αἰτία καὶ νῦν οὖσα καὶ πρότερον γεγενημένη καὶ τοῖς πολίταις καὶ τοῖς ἄλλοις Ἕλλησι, καὶ πολλῶν ἡδονῶν γέμουσα,", "st": "15.171"}, {"sp": "N", "t": "τοῦτ’ ἔχει δυσκολώτατον· διὰ γὰρ τὸ μέγεθος καὶ τὸ πλῆθος τῶν ἐνοικούντων οὐκ εὐσύνοπτός ἐστιν οὐδ’ ἀκριβής, ἀλλ’ ὥσπερ χειμάρρους, ὅπως ἂν ἕκαστον ὑπολαβοῦσα τύχῃ καὶ τῶν ἀνθρώπων καὶ τῶν πραγμάτων, οὕτω κατήνεγκε, καὶ δόξαν ἐνίοις τὴν ἐναντίαν τῆς προσηκούσης περιέθηκεν· ὅπερ καὶ τῇ παιδεία ταύτῃ συμβέβηκεν.", "st": "15.172"}, {"sp": "N", "t": "ὧν ἐνθυμουμένους χρὴ μηδενὸς πράγματος ἄνευ λόγου καταγιγνώσκειν, μηδ’ ὁμοίως διακεῖσθαι δικάζοντας ὥσπερ ἐν ταῖς ἰδίαις διατριβαῖς, ἀλλὰ διακριβοῦσθαι περὶ ἑκάστου καὶ τὴν ἀλήθειαν ζητεῖν, μεμνημένους τῶν ὅρκων καὶ τῶν νόμων καθ’ οὓς συνεληλύθατε δικάσοντες· ἔστι δ’ οὐ περὶ μικρῶν οὔθ’ ὁ λόγος οὔθ’ ἡ κρίσις ἐν ᾗ καθέσταμεν, ἀλλὰ περὶ τῶν μεγίστων· οὐ γὰρ περὶ ἐμοῦ μέλλετε μόνον τὴν ψῆφον διοίσειν, ἀλλὰ καὶ περὶ ἐπιτηδεύματος ᾧ πολλοὶ τῶν νεωτέρων προσέχουσι τὸν νοῦν.", "st": "15.173"}, {"sp": "N", "t": "οἶμαι δ’ ὑμᾶς οὐκ ἀγνοεῖν ὅτι τὰ πράγματα τῆς πόλεως τοῖς ἐπιγιγνομένοις καὶ τοῖς τοιούτοις οἱ πρεσβύτεροι παραδιδόασι. τοιαύτης οὖν ἀεὶ τῆς περιόδου γιγνομένης ἀναγκαῖόν ἐστιν, ὅπως ἃ οἱ νεώτεροι παιδευθῶσιν, οὕτω τὴν πόλιν πράττουσαν διατελεῖν· ὥστ’ σὺ ποιητέον τοὺς συκοφάντας κυρίους τηλικούτου πράγματος, οὐδὲ τοὺς μὲν μὴ διδόντας τούτοις ἀργύριον τιμωρητέον, παρ’ ὧν δ’ ἂν λάβωσιν ἐατέον ποιεῖν ὅ τι ἂν βουληθῶσιν,", "st": "15.174"}, {"sp": "N", "t": "ἀλλ’ εἰ μὲν ἡ φιλοσοφία τοιαύτην ἔχει δύναμιν ὥστε διαφθείρειν τοὺς νεωτέρους, οὐ τοῦτον χρὴ μόνον κολάζειν ὃν ἂν γράψηταί τις τούτων, ἀλλὰ πάντας ἐκποδὼν ποιεῖσθαι τοὺς περὶ τὴν διατριβὴν ταύτην ὄντας· εἰ δὲ τοὐναντίον πέφυκεν ὥστ’ ὠφελεῖν καὶ βελτίους ποιεῖν τοὺς πλησιάζοντας καὶ πλέονος ἀξίους, τοὺς μὲν διαβεβλημένους πρὸς αὐτὴν παυστέον, τοὺς δὲ συκοφαντοῦντας ἀτιμητέον, τοῖς δὲ νεωτέροις συμβουλευτέον ἐν ταύτῃ διατρίβειν μᾶλλον ἢ τοῖς ἄλλοις ἐπιτηδεύμασι.", "st": "15.175"}, {"sp": "N", "t": "πρὸ πολλῶν δ’ ἂν ἐποιησάμην, εἴπερ ἦν εἱμαρμένον μοι φεύγειν τὴν γραφὴν ταύτην, ἀκμάζοντί μοι προσπεσεῖν τὸν κίνδυνον· οὐ γὰρ ἂν ἠθύμουν, ἀλλὰ μᾶλλον οἷός τ’ ἂν ἐγενόμην καὶ τὸν κατήγορον ἀμύνασθαι καὶ τῇ φιλοσοφίᾳ βοηθῆσαι· νῦν δὲ φοβοῦμαι μὴ διὰ ταύτην ὑπὲρ ἄλλων πραγμάτων ἐπιεικῶς εἰρηκώς, περὶ αὐτῆς ταύτης χεῖρον τύχω διαλεχθεὶς ἢ περὶ ὧν ἧττόν μοι σπουδάσαι προσῆκε.", "st": "15.176"}, {"sp": "N", "t": "καίτοι δεξαίμην ἄν, εἰρήσεται γὰρ τἀληθὲς εἰ καὶ μωρὸς ὁ λόγος ἐστίν, ἤδη τελευτῆσαι τὸν βίον ἀξίως εἰπὼν τῆς ὑποθέσεως καὶ πείσας ὑμᾶς τοιαύτην νομίζειν τὴν τῶν λόγων μελέτην οἵα πέρ ἐστι, μᾶλλον ἢ ζῆν πολυπλασίω χρόνον ἐφορῶν οὕτως αὐτὴν ὥσπερ νῦν παρ’ ὑμῖν φερομένην.", "st": "15.177"}, {"sp": "N", "t": "τῆς μὲν οὖν ἐπιθυμίας οἶδ’ ὅτι πολὺ καταδεέστερον ἐροῦμεν· ὅμως δ’ ὅπως ἂν δύνωμαι, πειράσομαι διελθεῖν τήν τε φύσιν αὐτῆς καὶ τὴν δύναμιν ἣν ἔχει, καὶ ποίᾳ τῶν ἄλλων τεχνῶν ὁμοιοειδής ἐστι, καὶ τί τοὺς συνόντας ὠφελεῖ, καὶ ποίας τινὰς ποιούμεθα ἡμεῖς τὰς ὑποσχέσεις· οἶμαι γὰρ ὑμᾶς μαθόντας τὴν ἀλήθειαν ἄμεινον καὶ βουλεύσεσθαι καὶ διαγνώσεσθαι περὶ αὐτῆς.", "st": "15.178"}, {"sp": "N", "t": "ἀξιῶ δ’ ὑμᾶς, ἢν ἄρα φαίνωμαι λόγους διεξιὼν πολὺ τῶν εἰθισμένων λέγεσθαι παρ’ ὑμῖν ἐξηλλαγμένους, μὴ δυσχεραίνειν ἀλλ’ ἔχειν συγγνώμην, ἐνθυμουμένους ὅτι τοὺς περὶ πραγμάτων ἀνομοίων τοῖς ἄλλοις ἀγωνιζομένους ἀναγκαῖόν ἐστι καὶ τοῖς λόγοις τοιούτοις χρῆσθαι περὶ αὐτῶν. ὑπομείναντες οὖν τὸν τρόπον τῶν λεγομένων καὶ τὴν παρρησίαν, καὶ τὸν χρόνον ἐάσαντες ἀναλῶσαί με τὸν δεδομένον ταῖς ἀπολογίαις, ὅπως ἂν ὑμῶν ἑκάστῳ δοκῇ δίκαιον εἶναι καὶ νόμιμον, οὕτω φέρετε τὴν ψῆφον.", "st": "15.179"}, {"sp": "N", "t": "βούλομαι δὲ περὶ τῆς τῶν λόγων παιδείας ὥσπερ οἱ γενεαλογοῦντες πρῶτον διελθεῖν πρὸς ὑμᾶς. ὁμολογεῖται μὲν γὰρ τὴν φύσιν ἡμῶν ἔκ τε τοῦ σώματος συγκεῖσθαι καὶ τῆς ψυχῆς, αὐτοῖν δὲ τούτοιν οὐδεὶς ἔστιν ὅστις οὐκ ἂν φήσειεν ἡγεμονικωτέραν πεφυκέναι τὴν ψυχὴν καὶ πλέονος ἀξίαν· τῆς μὲν γὰρ ἔργον εἶναι βουλεύσασθαι καὶ περὶ τῶν ἰδίων καὶ περὶ τῶν κοινῶν, τοῦ δὲ σώματος ὑπηρετῆσαι τοῖς ὑπὸ τῆς ψυχῆς γνωσθεῖσιν.", "st": "15.180"}, {"sp": "N", "t": "οὕτω δὲ τούτων ἐχόντων ὁρῶντές τινες τῶν πολὺ πρὸ ἡμῶν γεγονότων περὶ μὲν τῶν ἄλλων πολλὰς τέχνας συνεστηκυίας, περὶ δὲ τὸ σῶμα καὶ τὴν ψυχὴν οὐδὲν τοιοῦτον συντεταγμένον, εὑρόντες διττὰς ἐπιμελείας κατέλιπον ἡμῖν, περὶ μὲν τὰ σώματα τὴν παιδοτριβικήν, ἧς ἡ γυμναστικὴ μέρος ἐστί, περὶ δὲ τὰς ψυχὰς τὴν φιλοσοφίαν, περὶ ἧς ἐγὼ μέλλω ποιεῖσθαι τοὺς λόγους,", "st": "15.181"}, {"sp": "N", "t": "ἀντιστρόφους καὶ σύζυγας καὶ σφίσιν αὐταῖς ὁμολογουμένας, δι’ ὧν οἱ προεστῶτες αὐτῶν τάς τε ψυχὰς φρονιμωτέρας καὶ τὰ σώματα χρησιμώτερα παρασκευάζουσιν, οὐ πολὺ διαστησάμενοι τὰς παιδείας ἀπ’ ἀλλήλων, ἀλλὰ παραπλησίαις χρώμενοι καὶ ταῖς διδασκαλίαις καὶ ταῖς γυμνασίαις καὶ ταῖς ἄλλαις ἐπιμελείαις.", "st": "15.182"}, {"sp": "N", "t": "ἐπειδὰν γὰρ λάβωσι μαθητάς, οἱ μὲν παιδοτρίβαι τὰ σχήματα τὰ πρὸς τὴν ἀγωνίαν εὑρημένα τοὺς φοιτῶντας διδάσκουσιν, οἱ δὲ περὶ τὴν φιλοσοφίαν ὄντες τὰς ἰδέας ἁπάσας, αἷς ὁ λόγος τυγχάνει χρώμενος,", "st": "15.183"}, {"sp": "N", "t": "διεξέρχονται τοῖς μαθηταῖς. ἐμπείρους δὲ τούτων ποιήσαντες καὶ διακριβώσαντες ἐν τούτοις πάλιν γυμνάζουσιν αὐτούς, καὶ πονεῖν ἐθίζουσι, καὶ συνείρειν καθ’ ἓν ἕκαστον ὧν ἔμαθον ἀναγκάζουσιν, ἵνα ταῦτα βεβαιότερον κατάσχωσι καὶ τῶν καιρῶν ἐγγυτέρω ταῖς δόξαις γένωνται. τῷ μὲν γὰρ εἰδέναι περιλαβεῖν αὐτοὺς οὐχ οἷόν τ’ ἐστίν· ἐπὶ γὰρ ἁπάντων τῶν πραγμάτων διαφεύγουσι τὰς ἐπιστήμας, οἱ δὲ μάλιστα προσέχοντες τὸν νοῦν καὶ δυνάμενοι θεωρεῖν τὸ συμβαῖνον ὡς ἐπὶ τὸ πολὺ πλειστάκις αὐτῶν τυγχάνουσι.", "st": "15.184"}, {"sp": "N", "t": "τοῦτον δὲ τὸν τρόπον ἐπιμελόμενοι καὶ παιδεύοντες μέχρι μὲν τοῦ γενέσθαι βελτίους αὐτοὺς αὑτῶν τοὺς μαθητὰς καὶ ἔχειν ἄμεινον, τοὺς μὲν τὰς διανοίας τοὺς δὲ τὰς τῶν σωμάτων ἕξεις, ἀμφότεροι δύνανται προαγαγεῖν· ἐκείνην δὲ τὴν ἐπιστήμην οὐδέτεροι τυγχάνουσιν ἔχοντες, δι’ ἧς ἂν οἱ μὲν ἀθλητὰς οὓς βουληθεῖεν, οἱ δὲ ῥήτορας ἱκανοὺς ποιήσαιεν, ἀλλὰ μέρος μὲν ἄν τι συμβάλοιντο, τὸ δ’ ὅλον αἱ δυνάμεις αὗται παραγίγνονται τοῖς καὶ τῇ φύσει καὶ ταῖς ἐπιμελείαις διενεγκοῦσιν.", "st": "15.185"}, {"sp": "N", "t": "ὁ μὲν οὖν τύπος τῆς φιλοσοφίας τοιοῦτός τίς ἐστιν· ἡγοῦμαι δ’ ὑμᾶς μᾶλλον ἂν ἔτι καταμαθεῖν τὴν δύναμιν αὐτῆς, εἰ διέλθοιμι τὰς ὑποσχέσεις ἃς ποιούμεθα πρὸς τοὺς πλησιάζειν ἡμῖν βουλομένους.", "st": "15.186"}, {"sp": "N", "t": "λέγομεν γὰρ ὡς δεῖ τοὺς μέλλοντας διοίσειν ἢ περὶ τοὺς λόγους ἢ περὶ τὰς πράξεις ἢ περὶ τὰς ἄλλας ἐργασίας πρῶτον μὲν πρὸς τοῦτο πεφυκέναι καλῶς, πρὸς ὃ ἂν προῃρημένοι τυγχάνωσιν, ἔπειτα παιδευθῆναι καὶ λαβεῖν τὴν ἐπιστήμην, ἥτις ἂν ᾗ περὶ ἑκάστου, τρίτον ἐντριβεῖς γενέσθαι καὶ γυμνασθῆναι περὶ τὴν χρείαν καὶ τὴν ἐμπειρίαν αὐτῶν· ἐκ τούτων γὰρ ἐν ἁπάσαις ταῖς ἐργασίαις τελείους γίγνεσθαι καὶ πολὺ διαφέροντας τῶν ἄλλων. εἶναι δὲ τούτων προσῆκον ἑκατέροις,", "st": "15.187"}, {"sp": "N", "t": "τοῖς τε διδάσκουσι καὶ τοῖς μανθάνουσιν, ἴδιον μὲν τοῖς μὲν εἰσενέγκασθαι τὴν φύσιν οἵαν δεῖ, τοῖς δὲ δύνασθαι παιδεῦσαι τοὺς τοιούτους, κοινὸν δ’ ἀμφοτέρων τὸ περὶ τὴν ἐμπειρίαν γυμνάσιον· δεῖν γὰρ τοὺς μὲν ἐπιμελῶς ἐπιστατῆσαι τοῖς παιδευομένοις, τοὺς δ’ ἐγκρατῶς ἐμμεῖναι τοῖς προσταττομένοις.", "st": "15.188"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἐστιν ἃ κατὰ πασῶν λέγομεν τῶν τεχνῶν· εἰ δὲ δή τις ἀφέμενος τῶν ἄλλων ἔροιτό με τί τούτων μεγίστην ἔχει δύναμιν πρὸς τὴν τῶν λόγων παιδείαν, ἀποκριναίμην ἂν ὅτι τὸ τῆς φύσεως ἀνυπέρβλητόν ἐστι καὶ πολὺ πάντων διαφέρει· τὸν γὰρ ἔχοντα τὴν μὲν ψυχὴν εὑρεῖν καὶ μαθεῖν καὶ πονῆσαι καὶ μνημονεῦσαι δυναμένην, τὴν δὲ φωνὴν καὶ τὴν τοῦ στόματος σαφήνειαν τοιαύτην ὥστε μὴ μόνοις τοῖς λεγομένοις ἀλλὰ καὶ ταῖς τούτων εὐαρμοστίαις συμπείθειν τοὺς ἀκούοντας,", "st": "15.189"}, {"sp": "N", "t": "ἔτι δὲ τὴν τόλμαν μὴ τὴν ἀναισχυντίας σημεῖον γιγνομένην, ἀλλὰ τὴν μετὰ σωφροσύνης οὕτω παρασκευάζουσαν τὴν ψυχὴν ὥστε μηδὲν ἧττον θαρρεῖν ἐν δὴ πᾶσι τοῖς πολίταις τοὺς λόγους ποιούμενον ἢ πρὸς αὑτὸν διανοούμενον, τίς οὐκ οἶδεν ὅτι τυχὼν ὁ τοιοῦτος παιδείας μὴ τῆς ἀπηκριβωμένης, ἀλλὰ τῆς ἐπιπολαίου καὶ πᾶσι κοινῆς, τοιοῦτος ἂν εἴη ῥήτωρ οἷος οὐκ οἶδ’ εἴ τις τῶν Ἑλλήνων γέγονεν;", "st": "15.190"}, {"sp": "N", "t": "καὶ μὲν δὴ κἀκείνους ἴσμεν, τοὺς καταδεεστέραν μὲν τούτων τὴν φύσιν ἔχοντας, ταῖς δ’ ἐμπειρίαις καὶ ταῖς ἐπιμελείαις προέχοντας, ὅτι γίγνονται κρείττους οὐ μόνον αὑτῶν ἀλλὰ καὶ τῶν εὖ μὲν πεφυκότων λίαν δ’ αὑτῶν κατημεληκότων· ὥσθ’ ἑκάτερόν τε τούτων δεινὸν ἂν καὶ λέγειν καὶ πράττειν ποιήσειεν, ἀμφότερά τε γενόμενα περὶ τὸν αὐτὸν ἀνυπέρβλητον ἂν τοῖς ἄλλοις ἀποτελέσειεν.", "st": "15.191"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς φύσεως καὶ τῆς ἐμπειρίας ταῦτα γιγνώσκω· περὶ δὲ τῆς παιδείας οὐκ ἔχω τοιοῦτον λόγον εἰπεῖν· οὔτε γὰρ ὁμοίαν οὔτε παραπλησίαν ἔχει τούτοις τὴν δύναμιν. εἰ γάρ τις διακούσειεν ἅπαντα τὰ περὶ τοὺς λόγους καὶ διακριβωθείη μᾶλλον τῶν ἄλλων, λόγων μὲν ποιητὴς τυχὸν ἂν χαριέστερος γένοιτο τῶν πολλῶν, εἰς ὄχλον δὲ καταστάς, τούτου μόνον ἀποστερηθείς, τοῦ τολμᾶν, οὐδ’ ἂν φθέγξασθαι δυνηθείη.", "st": "15.192"}, {"sp": "N", "t": "καὶ μηδεὶς οἰέσθω με πρὸς μὲν ὑμᾶς συστέλλειν τὴν ὑπόσχεσιν, ἐπειδὰν δὲ διαλέγωμαι πρὸς τοὺς συνεῖναί μοι βουλομένους, ἅπασαν ὑπ’ ἐμαυτῷ ποιεῖσθαι τὴν δύναμιν· φεύγων γὰρ τὰς τοιαύτας αἰτίας, ὅτ’ ἠρχόμην περὶ ταύτην εἶναι τὴν πραγματείαν, λόγον διέδωκα γράψας ἐν ᾧ φανήσομαι τοῖς τε μείζους ποιουμένοις τὰς ὑποσχέσεις ἐπιτιμῶν καὶ τὴν ἐμαυτοῦ γνώμην ἀποφαινόμενος.", "st": "15.193"}, {"sp": "N", "t": "ἃ μὲν οὖν κατηγορῶ τῶν ἄλλων παραλείψω· καὶ γάρ ἐστι πλείω τοῦ καιροῦ τοῦ παρόντος· ἃ δ’ αὐτὸς ἀποφαίνομαι, πειράσομαι διελθεῖν ὑμῖν. ἄρχομαι δ’ ἐνθένδε ποθέν. [Ἐκ τοῦ Κατὰ τῶν σοφιστῶν, 14–18.]", "st": "15.194"}, {"sp": "N", "t": "ταῦτα κομψοτέρως μὲν πέφρασται τῶν ἔμπροσθεν εἰρημένων, βούλεται δὲ ταὐτὰ δηλοῦν ἐκείνοις. ὃ χρὴ μέγιστον ὑμῖν γενέσθαι τεκμήριον τῆς ἐμῆς ἐπιεικείας· οὐ γάρ, ὅτε μὲν ἦν νεώτερος, ἀλαζονευόμενος φαίνομαι καὶ μεγάλας τὰς ὑποσχέσεις ποιούμενος, ἐπειδὴ δ’ ἀπολέλαυκα τοῦ πράγματος καὶ πρεσβύτερος γέγονα, τηνικαῦτα ταπεινὴν ποιῶν τὴν φιλοσοφίαν, ἀλλὰ τοῖς αὐτοῖς λόγοις χρώμενος καὶ ἀκμάζων καὶ παυόμενος αὐτῆς, καὶ θαρρῶν καὶ κινδυνεύων, καὶ πρὸς τοὺς βουλομένους πλησιάζειν καὶ πρὸς τοὺς μέλλοντας περί μου τὴν ψῆφον οἴσειν, ὥστ’ οὐκ οἶδ’ ὅπως ἄν τις ἀληθέστερος ἢ δικαιότερος περὶ αὐτὴν ἐπιδειχθείη γεγενημένος.", "st": "15.195"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἐκείνοις προσκείσθω τοῖς πρότερον περὶ ἡμῶν εἰρημένοις· οὐκ ἀγνοῶ δ’ ὅτι τοὺς δυσκόλως διακειμένους οὐδέν πω τῶν εἰρημένων ἱκανόν ἐστιν ἀπαλλάξαι τῆς διανοίας ταύτης, ἀλλὰ πολλῶν ἔτι δέονται λόγων καὶ παντοδαπῶν, εἰ μέλλουσιν ἑτέραν μεταλήψεσθαι δόξαν ἀνθ’ ἧς νῦν τυγχάνουσιν ἔχοντες.", "st": "15.196"}, {"sp": "N", "t": "δεῖ δὴ μηδ’ ἡμᾶς προαπειπεῖν διδάσκοντας καὶ λέγοντας, ἐξ ὧν, δυοῖν θάτερον, ἢ μεταστήσομεν τὰς γνώμας αὐτῶν, ἢ τὰς βλασφημίας καὶ κατηγορίας αἷς χρῶνται καθ’ ἡμῶν ἐξελέγξομεν ψευδεῖς οὔσας. εἰσὶ δὲ διτταί. λέγουσι γὰρ οἱ μὲν ὡς ἔστιν ἡ περὶ τοὺς σοφιστὰς διατριβὴ φλυαρία καὶ φενακισμός· οὐδεμία γὰρ εὕρηται παιδεία τοιαύτη δι’ ἦς γένοιτό τις ἂν ἢ περὶ τοὺς λόγους δεινότερος ἢ περὶ τὰς πράξεις φρονιμώτερος, ἀλλ’ οἱ προέχοντες ἐν τούτοις τῇ φύσει τῶν ἄλλων διαφέρουσιν·", "st": "15.197"}, {"sp": "N", "t": "οἱ δὲ δεινοτέρους μὲν ὁμολογοῦσιν εἶναι τοὺς περὶ τὴν μελέτην ταύτην ὄντας, οὐ μὴν ἀλλὰ διαφθέρεσθαι καὶ γίγνεσθαι χείρους· ἐπειδὰν γὰρ λάβωσι δύναμιν, τοῖς ἀλλοτρίοις ἐπιβουλεύειν. ὡς οὖν οὐδὲν ὑγιὲς οὐδ’ ἀληθὲς οὐδέτεροι τούτων λέγουσι, πολλὰς ἐλπίδας ἔχω πᾶσι φανερὸν ποιήσειν.", "st": "15.198"}, {"sp": "N", "t": "πρῶτον δ’ ἐνθυμήθητε περὶ τῶν φλυαρίαν φασκόντων εἶναι τὴν παιδείαν, ὡς αὐτοὶ λίαν καταφανῶς ληροῦσι. διασύρουσι μὲν γὰρ αὐτὴν ὡς οὐδὲν ὠφελεῖν δυναμένην ἀλλ’ ἀπάτην καὶ φενακισμὸν οὖσαν, ἀξιοῦσι δὲ τοὺς συνόντας ἡμῖν εὐθὺς μὲν προσελθόντας διαφέρειν αὐτοὺς αὑτῶν,", "st": "15.199"}, {"sp": "N", "t": "ὀλίγας δ’ ἡμέρας συνδιατρίψαντας σοφωτέρους ἐν τοῖς λόγοις καὶ κρείττους φαίνεσθαι τῶν καὶ ταῖς ἡλικίαις καὶ ταῖς ἐμπειρίαις προεχόντων, ἐνιαυτὸν δὲ μόνον παραμείναντας ῥήτορας ἅπαντας ἀγαθοὺς εἶναι καὶ τελέους καὶ μηδὲν φαυλοτέρους τοὺς ἀμελεῖς τῶν πονεῖν ἐθελόντων μηδὲ τοὺς ἀφυεῖς τῶν τὰς ψυχὰς ἀνδρικὰς ἐχόντων.", "st": "15.200"}, {"sp": "N", "t": "καὶ ταῦτα προστάττουσιν οὔθ’ ἡμῶν ἀκηκοότες τοιαύτας ποιουμένων τὰς ὑποσχέσεις, οὔτ’ ἐν ταῖς ἄλλαις τέχναις καὶ παιδείαις οὐδὲν ἑωρακότες τούτων συμβαῖνον, ἀλλὰ μόλις μὲν ἡμῖν τὰς ἐπιστήμας παραγιγνομένας, οὐχ ὁμοίως δ’ ἀλλήλοις ὅ τι ἂν μάθωμεν ἐξεργαζομένους, ἀλλὰ δύο μὲν ἢ τρεῖς ἐξ ἁπάντων τῶν διδασκαλείων ἀγωνιστὰς γιγνομένους, τοὺς δ’ ἄλλους ἐξ αὐτῶν ἰδιώτας ἀπαλλαττομένους.", "st": "15.201"}, {"sp": "N", "t": "καί τοι πῶς οὐκ ἄφρονας εἶναι χρὴ νομίζειν τοὺς τὰς δυνάμεις τὰς ἐν ταῖς ὁμολογουμέναις τῶν τεχνῶν οὐκ ἐνούσας, ταύτας ἀπαιτεῖν τολμῶντας παρὰ ταύτης ἣν οὐκ εἶναί φασι, καὶ πλείους τὰς ὠφελείας ἀξιοῦντας γίγνεσθαι παρὰ τῆς ἀπιστουμένης ὑφ’ αὑτῶν ἢ παρὰ τῶν ἀκριβῶς εὑρῆσθαι δοκουσῶν;", "st": "15.202"}, {"sp": "N", "t": "χρὴ δὲ τοὺς νοῦν ἔχοντας οὐκ ἀνωμάλως ποιεῖσθαι τὰς κρίσεις περὶ τῶν ὁμοίων πραγμάτων, οὐδ’ ἀποδοκιμάζειν τὴν παιδείαν τὴν ταὐτὰ ταῖς πλείσταις τῶν τεχνῶν ἀπεργαζομένην. τίς γὰρ οὐκ οἶδεν ὑμῶν πολλοὺς τῶν ὑπὸ τοῖς σοφισταῖς γενομένων οὐ φενακισθέντας οὐδ’ οὕτω διατεθέντας ὡς οὗτοι λέγουσιν,", "st": "15.203"}, {"sp": "N", "t": "ἀλλὰ τοὺς μὲν αὐτῶν ἱκανοὺς ἀγωνιστὰς ἀποτελεσθέντας, τοὺς δὲ παιδεύειν ἑτέρους δυνηθέντας, ὅσοι δ’ αὐτῶν ἰδιωτεύειν ἐβουλήθησαν, ἔν τε ταῖς ὁμιλίαις χαριεστέρους ὄντας ἢ πρότερον ἦσαν, τῶν τε λόγων κριτὰς καὶ συμβούλους ἀκριβεστέρους τῶν πλείστων γεγενημένους; ὥστε πῶς χρὴ τῆς τοιαύτης διατριβῆς καταφρονεῖν, τῆς τοὺς κεχρημένους αὐτῇ τοιούτους παρασκευάζειν δυναμένης;", "st": "15.204"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τόδε πάντες ἂν ὁμολογήσαιεν, ὅτι τούτους τεχνικωτάτους εἶναι νομίζομεν ἐπὶ πασῶν τῶν τεχνῶν καὶ χειρουργιῶν, οἵ τινες ἂν τοὺς μαθητὰς ὡς οἷόν θ’ ὁμοιοτάτους ἐργάτας ἀλλήλοις ἀποδείξωσι. τῇ τοίνυν φιλοσοφίᾳ φανήσεται καὶ τοῦτο συμβεβηκός.", "st": "15.205"}, {"sp": "N", "t": "ὅσοι γὰρ ἡγεμόνος ἔτυχον ἀληθινοῦ καὶ νοῦν ἔχοντος, εὑρεθεῖεν ἂν ἐν τοῖς λόγοις οὕτως ὁμοίαν τὴν δύναμιν ἔχοντες ὥστε πᾶσιν εἶναι φανερὸν ὅτι τῆς αὐτῆς παιδείας μετεσχήκασι. καί τοι μηδενὸς ἔθους αὐτοῖς ἐγγενομένου κοινοῦ μηδὲ διατριβῆς μηδὲ διατριβῆς τεχνικῆς ὑπαρξάσης οὐκ ἔστιν ὅπως ἂν εἰς τὴν ὁμοιότητα ταύτην κατέστησαν.", "st": "15.206"}, {"sp": "N", "t": "ἔτι τοίνυν ὑμῶν αὐτῶν οὐδεὶς ἔστιν ὅστις οὐκ ἂν εἰπεῖν ἔχοι πολλοὺς τῶν συμπαιδευθέντων, οἳ παῖδες μὲν ὄντες ἀμαθέστατοι τῶν ἡλικιωτῶν ἔδοξαν εἶναι, πρεσβύτεροι δὲ γενόμενοι πλέον διήνεγκαν πρὸς τὸ φρονεῖν καὶ λέγειν τῶν αὐτῶν τούτων ὧν παῖδες ὄντες ἀπελείφθησαν. ὅθεν μάλιστ’ ἄν τις γνοίη τὴν ἐπιμέλειαν ὅσην ἔχει δύναμιν· δῆλον γὰρ ὅτι τότε μὲν ἅπαντες τοιαύταις ἐχρῶντο ταῖς διανοίαις οἵας περ ἐξ ἀρχῆς ἔφυσαν ἔχοντες, ἄνδρες δὲ γενόμενοι τούτων διήνεγκαν καὶ μετήλλαξαν τὴν φρόνησιν τῷ τοὺς μὲν ἐκκεχυμένως ζῆν καὶ ῥᾳθύμως, τοὺς δὲ τοῖς τε πράγμασι καὶ σφίσιν αὐτοῖς προσέχειν τὸν νοῦν.", "st": "15.207"}, {"sp": "N", "t": "ὅπου δὲ καὶ διὰ τὰς αὑτῶν ἐπιμελείας γίγνονταί τινες βελτίους, πῶς οὐκ ἂν οὗτοι λαβόντες ἐπιστάτην καὶ πρεσβύτερον καὶ πολλῶν πραγμάτων ἔμπειρον, καὶ τὰ μὲν παρειληφότα τὰ δ’ αὐτὸν εὑρηκότα, πολὺ ἃ ἔτι πλέον καὶ σφῶν αὐτῶν καὶ τῶν ἄλλων διήνεγκαν;", "st": "15.208"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐκ τούτων ἀλλὰ καὶ τῶν λοιπῶν εἰκότως ἄν ἅπαντες τὴν ἄγνοιαν θαυμάσειαν τῶν τολμώντων οὕτως εἰκῇ καταφρονεῖν τῆς φιλοσοφίας· πρῶτον μὲν εἰ πάσας τὰς πράξεις καὶ τὰς τέχνας εἰδότες ταῖς μελέταις καὶ ταῖς φιλοπονίαις ἁλισκομένας πρὸς τὴν τῆς φρονήσεως ἄσκησιν ταῦτα μηδεμίαν ἡγοῦνται δύναμιν ἔχειν,", "st": "15.209"}, {"sp": "N", "t": "ἔπειτ’ εἰ τῶν μὲν σωμάτων μηδὲν οὕτως ἄν φήσαιεν εἶναι φαῦλον, ὅ τι γυμνασθὲν καὶ πονῆσαν οὐκ ἂν εἴη βέλτιον, τὰς δὲ ψυχὰς τὰς ἄμεινον πεφυκυίας τῶν σωμάτων μηδὲν ἂν νομίζουσι γενέσθαι σπουδαιοτέρας παιδευθείσας καὶ τυχούσας τῆς προσηκούσης ἐπιμελείας·", "st": "15.210"}, {"sp": "N", "t": "ἔτι δ’ εἰ περὶ τοὺς ἵππους καὶ τοὺς κύνας καὶ τὰ πλεῖστα τῶν ζώων ὁρῶντες τέχνας ἔχοντάς τινας, αἷς τὰ μὲν ἀνδρειότερα τὰ δὲ πραότερα τὰ δὲ φρονιμώτερα ποιοῦσι, περὶ τὴν τῶν ἀνθρώπων φύσιν μηδεμίαν οἴονται τοιαύτην εὑρῆσθαι παιδείαν, ἥ τις ἂν αὐτοὺς ἐπί τι τούτων ὧν περ καὶ τὰ θηρία δυνηθείη προαγαγεῖν,", "st": "15.211"}, {"sp": "N", "t": "ἀλλὰ τοσαύτην ἁπάντων ἡμῶν ἀτυχίαν κατεγνώκασιν, ὥσθ’ ὁμολογήσειαν μὲν ἂν ταῖς ἡμετέραις διανοίαις ἕκαστον τῶν ὄντων βέλτιον γίγνεσθαι καὶ χρησιμώτερον, αὐτοὺς δ’ ἡμᾶς τοὺς ἔχοντας τὴν φρόνησιν ταύτην, ᾗ πάντα πλέονος ἄξια ποιοῦμεν, τολμῶσι λέγειν ὡς οὐδὲν ἂν ἀλλήλους πρὸς ἐπιείκειαν εὐεργετήσαιμεν.", "st": "15.212"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὅτι καθ’ ἕκαστον τὸν ἐνιαυτὸν θεωροῦντες ἐν τοῖς θαύμασι τοὺς μὲν λέοντας πραότερον διακειμένους πρὸς τοὺς θεραπεύοντας ἤ τῶν ἀνθρώπων ἔνιοι πρὸς τοὺς εὖ ποιοῦντας, τὰς δ’ ἄρκτους καλινδουμένας καὶ παλαιούσας καὶ μιμουμένας τὰς ἡμετέρας ἐπιστήμας,", "st": "15.213"}, {"sp": "N", "t": "οὐδ’ ἐκ τούτων δύνανται γνῶναι τὴν παιδείαν καὶ τὴν ἐπιμέλειαν ὅσην ἔχει δύναμιν, οὐδ’ ὅτι ταῦτα πολὺ ἂν θᾶττον τὴν ἡμετέραν φύσιν ἢ τὴν ἐκείνων ὠφελήσειεν· ὥστ’ ἀπορῶ πότερον ἄν τις δικαιότερον θαυμάσειε τὰς πραότητας τὰς τοῖς χαλεπωτάτοις τῶν θηρίων ἐγγιγνομένας ἢ τὰς ἀγριότητας τὰς ἐν ταῖς ψυχαῖς τῶν τοιούτων ἀνθρώπων ἐνούσας.", "st": "15.214"}, {"sp": "N", "t": "ἔχοι δ’ ἄν τις πλείω περὶ τούτων εἰπεῖν· ἀλλὰ γὰρ ἢν πολλὰ λίαν λέγω περὶ τῶν παρὰ τοῖς πλείστοις ὁμολογουμένων, δέδοικα μὴ περὶ τῶν ἀμφισβητουμένων ἀπορεῖν δόξω. παυσάμενος οὖν τούτων ἐπ’ ἐκείνους τρέψομαι, τοὺς οὐ καταφρονοῦντας μὲν τῆς φιλοσοφίας, πολὺ δὲ πικρότερον κατηγοροῦντας αὐτῆς, καὶ μεταφέροντας τὰς πονηρίας τὰς τῶν φασκόντων μὲν εἶναι σοφιστῶν ἄλλο δέ τι πραττόντων ἐπὶ τοὺς οὐδὲν τῶν αὐτῶν ἐκείνοις ἐπιτηδεύοντας.", "st": "15.215"}, {"sp": "N", "t": "ἐγὼ δ’ οὐχ ὑπὲρ ἁπάντων τῶν προσποιουμένων δύνασθαι παιδεύειν ποιοῦμαι τοὺς λόγους, ἀλλ’ ὑπὲρ τῶν δικαίως τὴν δόξαν ταύτην ἐχόντων. οἶμαι δὲ σαφῶς ἐπιδείξειν τοὺς κατηγοροῦντας ἡμῶν πολὺ τῆς ἀληθείας διημαρτηκότας, ἤν περ ἐθελήσητε διὰ τέλους ἀκοῦσαι τῶν λεγομένων.", "st": "15.216"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὁρίσασθαι δεῖ τίνων ὀρεγόμενοι καὶ τίνος τυχεῖν βουλόμενοι τολμῶσί τινες ἀδικεῖν· ἢν γὰρ ταῦτα καλῶς περιλάβωμεν, ἄμεινον γνώσεσθε τὰς αἰτίας τὰς καθ’ ἡμῶν λεγομένας, εἴτ’ ἀληθεῖς εἰσιν εἴτε ψευδεῖς. ἐγὼ μὲν οὖν ἡδονῆς ἢ κέρδους ἢ τιμῆς ἕνεκα φημὶ πάντας πάντα πράττειν· ἔξω γὰρ τούτων οὐδεμίαν ἐπιθυμίαν ὁρῶ τοῖς ἀνθρώποις ἐγγιγνομένην.", "st": "15.217"}, {"sp": "N", "t": "εἰ δὴ ταῦθ’ οὕτως ἔχει, λοιπόν ἐστι σκέψασθαι τί τούτων ἂν ἡμῖν γίγνοιτο διαφθείρουσι τοὺς νεωτέρους. πότερ’ ἂν ἡσθείημεν ὁρῶντες ἢ καὶ πυνθανόμενοι πονηροὺς αὐτοὺς ὄντας καὶ δοκοῦντας τοῖς συμπολιτευομένοις; καὶ τίς οὕτως ἐστὶν ἀναίσθητος ὅστις οὐκ ἂν ἀλγήσειε τοιαύτης διαβολῆς περὶ αὑτὸν γιγνομένης;", "st": "15.218"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἂν θαυμασθεῖμεν οὐδὲ τιμῆς μεγάλης τύχοιμεν τοιούτους τοὺς συνόντας ἀποπέμποντες, ἀλλὰ πολὺ ἂν μᾶλλον καταφρονηθεῖμεν καὶ μισηθεῖμεν τῶν ταῖς ἄλλαις πονηρίαις ἐνόχων ὄντων. καὶ μὴν οὐδ’ εἰ ταῦτα παρίδοιμεν, χρήματα πλεῖστ’ ἂν λάβοιμεν οὕτω παιδείας προεστῶτες.", "st": "15.219"}, {"sp": "N", "t": "οἶμαι γὰρ δήπου τοῦτό γε πάντας γιγνώσκειν, ὅτι σοφιστῇ μισθὸς κάλλιστός ἐστι καὶ μέγιστος, ἢν τῶν μαθητῶν τινες καλοὶ κἀγαθοὶ καὶ φρόνιμοι γένωνται καὶ παρὰ τοῖς πολίταις εὐδοκιμοῦντες· οἱ μὲν γὰρ τοιοῦτοι πολλοὺς μετασχεῖν τῆς παιδείας εἰς ἐπιθυμίαν καθιστᾶσιν, οἱ δὲ πονηροὶ καὶ τοὺς πρότερον συνεῖναι διανοουμένους ἀποτρέπουσιν. ὥστε τίς ἂν ἐν τούτοις τὸ κρεῖττον ἀγνοήσειεν, οὕτω μεγάλην τὴν διαφορὰν τῶν πραγμάτων ἐχόντων;", "st": "15.220"}, {"sp": "N", "t": "ἴσως οὖν ἄν τις πρὸς ταῦτα τολμήσειεν εἰπεῖν ὡς πολλοὶ τῶν ἀνθρώπων διὰ τὰς ἀκρασίας οὐκ ἐμμένουσι τοῖς λογισμοῖς, ἀλλ’ ἀμελήσαντες τοῦ συμφέροντος ἐπὶ τὰς ἡδονὰς ὁρμῶσιν. ἐγὼ δ’ ὁμολογῶ καὶ τῶν ἄλλων πολλοὺς καὶ τῶν προσποιουμένων εἶναι σοφιστῶν ἔχειν τινὰς τὴν φύσιν ταύτην,", "st": "15.221"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐδὲ τῶν τοιούτων οὐδείς ἐστιν οὕτως ἀκρατὴς ὅστις ἂν δέξαιτο καὶ τοὺς μαθητὰς εἶναι τοιούτους· τῶν μὲν γὰρ ἡδονῶν τῶν διὰ τὴν ἀκρασίαν ἐκείνοις συμβαινουσῶν οὐκ ἂν δύναιτο μετασχεῖν, τῆς δὲ δόξης τῆς διὰ τὴν πονηρίαν γιγνομένης αὐτὸς ἂν τὸ πλεῖστον μέρος ἀπολαύσειεν. ἔπειτα τίνας ἂν καὶ διαφθείραιεν, καὶ τοὺς πῶς διακειμένους λάβοιεν ἂν μαθητάς; ἄξιον γὰρ καὶ ταῦτα διελθεῖν.", "st": "15.222"}, {"sp": "N", "t": "πότερον τοὺς ἤδη κακοήθεις ὄντας καὶ πονηρούς; καὶ τίς ἄν, ἃ παρὰ τῆς αὑτοῦ φύσεως ἐπίσταται, ταῦτα παρ’ ἑτέρου μανθάνειν ἐπιχειρήσειεν; ἀλλὰ τοὺς ἐπιεικεῖς καὶ χρηστῶν ἐπιτηδευμάτων ἐπιθυμοῦντας; ἀλλ’ οὐδ’ ἂν εἷς τῶν τοιούτων τοῖς κακόν τι λέγουσιν ἢ πράττουσι διαλεχθῆναι τολμήσειεν.", "st": "15.223"}, {"sp": "N", "t": "ἡδέως δ’ ἂν κἀκεῖνο πυθοίμην παρὰ τῶν χαλεπῶς ἐχόντων πρὸς ἡμᾶς, τίνα ποτὲ γνώμην ἔχουσι περὶ τῶν ἐκ Σικελίας καὶ τοῦ Πόντου καὶ τῶν ἄλλων τόπων δεῦρο πλεόντων, ἵνα παιδευθῶσι. πότερον αὐτοὺς οἴονται σπανίζοντας ἐκεῖ πονηρῶν ἀνθρώπων ἐνθάδε ποιεῖσθαι τὴν πορείαν; ἀλλὰ πανταχοῦ πολλὴν ἀφθονίαν εὕροι τις ἂν τῶν συμπονηρεύεσθαι καὶ συνεξαμαρτάνειν βουλομένων. ἀλλ’ ἵνα κακοπράγμονες καὶ συκοφάνται γένωνται,", "st": "15.224"}, {"sp": "N", "t": "πολλὰ χρήματα τελέσαντες; ἀλλὰ πρῶτον μὲν οἱ ταύτην ἔχοντες τὴν γνώμην πολὺ ἂν ἥδιον τὰ τῶν ἄλλων λάβοιεν ἢ δοῖεν ἑτέροις ὁτιοῦν τῶν σφετέρων αὐτῶν· ἔτι δὲ τίνες ἂν ὑπὲρ πονηρίας ἀργύριον ἀναλώσαιεν, ἐξὸν αὐτοῖς μηδὲν δαπανηθεῖσιν εἶναι τοιούτοις, ὁπόταν βουληθῶσιν; οὐ γὰρ μαθεῖν ἀλλ’ ἐπιχειρῆσαι μόνον δεῖ τοῖς τοιούτοις τῶν ἔργων.", "st": "15.225"}, {"sp": "N", "t": "ἀλλὰ δῆλον ὅτι καὶ πλέουσι καὶ χρήματα διδόασι καὶ πάντα ποιοῦσι νομίζοντες αὐτοί τε βελτίους γενήσεσθαι καὶ τοὺς ἐνθάδε παιδεύοντας πολὺ φρονιμωτέρους εἶναι τῶν παρὰ σφίσιν αὐτοῖς· ἐφ’ οἷς ἄξιον ἦν ἅπαντας τοὺς πολίτας φιλοτιμεῖσθαι, καὶ περὶ πολλοῦ ποιεῖσθαι τοὺς αἰτίους τῇ πόλει τῆς δόξης ταύτης γενομένους.", "st": "15.226"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὕτω τινὲς ἀγνωμόνως ἔχουσιν ὥστ’ εἰδότες καὶ τοὺς ξένους τοὺς ἀφικνουμένους καὶ τοὺς προεστῶτας τῆς παιδείας οὐδὲν κακὸν ἐπιτηδεύοντας, ἀλλ’ ἀπραγμονεστάτους μὲν ὄντας τῶν ἐν τῇ πόλει καὶ πλείστην ἡσυχίαν ἄγοντας, προσέχοντας δὲ τὸν νοῦν σφίσιν αὐτοῖς καὶ τὰς συνουσίας μετ’ ἀλλήλων ποιουμένους,", "st": "15.227"}, {"sp": "N", "t": "ἔτι δὲ τὰ καθ’ ἡμέραν εὐτελέστατα καὶ κοσμιώτατα ζῶντας, καὶ τῶν λόγων ἐπιθυμοῦντας οὐ τῶν ἐπὶ τοῖς ἰδίοις συμβολαίοις λεγομένων οὐδὲ τῶν λυπούντων τινάς, ἀλλὰ τῶν παρὰ πᾶσιν ἀνθρώποις εὐδοκιμούντων, ὅμως τολμῶσι βλασφημεῖν περὶ αὐτῶν καὶ λέγειν ὡς ταύτην ποιοῦνται τὴν μελέτην, ἵν’ ἐν τοῖς ἀγῶσι παρὰ τὸ δίκαιον πλεονεκτῶσι.", "st": "15.228"}, {"sp": "N", "t": "καί τοι τίνες ἂν ἀδικίαν καὶ κακίαν ἀσκοῦντες σωφρονέστερον τῶν ἄλλων ζῆν ἐθελήσαιεν; τίνας δὲ πώποθ’ ἑωράκασιν οἱ ταῦτα λέγοντες ἀναβαλλομένους καὶ θησαυριζομένους τὰς πονηρίας, ἀλλ’ οὐκ εὐθὺς τῇ φύσει τῇ παρούσῃ χρωμένους;", "st": "15.229"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, εἴπερ ἡ περὶ τοὺς λόγους δεινότης ποιεῖ τοῖς ἀλλοτρίοις ἐπιβουλεύειν, προσῆκεν ἅπαντας τοὺς δυναμένους εἰπεῖν πολυπράγμονας καὶ συκοφάντας εἶναι· τὸ γὰρ αἴτιον ἐν ἅπασι ταὐτὸ πέφυκεν ἐνεργάζεσθαι.", "st": "15.230"}, {"sp": "N", "t": "νῦν δ’ εὑρήσετε καὶ τῶν ἐν τῷ παρόντι πολιτευομένων καὶ τῶν νεωστὶ τετελευτηκότων τοὺς πλείστην ἐπιμέλειαν τῶν λόγων ποιουμένους βελτίστους ὄντας τῶν ἐπὶ τὸ βῆμα παριόντων, ἔτι δὲ τῶν παλαιῶν τοὺς ἀρίστους ῥήτορας καὶ μεγίστην δόξαν λαβόντας πλείστων ἀγαθῶν αἰτίους τῇ πόλει γεγενημένους, ἀρξαμένους ἀπὸ Σόλωνος.", "st": "15.231"}, {"sp": "N", "t": "ἐκεῖνός τε γὰρ προστάτης τοῦ δήμου καταστὰς οὕτως ἐνομοθέτησε καὶ τὰ πράγματα διέταξε καὶ τὴν πόλιν κατεσκεύασεν, ὥστ’ ἔτι καὶ νῦν ἀγαπᾶσθαι τὴν διοίκησιν τὴν ὑπ’ ἐκείνου συνταχθεῖσαν· μετὰ δὲ ταῦτα Κλεισθένης ἐκπεσὼν ἐκ τῆς πόλεως ὑπὸ τῶν τυράννων, λόγῳ πείσας τοὺς Ἀμφικτύονας δανεῖσαι τῶν τοῦ θεοῦ χρημάτων αὑτῷ, τόν τε δῆμον κατήγαγε καὶ τοὺς τυράννους ἐξέβαλε καὶ τὴν δημοκρατίαν ἐκείνην κατέστησε, τὴν αἰτίαν τοῖς Ἕλλησι τῶν μεγίστων ἀγαθῶν γενομένην·", "st": "15.232"}, {"sp": "N", "t": "ἐπὶ δὲ τούτῳ Θεμιστοκλῆς ἡγεμὼν ἐν τῷ πολέμῳ τῷ Περσικῷ γενόμενος, συμβουλεύσας τοῖς προγόνοις ἡμῶν ἐκλιπεῖν τὴν πόλιν, (ὃ τίς ἂν οἷός τ’ ἐγένετο πεῖσαι μὴ πολὺ τῷ λόγῳ διενεγκών;) εἰς τοῦτ’ αὐτῶν τὰ πράγματα προήγαγεν ὥστ’ ὀλίγας ἡμέρας ἀνάστατοι γενόμενοι πολὺν χρόνον δεσπόται τῶν Ἑλλήνων κατέστησαν·", "st": "15.233"}, {"sp": "N", "t": "τὸ δὲ τελευταῖον Περικλῆς καὶ δημαγωγὸς ὢν ἀγαθὸς καὶ ῥήτωρ ἄριστος οὕτως ἐκόσμησε τὴν πόλιν καὶ τοῖς ἱεροῖς καὶ τοῖς ἀναθήμασι καὶ τοῖς ἄλλοις ἅπασιν, ὥστ’ ἔτι καὶ νῦν τοὺς εἰσαφικνουμένους εἰς αὐτὴν νομίζειν μὴ μόνον ἄρχειν ἀξίαν εἶναι τῶν Ἑλλήνων ἀλλὰ καὶ τῶν ἄλλων ἁπάντων, καὶ πρὸς τούτοις εἰς τὴν ἀκρόπολιν οὐκ ἐλάττω μυρίων ταλάντων ἀνήνεγκε.", "st": "15.234"}, {"sp": "N", "t": "καὶ τούτων τῶν ἀνδρῶν τῶν τηλικαῦτα διαπραξαμένων οὐδεὶς λόγων ἠμέλησεν, ἀλλὰ τοσούτῳ μᾶλλον τῶν ἄλλων προσέσχον αὐτοῖς τὸν νοῦν, ὥστε Σόλων μὲν τῶν ἑπτὰ σοφιστῶν ἐκλήθη καὶ ταύτην ἔσχε τὴν ἐπωνυμίαν, τὴν νῦν ἀτιμαζομένην καὶ κρινομένην παρ’ ὑμῖν, Περικλῆς δὲ δυοῖν ἐγένετο μαθητής, Ἀναξαγόρου τε τοῦ Κλαζομενίου καὶ Δάμωνος, τοῦ κατ’ ἐκεῖνον τὸν χρόνον φρονιμωτάτου δόξαντος εἶναι τῶν πολιτῶν.", "st": "15.235"}, {"sp": "N", "t": "ὥστ’ ἐκ τίνων ἄν τις ὑμῖν σαφέστερον ἐπιδείξειεν ὡς οὐχ αἱ δυνάμεις αἱ τῶν λόγων κακοπράγμονας τοὺς ἀνθρώπους ποιοῦσιν; ἀλλ’ οἱ τοιαύτην φύσιν ἔχοντες, οἵαν περ ὁ κατήγορος, πονηροῖς οἶμαι καὶ τοῖς λόγοις καὶ τοῖς πράγμασι χρώμενοι διατελοῦσιν.", "st": "15.236"}, {"sp": "N", "t": "ἔχω δὲ δεῖξαι καὶ τόπους ἐν οἷς ἔξεστιν ἰδεῖν τοῖς βουλομένοις τοὺς πολυπράγμονας καὶ τοὺς ταῖς αἰτίαις ἐνόχους ὄντας ἃς οὗτοι τοῖς σοφισταῖς ἐπιφέρουσιν. ἐν γὰρ ταῖς σανίσι ταῖς ὑπὸ τῶν ἀρχόντων ἐκτιθεμέναις ἀναγκαῖόν ἐστιν, ἐν μὲν ταῖς ὑπὸ τῶν θεσμοθετῶν ἀμφοτέρους ἐνεῖναι, τούς τε τὴν πόλιν ἀδικοῦντας καὶ τοὺς συκοφαντοῦντας, ἐν δὲ ταῖς τῶν ἕνδεκα τούς τε κακουργοῦντας καὶ τοὺς τούτοις ἐφεστῶτας, ἐν δὲ ταῖς τῶν τετταράκοντα τούς τ’ ἐν τοῖς ἰδίοις πράγμασιν ἀδικοῦντας καὶ τοὺς μὴ δικαίως ἐγκαλοῦντας·", "st": "15.237"}, {"sp": "N", "t": "ἐν αἷς τοῦτον μὲν καὶ τοὺς τούτου φίλους εὕροιτ’ ἂν ἐν πολλαῖς ἐγγεγραμμένους, ἐμὲ δὲ καὶ τοὺς περὶ τὴν αὐτὴν ἐμοὶ διατριβὴν ὄντας οὐδ’ ἐν μιᾷ τούτων ἐνόντας, ἀλλ’ οὕτω τὰ περὶ ἡμᾶς αὐτοὺς διοικοῦντας ὥστε μηδὲν δεῖσθαι τῶν ἀγώνων τῶν παρ’ ὑμῖν.", "st": "15.238"}, {"sp": "N", "t": "καί τοι τοὺς μήτ’ ἐν ταῖς πραγματείαις ταύταις ὄντας μήτ’ ἀκολάστως ζῶντας μήτε περὶ ἄλλην πρᾶξιν μηδεμίαν αἰσχρὰν γεγενημένους πῶς οὐκ ἐπαινεῖσθαι προσήκει μᾶλλον ἢ κρίνεσθαι; δῆλον γὰρ ὅτι τοιαῦτα τοὺς συνόντας παιδεύομεν, οἷά περ αὐτοὶ τυγχάνομεν ἐπιτηδεύοντες.", "st": "15.239"}, {"sp": "N", "t": "ἔτι τοίνυν γνώσεσθε σαφέστερον ἐκ τῶν ῥηθήσεσθαι μελλόντων ὡς πόρρω τοῦ διαφθείρειν τοὺς νεωτέρους ἐσμέν. εἰ γάρ τι τοιοῦτον ἐποιοῦμεν, οὐκ ἂν Λυσίμαχος ἦν ὁ λυπούμενος ὑπὲρ αὐτῶν οὐδ’ ἄλλος οὐδεὶς τῶν τοιούτων, ἀλλὰ τοὺς πατέρας ἂν ἑωρᾶτε τῶν συνόντων ἡμῖν καὶ τοὺς οἰκείους ἀγανακτοῦντας καὶ γραφομένους καὶ δίκην ζητοῦντας παρ’ ἡμῶν λαμβάνειν.", "st": "15.240"}, {"sp": "N", "t": "νῦν δ’ ἐκεῖνοι μὲν συνιστᾶσι τοὺς παῖδας τοὺς αὑτῶν, καὶ χρήματα διδόασι, καὶ χαίρουσιν ὁπόταν ὁρῶσιν αὐτοὺς μεθ’ ἡμῶν ἡμερεύοντας, οἱ δὲ συκοφάνται διαβάλλουσι καὶ πράγματα παρέχουσιν ἡμῖν, ὧν τίνες ἂν ἥδιον ἴδοιεν πολλοὺς τῶν πολιτῶν διαφθειρομένους καὶ πονηροὺς γιγνομένους; ἴσασι γὰρ σφᾶς αὐτοὺς ἐν μὲν τοῖς τοιούτοις δυναστεύοντας, ὑπὸ δὲ τῶν καλῶν κἀγαθῶν καὶ νοῦν ἐχόντων ἀπολλυμένους, ὁπόταν ληφθῶσιν.", "st": "15.241"}, {"sp": "N", "t": "ὥσθ’ οὗτοι μὲν σωφρονοῦσιν ἀναιρεῖν ζητοῦντες ἁπάσας τὰς τοιαύτας διατριβάς, ἐν αἷς ἡγοῦνται βελτίους γενομένους χαλεπωτέρους ἔσεσθαι ταῖς αὑτῶν πονηρίαις καὶ συκοφαντίαις, ὑμᾶς δὲ προσήκει τἀναντία τούτοις πράττειν, καὶ ταῦτα νομίζειν εἶναι κάλλιστα τῶν ἐπιτηδευμάτων οἷς ἂν τούτους ὁρᾶτε μάλιστα πολεμοῦντας.", "st": "15.242"}, {"sp": "N", "t": "ἄτοπον δέ τι τυγχάνω πεπονθώς· εἰρήσεται γὰρ, εἰ καί τινες λίαν εὐμετάβολον εἶναί με φήσουσιν. ὀλίγῳ μὲν γὰρ πρότερον ἔλεγον ὡς πολλοὶ τῶν καλῶν κἀγαθῶν ἀνδρῶν διεψευσμένοι τῆς φιλοσοφίας τραχύτερον πρὸς αὐτὴν ἔχουσι· νῦν δ’ οὕτως ἐναργεῖς ὑπείληφα τοὺς λόγους εἶναι τοὺς εἰρημένους καὶ πᾶσι φανερούς, ὥστ’ οὐδεὶς ἀγνοεῖν μοι δοκεῖ τὴν δύναμιν αὐτῆς, οὐδὲ καταγιγνώσκειν ἡμῶν ὡς διαφθείρομεν τοὺς μαθητάς, οὐδὲ πεπονθέναι τοιοῦτον οὐδὲν οἷον αὐτοὺς ὀλίγῳ πρότερον ᾐτιώμην·", "st": "15.243"}, {"sp": "N", "t": "ἀλλ’ εἰ δεῖ τἀληθὲς εἰπεῖν καὶ τὸ νῦν ἐν τῇ διανοίᾳ μοι παρεστηκός, ἡγοῦμαι πάντας τοὺς φιλοτίμως μοι διακειμένους ἐπιθυμητικῶς ἔχοντας τοῦ φρονεῖν εὖ καὶ λέγειν αὐτοὺς μὲν ἀμελεῖν τούτων, τοὺς μὲν διὰ ῥᾳθυμίαν, τοὺς δὲ καταμεμφομένους τὴν φύσιν τὴν αὑτῶν, τοὺς δὲ δι’ ἄλλας τινὰς προφάσεις (παμπληθεῖς δ’ εἰσί),", "st": "15.244"}, {"sp": "N", "t": "πρὸς δὲ τοὺς πολλὴν ἐπιμέλειαν ποιουμένους καὶ τυχεῖν βουλομένους ὧν εἰς ἐπιθυμίαν αὐτοὶ καθεστᾶσι, δυσκόλως ἔχειν καὶ ζηλοτυπεῖν καὶ τὰς ψυχὰς τεταραγμένως διακεῖσθαι καὶ πεπονθέναι παραπλήσια τοῖς ἐρῶσι· τίνα γὰρ ἄν τις αὐτοῖς ἐπενεγκεῖν αἰτίαν ἔχοι πρεπωδεστέραν ταύτης;", "st": "15.245"}, {"sp": "N", "t": "οἵτινες μακαρίζουσι μὲν καὶ ζηλοῦσι τοὺς καλῶς χρῆσθαι τῷ λόγῳ δυναμένους, ἐπιτιμῶσι δὲ τῶν νεωτέρων τοῖς τυχεῖν ταύτης τῆς τιμῆς βουλομένοις. καὶ τοῖς μὲν θεοῖς οὐδεὶς ἔστιν ὅστις οὐκ ἂν εὔξαιτο μάλιστα μὲν αὐτὸς δύνασθαι λέγειν, εἰ δὲ μή, τοὺς παῖδας καὶ τοὺς οἰκείους τοὺς αὑτοῦ·", "st": "15.246"}, {"sp": "N", "t": "τοὺς δὲ πόνῳ καὶ φιλοσοφίᾳ τοῦτο κατεργάσασθαι πειρωμένους, ὃ παρὰ τῶν θεῶν αὐτοὶ βούλονται λαβεῖν, οὐδέν φασι τῶν δεόντων πράττειν, ἀλλ’ ἐνίοτε μὲν ὡς ἐξηπατημένων καὶ πεφενακισμένων προσποιοῦνται καταγελᾶν αὐτῶν, ὁπόταν δὲ τύχωσι, μεταβαλόντες ὡς περὶ πλεονεκτεῖν δυναμένων τοὺς λόγους ποιοῦνται.", "st": "15.247"}, {"sp": "N", "t": "καὶ συμβούλοις μέν, ὅταν κίνδυνός τις καταλάβῃ τὴν πόλιν, τοῖς ἄριστα περὶ τῶν πραγμάτων λέγουσι, τούτοις χρῶνται, καὶ πράττουσιν ὅ τι ἂν οἱ τοιοῦτοι παραινέσωσι· περὶ δὲ τοὺς ἔργον ποιουμένους ὅπως χρησίμους αὑτοὺς ἐν τοῖς καιροῖς τοῖς τοιούτοις τῇ πόλει παρασχήσουσι, βλασφημεῖν οἴονται χρῆναι. καὶ Θηβαίοις μὲν καὶ τοῖς ἄλλοις ἐχθροῖς τὴν ἀμαθίαν ὀνειδίζουσι, τοὺς δ’ ἐκ παντὸς τρόπου ζητοῦντας τὴν νόσον ταύτην διαφυγεῖν λοιδοροῦντες διατελοῦσιν.", "st": "15.248"}, {"sp": "N", "t": "ὃ δ’ οὐ μόνον ταραχῆς σημεῖόν ἐστιν, ἀλλὰ καὶ τῆς περὶ τοὺς θεοὺς ὀλιγωρίας· τὴν μὲν γὰρ Πειθὼ μίαν τῶν θεῶν νομίζουσιν εἶναι, καὶ τὴν πόλιν ὁρῶσι καθ’ ἕκαστον τὸν ἐνιαυτὸν θυσίαν αὐτῇ ποιουμένην, τοὺς δὲ τῆς δυνάμεως ἧς ἡ θεὸς ἔχει μετασχεῖν βουλομένους ὡς κακοῦ πράγματος ἐπιθυμοῦντας διαφθείρεσθαί φασιν.", "st": "15.249"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὅτι προκρίναιεν μὲν ἂν τὴν ψυχὴν σπουδαιοτέραν εἶναι τοῦ σώματος, οὕτω δὲ γιγνώσκοντες ἀποδέχονται μᾶλλον τοὺς γυμναζομένους τῶν φιλοσοφούντων. καί τοι πῶς οὐκ ἄλογον τοὺς τοῦ φαυλοτέρου ποιουμένους τὴν ἐπιμέλειαν ἐπαινεῖν μᾶλλον ἢ τοὺς τοῦ σπουδαιοτέρου, καὶ ταῦτα πάντων εἰδότων διὰ μὲν εὐεξίαν σώματος οὐδὲν πώποτε τὴν πόλιν τῶν ἐλλογίμων ἔργων διαπραξαμένην, διὰ δὲ φρόνησιν ἀνδρὸς εὐδαιμονεστάτην καὶ μεγίστην τῶν Ἑλληνίδων πόλεων γενομένην;", "st": "15.250"}, {"sp": "N", "t": "πολὺ δ’ ἄν τις ἔχοι πλείους τούτων ἐναντιώσεις συναγαγεῖν τῶν ἀκμαζόντων τε μᾶλλον ἢ ’γὼ καὶ τοῦ καιροῦ τοῦ παρόντος μὴ φροντιζόντων· ἐπεὶ καὶ τάδε περὶ τῶν αὐτῶν τούτων ἔνεστιν εἰπεῖν. φέρε γὰρ εἴ τινες πολλὰ χρήματα παρὰ τῶν προγόνων παραλαβόντες τῇ μὲν πόλει μηδὲν εἶεν χρήσιμοι, τοὺς δὲ πολίτας ὑβρίζοιεν καὶ τούς τε παῖδας καὶ τὰς γυναῖκας αἰσχύνοιεν, ἔστιν ὅστις ἂν τοὺς αἰτίους τοῦ πλούτου μέμψασθαι τολμήσειεν, ἀλλ’ οὐκ ἂν αὐτοὺς τοὺς ἐξαμαρτάνοντας κολάζειν ἀξιώσειε;", "st": "15.251"}, {"sp": "N", "t": "τί δ’ εἴ τινες ὁπλομαχεῖν μαθόντες πρὸς μὲν τοὺς πολεμίους μὴ χρῷντο ταῖς ἐπιστήμαις, ἐπανάστασιν δὲ ποιήσαντες πολλοὺς τῶν πολιτῶν διαφθείραιεν, ἢ καὶ πυκτεύειν καὶ παγκρατιάζειν ὡς οἷόν τ’ ἄριστα παιδευθέντες τῶν μὲν ἀγώνων ἀμελοῖεν, τοὺς δ’ ἀπαντῶντας τύπτοιεν, τίς οὐκ ἂν τούτων τοὺς μὲν διδασκάλους ἐπαινέσειε, τοὺς δὲ κακῶς χρωμένους οἷς ἔμαθον ἀποκτείνειεν;", "st": "15.252"}, {"sp": "N", "t": "οὐκοῦν χρὴ καὶ περὶ τῶν λόγων τὴν αὐτὴν ἔχειν διάνοιαν ἥν περ καὶ περὶ τῶν ἄλλων, καὶ μὴ περὶ τῶν ὁμοίων τἀναντία γιγνώσκειν, μηδὲ πρὸς τοιοῦτο πρᾶγμα δυσμενῶς φαίνεσθαι διακειμένους, ὃ πάντων τῶν ἐνόντων ἐν τῇ τῶν ἀνθρώπων φύσει πλείστων ἀγαθῶν αἴτιόν ἐστι. τοῖς μὲν γὰρ ἄλλοις οἷς ἔχομεν, ὅ περ ἤδη καὶ πρότερον εἶπον, οὐδὲν τῶν ἄλλων ζώων διαφέρομεν, ἀλλὰ πολλῶν καὶ τῷ τάχει καὶ τῇ ῥώμῃ καὶ ταῖς ἄλλαις εὐπορίαις καταδεέστεροι τυγχάνομεν ὄντες·", "st": "15.253"}, {"sp": "N", "t": "ἐγγενομένου δ’ ἡμῖν τοῦ πείθειν ἀλλήλους καὶ δηλοῦν πρὸς ἡμᾶς αὐτοὺς περὶ ὧν ἂν βουληθῶμεν, οὐ μόνον τοῦ θηριωδῶς ζῆν ἀπηλλάγημεν, ἀλλὰ καὶ συνελθόντες πόλεις ᾠκίσαμεν καὶ νόμους ἐθέμεθα καὶ τέχνας εὕρομεν, καὶ σχεδὸν ἅπαντα τὰ δι’ ἡμῶν μεμηχανημένα λόγος ἡμῖν ἐστιν ὁ συγκατασκευάσας.", "st": "15.254"}, {"sp": "N", "t": "οὗτος γὰρ περὶ τῶν δικαίων καὶ τῶν ἀδίκων καὶ τῶν καλῶν καὶ τῶν αἰσχρῶν ἐνομοθέτησεν, ὧν μὴ διαταχθέντων οὐκ ἂν οἷοί τ’ ἦμεν οἰκεῖν μετ’ ἀλλήλων. τούτῳ καὶ τοὺς κακοὺς ἐξελέγχομεν καὶ τοὺς ἀγαθοὺς ἐγκωμιάζομεν. διὰ τούτου τοὺς τ’ ἀνοήτους παιδεύομεν καὶ τοὺς φρονίμους δοκιμάζομεν· τὸ γὰρ λέγειν ὡς δεῖ τοῦ φρονεῖν εὖ μέγιστον σημεῖον ποιούμεθα, καὶ λόγος ἀληθὴς καὶ νόμιμος καὶ δίκαιος ψυχῆς ἀγαθῆς καὶ πιστῆς εἴδωλόν ἐστι.", "st": "15.255"}, {"sp": "N", "t": "μετὰ τούτου καὶ περὶ τῶν ἀμφισβητησίμων ἀγωνιζόμεθα καὶ περὶ τῶν ἀγνοουμένων σκοπούμεθα· ταῖς γὰρ πίστεσιν, αἷς τοὺς ἄλλους λέγοντες πείθομεν, ταῖς αὐταῖς ταύταις βουλευόμενοι χρώμεθα, καὶ ῥητορικοὺς μὲν καλοῦμεν τοὺς ἐν τῷ πλήθει λέγειν δυναμένους, εὐβούλους δὲ νομίζομεν οἵτινες ἂν αὐτοὶ πρὸς αὑτοὺς ἄριστα περὶ τῶν πραγμάτων διαλεχθῶσιν.", "st": "15.256"}, {"sp": "N", "t": "εἰ δὲ δεῖ συλλήβδην περὶ τῆς δυνάμεως ταύτης εἰπεῖν, οὐδὲν τῶν φρονίμως πραττομένων εὑρήσομεν ἀλόγως γιγνόμενον, ἀλλὰ καὶ τῶν ἔργων καὶ τῶν διανοημάτων ἁπάντων ἡγεμόνα λόγον ὄντα, καὶ μάλιστα χρωμένους αὐτῷ τοὺς πλεῖστον νοῦν ἔχοντας. ὧν οὐδὲν ἐνθυμηθεὶς Λυσίμαχος κατηγορεῖν ἐτόλμησε τῶν ἐπιθυμούντων τοιούτου πράγματος, ὃ τοσούτων τὸ πλῆθος καὶ τηλικούτων τὸ μέγεθος ἀγαθῶν αἴτιόν ἐστιν.", "st": "15.257"}, {"sp": "N", "t": "καὶ τί δεῖ τούτου θαυμάζειν, ὅπου καὶ τῶν περὶ τὰς ἔριδας σπουδαζόντων ἔνιοί τινες ὁμοίως βλασφημοῦσι περὶ τῶν λόγων τῶν κοινῶν καὶ τῶν χρησίμων ὥσπερ οἱ φαυλότατοι τῶν ἀνθρώπων, οὐκ ἀγνοοῦντες τὴν δύναμιν αὐτῶν, οὐδ’ ὅτι τάχιστ’ ἂν οὗτοι τοὺς χρωμένους ὠφελήσαιεν, ἀλλ’ ἐλπίζοντες, ἢν τούτους διαβάλλωσι, τοὺς αὑτῶν ἐντιμοτέρους ποιήσειν.", "st": "15.258"}, {"sp": "N", "t": "περὶ ὧν δυνηθείην μὲν ἂν ἴσως διαλεχθῆναι πολὺ πικρότερον ἢ ’κεῖνοι περὶ ἡμῶν, οὐδέτερον δ’ οἶμαι δεῖν, οὔθ’ ὅμοιος γίγνεσθαι τοῖς ὑπὸ τοῦ φθόνου διεφθαρμένοις, οὔτε ψέγειν τοὺς μηδὲν μὲν κακὸν τοὺς συνόντας ἐργαζομένους, ἧττον δ’ ἑτέρων εὐεργετεῖν δυναμένους. οὐ μὴν ἀλλὰ μικρά γε μνησθήσομαι περὶ αὐτῶν, μάλιστα μὲν ὅτι κἀκεῖνοι περὶ ἡμῶν, ἔπειθ’ ὅπως ἂν ὑμεῖς σαφέστερον εἰδότες τὴν δύναμιν αὐτῶν οὕτω διακέησθε πρὸς ἑκάστους ἡμῶν ὥσπερ δίκαιόν ἐστι,", "st": "15.259"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἵνα καὶ τοῦτο ποιήσω φανερόν, ὅτι περὶ τοὺς πολιτικοὺς λόγους ἡμεῖς ὄντες, οὓς ἐκεῖνοί φασιν εἶναι φιλαπεχθήμονας, πολὺ πραότεροι τυγχάνομεν αὐτῶν ὄντες· οἱ μὲν γὰρ ἀεί τι περὶ ἡμῶν φλαῦρον λέγουσιν, ἐγὼ δ’ οὐδὲν ἂν εἴποιμι τοιοῦτον, ἀλλὰ ταῖς ἀληθείαις χρήσομαι περὶ αὐτῶν.", "st": "15.260"}, {"sp": "N", "t": "ἡγοῦμαι γὰρ καὶ τοὺς ἐν τοῖς ἐριστικοῖς λόγοις δυναστεύοντας καὶ τοὺς περὶ τὴν ἀστρολογίαν καὶ τὴν γεωμετρίαν καὶ τὰ τοιαῦτα τῶν μαθημάτων διατρίβοντας οὐ βλάπτειν ἀλλ’ ὠφελεῖν τοὺς συνόντας, ἐλάττω μὲν ὧν ὑπισχνοῦνται, πλείω δ’ ὧν τοῖς ἄλλοις δοκοῦσιν.", "st": "15.261"}, {"sp": "N", "t": "οἱ μὲν γὰρ πλεῖστοι τῶν ἀνθρώπων ὑπειλήφασιν ἀδολεσχίαν καὶ μικρολογίαν εἶναι τὰ τοιαῦτα τῶν μαθημάτων· οὐδὲν γὰρ αὐτῶν οὔτ’ ἐπὶ τῶν ἰδίων οὔτ’ ἐπὶ τῶν κοινῶν εἶναι χρήσιμον, ἀλλ’ οὐδ’ ἐν ταῖς μνείαις οὐδὲνα χρόνον ἐμμένειν ταῖς τῶν μαθόντων διὰ τὸ μήτε τῷ βίω παρακολουθεῖν μήτε ταῖς πράξεσιν ἐπαμύνειν, ἀλλ’ ἔξω παντάπασιν εἶναι τῶν ἀναγκαίων.", "st": "15.262"}, {"sp": "N", "t": "ἐγὼ δ’ οὔθ’ οὕτως οὔτε πόρρω τούτων ἔγνωκα περὶ αὐτῶν, ἀλλ’ οἵ τε νομίζοντες μηδὲν χρησίμην εἶναι τὴν παιδείαν ταύτην πρὸς τὰς πράξεις ὀρθῶς μοι δοκοῦσι γιγνώσκειν, οἵ τ’ ἐπαινοῦντες αὐτὴν ἀληθῆ λέγειν. διὰ τοῦτο δ’ οὐχ ὁμολογούμενον αὐτὸν αὑτῷ τὸν λόγον εἴρηκα, διότι καὶ ταῦτα τὰ μαθήματα τὴν φύσιν οὐδὲν ὁμοίαν ἔχει τοῖς ἄλλοις οἷς διδασκόμεθα.", "st": "15.263"}, {"sp": "N", "t": "τὰ μὲν γὰρ ἄλλα τότ’ ὠφελεῖν ἡμᾶς πέφυκεν, ὅταν λάβωμεν αὐτῶν τὴν ἐπιστήμην, ταῦτα δὲ τοὺς μὲν ἀπηκριβωμένους οὐδὲν ἂν εὐεργετήσειε, πλὴν τοὺς ἐντεῦθεν ζῆν προῃρημένους, τοὺς δὲ μανθάνοντας ὀνίνησι· περὶ γὰρ τὴν περιττολογίαν καὶ τὴν ἀκρίβειαν τῆς ἀστρολογίας καὶ γεωμετρίας διατρίβοντες,", "st": "15.264"}, {"sp": "N", "t": "καὶ δυσκαταμαθήτοις πράγμασιν ἀναγκαζόμενοι προσέχειν τὸν νοῦν, ἔτι δὲ συνεθιζόμενοι λέγειν καὶ πονεῖν ἐπὶ τοῖς λεγομένοις καὶ δεικνυμένοις καὶ μὴ πεπλανημένην ἔχειν τὴν διάνοιαν, ἐν τούτοις γυμνασθέντες καὶ παροξυνθέντες ῥᾷον καὶ θᾶττον τὰ σπουδαιότερα καὶ πλέονος ἄξια τῶν πραγμάτων ἀποδέχεσθαι καὶ μανθάνειν δύνανται.", "st": "15.265"}, {"sp": "N", "t": "φιλοσοφίαν μὲν οὖν οὐκ οἶμαι δεῖν προσαγορεύειν τὴν μηδὲν ἐν τῷ παρόντι μήτε πρὸς τὸ λέγειν μήτε πρὸς τὸ πράττειν ὠφελοῦσαν, γυμνασίαν μέντοι τῆς ψυχῆς καὶ παρασκευὴν φιλοσοφίας καλῶ τὴν διατριβὴν τὴν τοιαύτην, ἀνδρικωτέραν μὲν ἧς οἱ παῖδες ἐν τοῖς διδασκαλείοις ποιοῦνται, τὰ δὲ πλεῖστα παραπλησίαν·", "st": "15.266"}, {"sp": "N", "t": "καὶ γὰρ ἐκείνων οἱ περὶ τὴν γραμματικὴν καὶ τὴν μουσικὴν καὶ τὴν ἄλλην παιδείαν διαπονηθέντες πρὸς μὲν τὸ βέλτιον εἰπεῖν ἢ βουλεύσασθαι περὶ τῶν πραγμάτων οὐδεμίαν πω λαμβάνουσιν ἐπίδοσιν, αὐτοὶ δ’ αὑτῶν εὐμαθέστεροι γίγνονται πρὸς τὰ μείζω καὶ σπουδαιότερα τῶν μαθημάτων.", "st": "15.267"}, {"sp": "N", "t": "διατρῖψαι μὲν οὖν περὶ τὰς παιδείας ταύτας χρόνον τινὰ συμβουλεύσαιμ’ ἂν τοῖς νεωτέροις, μὴ μέντοι περιιδεῖν τὴν αὑτῶν κατασκελετευθεῖσαν ἐπὶ τούτοις, μηδ’ ἐξοκείλασαν εἰς τοὺς λόγους τοὺς τῶν παλαιῶν σοφιστῶν, ὧν ὁ μὲν ἄπειρον τὸ πλῆθος ἔφησεν εἶναι τῶν ὄντων, Ἐμπεδοκλῆς δὲ τέτταρα, καὶ νεῖκος καὶ φιλίαν ἐν αὐτοῖς, Ἴων δ’ οὐ πλείω τριῶν, Ἀλκμαίων δὲ δύο μόνα, Παρμενίδης δὲ καὶ Μέλισσος ἕν, Γοργίας δὲ παντελῶς οὐδέν.", "st": "15.268"}, {"sp": "N", "t": "ἡγοῦμαι γὰρ τὰς μὲν τοιαύτας περιττολογίας ὁμοίας εἶναι ταῖς θαυματοποιίαις, ταῖς οὐδὲν μὲν ὠφελούσαις ὑπὸ δὲ τῶν ἀνοήτων περιστάτοις γιγνομέναις, δεῖν δὲ τοὺς προὔργου τι ποιεῖν βουλομένους καὶ τῶν λόγων τοὺς ματαίους καὶ τῶν πράξεων τὰς μηδὲν πρὸς τὸν βίον φερούσας ἀναιρεῖν ἐξ ἁπασῶν τῶν διατριβῶν.", "st": "15.269"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων ἀπόχρη μοι τὸ νῦν εἶναι ταῦτ’ εἰρηκέναι καὶ συμβεβουλευκέναι· περὶ δὲ σοφίας καὶ φιλοσοφίας τοῖς μὲν περὶ ἄλλων τινῶν ἀγωνιζομένοις οὐκ ἂν ἁρμόσειε λέγειν περὶ τῶν ὀνομάτων τούτων (ἔστι γὰρ ἀλλότρια πάσαις ταῖς πραγματείαις), ἐμοὶ δ’ ἐπειδὴ καὶ κρίνομαι περὶ τῶν τοιούτων καὶ τὴν καλουμένην ὑπό τινων φιλοσοφίαν οὐκ εἶναι φημί, προσήκει τὴν δικαίως ἂν νομιζομένην ὁρίσαι καὶ δηλῶσαι πρὸς ὑμᾶς. ἁπλῶς δέ πως τυγχάνω γιγνώσκων περὶ αὐτῶν.", "st": "15.270"}, {"sp": "N", "t": "ἐπειδὴ γὰρ οὐκ ἔνεστιν ἐν τῇ φύσει τῇ τῶν ἀνθρώπων ἐπιστήμην λαβεῖν ἣν ἔχοντες ἂν εἰδεῖμεν ὅ τι πρακτέον ἤ λεκτέον ἐστίν, ἐκ τῶν λοιπῶν σοφοὺς μὲν νομίζω τοὺς ταῖς δόξαις ἐπιτυγχάνειν ὡς ἐπὶ τὸ πολὺ τοῦ βελτίστου δυναμένους, φιλοσόφους δὲ τοὺς ἐν τούτοις διατρίβοντας ἐξ ὧν τάχιστα λήψονται τὴν τοιαύτην φρόνησιν.", "st": "15.271"}, {"sp": "N", "t": "ἃ δ’ ἐστὶ τῶν ἐπιτηδευμάτων ταύτην ἔχοντα τὴν δύναμιν, ἔχω μὲν εἰπεῖν, ὀκνῶ δὲ λέγειν· οὕτω γάρ ἐστι σφόδρα καὶ παράδοξα καὶ πολὺ τῆς τῶν ἄλλων ἀφεστῶτα διανοίας, ὥστε φοβοῦμαι μὴ τὴν ἀρχὴν αὐτῶν ἀκούσαντες θορύβου καὶ βοῆς ἅπαν ἐμπλήσητε τὸ δικαστήριον. ὅμως δὲ καὶ περ οὕτω διακείμενος ἐπιχειρήσω διαλεχθῆναι περὶ αὐτῶν· αἰσχύνομαι γὰρ εἴ τισι δόξω δεδιὼς ὑπὲρ γήρως καὶ μικροῦ βίου προδιδόναι τὴν ἀλήθειαν.", "st": "15.272"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν μὴ προκαταγνῶναί μου τοιαύτην μανίαν, ὡς ἄρ’ ἐγὼ κινδυνεύων προειλόμην ἂν λόγους εἰπεῖν ἐναντίους ταῖς ὑμετέραις γνώμαις, εἰ μὴ καὶ τοῖς προειρημένοις ἀκολούθους αὐτοὺς ἐνόμιζον εἶναι, καὶ τὰς ἀποδείξεις ἀληθεῖς καὶ σαφεῖς ᾤμην ἔχειν ὑπὲρ αὐτῶν.", "st": "15.273"}, {"sp": "N", "t": "ἡγοῦμαι δὲ τοιαύτην μὲν τέχνην, ἥτις τοῖς κακῶς πεφυκόσιν ἀρετὴν ἐνεργάσαιτ’ ἂν καὶ δικαιοσύνην, οὔτε πρότερον οὔτε νῦν οὐδεμίαν εἶναι, τούς τε τὰς ὑποσχέσεις ποιουμένους περὶ αὐτῶν πρότερον ἀπερεῖν καὶ παύσεσθαι ληροῦντας, πρὶν εὑρεθῆναί τινα παιδείαν τοιαύτην,", "st": "15.274"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ αὐτούς γ’ αὑτῶν βελτίους ἂν γίγνεσθαι καὶ πλέονος ἀξίους, εἰ πρός τε τὸ λέγειν εὖ φιλοτίμως διατεθεῖεν, καὶ τοῦ πείθειν δύνασθαι τοὺς ἀκούοντας ἐρασθεῖεν, καὶ πρὸς τούτοις τῆς πλεονεξίας ἐπιθυμήσαιεν, μὴ τῆς ὑπὸ τῶν ἀνοήτων νομιζομένης, ἀλλὰ τῆς ὡς ἀληθῶς τὴν δύναμιν ταύτην ἐχούσης.", "st": "15.275"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς οὕτω πέφυκε, ταχέως οἶμαι δηλώσειν. πρῶτον μὲν γὰρ ὁ λέγειν ἢ γράφειν προαιρούμενος λόγους ἀξίους ἐπαίνου καὶ τιμῆς οὐκ ἔστιν ὅπως ποιήσεται τὰς ὑποθέσεις ἀδίκους ἢ μικρὰς ἢ περὶ τῶν ἰδίων συμβολαίων, ἀλλὰ μεγάλας καὶ καλὰς καὶ φιλανθρώπους καὶ περὶ τῶν κοινῶν πραγμάτων· μὴ γὰρ τοιαύτας εὑρίσκων οὐδὲν διαπράξεται τῶν δεόντων.", "st": "15.276"}, {"sp": "N", "t": "ἔπειτα τῶν πράξεων τῶν συντεινουσῶν πρὸς τὴν ὑπόθεσιν ἐκλέξεται τὰς πρεπωδεστάτας καὶ μάλιστα συμφερούσας· ὁ δὲ τὰς τοιαύτας συνεθιζόμενος θεωρεῖν καὶ δοκιμάζειν οὐ μόνον περὶ τὸν ἐνεστῶτα λόγον ἀλλὰ καὶ περὶ τὰς ἄλλας πράξεις τὴν αὐτὴν ἕξει ταύτην δύναμιν, ὥσθ’ ἅμα τὸ λέγειν εὖ καὶ τὸ φρονεῖν παραγενήσεται τοῖς φιλοσόφως καὶ φιλοτίμως πρὸς τοὺς λόγους διακειμένοις.", "st": "15.277"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ὁ πείθειν τινὰς βουλόμενος ἀμελήσει τῆς ἀρετῆς, ἀλλὰ τούτῳ μάλιστα προσέξει τὸν νοῦν, ὅπως δόξαν ὡς ἐπιεικεστάτην λήψεται παρὰ τοῖς συμπολιτευομένοις. τίς γὰρ οὐκ οἶδε καὶ τοὺς λόγους ἀληθεστέρους δοκοῦντας εἶναι τοὺς ὑπὸ τῶν εὖ διακειμένων λεγομένους ἢ τοὺς ὑπὸ τῶν διαβεβλημένων, καὶ τὰς πίστεις μεῖζον δυναμένας τὰς ἐκ τοῦ βίου γεγενημένας ἢ τὰς ὑπὸ τοῦ λόγου πεπορισμένας; ὥσθ’ ὅσῳ ἄν τις ἐρρωμενεστέρως ἐπιθυμῇ πείθειν τοὺς ἀκούοντας, τοσούτῳ μᾶλλον ἀσκήσει καλὸς κἀγαθὸς εἶναι καὶ παρὰ τοῖς πολίταις εὐδοκιμεῖν.", "st": "15.278"}, {"sp": "N", "t": "καὶ μηδεὶς ὑμῶν οἰέσθω τοὺς μὲν ἄλλους ἅπαντας γιγνώσκειν ὅσην ἔχει ῥοπὴν εἰς τὸ πείθειν τὸ τοῖς κρίνουσιν ἀρέσκειν, τοὺς δὲ περὶ τὴν φιλοσοφίαν ὄντας μόνους ἀγνοεῖν τὴν τῆς εὐνοίας δύναμιν· πολὺ γὰρ ἀκριβέστερον τῶν ἄλλων καὶ ταῦτ’ ἴσασι,", "st": "15.279"}, {"sp": "N", "t": "καὶ πρὸς τούτοις ὅτι τὰ μὲν εἰκότα καὶ τὰ τεκμήρια καὶ πᾶν τὸ τῶν πίστεων εἶδος τοῦτο μόνον ὠφελεῖ τὸ μέρος, ἐφ’ ᾧ ἂν αὐτῶν ἕκαστον τύχῃ ῥηθέν, τὸ δὲ δοκεῖν εἶναι καλὸν κἀγαθὸν οὐ μόνον τὸν λόγον πιστότερον ἐποίησεν, ἀλλὰ καὶ τὰς πράξεις τοῦ τὴν τοιαύτην δόξαν ἔχοντος ἐντιμοτέρας κατέστησεν, ὑπὲρ οὗ σπουδαστέον ἐστὶ τοῖς εὖ φρονοῦσι μᾶλλον ἢ περὶ τῶν ἄλλων ἁπάντων.", "st": "15.280"}, {"sp": "N", "t": "τὸ τοίνυν περὶ τὴν πλεονεξίαν, ὃ δυσχερέστατον ἦν τῶν ῥηθέντων· εἰ μέν τις ὑπολαμβάνει τοὺς ἀποστεροῦντας ἢ παραλογιζομένους ἢ κακόν τι ποιοῦντας πλεονεκτεῖν, οὐκ ὀρθῶς ἔγνωκεν· οὐδένες γὰρ ἐν ἅπαντι τῷ βίῳ μᾶλλον ἐλαττοῦνται τῶν τοιούτων, οὐδ’ ἐν πλέοσιν ἀπορίαις εἰσίν, οὐδ’ ἐπονειδιστότερον ζῶσιν, οὐδ’ ὅλως ἀθλιώτεροι τυγχάνουσιν ὄντες·", "st": "15.281"}, {"sp": "N", "t": "χρὴ δὲ καὶ νῦν πλέον ἔχειν ἡγεῖσθαι καὶ πλεονεκτήσειν νομίζειν παρὰ μὲν τῶν θεῶν τοὺς εὐσεβεστάτους καὶ τοὺς περὶ τὴν θεραπείαν τὴν ἐκείνων ἐπιμελεστάτους ὄντας, παρὰ δὲ τῶν ἀνθρώπων τοὺς ἄριστα πρὸς τούτους μεθ’ ὧν ἂν οἰκῶσι καὶ πολιτεύωνται διακειμένους καὶ τοὺς βελτίστους αὐτοὺς εἶναι δοκοῦντας.", "st": "15.282"}, {"sp": "N", "t": "καὶ ταῦτα καὶ ταῖς ἀληθείαις οὕτως ἔχει, καὶ συμφέρει τὸν τρόπον τοῦτον λέγεσθαι περὶ αὐτῶν, ἐπεὶ νῦν γ’ οὕτως ἀνέστραπται καὶ συγκέχυται πολλὰ τῶν κατὰ τὴν πόλιν, ὥστ’ οὐδὲ τοῖς ὀνόμασιν ἔνιοί τινες ἔτι χρῶνται κατὰ φύσιν, ἀλλὰ μεταφέρουσιν ἀπὸ τῶν καλλίστων πραγμάτων ἐπὶ τὰ φαυλότατα τῶν ἐπιτηδευμάτων.", "st": "15.283"}, {"sp": "N", "t": "τοὺς μέν γε βωμολοχευομένους καὶ σκώπτειν καὶ μιμεῖσθαι δυναμένους εὐφυεῖς καλοῦσι, προσῆκον τῆς προσηγορίας ταύτης τυγχάνειν τοὺς ἄριστα πρὸς ἀρετὴν πεφυκότας· τοὺς δὲ ταῖς κακοηθείαις καὶ ταῖς κακουργίαις χρωμένους, καὶ μικρὰ μὲν λαμβάνοντας πονηρὰν δὲ δόξαν κτωμένους, πλεονεκτεῖν νομίζουσιν, ἀλλ’ οὐ τοὺς ὁσιωτάτους καὶ δικαιοτάτους, οἳ περὶ τῶν ἀγαθῶν ἀλλ’ οὐ τῶν κακῶν πλεονεκτοῦσι·", "st": "15.284"}, {"sp": "N", "t": "τοὺς δὲ τῶν μὲν ἀναγκαίων ἀμελοῦντας, τὰς δὲ τῶν παλαιῶν σοφιστῶν τερατολογίας ἀγαπῶντας φιλοσοφεῖν φασιν, ἀλλ’ οὐ τοὺς τὰ τοιαῦτα μανθάνοντας καὶ μελετῶντας ἐξ ὧν καὶ τὸν ἴδιον οἶκον καὶ τὰ κοινὰ τὰ τῆς πόλεως καλῶς διοικήσουσιν, ὧνπερ ἕνεκα καὶ πονητέον καὶ φιλοσοφητέον καὶ πάντα πρακτέον ἐστίν. ἀφ’ ὧν ὑμεῖς πολὺν ἤδη χρόνον ἀπελαύνετε τοὺς νεωτέρους, ἀποδεχόμενοι τοὺς λόγους τῶν διαβαλλόντων τὴν τοιαύτην παιδείαν.", "st": "15.285"}, {"sp": "N", "t": "καὶ γάρ τοι πεποιήκατε τοὺς μὲν ἐπιεικεστάτους αὐτῶν ἐν πότοις καὶ συνουσίαις καὶ ῥᾳθυμίαις καὶ παιδιαῖς τὴν ἡλικίαν διάγειν, ἀμελήσαντας τοῦ σπουδάζειν ὅπως ἔσονται βελτίους, τοὺς δὲ χείρω τὴν φύσιν ἔχοντας ἐν τοιαύταις ἀκολασίαις ἡμερεύειν, ἐν αἷς πρότερον οὐδ’ ἂν οἰκέτης ἐπιεικὴς οὐδεὶς ἐτόλμησεν·", "st": "15.286"}, {"sp": "N", "t": "οἱ μὲν γὰρ αὐτῶν ἐπὶ τῆς Ἐννεακρούνου ψύχουσιν οἶνον, οἱ δ’ ἐν τοῖς καπηλείοις πίνουσιν, ἕτεροι δ’ ἐν τοῖς σκιραφείοις κυβεύουσι, πολλοὶ δ’ ἐν τοῖς τῶν αὐλητρίδων διδασκαλείοις διατρίβουσι. καὶ τοὺς μὲν ἐπὶ ταῦτα προτρέποντας οὐδεὶς πώποτε τῶν κήδεσθαι φασκόντων τῆς ἡλικίας ταύτης εἰς ὑμᾶς εἰσήγαγεν· ἡμῖν δὲ κακὰ παρέχουσιν, οἷς ἄξιον ἦν, εἰ καὶ μηδενὸς ἄλλου, τούτου γε χάριν ἔχειν, ὅτι τοὺς συνόντας τῶν τοιούτων ἐπιτηδευμάτων ἀποτρέπομεν.", "st": "15.287"}, {"sp": "N", "t": "οὕτω δ’ ἐστὶ δυσμενὲς ἅπασι τὸ τῶν συκοφαντῶν γένος, ὥστε τοῖς μὲν λυομένοις εἴκοσι καὶ τριάκοντα μνῶν τὰς μελλούσας καὶ τὸν ἄλλον οἶκον συναναιρήσειν οὐχ ὅπως ἂν ἐπιπλήξειαν, ἀλλὰ καὶ συγχαίρουσι ταῖς ἀσωτίαις αὐτῶν, τοὺς δ’ εἰς τὴν αὑτῶν παιδείαν ὁτιοῦν ἀναλίσκοντας διαφθείρεσθαί φασιν. ὧν τίνες ἂν ἀδικώτερον ἔχοιεν τὴν αἰτίαν ταύτην;", "st": "15.288"}, {"sp": "N", "t": "οἵτινες ἐν ταύταις μὲν ταῖς ἀκμαῖς ὄντες ὑπερεῖδον τὰς ἡδονάς, ἐν αἷς οἱ πλεῖστοι τῶν τηλικούτων μάλιστ’ αὐτῶν ἐπιθυμοῦσιν, ἐξὸν δ’ αὐτοῖς ῥᾳθυμεῖν μηδὲν δαπανωμένοις εἵλοντο πονεῖν χρήματα τελέσαντες, ἄρτι δ’ ἐκ παίδων ἐξεληλυθότες ἔγνωσαν ἃ πολλοὶ τῶν πρεσβυτέρων οὐκ ἴσασιν,", "st": "15.289"}, {"sp": "N", "t": "ὅτι δεῖ τὸν ὀρθῶς καὶ πρεπόντως προεστῶτα τῆς ἡλικίας καὶ καλὴν ἀρχὴν τοῦ βίου ποιούμενον αὑτοῦ πρότερον ἢ τῶν αὑτοῦ ποιήσασθαι τὴν ἐπιμέλειαν, καὶ μὴ σπεύδειν μηδὲ ζητεῖν ἑτέρων ἄρχειν πρὶν ἂν τῆς αὑτοῦ διανοίας λάβῃ τὸν ἐπιστατήσοντα, μηδ’ οὕτω χαίρειν μηδὲ μέγα φρονεῖν ἐπὶ τοῖς ἄλλοις ἀγαθοῖς ὡς ἐπὶ τοῖς ἐν τῇ ψυχῇ διὰ τὴν παιδείαν ἐγγιγνομένοις. καί τοι τοὺς τοιούτῳ λογισμῷ κεχρημένους πῶς οὐκ ἐπαινεῖσθαι χρὴ μᾶλλον ἢ ψέγεσθαι, καὶ νομίζεσθαι βελτίστους εἶναι καὶ σωφρονεστάτους τῶν ἡλικιωτῶν;", "st": "15.290"}, {"sp": "N", "t": "θαυμάζω δ’ ὅσοι τοὺς μὲν φύσει δεινοὺς ὄντας εἰπεῖν εὐδαιμονίζουσιν ὡς ἀγαθοῦ καὶ καλοῦ πράγματος αὐτοῖς συμβεβηκότος, τοὺς δὲ τοιούτους γενέσθαι βουλομένους λοιδοροῦσιν ὡς ἀδίκου καὶ κακοῦ παιδεύματος ἐπιθυμοῦντας. καί τοι τί τῶν φύσει καλῶν ὄντων μελέτῃ κατεργασθὲν αἰσχρὸν ἢ κακόν ἐστιν; οὐδὲν γὰρ εὑρήσομεν τοιοῦτον, ἀλλ’ ἔν γε τοῖς ἄλλοις ἐπαινοῦμεν τοὺς ταῖς φιλοπονίαις ταῖς αὑτῶν ἀγαθόν τι κτήσασθαι δυνηθέντας μᾶλλον ἢ τοὺς παρὰ τῶν προγόνων παραλαβόντας,", "st": "15.291"}, {"sp": "N", "t": "εἰκότως· συμφέρει γὰρ ἐπί τε τῶν ἄλλων ἁπάντων, καὶ μάλιστ’ ἐπὶ τῶν λόγων, μὴ τὰς εὐτυχίας ἀλλὰ τὰς ἐπιμελείας εὐδοκιμεῖν. οἱ μὲν γὰρ φύσει καὶ τύχῃ δεινοὶ γενόμενοι λέγειν οὐ πρὸς τὸ βέλτιστον ἀποβλέπουσιν, ἀλλ’ ὅπως ἂν τύχωσιν, οὕτω χρῆσθαι τοῖς λόγοις εἰώθασιν· οἱ δὲ φιλοσοφίᾳ καὶ λογισμῷ τὴν δύναμιν ταύτην λαβόντες, οὐδὲν ἀσκέπτως λέγοντες, ἧττον περὶ τὰς πράξεις πλημμελοῦσιν.", "st": "15.292"}, {"sp": "N", "t": "ὥσθ’ ἅπασι μὲν βούλεσθαι προσήκει πολλοὺς εἶναι τοὺς ἐκ παιδείας δεινοὺς εἰπεῖν γιγνομένους, μάλιστα δ’ ὑμῖν· καὶ γὰρ αὐτοὶ προέχετε καὶ διαφέρετε τῶν ἄλλων οὐ ταῖς περὶ τὸν πόλεμον ἐπιμελείαις, οὐδ’ ὅτι κάλλιστα πολιτεύεσθε καὶ μάλιστα φυλάττετε τοὺς νόμους οὓς ὑμῖν οἱ πρόγονοι κατέλιπον, ἀλλὰ τούτοις οἷς περ ἡ φύσις ἡ τῶν ἀνθρώπων τῶν ἄλλων ζώων, καὶ τὸ γένος τὸ τῶν Ἑλλήνων τῶν βαρβάρων,", "st": "15.293"}, {"sp": "N", "t": "τῷ καὶ πρὸς τὴν φρόνησιν καὶ πρὸς τοὺς λόγους ἄμεινον πεπαιδεῦσθαι τῶν ἄλλων. ὥστε πάντων ἂν συμβαίη δεινότατον, εἰ τοὺς βουλομένους τοῖς αὐτοῖς τούτοις διενεγκεῖν τῶν ἡλικιωτῶν, οἷς περ ὑμεῖς ἁπάντων, διαφθείρεσθαι ψηφίσαισθε, καὶ τοὺς τῇ παιδείᾳ ταύτῃ χρωμένους, ἧς ὑμεῖς ἡγεμόνες γεγένησθε, συμφορᾷ τινι περιβάλοιτε.", "st": "15.294"}, {"sp": "N", "t": "χρὴ γὰρ μηδὲ τοῦτο λανθάνειν ὑμᾶς, ὅτι πάντων τῶν δυναμένων λέγειν ἢ παιδεύειν ἡ πόλις ἡμῶν δοκεῖ γεγενῆσθαι διδάσκαλος. εἰκότως· καὶ γὰρ ἆθλα μέγιστα τιθεῖσαν αὐτὴν ὁρῶσι τοῖς τὴν δύναμιν ταύτην ἔχουσι, καὶ γυμνάσια πλεῖστα καὶ παντοδαπώτατα παρέχουσαν τοῖς ἀγωνίζεσθαι προῃρημένοις καὶ περὶ τὰ τοιαῦτα γυμνάζεσθαι βουλομένοις,", "st": "15.295"}, {"sp": "N", "t": "ἔτι δὲ τὴν ἐμπειρίαν, ἥ περ μάλιστα ποιεῖ δύνασθαι λέγειν, ἐνθένδε πάντας λαμβάνοντας· πρὸς δὲ τούτοις καὶ τὴν τῆς φωνῆς κοινότητα καὶ μετριότητα καὶ τὴν ἄλλην εὐτραπελίαν καὶ φιλολογίαν οὐ μικρὸν ἡγοῦνται συμβαλέσθαι μέρος πρὸς τὴν τῶν λόγων παιδείαν· ὥστ’ οὐκ ἀδίκως ὑπολαμβάνουσιν ἅπαντας τοὺς λέγειν ὄντας δεινοὺς τῆς πόλεως εἶναι μαθητάς.", "st": "15.296"}, {"sp": "N", "t": "σκοπεῖτ’ οὖν μὴ παντάπασιν ᾖ καταγέλαστον τῆς δόξης ταύτης φλαῦρόν τι καταγιγνώσκειν, ἣν ὑμεῖς ἔχετε παρὰ τοῖς Ἕλλησι πολὺ μᾶλλον ἢ ἐγὼ παρ’ ὑμῖν· οὐδὲν γὰρ ἀλλ’ ἢ φανερῶς ὑμῶν αὐτῶν ἔσεσθε κατεψηφισμένοι τὴν τοιαύτην ἀδικίαν,", "st": "15.297"}, {"sp": "N", "t": "καὶ πεποιηκότες ὅμοιον ὥσπερ ἂν εἰ Λακεδαιμόνιοι τοὺς τὰ περὶ τὸν πόλεμον ἀσκοῦντας ζημιοῦν ἐπιχειροῖεν, ἢ Θετταλοὶ παρὰ τῶν ἱππεύειν μελετώντων δίκην λαμβάνειν ἀξιοῖεν. ὑπὲρ ὧν φυλακτέον ἐστίν, ὅπως μηδὲν τοιοῦτον ἐξαμαρτήσεσθε περὶ ὑμᾶς αὐτούς, μηδὲ πιστοτέρους ποιήσετε τοὺς λόγους τοὺς τῶν κατηγορούντων τῆς πόλεως ἢ τοὺς τῶν ἐπαινούντων.", "st": "15.298"}, {"sp": "N", "t": "οἶμαι δ’ ὑμᾶς οὐκ ἀγνοεῖν ὅτι τῶν Ἑλλήνων οἱ μὲν δυσκόλως πρὸς ὑμᾶς ἔχουσιν, οἱ δ’ ὡς οἷόν τε μάλιστα φιλοῦσι καὶ τὰς ἐλπίδας τῆς σωτηρίας ἐν ὑμῖν ἔχουσι. καὶ φασιν οἱ μὲν τοιοῦτοι μόνην εἶναι ταύτην πόλιν, τὰς δ’ ἄλλας κώμας, καὶ δικαίως ἂν αὐτὴν ἄστυ τῆς Ἑλλάδος προσαγορεύεσθαι καὶ διὰ τὸ μέγεθος καὶ διὰ τὰς εὐπορίας τὰς ἐνθένδε τοῖς ἄλλοις γιγνομένας καὶ μάλιστα διὰ τὸν τρόπον τῶν ἐνοικούντων·", "st": "15.299"}, {"sp": "N", "t": "οὐδένας γὰρ εἶναι πραοτέρους οὐδὲ κοινοτέρους οὐδ’ οἷς οἰκειότερον ἄν τις τὸν ἅπαντα βίον συνδιατρίψειεν οὕτω δὲ μεγάλαις χρῶνται ταῖς ὑπερβολαῖς, ὥστ’ οὐδὲ τοῦτ’ ὀκνοῦσι λέγειν, ὡς ἥδιον ἂν ὑπ’ ἀνδρὸς Ἀθηναίου ζημιωθεῖεν ἢ διὰ τῆς ἑτέρων ὠμότητος εὖ πάθοιεν. οἱ δὲ ταῦτα μὲν διασύρουσι, διεξιόντες δὲ τὰς τῶν συκοφαντῶν πικρότητας καὶ κακοπραγίας ὅλης τῆς πόλεως ὡς ἀμίκτου καὶ χαλεπῆς οὔσης κατηγοροῦσιν.", "st": "15.300"}, {"sp": "N", "t": "ἔστιν οὖν δικαστῶν νοῦν ἐχόντων τοὺς μὲν τῶν τοιούτων λόγων αἰτίους γιγνομένους ἀποκτείνειν ὡς μεγάλην αἰσχύνην τῇ πόλει περιποιοῦντας, τοὺς δὲ τῶν ἐπαίνων τῶν λεγομένων περὶ αὐτῆς μέρος τι συμβαλλομένους τιμᾶν μᾶλλον ἢ τοὺς ἀθλητὰς τοὺς ἐν τοῖς στεφανίταις ἀγῶσι νικῶντας· πολὺ γὰρ καλλίω δόξαν ἐκείνων κτώμενοι τῇ πόλει τυγχάνουσι καὶ μᾶλλον ἁρμόττουσαν.", "st": "15.301"}, {"sp": "N", "t": "περὶ μὲν γὰρ τὴν τῶν σωμάτων ἀγωνίαν πολλοὺς τοὺς ἀμφισβητοῦντας ἔχομεν, περὶ δὲ τὴν παιδείαν ἅπαντες ἂν ἡμᾶς πρωτεύειν προκρίνειαν. χρὴ δὲ τοὺς καὶ μικρὰ λογίζεσθαι δυναμένους τοὺς ἐν τοῖς τοιούτοις τῶν ἔργων διαφέροντας, ἐν οἷς ἡ πόλις εὐδοκιμεῖ, τιμῶντας φαίνεσθαι, καὶ μὴ φθονερῶς ἔχειν, μηδ’ ἐναντία τοῖς ἄλλοις Ἕλλησι γιγνώσκειν περὶ αὐτῶν.", "st": "15.302"}, {"sp": "N", "t": "ὧν ὑμῖν οὐδὲν πώποτ’ ἐμέλησεν, ἀλλὰ τοσοῦτον διημαρτήκατε τοῦ συμφέροντος, ὥσθ’ ἥδιον ἔχετε δι’ οὓς ἀκούετε κακῶς ἢ δι’ οὓς ἐπαινεῖσθε, καὶ δημοτικωτέρους εἶναι νομίζετε τοὺς τοῦ μισεῖσθαι τὴν πόλιν ὑπὸ πολλῶν αἰτίους ὄντας, ἢ τοὺς ἅπαντας οἷς πεπλησιάκασιν εὖ διακεῖσθαι πρὸς αὐτὴν πεποιηκότας.", "st": "15.303"}, {"sp": "N", "t": "ἤν οὖν σωφρονῆτε, τῆς μὲν ταραχῆς παύσεσθε ταύτης, οὐχ οὕτω δ’ ὥσπερ νῦν οἱ μὲν τραχέως οἱ δ’ ὀλιγώρως διακείσεσθε πρὸς τὴν φιλοσοφίαν, ἀλλ’ ὑπολαβόντες κάλλιστον εἶναι καὶ σπουδαιότατον τῶν ἐπιτηδευμάτων τὴν τῆς ψυχῆς ἐπιμέλειαν, προτρέψετε τῶν νεωτέρων τοὺς βίον ἱκανὸν κεκτημένους καὶ σχολὴν ἄγειν δυναμένους ἐπὶ τὴν παιδείαν καὶ τὴν ἄσκησιν τὴν τοιαύτην,", "st": "15.304"}, {"sp": "N", "t": "καὶ τοὺς μὲν πονεῖν ἐθέλοντας καὶ παρασκευάζειν σφᾶς αὐτοὺς χρησίμους τῇ πόλει περὶ πολλοῦ ποιήσεσθε, τοὺς δὲ καταβεβλημένως ζῶντας καὶ μηδενὸς ἄλλου φροντίζοντας πλὴν ὅπως ἀσελγῶς ἀπολαύσονται τῶν καταλειφθέντων, τούτους δὲ μισήσετε καὶ προδότας νομιεῖτε καὶ τῆς πόλεως καὶ τῆς τῶν προγόνων δόξης· μόλις γὰρ ἢν οὕτως ὑμᾶς αἴσθωνται πρὸς ἑκατέρους αὐτῶν διακειμένους, ἐθελήσουσιν οἱ νεώτεροι καταφρονήσαντες τῆς ῥᾳθυμίας προσέχειν σφίσιν αὐτοῖς καὶ τῇ φιλοσοφίᾳ τὸν νοῦν.", "st": "15.305"}, {"sp": "N", "t": "ἀναμνήσθητε δὲ τὸ κάλλος καὶ τὸ μέγεθος τῶν ἔργων τῶν τῇ πόλει καὶ τοῖς προγόνοις πεπραγμένων, καὶ διέλθετε πρὸς ὑμᾶς αὐτοὺς καὶ σκέψασθε ποῖός τις ἦν καὶ πῶς γεγονὼς καὶ τίνα τρόπον πεπαιδευμένος ὁ τοὺς τυράννους ἐκβαλὼν καὶ τὸν δῆμον καταραρὼν καὶ τὴν δημοκρατίαν καταστήσας, ποῖος δέ τις ὁ τοὺς βαρβάρους Μαραθῶνι τῇ μάχῃ νικήσας καὶ τὴν δόξαν τὴν ἐκ ταύτης γενομένην τῇ πόλει κτησάμενος,", "st": "15.306"}, {"sp": "N", "t": "τίς δ’ ἦν, ὁ μετ’ ἐκεῖνον τοὺς Ἕλληνας ἐλευθερώσας καὶ τοὺς προγόνους ἐπὶ ἡγεμονίαν καὶ τὴν δυναστείαν ἣν ἔσχον προαγαγών, ἔτι δὲ τὴν φύσιν τὴν τοῦ Πειραιέως κατιδὼν καὶ τὸ τεῖχος ἀκόντων Λακεδαιμονίων τῇ πόλει περιβαλών, τίς δὲ ὁ μετὰ τοῦτον ἀργυρίου καὶ χρυσίου τὴν ἀκρόπολιν ἐμπλήσας καὶ τοὺς οἴκους τοὺς ἰδίους μεστοὺς πολλῆς εὐδαιμονίας καὶ πλούτου ποιήσας·", "st": "15.307"}, {"sp": "N", "t": "εὑρήσετε γάρ, ἢν ἐξετάζητε τούτων ἕκαστον, οὐ τοὺς συκοφαντικῶς βεβιωκότας οὐδὲ τοὺς ἀμελῶς, οὐδὲ τοὺς τοῖς πολλοῖς ὁμοίους ὄντας, ταῦτα διαπεπραγμένους, ἀλλὰ τοὺς διαφέροντας καὶ προέχοντας μὴ μόνον ταῖς εὐγενείαις καὶ ταῖς δόξαις, ἀλλὰ καὶ τῷ φρονεῖν καὶ λέγειν, τούτους ἁπάντων ἀγαθῶν αἰτίους γεγενημένους.", "st": "15.308"}, {"sp": "N", "t": "ὦν εἰκὸς ὑμᾶς ἐνθυμουμένους ὑπὲρ μὲν τοῦ πλήθους τοῦτο σκοπεῖν, ὅπως ἔν τε τοῖς ἀγῶσι τοῖς περὶ τῶν συμβολαίων τῶν δικαίων τεύξονται καὶ τῶν ἄλλων τῶν κοινῶν μεθέξουσι, τοὺς δ’ ὑπερέχοντας καὶ τῇ φύσει καὶ ταῖς μελέταις, καὶ τοὺς τοιούτους γενέσθαι προθυμουμένους, ἀγαπᾶν καὶ τιμᾶν καὶ θεραπεύειν, ἐπισταμένους ὅτι καὶ τὸ καλῶν καὶ μεγάλων ἡγήσασθαι πραγμάτων καὶ τὸ δύνασθαι τὰς πόλεις ἐκ τῶν κινδύνων σώζειν καὶ τὴν δημοκρατίαν διαφυλάττειν ἐν τοῖς τοιούτοις ἔνεστιν, ἀλλ’ οὐκ ἐν τοῖς συκοφάνταις.", "st": "15.309"}, {"sp": "N", "t": "πολλῶν δ’ ἐφεστώτων μοι λόγων ἀπορῶ πῶς αὐτοὺς διαθῶμαι· δοκεῖ γάρ μοι καθ’ αὑτὸ μὲν ἕκαστον ὧν διανοοῦμαι ῥηθὲν ἐπιεικὲς ἂν φανῆναι, πάντα δὲ νυνὶ λεγόμενα πολὺν ἂν ὄχλον ἐμοί τε καὶ τοῖς ἀκούουσι παρασχεῖν. ὅπερ καὶ περὶ τῶν ἤδη προειρημένων δέδοικα, μὴ τοιοῦτόν τι πάθος αὐτοῖς διὰ τὸ πλῆθος τυγχάνῃ συμβεβηκός.", "st": "15.310"}, {"sp": "N", "t": "οὕτω γὰρ ἀπλήστως ἅπαντες ἔχομεν περὶ τοὺς λόγους, ὥστ’ ἐπαινοῦμεν μὲν τὴν εὐκαιρίαν καὶ φαμὲν οὐδὲν εἶναι τοιοῦτον, ἐπειδὰν δ’ οἰηθῶμεν ὡς ἔχομέν τι λέγειν, ἀμελήσαντες τοῦ μετριάζειν, κατὰ μικρὸν ἀεὶ προστιθέντες εἰς τὰς ἐσχάτας ἀκαιρίας ἐμβάλλομεν ἡμᾶς αὐτούς· ὅπου γε καὶ λέγων ἐγὼ ταῦτα καὶ γιγνώσκων, ὅμως ἔτι βούλομαι διαλεχθῆναι πρὸς ὑμᾶς.", "st": "15.311"}, {"sp": "N", "t": "ἀγανακτῶ γὰρ ὁρῶν τὴν συκοφαντίαν ἄμεινον τῆς φιλοσοφίας φερομένην, καὶ τὴν μὲν κατηγοροῦσαν, τὴν δὲ κρινομένην. ὃ τίς ἂν τῶν παλαιῶν ἀνδρῶν γενήσεσθαι προσεδόκησεν, ἄλλως τε καὶ παρ’ ὑμῖν τοῖς ἐπὶ σοφίᾳ μεῖζον τῶν ἄλλων φρονοῦσιν;", "st": "15.312"}, {"sp": "N", "t": "οὔκουν ἐπί γε τῶν προγόνων οὕτως εἶχεν, ἀλλὰ τοὺς μὲν καλουμένους σοφιστὰς ἐθαύμαζον καὶ τοὺς συνόντας αὐτοῖς ἐζήλουν, τοὺς δὲ συκοφάντας πλείστων κακῶν αἰτίους ἐνόμιζον εἶναι. μέγιστον δὲ τεκμήριον· Σόλωνα μὲν γάρ, τὸν πρῶτον τῶν πολιτῶν λαβόντα τὴν ἐπωνυμίαν ταύτην, προστάτην ἠξίωσαν τῆς πόλεως εἶναι, περὶ δὲ τῶν συκοφαντῶν χαλεπωτέρους ἢ περὶ τῶν ἄλλων κακουργιῶν τοὺς νόμους ἔθεσαν.", "st": "15.313"}, {"sp": "N", "t": "τοῖς μὲν γὰρ μεγίστοις τῶν ἀδικημάτων ἐν ἑνὶ τῶν δικαστηρίων τὴν κρίσιν ἐποίησαν, κατὰ δὲ τούτων γραφὰς μὲν πρὸς τοὺς θεσμοθέτας, εἰσαγγελίας δ’ εἰς τὴν βουλήν, προβολὰς δ’ ἐν τῷ δήμῳ, νομίζοντες τοὺς ταύτῃ τῇ τέχνῃ χρωμένους ἁπάσας ὑπερβάλλειν τὰς πονηρίας. τοὺς μὲν γὰρ ἄλλους ἀλλ’ οὖν πειρᾶσθαί γε λανθάνειν κακουργοῦντας,", "st": "15.314"}, {"sp": "N", "t": "τούτους δ’ ἐν ἅπασιν ἐπιδείκνυσθαι τὴν αὑτῶν ὠμότητα καὶ μισανθρωπίαν καὶ φιλαπεχθημοσύνην. κἀκεῖνοι μὲν οὕτως ἐγίγνωσκον περὶ αὐτῶν· ὑμεῖς δὲ τοσοῦτον ἀπέχετε τοῦ κολάζειν αὐτούς, ὥστε τούτοις χρῆσθε καὶ κατηγόροις καὶ νομοθέταις περὶ τῶν ἄλλων. καί τοι προσῆκεν αὐτοὺς νῦν μισεῖσθαι μᾶλλον ἢ κατ’ ἐκεῖνον τὸν χρόνον.", "st": "15.315"}, {"sp": "N", "t": "τότε μὲν γὰρ ἐν τοῖς ἐγκυκλίοις μόνον καὶ τοῖς κατὰ τὴν πόλιν ἔβλαπτον τοὺς συμπολιτευομένους· ἐπειδὴ δ’ αὐξηθείσης τῆς πόλεως καὶ λαβούσης τὴν ἀρχὴν οἱ πατέρες ἡμῶν, μᾶλλον θαρρήσαντες τοῦ συμφέροντος, τοῖς μὲν καλοῖς κἀγαθοῖς τῶν ἀνδρῶν καὶ μεγάλην τὴν πόλιν ποιήσασι διὰ τὰς δυναστείας ἐφθόνησαν, πονηρῶν δ’ ἀνθρώπων καὶ μεστῶν θρασύτητος ἐπεθύμησαν,", "st": "15.316"}, {"sp": "N", "t": "οἰηθέντες ταῖς μὲν τόλμαις καὶ ταῖς φιλαπεχθημοσύναις ἱκανοὺς αὐτοὺς ἔσεσθαι διαφυλάττειν τὴν δημοκρατίαν, διὰ δὲ τὴν φαυλότητα τῶν ἐξ ἀρχῆς αὐτοῖς ὑπαρξάντων οὐ μέγα φρονήσειν οὐδ’ ἐπιθυμήσειν ἑτέρας πολιτείας. ἐκ ταύτης τῆς μεταβολῆς τί τῶν δεινῶν οὐ συνέπεσε τῇ πόλει, τί δὲ τῶν μεγίστων κακῶν οἱ ταύτην ἔχοντες τὴν φύσιν οὐ καὶ λέγοντες καὶ πράττοντες διετέλεσαν;", "st": "15.317"}, {"sp": "N", "t": "οὐ τοὺς μὲν ἐνδοξοτάτους τῶν πολιτῶν καὶ μάλιστα δυναμένους ποιῆσαί τι τὴν πόλιν ἀγαθόν, ὀλιγαρχίαν ὀνειδίζοντες καὶ λακωνισμόν, οὐ πρότερον ἐπαύοντο πρὶν ἠνάγκασαν ὁμοίους γενέσθαι ταῖς αἰτίαις ταῖς λεγομέναις περὶ αὐτῶν· τοὺς δὲ συμμάχους λυμαινόμενοι καὶ συκοφαντοῦντες, καὶ τοὺς βελτίστους ἐκ τῶν ὄντων ἐκβάλλοντες, οὕτω διέθεσαν ὥσθ’ ἡμῶν μὲν ἀποστῆναι, τῆς δὲ Λακεδαιμονίων ἐρασθῆναι φιλίας καὶ συμμαχίας;", "st": "15.318"}, {"sp": "N", "t": "ἐξ ὧν εἰς πόλεμον καταστάντες πολλοὺς ἐπείδομεν τῶν πολιτῶν τοὺς μὲν τελευτήσαντας, τοὺς δ’ ἐπὶ τοῖς πολεμίοις γενομένους, τοὺς δ’ εἰς ἔνδειαν τῶν ἀναγκαίων καταστάντας, ἔτι δὲ τὴν δημοκρατίαν δὶς καταλυθεῖσαν καὶ τὰ τείχη τῆς πατρίδος κατασκαφέντα, τὸ δὲ μέγιστον, ὅλην τὴν πόλιν περὶ ἀνδραποδισμοῦ κινδυνεύσασαν καὶ τὴν ἀκρόπολιν τοὺς πολεμίους οἰκήσαντας.", "st": "15.319"}, {"sp": "N", "t": "ἀλλὰ γὰρ αἰσθάνομαι, καίπερ ὑπὸ τῆς ὀργῆς βίᾳ φερόμενος, τὸ μὲν ὕδωρ ἡμᾶς ἐπιλεῖπον, αὐτὸς δ’ ἐμπεπτωκὼς εἰς λόγους ἡμερησίους καὶ κατηγορίας. ὑπερβὰς οὖν τὸ πλῆθος τῶν συμφορῶν τῶν διὰ τούτους γεγενημένων, καὶ διωσάμενος τὸν ὄχλον τῶν ἐνόντων εἰπεῖν περὶ τῆς τούτων συκοφαντίας, μικρῶν ἔτι πάνυ μνησθεὶς ἤδη καταλύσω τὸν λόγον.", "st": "15.320"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους ὁρῶ τοὺς κινδυνεύοντας, ἐπειδὰν περὶ τὴν τελευτὴν ὦσι τῆς ἀπολογίας, ἱκετεύοντας, δεομένους, τοὺς παῖδας, τοὺς φίλους ἀναβιβαζομένους· ἐγὼ δὲ οὔτε πρέπειν οὐδὲν ἡγοῦμαι τῶν τοιούτων τοῖς τηλικούτοις, πρός τε τῷ ταῦτα γιγνώσκειν, αἰσχυνθείην ἄν, εἰ δι’ ἄλλο τι σωζοίμην ἢ διὰ τοὺς λόγους τοὺς προειρημένους. οἶδα γὰρ ἐμαυτὸν οὕτως ὁσίως καὶ δικαίως κεχρημένον αὐτοῖς καὶ περὶ τὴν πόλιν καὶ περὶ τοὺς προγόνους καὶ μάλιστα περὶ τοὺς θεούς, ὥστε, εἴ τι μέλει τῶν ἀνθρωπίνων αὐτοῖς πραγμάτων,", "st": "15.321"}, {"sp": "N", "t": "οὐδὲ τῶν νῦν περὶ ἐμὲ γιγνομένων οὐδὲν αὐτοὺς οἶμαι λανθάνειν. διόπερ οὐκ ὀρρωδῶ τὸ μέλλον συμβήσεσθαι παρ’ ὑμῶν, ἀλλὰ θαρρῶ καὶ πολλὰς ἐλπίδας ἔχω τότε μοι τοῦ βίου τὴν τελευτὴν ἥξειν, ὅταν μέλλῃ συνοίσειν ἡμῖν, σημείῳ χρώμενος ὅτι καὶ τὸν παρελθόντα χρόνον οὕτω τυγχάνω βεβιωκὼς μέχρι ταύτης τῆς ἡμέρας, ὥς περ προσήκει τοὺς εὐσεβεῖς καὶ θεοφιλεῖς τῶν ἀνθρώπων.", "st": "15.322"}, {"sp": "N", "t": "ὡς οὖν ἐμοῦ ταύτην ἔχοντος τὴν γνώμην, καὶ νομίζοντος ὅ τι ἂν ὑμῖν δόξῃ, τοῦθ’ ἕξειν μοι καλῶς καὶ συμφερόντως, ὅπως ἕκαστος ὑμῶν χαίρει καὶ βούλεται, τοῦτον τὸν τρόπον φερέτω τὴν ψῆφον.", "st": "15.323"}, {"sp": "HDR", "t": "Παναθηναϊκός", "st": "12"}, {"sp": "N", "t": "νεώτερος μὲν ὢν προῃρούμην γράφειν τῶν λόγων οὐ τοὺς μυθώδεις οὐδὲ τοὺς τερατείας καὶ ψευδολογίας μεστούς, οἷς οἱ πολλοὶ μᾶλλον χαίρουσιν ἢ τοῖς περὶ τῆς αὑτῶν σωτηρίας λεγομένοις, οὐδὲ τοὺς τὰς παλαιὰς πράξεις καὶ τοὺς πολέμους τοὺς Ἑλληνικοὺς ἐξηγουμένους, καίπερ εἰδὼς δικαίως αὐτοὺς ἐπαινουμένους, οὐδ’ αὖ τοὺς ἁπλῶς δοκοῦντας εἰρῆσθαι καὶ μηδεμιᾶς κομψότητος μετέχοντας, οὓς οἱ δεινοὶ περὶ τοὺς ἀγῶνας παραινοῦσι τοῖς νεωτέροις μελετᾶν, εἴπερ βούλονται πλέον ἔχειν τῶν ἀντιδίκων,", "st": "12.1"}, {"sp": "N", "t": "ἀλλὰ πάντας τούτους ἐάσας περὶ ἐκείνους ἐπραγματευόμην, τοὺς περὶ τῶν συμφερόντων τῇ τε πόλει καὶ τοῖς ἄλλοις Ἕλλησι συμβουλεύοντας, καὶ πολλῶν μὲν ἐνθυμημάτων γέμοντας, οὐκ ὀλίγων δ’ ἀντιθέσεων καὶ παρισώσεων καὶ τῶν ἄλλων ἰδεῶν τῶν ἐν ταῖς ῥητορείαις διαλαμπουσῶν καὶ τοὺς ἀκούοντας ἐπισημαίνεσθαι καὶ θορυβεῖν ἀναγκαζουσῶν.", "st": "12.2"}, {"sp": "N", "t": "νῦν δ’ οὐδ’ ὁπωσοῦν τοὺς τοιούτους. ἡγοῦμαι γὰρ οὐχ ἁρμόττειν οὔτε τοῖς ἔτεσι τοῖς ἐνενήκοντα καὶ τέτταρσιν, ἁγὼ τυγχάνω γεγονώς, οὔθ’ ὅλως τοῖς ἤδη πολιὰς ἔχουσιν, ἐκεῖνον τὸν τρόπον ἔτι λέγειν, ἀλλ’ ὡς ἅπαντες μὲν ἂν ἐλπίσειαν εἰ βουληθεῖεν, οὐδεὶς δ’ ἂν δυνηθείη ῥᾳδίως πλὴν τῶν πονεῖν ἐθελόντων καὶ σφόδρα προσεχόντων τὸν νοῦν.", "st": "12.3"}, {"sp": "N", "t": "τούτου δ’ ἕνεκεν ταῦτα προεῖπον, ἵν’ ἤν τισιν ὁ μέλλων δειχθήσεσθαι λόγος μαλακώτερος ὢν φαίνηται τῶν πρότερον διαδεδομένων, μὴ παραβάλλωσι πρὸς τὴν ἐκείνων ποικιλίαν, ἀλλὰ πρὸς τὴν ὑπόθεσιν αὐτὸν κρίνωσι τὴν ἐν τῷ παρόντι δεδοκιμασμένην.", "st": "12.4"}, {"sp": "N", "t": "διαλέξομαι δὲ περί τε τῶν τῇ πόλει πεπραγμένων καὶ περὶ τῆς τῶν προγόνων ἀρετῆς, οὐκ ἀπὸ τούτων ἀρξάμενος, ἀλλ’ ἀπὸ τῶν ἐμοὶ συμβεβηκότων· ἐντεῦθεν γὰρ οἶμαι μᾶλλον κατεπείγειν. πειρώμενος γὰρ ἀναμαρτήτως ζῆν καὶ τοῖς ἄλλοις ἀλύπως, οὐδένα διαλέλοιπα χρόνον ὑπὸ μὲν τῶν σοφιστῶν τῶν ἀδοκίμων καὶ πονηρῶν διαβαλλόμενος, ὑπ’ ἄλλων δέ τινων οὐχ οἷός εἰμι γιγνωσκόμενος, ἀλλὰ τοιοῦτος ὑπολαμβανόμενος οἷον ἂν παρ’ ἑτέρων ἀκούσωσιν.", "st": "12.5"}, {"sp": "N", "t": "βούλομαι οὖν προδιαλεχθῆναι περί τ’ ἐμαυτοῦ καὶ περὶ τῶν οὕτω πρός με διακειμένων, ἵν’ ἤν πως οἷός τε γένωμαι, τοὺς μὲν παύσω βλασφημοῦντας, τοὺς δ’ εἰδέναι ποιήσω περὶ ἃ τυγχάνω διατρίβων· ἢν γὰρ ταῦτα τῷ λόγῳ δυνηθῶ διοικῆσαι κατὰ τρόπον, ἐλπίζω τὸν ἐπίλοιπον χρόνον αὐτός τε ἀλύπως διάξειν, καὶ τῷ λόγῳ τῷ μέλλοντι ῥηθήσεσθαι τοὺς παρόντας μᾶλλον προσέξειν τὸν νοῦν.", "st": "12.6"}, {"sp": "N", "t": "οὐκ ὀκνήσω δὲ κατειπεῖν οὔτε τὴν νῦν ἐγγιγνομένην ἐν τῇ διανοίᾳ μοι ταραχήν, οὔτε τὴν ἀτοπίαν ὧν ἐν τῷ παρόντι τυγχάνω γιγνώσκων, οὔτ’ εἴ τι πράττω τῶν δεόντων. ἐγὼ γὰρ μετεσχηκὼς τῶν μεγίστων ἀγαθῶν, ὧν ἅπαντες ἂν εὔξαιντο μεταλαβεῖν, πρῶτον μὲν τῆς περὶ τὸ σῶμα καὶ τὴν ψυχὴν ὑγιείας οὐχ ὡς ἔτυχον, ἀλλ’ ἐναμίλλως τοῖς μάλιστα περὶ ἑκάτερον τούτων εὐτυχηκόσιν, ἔπειτα τῆς περὶ τὸν βίον εὐπορίας, ὥστε μηδενὸς πώποτ’ ἀπορῆσαι τῶν μετρίων μηδ’ ὧν ἄνθρωπος ἂν νοῦν ἔχων ἐπιθυμήσειεν,", "st": "12.7"}, {"sp": "N", "t": "ἔτι τοῦ μὴ τῶν καταβεβλημένων εἷς εἶναι μηδὲ τῶν κατημελημένων, ἀλλ’ ἐκείνων περὶ ὧν οἱ χαριέστατοι τῶν Ἑλλήνων καὶ μνησθεῖεν ἂν καὶ διαλεχθεῖεν ὡς σπουδαίων ὄντων,—τούτων ἁπάντων μοι συμβεβηκότων τῶν μὲν ὑπερβαλλόντως τῶν δ’ ἐξαρκούντως οὐκ ἀγαπῶ ζῶν ἐπὶ τούτοις, ἀλλ’ οὕτω τὸ γῆράς ἐστι δυσάρεστον καὶ μικρολόγον καὶ μεμψίμοιρον, ὥστε πολλάκις ἤδη τήν τε φύσιν τὴν ἐμαυτοῦ κατεμεμψάμην,", "st": "12.8"}, {"sp": "N", "t": "ἧς οὐδεὶς ἄλλος καταπεφρόνηκε, καὶ τὴν τύχην ὠδυράμην, ταύτῃ μὲν οὐδὲν ἔχων ἐπικαλεῖν ἄλλο πλὴν ὅτι περὶ τὴν φιλοσοφίαν ἣν προειλόμην ἀτυχίαι τινὲς καὶ συκοφαντίαι γεγόνασι, τὴν δὲ φύσιν εἰδὼς πρὸς μὲν τὰς πράξεις ἀρρωστοτέραν καὶ μαλακωτέραν οὖσαν τοῦ δέοντος, πρὸς δὲ τοὺς λόγους οὔτε τελείαν οὔτε πανταχῇ χρησίμην, ἀλλὰ δοξάσαι μὲν περὶ ἑκάστου τὴν ἀλήθειαν μᾶλλον δυναμένην τῶν εἰδέναι φασκόντων, εἰπεῖν δὲ περὶ τῶν αὐτῶν τούτων ἐν συλλόγῳ πολλῶν ἀνθρώπων ἁπασῶν ὡς ἔπος εἰπεῖν ἀπολελειμμένην.", "st": "12.9"}, {"sp": "N", "t": "οὕτω γὰρ ἐνδεὴς ἀμφοτέρων ἐγενόμην τῶν μεγίστην δύναμιν ἐχόντων παρ’ ἡμῖν, φωνῆς ἱκανῆς καὶ τόλμης, ὡς οὐκ οἶδ’ εἴ τις ἄλλος τῶν πολιτῶν· ὧν οἱ μὴ τυχόντες ἀτιμότεροι περιέρχονται πρὸς τὸ δοκεῖν ἄξιοί τινος εἶναι τῶν ὀφειλόντων τῷ δημοσίῳ· τοῖς μὲν γὰρ ἐκτίσειν τὸ καταγνωσθὲν ἐλπίδες ὕπεισιν, οἱ δ’ οὐδέποτ’ ἂν τὴν φύσιν μεταβάλοιεν.", "st": "12.10"}, {"sp": "N", "t": "οὐ μὴν ἐπὶ τούτοις ἀθυμήσας περιεῖδον ἐμαυτὸν ἄδοξον οὐδ’ ἀφανῆ παντάπασι γενόμενον, ἀλλ’ ἐπειδὴ τοῦ πολιτεύεσθαι διήμαρτον, ἐπὶ τὸ φιλοσοφεῖν καὶ πονεῖν καὶ γράφειν ἃ διανοηθείην κατέφυγον, οὐ περὶ μικρῶν τὴν προαίρεσιν ποιούμενος οὐδὲ περὶ τῶν ἰδίων συμβολαίων οὐδὲ περὶ ὧν ἄλλοι τινὲς ληροῦσιν, ἀλλὰ περὶ τῶν Ἐλληνικῶν καὶ βασιλικῶν καὶ πολιτικῶν πραγμάτων, δι’ ἃ προσήκειν ᾠόμην μοι τοσούτῳ μᾶλλον τιμᾶσθαι τῶν ἐπὶ τὸ βῆμα παριόντων, ὅσῳ περ περὶ μειζόνων καὶ καλλιόνων ἢ κεῖνοι τοὺς λόγους ἐποιούμην. ὧν οὐδὲν ἡμῖν ἀποβέβηκεν.", "st": "12.11"}, {"sp": "N", "t": "καίτοι πάντες ἴσασι τῶν μὲν ῥητόρων τοὺς πολλοὺς οὐχ ὑπὲρ τῶν τῇ πόλει συμφερόντων, ἀλλ’ ὑπὲρ ὧν αὐτοὶ λήψεσθαι προσδοκῶσι, δημηγορεῖν τολμῶντας, ἐμὲ δὲ καὶ τοὺς ἐμοὺς οὐ μόνον τῶν κοινῶν ἀπεχομένους μᾶλλον τῶν ἄλλων, ἀλλὰ καὶ τῶν ἰδίων εἰς τὰς τῆς πόλεως χρείας ὑπὲρ τὴν δύναμιν τὴν ἡμετέραν αὐτῶν δαπανωμένους,", "st": "12.12"}, {"sp": "N", "t": "ἔτι δὲ τοὺς μὲν ἢ λοιδορουμένους ἐν ταῖς ἐκκλησίαις περὶ μεσεγγυήματος σφίσιν αὐτοῖς ἢ λυμαινομένους τοὺς συμμάχους ἢ τῶν ἄλλων ὃν ἂν τύχωσι συκοφαντοῦντας, ἐμὲ δὲ τῶν λόγων ἡγεμόνα τούτων γεγενημένον, τῶν παρακαλούντων τοὺς Ἕλληνας ἐπί τε τὴν ὁμόνοιαν τὴν πρὸς ἀλλήλους καὶ τὴν στρατείαν τὴν ἐπὶ τοὺς βαρβάρους,", "st": "12.13"}, {"sp": "N", "t": "καὶ τῶν συμβουλευόντων ἀποικίαν ἐκπέμπειν κοινῇ πάντας ἡμᾶς ἐπὶ τοσαύτην χώραν καὶ τοιαύτην, περὶ ἧς ὅσοι περ ἀκηκόασιν ὁμολογοῦσιν ἡμᾶς τε, εἰ σωφρονήσαιμεν καὶ παυσαίμεθα τῆς πρὸς ἀλλήλους μανίας, ταχέως ἂν ἄνευ πόνων καὶ κινδύνων κατασχεῖν αὐτήν, ἐκείνην τε ῥᾳδίως ἂν ἅπαντας δέξασθαι τοὺς ἐνδεεῖς ἡμῶν ὄντας τῶν ἐπιτηδείων· ὧν πράξεις, εἰ πάντες συνελθόντες ζητοῖεν, οὐδέποτ’ ἂν εὕροιεν καλλίους οὐδὲ μείζους οὐδὲ μᾶλλον ἅπασιν ἡμῖν συμφερούσας.", "st": "12.14"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὕτω πολὺ τῇ διανοία διεστώτων ἡμῶν, καὶ τοσούτῳ σπουδαιοτέραν ἐμοῦ πεποιημένου τὴν αἵρεσιν, οὐ δικαίως οἱ πολλοὶ περὶ ἡμῶν ὑπειλήφασιν, ἀλλὰ ταραχωδῶς καὶ παντάπασιν ἀλογίστως. τῶν μὲν γὰρ ῥητόρων τὸν τρόπον ψέγοντες προστάτας αὐτοὺς τῆς πόλεως ποιοῦνται καὶ κυρίους ἁπάντων καθιστᾶσιν, ἐμοῦ δὲ τοὺς λόγους ἐπαινοῦντες αὐτῷ μοι φθονοῦσι, δι’ οὐδὲν ἕτερον ἢ διὰ τούτους οὓς ἀποδεχόμενοι τυγχάνουσιν· οὕτως ἀτυχῶς φέρομαι παρ’ αὐτοῖς.", "st": "12.15"}, {"sp": "N", "t": "καὶ τί δεῖ θαυμάζειν τῶν πρὸς ἁπάσας τὰς ὑπεροχὰς οὕτω διακεῖσθαι πεφυκότων, ὅπου καὶ τῶν οἰομένων διαφέρειν καὶ ζηλούντων ἐμὲ καὶ μιμεῖσθαι γλιχομένων τινὲς ἔτι δυσμενέστερον ἔχουσί μοι τῶν ἰδιωτῶν· ὧν τίνας ἄν τις εὕροι πονηροτέρους, εἰρήσεται γάρ, εἰ καί τισι δόξω νεώτερα καὶ βαρύτερα λέγειν τῆς ἡλικίας, οἵτινες οὔτε φράζειν οὐδὲν μέρος ἔχοντες τοῖς μαθηταῖς τῶν εἰρημένων ὑπ’ ἐμοῦ, τοῖς τε λόγοις παραδείγμασι χρώμενοι τοῖς ἐμοῖς καὶ ζῶντες ἐντεῦθεν τοσούτου δέουσι χάριν ἔχειν τούτων, ὥστ’ οὐδ’ ἀμελεῖν ἡμῶν ἐθέλουσιν, ἀλλ’ ἀεί τι φλαῦρον περὶ ἐμοῦ λέγουσιν;", "st": "12.16"}, {"sp": "N", "t": "ἕως μὲν οὗν τοὺς λόγους μου ἐλυμαίνοντο, παραναγιγνώσκοντες ὡς δυνατὸν κάκιστα τοῖς ἑαυτῶν καὶ διαιροῦντες οὐκ ὀρθῶς καὶ κατακνίζοντες καὶ πάντα τρόπον διαφθείροντες, οὐδὲν ἐφρόντιζον τῶν ἀπαγγελλομένων, ἀλλὰ ῥᾳθύμως εἶχον· μικρὸν δὲ πρὸ τῶν Παναθηναίων τῶν μεγάλων ἠχθέσθην δι’ αὐτούς.", "st": "12.17"}, {"sp": "N", "t": "ἀπαντήσαντες γάρ τινές μοι τῶν ἐπιτηδείων ἔλεγον ὡς ἐν τῷ Λυκείω συγκαθεζόμενοι τρεῖς ἢ τέτταρες τῶν ἀγελαίων σοφιστῶν καὶ πάντα φασκόντων εἰδέναι καὶ ταχέως πανταχοῦ γιγνομένων διαλέγοιντο περί τε τῶν ἄλλων ποιητῶν καὶ τῆς Ἡσιόδου καὶ τῆς Ὁμήρου ποιήσεως, οὐδὲν μὲν παρ’ αὑτῶν λέγοντες, τὰ δ’ ἐκείνων ῥαψῳδοῦντες καὶ τῶν πρότερον ἄλλοις τισὶν εἰρημένων τὰ χαριέστατα μνημονεύοντες·", "st": "12.18"}, {"sp": "N", "t": "ἀποδεξαμένων δὲ τῶν περιεστώτων τὴν διατριβὴν αὐτῶν ἕνα τὸν τολμηρότατον ἐπιχειρῆσαί με διαβάλλειν, λέγονθ’ ὡς ἐγὼ πάντων καταφρονῶ τῶν τοιούτων, καὶ τάς τε φιλοσοφίας τὰς τῶν ἄλλων καὶ τὰς παιδεὶας ἁπάσας ἀναιρῶ, καί φημι πάντας ληρεῖν πλὴν τοὺς μετεσχηκότας τῆς ἐμῆς διατριβῆς· τούτων δὲ ῥηθέντων ἀηδῶς τινας τῶν παρόντων διατεθῆναι πρὸς ἡμᾶς.", "st": "12.19"}, {"sp": "N", "t": "ὡς μὲν οὖν ἐλυπήθην καὶ συνεταράχθην ἀκούσας ἀποδέξασθαί τινας τοὺς λόγους τούτους, οὐκ ἂν δυναίμην εἰπεῖν· ᾤμην γὰρ οὕτως ἐπιφανὴς εἶναι τοῖς ἀλαζονευομένοις πολεμῶν καὶ περὶ ἐμαυτοῦ μετρίως διειλεγμένος, μᾶλλον δὲ ταπεινῶς, ὥστε μηδέν’ ἄν ποτε γενέσθαι πιστὸν τῶν λεγόντων ὡς ἐγὼ τοιαύταις ἀλαζονείαις ἐχρησάμην.", "st": "12.20"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἀλόγως ὠδυράμην ἐν ἀρχῇ τὴν ἀτυχίαν τὴν παρακολουθοῦσάν μοι πάντα τὸν χρόνον ἐν τοῖς τοιούτοις· αὕτη γάρ ἐστιν αἰτία καὶ τῆς ψευδολογίας τῆς περί με γιγνομένης καὶ τῶν διαβολῶν καὶ τοῦ φθόνου καὶ τοῦ μὴ δύνασθαί με τυχεῖν τῆς δόξης ἧς ἄξιός εἰμι, μηδὲ τῆς ὁμολογουμένης, μηδ’ ἣν ἔχουσί τινες τῶν πεπλησιακότων μοι καὶ πανταχῇ τεθεωρηκότων ἡμᾶς.", "st": "12.21"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οὐχ οἷόν τ’ ἄλλως ἔχειν, ἀλλ’ ἀνάγκη στέργειν τοῖς ἤδη συμβεβηκόσι. πολλῶν δέ μοι λόγων ἐφεστώτων, ἀπορῶ πότερον ἀντικατηγορῶ τῶν εἰθισμένων ἀεί τι ψεύδεσθαι περί μου καὶ λέγειν ἀνεπιτήδειον τολμώντων· ἀλλ’ εἰ φανείην σπουδάζων καὶ πολλοὺς λόγους ποιούμενος περὶ ἀνθρώπων οὓς οὐδεὶς ὑπείληφεν ἀξίους εἶναι λόγου, δικαίως ἂν μωρὸς εἶναι δοκοίην.", "st": "12.22"}, {"sp": "N", "t": "ἀλλὰ τούτους ὑπεριδὼν ἀπολογῶμαι πρὸς τοὺς ἀδίκως μοι τῶν ἰδιωτῶν φθονοῦντας, καὶ πειρῶμαι διδάσκειν αὐτοὺς ὡς οὐ δικαίως οὐδὲ προσηκόντως περί μου ταύτην ἔχουσι τὴν γνώμην; καὶ τίς οὐκ ἂν καταγνοίη μου πολλὴν ἄνοιαν, εἰ τοὺς μηδὲν δι’ ἕτερον δυσκόλως πρός με διακειμένους ἢ διὰ τὸ δοκεῖν χαριέντως εἰρηκέναι περὶ τινων, τούτους οἰηθείην ὁμοίως διαλεχθεὶς ὥσπερ πρότερον παύσειν ἐπὶ τοῖς λεγομένοις λυπουμένους, ἀλλ’ οὐ μᾶλλον ἀλγήσειν, ἄλλως τε κἂν φανῶ μηδὲ νῦν πω τηλικοῦτος ὢν πεπαυμένος παραληρῶν;", "st": "12.23"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἐκεῖνο ποιεῖν οὐδεὶς ἄν μοι συμβουλεύσειεν, ἀμελήσαντι τούτων καὶ μεταξὺ καταβαλόντι περαίνειν τὸν λόγον, ὃν προῄρημαι βουλόμενος ἐπιδεῖξαι τὴν πόλιν ἡμῶν πλειόνων ἀγαθῶν αἰτίαν γεγενημένην τοῖς Ἕλλησιν ἢ τὴν Λακεδαιμονίων· εἰ γὰρ τοῦτ’ ἤδη ποιοίην μήτε τέλος ἐπιθεὶς τοῖς γεγραμμένοις μήτε συγκλείσας τὴν ἀρχὴν τῶν ῥηθήσεσθαι μελλόντων τῇ τελευτῇ τῶν ἤδη προειρημένων, ὅμοιος ἂν εἶναι δόξαιμι τοῖς εἰκῇ καὶ φορτικῶς καὶ χύδην ὅ τι ἂν ἐπέλθῃ λέγουσιν· ἃ φυλακτέον ἡμῖν ἐστιν.", "st": "12.24"}, {"sp": "N", "t": "κράτιστον οὖν ἐξ ἁπάντων τούτων, περὶ ὧν τὸ τελευταῖόν με διέβαλλον ἀποφηνάμενον ἃ δοκεῖ μοι, τότ’ ἤδη λέγειν περὶ ὦν ἐξ ἀρχῆς διενοήθην· οἶμαι γάρ, ἢν ἐξενέγκω γράψας καὶ ποιήσω φανερὰν ἣν ἔχω γνώμην περὶ τε τῆς παιδείας καὶ τῶν ποιητῶν, παύσειν αὐτοὺς ψευδεῖς πλάττοντας αἰτίας καὶ λέγοντας ὅ τι ἂν τύχωσιν.", "st": "12.25"}, {"sp": "N", "t": "τῆς μὲν οὖν παιδείας τῆς ὑπὸ τῶν προγόνων καταλειφθείσης τοσούτου δέω καταφρονεῖν, ὥστε καὶ τὴν ἐφ’ ἡμῶν κατασταθεῖσαν ἐπαινῶ, λέγω δὲ τήν τε γεωμετρίαν καὶ τὴν ἀστρολογίαν καὶ τοὺς διαλόγους τοὺς ἐριστικοὺς καλουμένους, οἷς οἱ μὲν νεώτεροι μᾶλλον χαίρουσι τοῦ δέοντος, τῶν δὲ πρεσβυτέρων οὐδεὶς ἔστιν ὅστις ἂν ἀνεκτοὺς αὐτοὺς εἶναι φήσειεν.", "st": "12.26"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἐγὼ τοῖς ὡρμημένοις ἐπὶ ταῦτα παρακελεύομαι πονεῖν καὶ προσέχειν τὸν νοῦν ἅπασι τούτοις, λέγων ὡς εἰ καὶ μηδὲν ἄλλο δύναται τὰ μαθήματα ταῦτα ποιεῖν ἀγαθόν, ἀλλ’ οὖν ἀποτρέπει γε τοὺς νεωτέρους πολλῶν ἄλλων ἁμαρτημάτων. τοῖς μὲν οὖν τηλικούτοις οὐδέποτ’ ἂν εὑρεθῆναι νομίζω διατριβὰς ὠφελιμωτέρας τούτων οὐδὲ μᾶλλον πρεπούσας·", "st": "12.27"}, {"sp": "N", "t": "τοῖς δὲ πρεσβυτέροις καὶ τοῖς εἰς ἄνδρας δεδοκιμασμένοις οὐκέτι φημὶ τὰς μελέτας ταύτας ἁρμόττειν. ὁρῶ γὰρ ἐνίους τῶν ἐπὶ τοῖς μαθήμασι τούτοις οὕτως ἀπηκριβωμένων ὥστε καὶ τοὺς ἄλλους διδάσκειν, οὔτ’ εὐκαίρως ταῖς ἐπιστήμαις αἷς ἔχουσι χρωμένους, ἔν τε ταῖς ἄλλαις πραγματείαις ταῖς περὶ τὸν βίον ἀφρονεστέρους ὄντας τῶν μαθητῶν· ὀκνῶ γὰρ εἰπεῖν τῶν οἰκετῶν.", "st": "12.28"}, {"sp": "N", "t": "τὴν αὐτὴν δὲ γνώμην ἔχω καὶ περὶ τῶν δημηγορεῖν δυναμένων καὶ τῶν περὶ τὴν γραφὴν τὴν τῶν λόγων εὐδοκιμούντων, ὅλως δὲ περὶ ἁπάντων τῶν περὶ τὰς τέχνας καὶ τὰς ἐπιστήμας καὶ τὰς δυνάμεις διαφερόντων. οἶδα γὰρ καὶ τούτων τοὺς πολλοὺς οὔτε τὰ περὶ σφᾶς αὐτοὺς καλῶς διῳκηκότας οὔτ’ ἐν ταῖς ἰδίαις συνουσίαις ἀνεκτοὺς ὄντας, τῆς τε δόξης τῆς τῶν συμπολιτευομένων ὀλιγωροῦντας, ἄλλων τε πολλῶν καὶ μεγάλων ἁμαρτημάτων γέμοντας· ὥστ’ οὐδὲ τούτους ἡγοῦμαι μετέχειν τῆς ἕξεως περὶ ἧς ἐγὼ τυγχάνω διαλεγόμενος.", "st": "12.29"}, {"sp": "N", "t": "τίνας οὖν καλῶ πεπαιδευμένους, ἐπειδὴ τὰς τέχνας καὶ τὰς ἐπιστήμας καὶ τὰς δυνάμεις ἀποδοκιμάζω; πρῶτον μὲν τοὺς καλῶς χρωμένους τοῖς πράγμασι τοῖς κατὰ τὴν ἡμέραν ἑκάστην προσπίπτουσι, καὶ τὴν δόξαν ἐπιτυχῆ τῶν καιρῶν ἔχοντας καὶ δυναμένην ὡς ἐπὶ τὸ πολὺ στοχάζεσθαι τοῦ συμφέροντος·", "st": "12.30"}, {"sp": "N", "t": "ἔπειτα τοὺς πρεπόντως καὶ δικαίως ὁμιλοῦντας τοῖς ἀεὶ πλησιάζουσι, καὶ τὰς μὲν τῶν ἄλλων ἀηδίας καὶ βαρύτητας εὐκόλως καὶ ῥᾳδίως φέροντας, σφᾶς δ’ αὐτοὺς ὡς δυνατὸν ἐλαφροτάτους καὶ μετριωτάτους τοῖς συνοῦσι παρέχοντας· ἔτι τοὺς τῶν μὲν ἡδονῶν ἀεὶ κρατοῦντας, τῶν δὲ συμφορῶν μὴ λίαν ἡττωμένους, ἀλλ’ ἀνδρωδῶς ἐν αὐταῖς διακειμένους καὶ τῆς φύσεως ἀξίως ἧς μετέχοντες τυγχάνομεν· τέταρτον,", "st": "12.31"}, {"sp": "N", "t": "ὅπερ μέγιστον, τοὺς μὴ διαφθειρομένους ὑπὸ τῶν εὐπραγιῶν μηδ’ ἐξισταμένους αὑτῶν μηδ’ ὑπερηφάνους γιγνομένους, ἀλλ’ ἐμμένοντας τῇ τάξει τῇ τῶν εὖ φρονούντων, καὶ μὴ μᾶλλον χαίροντας τοῖς διὰ τύχην ὑπάρξασιν ἀγαθοῖς ἢ τοῖς διὰ τὴν αὑτῶν φύσιν καὶ φρόνησιν ἐξ ἀρχῆς γιγνομένοις. τοὺς δὲ μὴ μόνον πρὸς ἓν τούτων ἀλλ’ καὶ πρὸς ἅπαντα ταῦτα τὴν ἕξιν τῆς ψυχῆς εὐάρμοστον ἔχοντας, τούτους φημὶ καὶ φρονίμους εἶναι καὶ τελέους ἄνδρας καὶ πάσας ἔχειν τὰς ἀρετάς.", "st": "12.32"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν πεπαιδευμένων τυγχάνω ταῦτα γιγνώσκων. περὶ δὲ τῆς Ὁμήρου καὶ τῆς Ἡσιόδου καὶ τῆς τῶν ἄλλων ποιήσεως ἐπιθυμῶ μὲν εἰπεῖν, οἶμαι γὰρ ἂν παῦσαι τοὺς ἐν τῷ Λυκείῳ ῥαψῳδοῦντας τἀκείνων καὶ ληροῦντας περὶ αὐτῶν, αἰσθάνομαι δ’ ἐμαυτὸν ἔξω φερόμενον τῆς συμμετρίας τῆς συντεταγμένης τοῖς προοιμίοις.", "st": "12.33"}, {"sp": "N", "t": "ἔστι δ’ ἀνδρὸς νοῦν ἔχοντος μὴ τὴν εὐπορίαν ἀγαπᾶν, ἢν ἔχῃ τις περὶ τῶν αὐτῶν πλείω τῶν ἄλλων εἰπεῖν, ἀλλὰ τὴν εὐκαιρίαν διαφυλάττειν ὑπὲρ ὦν ἂν ἀεὶ τυγχάνῃ διαλεγόμενος· ὅπερ ἐμοὶ ποιητέον ἐστίν. περὶ μὲν οὖν τῶν ποιητῶν αὖθις ἐροῦμεν, ἢ μή με προανέλῃ τὸ γῆρας, ἢ περὶ σπουδαιοτέρων πραγμάτων ἔχω τι λέγειν ἢ τούτων.", "st": "12.34"}, {"sp": "N", "t": "περὶ δὲ τῶν τῆς πόλεως εὐεργεσιῶν τῶν εἰς τοὺς Ἕλληνας ἤδη ποιήσομαι τοὺς λόγους, οὐχ ὡς οὐ πλείους ἐπαίνους πεποιημένος περὶ αὐτῆς ἢ σύμπαντες οἱ περὶ τὴν ποίησιν καὶ τοὺς λόγους ὄντες· οὐ μὴν ὁμοίως καὶ νῦν. τότε μὲν γὰρ ἐν λόγοις περὶ ἑτέρων πραγμάτων ἐμεμνήμην αὐτῆς, νῦν δὲ περὶ ταύτης τὴν ὑπόθεσιν ποιησάμενος.", "st": "12.35"}, {"sp": "N", "t": "οὐκ ἀγνοῶ δ’ ἡλίκος ὢν ὅσον ἔργον ἐνίσταμαι τὸ μέγεθος, ἀλλ’ ἀκριβῶς εἰδὼς καὶ πολλάκις εἰρηκὼς ὅτι τὰ μὲν μικρὰ τῶν πραγμάτων ῥᾴδιον τοῖς λόγοις αὐξῆσαι, τοῖς δ’ ὑπερβάλλουσι τῶν ἔργων καὶ τῷ μεγέθει καὶ τῷ κάλλει χαλεπὸν ἐξισῶσαι τοὺς ἐπαίνους.", "st": "12.36"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐδὲν μᾶλλον ἀποστατέον αὐτῶν ἐστιν, ἀλλ’ ἐπιτελεστέον, ἤν περ ἔτι ζῆν δυνηθῶμεν, ἄλλως τε καὶ πολλῶν με παροξυνόντων γράφειν αὐτόν, πρῶτον μὲν τῶν εἰθισμένων ἀσελγῶς κατηγορεῖν τῆς πόλεως ἡμῶν, ἔπειτα τῶν χαριέντως μὲν ἀπειροτέρως δὲ καὶ καταδεεστέρως ἐπαινούντων αὐτήν,", "st": "12.37"}, {"sp": "N", "t": "ἔτι δὲ τῶν ἑτέρων μᾶλλον εὐλογεῖν τολμώντων οὐκ ἀνθρωπίνως ἀλλ’ οὕτως ὥστε πολλοὺς ἀντιτάττεσθαι πρὸς αὐτούς, πάντων δὲ μάλιστα τῆς ἡλικίας τῆς παρούσης, ἣ τοὺς ἄλλους πέφυκεν ἀποτρέπειν· ἐλπίξω γὰρ, ἢν μὲν κατορθώσω, μείζω λήψεσθαι δόξαν τῆς ὑπαρχούσης, ἢν δ’ ἐνδεέστερον τύχω διαλεχθείς, πολλῆς συγγνώμης τεύξεσθαι παρὰ τῶν ἀκουόντων.", "st": "12.38"}, {"sp": "N", "t": "ἃ μὲν οὖ ἐβουλήθην καὶ περὶ ἐμαυτοῦ καὶ περὶ τῶν ἄλλων ὥπερ χορὸς πρὸ τοῦ ἀγῶνος προαναβαλέσθαι ταῦτ’ ἐστίν. ἡγοῦμαι δὲ χρῆναι τοὺς βουλομένους ἐγκωμιάσαι τινὰ τῶν πόλεων ἀκριβῶς καὶ δικαίως μὴ μόνον περὶ αὐτῆς ποιεῖσθαι τοὺς λόγους ἧς προῃρημένοι τυγχάνουσιν, ἀλλ’ ὥσπερ τὴν πορφύραν καὶ τὸν χρυσὸν θεωροῦμεν καὶ δοκιμάζομεν ἕτερα παραδεικνύοντες τῶν καὶ τὴν ὄψιν ὁμοίαν ἐχόντων καὶ τῆς τιμῆς τῆς αὐτῆς ἀξιουμένων,", "st": "12.39"}, {"sp": "N", "t": "οὕτω καὶ ταῖς πόλεσι παριστάναι μὴ τὰς μικρὰς ταῖς μεγάλαις, μηδὲ τὰς πάντα τὸν χρόνον ὑφ’ ἑτέραις οὔσας ταῖς ἄρχειν εἰθισμέναις, μηδὲ τὰς σώζεσθαι δεομένας πρὸς τὰς σώζειν δυναμένας, ἀλλὰ τὰς παραπλησίαν καὶ τὴν δύναμιν ἐχούσας καὶ περὶ τὰς αὐτὰς πράξεις γεγενημένας καὶ ταῖς ἐξουσίαις ὁμοίαις κεχρημένας· οὕτω γὰρ ἂν μάλιστα τῆς ἀληθείας τύχοιεν.", "st": "12.40"}, {"sp": "N", "t": "ἢν δή τις ἡμᾶς τὸν τρόπον τοῦτον σκοπῆται καὶ παραβάλλῃ μὴ πρὸς τὴν τυχοῦσαν πόλιν ἀλλὰ πρὸς τὴν Σπαρτιατῶν, ἣν οἱ μὲν πολλοὶ μετρίως ἐπαινοῦσιν, ἔνιοι δέ τινες ὥσπερ τῶν ἡμιθέων ἐκεῖ πεπολιτευμένων μέμνηνται περὶ αὐτῶν, φανησόμεθα καὶ τῇ δυνάμει καὶ ταῖς πράξεσι καὶ ταῖς εὐεργεσίαις ταῖς περὶ τοὺς Ἕλληνας πλέον ἀπολελοιπότες αὐτοὺς ἢ ’κεῖνοι τοὺς ἄλλους.", "st": "12.41"}, {"sp": "N", "t": "τοὺς μὲν οὖν παλαιοὺς ἀγῶνας τοὺς ὑπὲρ τῶν Ἑλλήνων γεγενημένους ὕστερον ἐροῦμεν, νῦν δὲ ποιήσομαι περὶ ἐκείνων τοὺς λόγους ἀρξάμενος, ἐπειδὴ κατέσχον τὰς πόλεις τὰς Ἀχαιίδας καὶ πρὸς Ἀργείους καὶ Μεσσηνίους διείλοντο τὴν χώραν· ἐντεῦθεν γὰρ προσήκει διαλέγεσθαι περὶ αὐτῶν. οἱ μὲν τοίνυν ἡμέτεροι πρόγονοι φανήσονται τήν τε πρὸς τοὺς Ἕλληνας ὁμόνοιαν καὶ τὴν πρὸς τοὺς βαρβάρους ἔχθραν, ἣν παρέλαβον ἐκ τῶν Τρωικῶν, διαφυλάττοντες καὶ μένοντες ἐν τοῖς αὐτοῖς.", "st": "12.42"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τὰς Κυκλάδας νήσους, περὶ ἃς ἐγένοντο πολλαὶ πραγματεῖαι κατὰ τὴν Μίνω τοῦ Κρητὸς δυναστείαν, ταύτας τὸ τελευταῖον ὑπὸ Καρῶν κατεχομένας, ἐκβαλόντες ἐκείνους οὐκ ἐξιδιώσασθαι τὰς χώρας ἐτόλμησαν, ἀλλὰ τοὺς μάλιστα βίου τῶν Ἑλλήνων δεομένους κατῴκισαν εἰς αὐτάς·", "st": "12.43"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα πολλὰς πόλεις ἐφ’ ἑκατέρας τῶν ἠπείρων καὶ μεγάλας ἔκτισαν, καὶ τοὺς μὲν βαρβάρους ἀνέστειλαν ἀπὸ τῆς θαλάττης, τοὺς δ’ Ἕλληνας ἐδίδαξαν ὃν τρόπον διοικοῦντες τὰς αὑτῶν πατρίδας καὶ πρὸς οὓς πολεμοῦντες μεγάλην ἂν τὴν Ἑλλάδα ποιήσειαν.", "st": "12.44"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ περὶ τὸν αὐτὸν χρόνον τοσοῦτον ἀπέσχον τοῦ πράττειν τι τῶν αὐτῶν τοῖς ἡμετέροις καὶ τοῦ τοῖς μὲν βαρβάροις πολεμεῖν τοὺς δ’ Ἕλληνας εὐεργετεῖν, ὥστ’ οὐδ’ ἡσυχίαν ἄγειν ἠθέλησαν, ἀλλ’ ἔχοντες πόλιν ἀλλοτρίαν καὶ χώραν οὐ μόνον ἱκανήν, ἀλλ’ ὅσην οὐδεμία πόλις τῶν Ἑλληνίδων, οὐκ ἔστερξαν ἐπὶ τούτοις,", "st": "12.45"}, {"sp": "N", "t": "ἀλλὰ μαθόντες ἐξ αὐτῶν τῶν συμβεβηκότων κατὰ μὲν τοὺς νόμους τάς τε πόλεις καὶ τὰς χώρας τούτων εἶναι δοκούσας, τῶν ὀρθῶς καὶ νομίμως κτησαμένων, κατὰ δὲ τὴν ἀλήθειαν τούτων γιγνομένας, τῶν τὰ περὶ τὸν πόλεμον μάλιστ’ ἀσκούντων καὶ νικᾶν ἐν ταῖς μάχαις τοὺς πολεμίους δυναμένων, ταῦτα διανοηθέντες, ἀμελήσαντες γεωργιῶν καὶ τεχνῶν καὶ τῶν ἄλλων ἁπάντων, οὐδὲν ἐπαύοντο κατὰ μίαν ἑκάστην τῶν πόλεων τῶν ἐν Πελοποννήσῳ πολιορκοῦντες καὶ κακῶς ποιοῦντες, ἕως ἁπάσας κατεστρέψαντο πλὴν τῆς Ἀργείων.", "st": "12.46"}, {"sp": "N", "t": "συνέβαινεν οὖν ἐξ ὧν μὲν ἡμεῖς ἐπράττομεν, αὐξάνεσθαί τε τὴν Ἑλλάδα καὶ τὴν Εὐρώπην κρείττω γίγνεσθαι τῆς Ἀσίας, καὶ πρὸς τούτοις τῶν μὲν Ἑλλήνων τοὺς ἀποροῦντας πόλεις λαμβάνειν καὶ χώρας, τῶν δὲ βαρβάρων τοὺς εἰθισμένους ὑβρίζειν ἐκπίπτειν ἐκ τῆς αὑτῶν καὶ φρονεῖν ἔλαττον ἢ πρότερον· ἐξ ὧν δὲ Σπαρτιᾶται, τὴν ἐκείνων μόνην μεγάλην γίγνεσθαι, καὶ πασῶν μὲν τῶν ἐν Πελοποννήσῳ πόλεων ἄρχειν, ταῖς δ’ ἄλλαις φοβερὰν εἶναι καὶ πολλῆς θεραπείας τυγχάνειν παρ’ αὐτῶν.", "st": "12.47"}, {"sp": "N", "t": "ἐπαινεῖν μὲν οὖν δίκαιόν ἐστι τὴν τοῖς ἄλλοις πολλῶν ἀγαθῶν αἰτίαν γεγενημένην, δεινὴν δὲ νομίζειν τὴν αὑτῇ τὰ συμφέροντα διαπραττομένην, καὶ φίλους μὲν ποιεῖσθαι τοὺς ὁμοίως αὑτοῖς τε καὶ τοῖς ἄλλοις χρωμένους, φοβεῖσθαι δὲ καὶ δεδιέναι τοὺς πρὸς σφᾶς μὲν αὐτοὺς ὡς δυνατὸν οἰκειότατα διακειμένους, πρὸς δὲ τοὺς ἄλλους ἀλλοτρίως καὶ πολεμικῶς τὴν αὑτῶν διοικοῦντας. τὴν μὲν οὖν ἀρχὴν ἑκατέρα τοῖν πολέοιν τοιαύτην ἐποιήσατο.", "st": "12.48"}, {"sp": "N", "t": "χρόνῳ δ’ ὕστερον γενομένου τοῦ Περσικοῦ πολέμου, καὶ Ξέρξου τοῦ τότε βασιλεύοντος τριήρεις μὲν συναγαγόντος τριακοσίας καὶ χιλίας, τῆς δὲ πεζῆς στρατιᾶς πεντακοσίας μὲν μυριάδας τῶν ἁπάντων, ἑβδομήκοντα δὲ τῶν μαχίμων, τηλικαύτῃ δὲ δυνάμει στρατεύσαντος ἐπὶ τοὺς Ἕλληνας,", "st": "12.49"}, {"sp": "N", "t": "Σπαρτιᾶται μὲν ἄρχοντες Πελοποννησίων εἰς τὴν ναυμαχίαν τὴν ποιήσασαν ῥοπὴν ἅπαντος τοῦ πολέμου δέκα μόνον συνεβάλοντο τριήρεις, οἱ δὲ πατέρες ἡμῶν ἀνάστατοι γενόμενοι καὶ τὴν πόλιν ἐκλελοιπότες διὰ τὸ μὴ τετειχίσθαι κατ’ ἐκεῖνον τὸν χρόνον πλείους ναῦς παρέσχοντο καὶ μείζω δύναμιν ἐχούσας ἢ σύμπαντες οἱ συγκινδυνεύσαντες· καὶ στρατηγὸν οἱ μὲν Εὐρυβιάδην,", "st": "12.50"}, {"sp": "N", "t": "ὃς εἰ τέλος ἐπέθηκεν οἷς διενοήθη πράττειν, οὐδὲν ἂν ἐκώλυεν ἀπολωλέναι τοὺς Ἕλληνας, οἱ δ’ ἡμέτεροι Θεμιστοκλέα τὸν ὁμολογουμένως ἅπασιν αἴτιον εἶναι δόξαντα καὶ τοῦ τὴν ναυμαχίαν γενέσθαι κατὰ τρόπον καὶ τῶν ἄλλων ἁπάντων τῶν ἐν ἐκείνῳ τῷ χρόνῳ κατορθωθέντων.", "st": "12.51"}, {"sp": "N", "t": "τεκμήριον δὲ μέγιστον· ἀφελόμενοι γὰρ Λακεδαιμονίους τὴν ἡγεμονίαν οἱ συγκινδυνεύσαντες τοῖς ἡμετέροις παρέδοσαν. καίτοι τίνας ἄν τις κριτὰς ἱκανωτέρους ποιήσαιτο καὶ πιστοτέρους τῶν τότε πραχθέντων ἢ τοὺς ἐν αὐτοῖς τοῖς ἀγῶσι παραγενομένους; τίνα δ’ ἄν τις εὐεργεσίαν εἰπεῖν ἔχοι ταύτης μείζω, τῆς ἅπασαν τὴν Ἑλλάδα σῶσαι δυνηθείσης;", "st": "12.52"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν συνέβη κυρίαν ἑκατέραν γενέσθαι τῆς ἀρχῆς τῆς κατὰ θάλατταν, ἣν ὁπότεροι ἂν κατάσχωσιν, ὑπηκόους ἔχουσι τὰς πλείστας τῶν πόλεων. ὅλως μὲν οὖν οὐδετέραν ἐπαινῶ· πολλὰ γὰρ ἄν τις αὐταῖς ἐπιτιμήσειεν· οὐ μὴν ἀλλὰ καὶ περὶ τὴν ἐπιμέλειαν ταύτην οὐκ ἔλαττον αὐτῶν διηνέγκαμεν ἢ περὶ τὰς πράξεις τὰς ὀλίγῳ πρότερον εἰρημένας.", "st": "12.53"}, {"sp": "N", "t": "οἱ μὲν γὰρ ἡμέτεροι πατέρες ἔπειθον τοὺς συμμάχους ποιεῖσθαι πολιτείαν ταύτην, ἥνπερ αὐτοὶ διετέλουν ἀγαπῶντες· ὃ σημεῖόν ἐστιν εὐνοίας καὶ φιλίας, ὅταν τινὲς παραινῶσι τοῖς ἄλλοις χρῆσθαι τούτοις, ἅπερ ἂν σφίσιν αὐτοῖς συμφέρειν ὑπολάβωσιν· Λακεδαιμόνιοι δὲ κατέστησαν οὔθ’ ὁμοίαν τῇ παρ’ αὑτοῖς οὔτε ταῖς ἄλλοθί που γεγενημέναις, ἀλλὰ δέκα μόνους ἄνδρας κυρίους ἑκάστης τῆς πόλεως ἐποίησαν, ὧν ἐπιχειρήσας ἄν τις κατηγορεῖν τρεῖς ἢ τέτταρας ἡμέρας συνεχῶς οὐδὲν ἂν μέρος εἰρηκέναι δόξειε τῶν ἐκείνοις ἡμαρτημένων.", "st": "12.54"}, {"sp": "N", "t": "καθ’ ἕκαστον μὲν οὖν διεξιέναι περὶ τῶν τοιούτων καὶ τοσούτων τὸ πλῆθος ἀνόητόν ἐστιν· ὀλίγα δὲ καθ’ ἁπάντων εἰπεῖν, ἃ τοῖς ἀκούσασιν ὀργὴν ἀξίαν ἐμποιήσειεν ἂν τῶν πεπραγμένων, νεώτερος μὲν ὢν ἴσως ἂν ἐξεῦρον, νῦν δ’ οὐδὲν ἐπέρχεταί μοι τοιοῦτον, ἀλλ’ ἅπερ ἅπασιν, ὅτι τοσοῦτον ἐκεῖνοι διήνεγκαν ἀνομίᾳ καὶ πλεονεξίᾳ τῶν προγεγενημένων, ὥστ’ οὐ μόνον αὑτοὺς ἀπώλεσαν καὶ τοὺς φίλους καὶ τὰς πατρίδας τὰς αὑτῶν, ἀλλὰ καὶ Λακεδαιμονίους πρὸς τοὺς συμμάχους διαβαλόντες εἰς τοιαύτας καὶ τοσαύτας συμφορὰς ἐνέβαλον, ὅσας οὐδεὶς πώποτ’ αὐτοῖς γενήσεσθαι προσεδόκησεν.", "st": "12.55"}, {"sp": "N", "t": "μάλιστα μὲν οὖν ἐντεῦθεν ἄν τις δυνηθείη κατιδεῖν ὅσῳ μετριώτερον καὶ πραότερον ἡμεῖς τῶν πραγμάτων ἐπεμελήθημεν, δεύτερον δ’ ἐκ τοῦ ῥηθήσεσθαι μέλλοντος· Σπαρτιᾶται μὲν γὰρ ἔτη δέκα μόλις ἐπεστάτησαν αὐτῶν, ἡμεῖς δὲ πέντε καὶ ἑξήκοντα συνεχῶς κατέσχομεν τὴν ἀρχήν. καίτοι πάντες ἴσασι τὰς πόλεις τὰς ὑφ’ ἑτέροις γιγνομένας, ὅτι πλεῖστον χρόνον τούτοις παραμένουσιν ὑφ’ ὧν ἂν ἐλάχιστα κακὰ πάσχουσαι τυγχάνωσιν.", "st": "12.56"}, {"sp": "N", "t": "ἐκ τούτων τοίνυν ἀμφότεραι μισηθεῖσαι κατέστησαν εἰς πόλεμον καὶ ταραχήν, ἐν ᾗ τὴν μὲν ἡμετέραν εὕροι τις ἄν, ἁπάντων αὐτῇ καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων ἐπιθεμένων, ἔτη δέκα τούτοις ἀντισχεῖν δυνηθεῖσαν, Λακεδαιμονίους δὲ κρατοῦντας ἔτι κατὰ γῆν, πρὸς Θηβαίους μόνους πολεμήσαντας καὶ μίαν μάχην ἡττηθέντας, ἁπάντων ἀποστερηθέντας ὧν εἶχον, καὶ παραπλησίαις ἀτυχίαις χρησαμένους καὶ συμφοραῖς αἷσπερ ἡμεῖς,", "st": "12.57"}, {"sp": "N", "t": "καὶ πρὸς τούτοις τὴν μὲν ἡμετέραν πόλιν ἐν ἐλάττοσιν ἔτεσιν ἀναλαβοῦσαν αὑτὴν ἢ κατεπολεμήθη, Σπαρτιάτας δὲ μετὰ τὴν ἧτταν μηδ’ ἐν πολλαπλασίῳ χρόνῳ δυνηθέντας καταστῆσαι σφᾶς αὐτοὺς εἰς τὴν αὐτὴν ἕξιν ἐξ ἧς περ ἐξέπεσον, ἀλλ’ ὁμοίως ἔτι καὶ νῦν ἔχοντας.", "st": "12.58"}, {"sp": "N", "t": "τὰ τοίνυν πρὸς τοὺς βαρβάρους ὡς ἑκάτεροι προσηνέχθημεν, δηλωτέον· ἔτι γὰρ τοῦτο λοιπόν ἐστιν. ἐπὶ μὲν γὰρ τῆς ἡμετέρας δυναστείας οὐκ ἐξῆν αὐτοῖς οὔτ’ ἐντὸς Ἅλυος πεζῷ στρατοπέδῳ καταβαίνειν οὔτε μακροῖς πλοίοις ἐπὶ τάδε πλεῖν Φασήλιδος· ἐπὶ δὲ τῆς Λακεδαιμονίων οὐ μόνον τοῦ πορεύεσθαι καὶ πλεῖν ὅποι βουληθεῖεν ἐξουσίαν ἔλαβον, ἀλλὰ καὶ δεσπόται πολλῶν Ἑλληνίδων πόλεων κατέστησαν.", "st": "12.59"}, {"sp": "N", "t": "τὴν δὴ καὶ τὰς συνθήκας τὰς πρὸς βασιλέα γενναιοτέρας καὶ μεγαλοφρονεστέρας ποιησαμένην, καὶ τῶν πλείστων καὶ μεγίστων τοῖς μὲν βαρβάροις κακῶν τοῖς δ’ Ἕλλησιν ἀγαθῶν αἰτίαν γεγενημένην, ἔτι δὲ τῆς Ἀσίας τὴν παραλίαν καὶ πολλὴν ἄλλην χώραν τοὺς μὲν πολεμίους ἀφελομένην τοῖς δὲ συμμάχοις κτησαμένην,", "st": "12.60"}, {"sp": "N", "t": "καὶ τοὺς μὲν ὑβρίζοντας τοὺς δ’ ἀποροῦντας παύσασαν, πρὸς δὲ τούτοις ὑπὲρ αὑτῆς τε πολεμήσασαν ἄμεινον τῆς εὐδοκιμούσης περὶ τὰ τοιαῦτα καὶ τὰς συμφορὰς θᾶττον διαλυσαμένην τῶν αὐτῶν τούτων, πῶς οὐ δίκαιον ἐπαινεῖν καὶ τιμᾶν μᾶλλον ἢ τὴν ἐν ἅπασι τούτοις ἀπολελειμμένην; περὶ μὲν οὖν τῶν πραχθέντων παρ’ ἄλληλα καὶ τῶν κινδύνων τῶν ἅμα καὶ πρὸς τοὺς αὐτοὺς γενομένων ἐν τῷ παρόντι ταῦτ’ εἶχον εἰπεῖν.", "st": "12.61"}, {"sp": "N", "t": "οἶμαι δὲ τοὺς ἀηδῶς ἀκούοντας τῶν λόγων τούτων τοῖς μὲν εἰρημένοις οὐδὲν ἀντερεῖν ὡς οὐκ ἀληθέσιν οὖσιν, οὐδ’ αὖ πράξεις ἑτέρας ἕξειν εἰπεῖν περὶ ἃς Λακεδαιμόνιοι γενόμενοι πολλῶν ἀγαθῶν αἴτιοι τοῖς Ἕλλησι κατέστησαν, κατηγορεῖν δὲ τῆς πόλεως ἡμῶν ἐπιχειρήσειν,", "st": "12.62"}, {"sp": "N", "t": "ὅπερ ἀεὶ ποιεῖν εἰώθασι, καὶ διεξιέναι τὰς δυσχερεστάτας τῶν πράξεων τῶν ἐπὶ τῆς ἀρχῆς τῆς κατὰ θάλατταν γεγενημένων, καὶ τάς τε δίκας καὶ τὰς κρίσεις τὰς ἐνθάδε γιγνομένας τοῖς συμμάχοις καὶ τὴν τῶν φόρων εἴσπραξιν διαβαλεῖν, καὶ μάλιστα διατρίψειν περὶ τὰ Μηλίων πάθη καὶ Σκιωναίων καὶ Τορωναίων, οἰομένους ταῖς κατηγορίαις ταύταις καταρρυπανεῖν τὰς τῆς πόλεως εὐεργεσίας τὰς ὀλίγῳ πρότερον εἰρημένας.", "st": "12.63"}, {"sp": "N", "t": "ἐγὼ δὲ πρὸς ἅπαντα μὲν τὰ δικαίως ἂν ῥηθέντα κατὰ τῆς πόλεως οὔτ’ ἂν δυναίμην ἀντειπεῖν οὔτ’ ἂν ἐπιχειρήσαιμι τοῦτο ποιεῖν· καὶ γὰρ ἂν αἰσχυνοίμην, ὅπερ εἶπον ἤδη καὶ πρότερον, εἰ τῶν ἄλλων μηδὲ τοὺς θεοὺς ἀναμαρτήτους εἶναι νομιζόντων ἐγὼ γλιχοίμην καὶ πειρῴμην πείθειν ὡς περὶ οὐδὲν πώποτε τὸ κοινὸν ἡμῶν πεπλημμέληκεν·", "st": "12.64"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐκεῖνό γ’ οἴομαι ποιήσειν, τήν τε πόλιν τὴν Σπαρτιατῶν ἐπιδείξειν περὶ τὰς πράξεις τὰς προειρημένας πολὺ πικροτέραν καὶ χαλεπωτέραν τῆς ἡμετέρας γεγενημένην, τούς θ’ ὑπὲρ ἐκείνων βλασφημοῦντας καθ’ ἡμῶν ὡς δυνατὸν ἀφρονέστατα διακειμένους καὶ τοῦ κακῶς ἀκούειν ὑφ’ ἡμῶν τοὺς φίλους αὐτῶν αἰτίους ὄντας·", "st": "12.65"}, {"sp": "N", "t": "ἐπειδὰν γὰρ τὰ τοιαῦτα κατηγορῶσιν, οἷς ἔνοχοι Λακεδαιμόνιοι μᾶλλον τυγχάνουσιν ὄντες, οὐκ ἀποροῦμεν τοῦ περὶ ἡμῶν ῥηθέντος μεῖζον ἁμάρτημα κατ’ ἐκείνων εἰπεῖν. οἷον καὶ νῦν, ἢν μνησθῶσι τῶν ἀγώνων τῶν τοῖς συμμάχοις ἐνθάδε γιγνομένων, τίς ἐστιν οὕτως ἀφυής, ὅστις οὐχ εὑρήσει πρὸς τοῦτ’ ἀντειπεῖν ὅτι πλείους Λακεδαιμόνιοι τῶν Ἑλλήνων ἀκρίτους ἀπεκτόνασι τῶν παρ’ ἡμῖν, ἐξ οὗ τὴν πόλιν οἰκοῦμεν, εἰς ἀγῶνα καὶ κρίσιν καταστάντων;", "st": "12.66"}, {"sp": "N", "t": "τοιαῦτα δὲ καὶ περὶ τῆς εἰσπράξεως τῶν φόρων ἤν τι λέγωσιν, ἕξομεν εἰπεῖν· πολὺ γὰρ ἐπιδείξομεν συμφορώτερα πράξαντας τοὺς ἡμετέρους ἢ Λακεδαιμονίους ταῖς πόλεσι ταῖς τὸν φόρον ἐνεγκούσαις. πρῶτον μὲν γὰρ οὐ προσταχθὲν ὑφ’ ἡμῶν τοῦτ’ ἐποίουν, ἀλλ’ αὐτοὶ γνόντες, ὅτε περ τὴν ἡγεμονίαν ἡμῖν τὴν κατὰ θάλατταν ἔδοσαν·", "st": "12.67"}, {"sp": "N", "t": "ἔπειτ’ οὐχ ὑπὲρ τῆς σωτηρίας τῆς ἡμετέρας ἔφερον, ἀλλ’ ὑπὲρ τῆς δημοκρατίας καὶ τῆς ἐλευθερίας τῆς αὑτῶν καὶ τοῦ μὴ περιπεσεῖν ὀλιγαρχίας γενομένης τηλικούτοις κακοῖς τὸ μέγεθος, ἡλίκοις ἐπὶ τῶν δεκαδαρχιῶν καὶ τῆς δυναστείας τῆς Λακεδαιμονίῶν. ἔτι δ’ οὐκ ἐκ τούτων ἔφερον ἐξ ὧν αὐτοὶ διέσωσαν, ἀλλ’ ἀφ’ ὧν δι’ ἡμᾶς εἶχον· ὑπὲρ ὧν,", "st": "12.68"}, {"sp": "N", "t": "εἰ καὶ μικρὸς λογισμὸς ἐνῆν αὐτοῖς, δικαίως ἂν χάριν εἶχον ἡμῖν. παραλαβόντες γὰρ τὰς πόλεις αὐτῶν τὰς μὲν παντάπασιν ἀναστάτους γεγενημένας ὑπὸ τῶν βαρβάρων, τὰς δὲ πεπορθημένας, εἰς τοῦτο προηγάγομεν, ὥστε μικρὸν μέρος τῶν γιγνομένων ἡμῖν διδόντας μηδὲν ἐλάττους ἔχειν τοὺς οἴκους Πελοποννησίων τῶν οὐδένα φόρον ὑποτελούντων.", "st": "12.69"}, {"sp": "N", "t": "περὶ τοίνυν τῶν ἀναστάτων γεγενημένων ὑφ’ ἑκατέρας τῶν πόλεων, ὃ μόνοις τινὲς ἡμῖν ὀνειδίζουσιν, ἐπιδείξομεν πολὺ δεινότερα πεποιηκότας οὓς ἐπαινοῦντες διατελοῦσιν. ἡμῖν μὲν γὰρ συνέπεσε περὶ νησύδρια τοιαῦτα καὶ τηλικαῦτα τὸ μέγεθος ἐξαμαρτεῖν, ἃ πολλοὶ τῶν Ἑλλήνων οὐδ’ ἴσασιν, ἐκεῖνοι δὲ τὰς μεγίστας πόλεις τῶν ἐν Πελοποννήσῳ καὶ τὰς πανταχῇ προεχούσας τῶν ἄλλων ἀναστάτους ποιήσαντες αὐτοὶ τἀκείνων ἔχουσιν,", "st": "12.70"}, {"sp": "N", "t": "ἃς ἄξιον ἦν, εἰ καὶ μηδὲν αὐταῖς πρότερον ὑπῆρχεν ἀγαθόν, τῆς μεγίστης δωρεᾶς παρὰ τῶν Ἑλλήνων τυχεῖν διὰ τὴν στρατείαν τὴν ἐπὶ Τροίαν, ἐν ᾗ σφᾶς τε αὐτὰς παρέσχον πρωτευούσας καὶ τοὺς ἡγεμόνας ἀρετὰς ἔχοντας οὐ μόνον τὰς τοιαύτας ὧν πολλοὶ καὶ τῶν φαύλων κοινωνοῦσιν, ἀλλὰ κἀκείνας ὧν οὐδεὶς ἂν πονηρὸς ὢν δυνηθείη μετασχεῖν.", "st": "12.71"}, {"sp": "N", "t": "Μεσσήνη μὲν γὰρ Νέστορα παρέσχε τὸν φρονιμώτατον ἁπάντων τῶν κατ’ ἐκεῖνον τὸν χρόνον γενομένων, Λακεδαίμων δὲ Μενέλαον τὸν διὰ σωφροσύνην καὶ δικαιοσύνην μόνον ἀξιωθέντα Διὸς γενέσθαι κηδεστήν, ἡ δ’ Ἀργείων πόλις Ἀγαμέμνονα τὸν οὐ μίαν οὐδὲ δύο σχόντα μόνον ἀρετάς, ἀλλὰ πάσας ὅσας ἂν ἔχοι τις εἰπεῖν,", "st": "12.72"}, {"sp": "N", "t": "καὶ ταύτας οὐ μετρίως ἀλλ’ ὑπερβαλλόντως· οὐδένα γὰρ εὑρήσομεν τῶν ἁπάντων οὔτ’ ἰδιωτέρας πράξεις μεταχειρισάμενον οὔτε καλλίους οὔτε μείζους οὔτε τοῖς Ἕλλησιν ὠφελιμωτέρας οὔτε πλειόνων ἐπαίνων ἀξίας. καὶ τούτοις οὕτω μὲν ἀπηριθμημένοις εἰκότως ἄν τινες ἀπιστήσειαν, μικρῶν δὲ περὶ ἑκάστου ῥηθέντων ἅπαντες ἂν ἀληθῆ με λέγειν ὁμολογήσειαν.", "st": "12.73"}, {"sp": "N", "t": "οὐ δύναμαι δὲ κατιδεῖν, ἀλλ’ ἀπορῶ ποίοις ἂν λόγοις μετὰ ταῦτα χρησάμενος ὀρθῶς εἴην βεβουλευμένος. αἰσχύνομαι μὲν γάρ, εἰ τοσαῦτα περὶ τῆς Ἀγαμέμνονος ἀρετῆς προειρηκὼς μηδενὸς μνησθήσομαι τῶν ὑπ’ ἐκείνου πεπραγμένων, ἀλλὰ δόξω τοῖς ἀκούουσιν ὅμοιος εἶναι τοῖς ἀλαζονευομένοις καὶ λέγουσιν ὅ τι ἂν τύχωσιν· ὁρῶ δὲ τὰς πράξεις τὰς ἔξω λεγομένας τῶν ὑποθέσεων οὐκ ἐπαινουμένας ἀλλὰ ταραχώδεις εἶναι δοκούσας, καὶ πολλοὺς μὲν ὄντας τοὺς κακῶς χρωμένους αὐταῖς,", "st": "12.74"}, {"sp": "N", "t": "πολὺ δὲ πλείους τοὺς ἐπιτιμῶντας. διὸ δέδοικα μὴ καὶ περὶ ἐμὲ συμβῇ τι τοιοῦτον. οὐ μὴν ἀλλ’ αἱροῦμαι βοηθῆσαι τῷ ταὐτὸν ἐμοί τε καὶ πολλοῖς πεπονθότι, καὶ διημαρτηκότι τῆς δόξης ἧς προσῆκε τυχεῖν αὐτόν, καὶ μεγίστων μὲν ἀγαθῶν αἰτίῳ γεγενημένῳ περὶ ἐκεῖνον τὸν χρόνον, ἧττον δ’ ἐπαινουμένῳ τῶν οὐδὲν ἄξιον λόγου διαπεπραγμένων.", "st": "12.75"}, {"sp": "N", "t": "τί γὰρ ἐκεῖνος ἐνέλιπεν, ὃς τηλικαύτην μὲν ἔσχε τιμήν, ἧς εἰ πάντες συνελθόντες μείζω ζητοῖεν, οὐδέποτ’ ἂν εὑρεῖν δυνηθεῖεν; μόνος γὰρ ἁπάσης τῆς Ἑλλάδος ἠξιώθη γενέσθαι στρατηγός. ὁπότερον δέ, εἴθ’ ὑπὸ πάντων αἱρεθεὶς εἴτ’ αὐτὸς κτησάμενος, οὐκ ἔχω λέγειν. ὁποτέρως δ’ οὖν συμβέβηκεν, οὐδεμίαν ὑπερβολὴν λέλοιπε τῆς περὶ αὑτὸν δόξης τοῖς ἄλλως πως τιμηθεῖσιν.", "st": "12.76"}, {"sp": "N", "t": "ταύτην δὲ λαβὼν τὴν δύναμιν οὐκ ἔστιν ἥν τινα τῶν Ἑλληνίδων πόλεων ἐλύπησεν, ἀλλ’ οὕτως ἦν πόρρω τοῦ περί τινας ἐξαμαρτεῖν, ὥστε παραλαβὼν τοὺς Ἕλληνας ἐν πολέμῳ καὶ ταραχαῖς καὶ πολλοῖς κακοῖς ὄντας τούτων μὲν αὐτοὺς ἀπήλλαξεν, εἰς ὁμόνοιαν δὲ καταστήσας τὰ μὲν περιττὰ τῶν ἔργων καὶ τερατώδη καὶ μηδὲν ὠφελοῦντα τοὺς ἄλλους ὑπερεῖδε, στρατόπεδον δὲ συστήσας ἐπὶ τοὺς βαρβάρους ἤγαγεν.", "st": "12.77"}, {"sp": "N", "t": "τούτου δὲ κάλλιον στρατήγημα καὶ τοῖς Ἕλλησιν ὠφελιμώτερον οὐδεὶς φανήσεται πράξας οὔτε τῶν κατ’ ἐκεῖνον τὸν χρόνον εὐδοκιμησάντων οὔτε τῶν ὕστερον ἐπιγενομένων. ἃ ’κεῖνος πράξας καὶ τοῖς ἄλλοις ὑποδείξας οὐχ οὕτως εὐδοκίμησεν, ὡς προσῆκεν αὐτόν, διὰ τοὺς μᾶλλον ἀγαπῶντας τὰς θαυματοποιίας τῶν εὐεργεσιῶν καὶ τὰς ψευδολογίας τῆς ἀληθείας, ἀλλὰ τοιοῦτος γενόμενος ἐλάττω δόξαν ἔχει τῶν οὐδὲ μιμήσασθαι τολμησάντων αὐτόν.", "st": "12.78"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐπὶ τούτοις ἄν τις ἐπαινέσειεν αὐτόν, ἀλλὰ καὶ ἐφ’ οἷς περὶ τὸν αὐτὸν χρόνον ἔπραξεν. εἰς τοῦτο γὰρ μεγαλοφροσύνης ἦλθεν, ὥστ’ οὐκ ἀπέχρησεν αὐτῷ λαβεῖν στρατιώτας τῶν ἰδιωτῶν ὁπόσους ἐξ ἑκάστης ἐβουλήθη τῆς πόλεως, ἀλλὰ τοὺς βασιλεῖς τοὺς ποιοῦντας ἐν ταῖς αὑτῶν ὅ τι βουληθεῖεν καὶ τοῖς ἄλλοις προστάττοντας, τούτους ἔπεισεν ὑφ’ αὑτῷ γενέσθαι, καὶ συνακολουθεῖν ἐφ’ οὓς ἂν ἡγῆται, καὶ ποιεῖν τὸ προσταττόμενον, καὶ βασιλικὸν βίον ἀφέντας στρατιωτικῶς ζῆν,", "st": "12.79"}, {"sp": "N", "t": "ἔτι δὲ κινδυνεύειν καὶ πολεμεῖν οὐχ ὑπὲρ τῆς σφετέρας αὐτῶν πατρίδος καὶ βασιλείας, ἀλλὰ λόγῳ μὲν ὑπὲρ Ἑλένης τῆς Μενελάου γυναικός, ἔργῳ δ’ ὑπὲρ τοῦ μὴ τὴν Ἑλλάδα πάσχειν ὑπὸ τῶν βαρβάρων μήτε τοιαῦτα μήθ’ οἷα πρότερον αὐτῇ συνέπεσε περὶ τὴν Πέλοπος μὲν ἁπάσης Πελοποννήσου κατάληψιν, Δαναοῦ δὲ τῆς πόλεως τῆς Ἀργείων, Κάδμου δὲ Θηβῶν· ὧν τίς ἄλλος φανήσεται προνοηθείς, ἢ τίς ἐμποδὼν καταστὰς τοῦ μηδὲν ἔτι γενέσθαι τοιοῦτον, πλὴν τῆς ἐκείνου φύσεως καὶ δυνάμεως;", "st": "12.80"}, {"sp": "N", "t": "τὸ τοίνυν ἐχόμενον, ὃ τῶν μὲν προειρημένων ἔλαττόν ἐστι, τῶν δὲ πολλάκις ἐγκεκωμιασμένων μεῖζον καὶ λόγου μᾶλλον ἄξιον· στρατόπεδον γὰρ συνεληλυθὸς ἐξ ἁπασῶν τῶν πόλεων, τοσοῦτον τὸ πλῆθος ὅσον εἰκός, ὃ πολλοὺς εἶχεν ἐν αὑτῷ τοὺς μὲν ἀπὸ θεῶν τοὺς δ’ ἐξ αὐτῶν τῶν θεῶν γεγονότας, οὐκ ὁμοίως διακειμένους τοῖς πολλοῖς οὐδ’ ἴσον φρονοῦντας τοῖς ἄλλοις, ἀλλ’ ὀργῆς καὶ θυμοῦ καὶ φθόνου καὶ φιλοτιμίας μεστούς,", "st": "12.81"}, {"sp": "N", "t": "ἀλλ’ ὅμως τὸ τοιοῦτον ἔτη δέκα κατέσχεν οὐ μισθοφοραῖς μεγάλαις οὐδὲ χρημάτων δαπάναις, αἷς νῦν ἅπαντες δυναστεύουσιν, ἀλλὰ τῷ καὶ τῇ φρονήσει διαφέρειν καὶ δύνασθαι τροφὴν ἐκ τῶν πολεμίων τοῖς στρατιώταις πορίζειν, καὶ μάλιστα τῷ δοκεῖν ἐκεῖνον ἄμεινον ὑπὲρ τῆς τῶν ἄλλων βουλεύεσθαι σωτηρίας ἢ τοὺς ἄλλους περὶ σφῶν αὐτῶν.", "st": "12.82"}, {"sp": "N", "t": "τὸ τοίνυν τέλος, ὃ πᾶσι τούτοις ἐπέθηκεν, οὐδενὸς ἧττον προσήκει θαυμάζειν· οὐ γὰρ ἀπρεπὲς οὐδ’ ἀνάξιον τῶν προειρημένων φανήσεται ποιησάμενος, ἀλλὰ λόγῳ μὲν πρὸς μίαν πόλιν πολεμήσας, ἔργῳ δ’ οὐ μόνον πρὸς ἅπαντας τοὺς τὴν Ἀσίαν κατοικοῦντας ἀλλὰ καὶ πρὸς ἄλλα γένη πολλὰ τῶν βαρβάρων κινδυνεύων οὐκ ἀπεῖπεν οὐδ’ ἀπῆλθε, πρὶν τήν τε πόλιν τοῦ τολμήσαντος ἐξαμαρτεῖν ἐξηνδραποδίσατο καὶ τοὺς βαρβάρους ἔπαυσεν ὑβρίζοντας.", "st": "12.83"}, {"sp": "N", "t": "οὐκ ἀγνοῶ δὲ τὸ πλῆθος τῶν εἰρημένων περὶ τῆς Ἀγαμέμνονος ἀρετῆς, οὐδ’ ὅτι τούτων καθ’ ἓν μὲν ἕκαστον εἴ τινες σκοποῖντο τί ἂν ἀποδοκιμάσαιεν, οὐδεὶς ἂν οὐδὲν αὐτῶν ἀφελεῖν τολμήσειεν, ἐφεξῆς δὲ ἀναγιγνωσκομένων ἅπαντες ἂν ἐπιτιμήσαιεν ὡς πολὺ πλείοσιν εἰρημένοις τοῦ δέοντος. ἐγὼ δ’ εἰ μὲν ἔλαθον ἐμαυτὸν πλεονάζων,", "st": "12.84"}, {"sp": "N", "t": "ᾐσχυνόμην ἄν, εἰ γράφειν ἐπιχειρῶν περὶ ὧν μηδεὶς ἂν ἄλλος ἐτόλμησεν, οὕτως ἀναισθήτως διεκείμην· νῦν δ’ ἀκριβέστερον ᾔδειν τῶν ἐπιπλήττειν μοι τολμησόντων, ὅτι πολλοὶ τούτοις ἐπιτιμήσουσιν· ἀλλὰ γὰρ ἡγησάμην οὐχ οὕτως ἔσεσθαι δεινόν, ἢν ἐπὶ τοῦ μέρους τούτου δόξω τισὶ τῶν καιρῶν ἀμελεῖν, ὡς ἢν περὶ ἀνδρὸς τοιούτου διαλεγόμενος παραλίπω τι τῶν ἐκείνῳ τε προσόντων ἀγαθῶν κἀμοὶ προσηκόντων εἰπεῖν.", "st": "12.85"}, {"sp": "N", "t": "ᾤμην δὲ καὶ παρὰ τοῖς χαριεστάτοις τῶν ἀκροατῶν εὐδοκιμήσειν, ἢν φαίνωμαι περὶ ἀρετῆς μὲν τοὺς λόγους ποιούμενος, ὅπως δὲ ταύτης ἀξίως ἐρῶ μᾶλλον σπουδάζων ἢ περὶ τὴν τοῦ λόγου συμμετρίαν, καὶ ταῦτα σαφῶς εἰδὼς τὴν μὲν περὶ τὸν λόγον ἀκαιρίαν ἀδοξότερον ἐμὲ ποιήσουσαν, τὴν δὲ περὶ τὰς πράξεις εὐβουλίαν αὐτοὺς τοὺς ἐπαινουμένους ὠφελήσουσαν· ἀλλ’ ὅμως ἐγὼ τὸ λυσιτελὲς ἐάσας τὸ δίκαιον εἱλόμην.", "st": "12.86"}, {"sp": "N", "t": "οὐ μόνον δ’ ἂν εὑρεθείην ἐπὶ τοῖς νῦν λεγομένοις ταύτην ἔχων τὴν διάνοιαν, ἀλλ’ ὁμοίως ἐπὶ πάντων, ἐπεὶ καὶ τῶν πεπλησιακότων μοι φανείην ἂν μᾶλλον χαίρων τοῖς ἐπὶ τῷ βίω καὶ ταῖς πράξεσιν εὐδοκιμοῦσιν ἢ τοῖς περὶ τοὺς λόγους δεινοῖς εἶναι δοκοῦσιν. καίτοι τῶν μὲν εὖ ῥηθέντων, εἰ καὶ μηδὲν συμβαλοίμην, ἅπαντες ἂν ἐμοὶ τὴν αἰτίαν ἀναθεῖεν, τῶν δ’ ὀρθῶς πραττομένων εἰ καὶ πάντες εἰδεῖέν με σύμβουλον γεγενημένον, οὐδεὶς ὅστις οὐκ ἂν αὐτὸν τὸν μεταχειριζόμενον τὰς πράξεις ἐπαινέσειεν.", "st": "12.87"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ οἶδ’ ὅποι τυγχάνω φερόμενος· ἀεὶ γὰρ οἰόμενος δεῖν προστιθέναι τὸ τῶν προειρημένων ἐχόμενον, παντάπασι πόρρω γέγονα τῆς ὑποθέσεως. λοιπὸν οὖν ἐστιν οὐδὲν ἄλλο, πλὴν αἰτησάμενον τῷ γήρᾳ συγγνώμην ὑπὲρ τῆς λήθης καὶ τῆς μακρολογίας, τῶν εἰθισμένων παραγίγνεσθαι τοῖς τηλικούτοις, ἐπανελθεῖν εἰς τὸν τόπον ἐκεῖνον ἐξ οὗπερ εἰσέπεσον εἰς τὴν περιττολογίαν ταύτην.", "st": "12.88"}, {"sp": "N", "t": "οἶμαι δ’ ἤδη καθορᾶν ὅθεν ἐπλανήθην· τοῖς γὰρ ὀνειδίζουσιν ἡμῶν τῇ πόλει τὰς Μηλίων καὶ τὰς τῶν τοιούτων πολιχνίων συμφορὰς ἀντέλεγον, οὐχ ὡς οὐχ ἡμαρτημένων τούτων, ἀλλ’ ἐπιδεικνύων τοὺς ἀγαπωμένους ὑπ’ αὐτῶν πολὺ πλείους πόλεις καὶ μείζους ἡμῶν ἀναστάτους πεποιηκότας, ἐν οἷς καὶ περὶ τῆς ἀρετῆς τῆς Ἀγαμέμνονος καὶ Μενελάου καὶ Νέστορος διελέχθην, ψεῦδος μὲν οὐδὲν λέγων, πλείω δ’ ἴσως τῶν μετρίων.", "st": "12.89"}, {"sp": "N", "t": "τοῦτο δ’ ἐποίουν ὑπολαβὼν οὐδενὸς ἔλαττον ἁμάρτημα τοῦτο δόξειν εἶναι τῶν τολμησάντων ἀναστάτους ποιῆσαι τὰς πόλεις τὰς γεννησάσας καὶ θρεψάσας τοιούτους ἄνδρας, περὶ ὧν καὶ νῦν ἔχοι τις ἂν πολλοῖς καὶ καλοῖς χρήσασθαι λόγοις. ἀλλὰ γὰρ ἴσως ἀνόητόν ἐστι περὶ μίαν πρᾶξιν διατρίβειν, ὥσπερ ἀπορίας οὔσης τί ἂν ἔχοι τις εἰπεῖν περὶ τῆς ὠμότητος καὶ χαλεπότητος τῆς Λακεδαιμονίων, ἀλλ’ οὐ πολλῆς ἀφθονίας ὑπαρχούσης.", "st": "12.90"}, {"sp": "N", "t": "οἷς οὐκ ἐξήρκεσε περὶ τὰς πόλεις ταύτας καὶ τοὺς ἄνδρας τοὺς τοιούτους ἐξαμαρτεῖν, ἀλλὰ καὶ περὶ τοὺς ἐκ τῶν αὐτῶν ὁρμηθέντας καὶ κοινὴν τὴν στρατείαν ποιησαμένους καὶ τῶν αὐτῶν κινδύνων μετασχόντας, λέγω δὲ περὶ Ἀργείων καὶ Μεσσηνίων. καὶ γὰρ τούτους ἐπεθύμησαν ταῖς αὐταῖς συμφοραῖς περιβαλεῖν αἷσπερ ἐκείνους· καὶ Μεσσηνίους μὲν πολιορκοῦντες οὐ πρότερον ἐπαύσαντο, πρὶν ἐξέβαλον ἐκ τῆς χώρας, Ἀργείοις δ’ ὑπὲρ τῶν αὐτῶν τούτων ἔτι καὶ νῦν πολεμοῦσιν. ἃ τοίνυν περὶ Πλαταιᾶς ἔπραξαν,", "st": "12.91"}, {"sp": "N", "t": "ἄτοπος ἂν εἴην, εἰ ταῦτ’ εἰρηκὼς ἐκείνων μὴ μνησθείην· ὧν ἐν τῇ χώρᾳ στρατοπεδευσάμενοι μεθ’ ἡμῶν καὶ τῶν ἄλλων συμμάχων, καὶ παραταξάμενοι τοῖς πολεμίοις, καὶ θυσάμενοι τοῖς θεοῖς τοῖς ὑπ’ ἐκείνων ἱδρυμένοις,", "st": "12.92"}, {"sp": "N", "t": "οὐ μόνον ἠλευθερώσαμεν τῶν Ἑλλήνων τοὺς μεθ’ ἡμῶν ὄντας ἀλλὰ καὶ τοὺς ἀναγκασθέντας γενέσθαι μετ’ ἐκείνων, καὶ ταῦτ’ ἐπράξαμεν Πλαταιέας λαβόντες μόνους Βοιωτῶν συναγωνιστάς· οὓς οὐ πολὺν χρόνον διαλιπόντες Λακεδαιμόνιοι, χαριζόμενοι Θηβαίοις, ἐκπολιορκήσαντες ἅπαντας ἀπέκτειναν πλὴν τῶν ἀποδρᾶναι δυνηθέντων. περὶ οὓς ἡ πόλις ἡμῶν οὐδὲν ὁμοία γέγονεν ἐκείνοις·", "st": "12.93"}, {"sp": "N", "t": "οἱ μὲν γὰρ περὶ τε τοὺς εὐεργέτας τῆς Ἑλλάδος καὶ τοὺς συγγενεῖς τοὺς αὑτῶν τὰ τοιαῦτ’ ἐξαμαρτάνειν ἐτόλμησαν, οἱ δ’ ἡμέτεροι Μεσσηνίων μὲν τοὺς διασωθέντας εἰς Ναύπακτον κατῴκισαν, Πλαταιέων δὲ τοὺς περιγενομένους πολίτας ἐποιήσαντο καὶ τῶν ὑπαρχόντων αὐτοῖς ἁπάντων μετέδοσαν. ὥστ’ εἰ μηδὲν εἴχομεν ἄλλο περὶ τοῖν πολέοιν εἰπεῖν, ἐκ τούτων ῥᾴδιον εἶναι καταμαθεῖν τὸν τρόπον ἑκατέρας αὐτῶν, καὶ ποτέρα πλείους πόλεις καὶ μείζους ἀναστάτους πεποίηκεν.", "st": "12.94"}, {"sp": "N", "t": "αἰσθάνομαι δὲ πάθος μοι συμβαῖνον ἐναντίον τοῖς ὀλίγῳ πρότερον εἰρημένοις· τότε μὲν γὰρ εἰς ἄγνοιαν καὶ πλάνον καὶ λήθην ἐνέπεσον, νῦν δ’ οἶδα σαφῶς ἐμαυτὸν οὐκ ἐμμένοντα τῇ πραότητι τῇ περὶ τὸν λόγον, ἣν εἶχον ὅτ’ ἠρχόμην γράφειν αὐτόν, ἀλλὰ λέγειν τ’ ἐπιχειροῦντα περὶ ὧν οὐκ ᾤμην ἐρεῖν, θρασύτερόν τε διακείμενον ἢ κατ’ ἐμαυτόν, ἀκρατῆ τε γιγνόμενον ἐνίων ὧν λέγω διὰ τὸ πλῆθος τῶν εἰπεῖν ἐπιρρεόντων.", "st": "12.95"}, {"sp": "N", "t": "ἐπειδή περ οὖν ἐπελήλυθέ μοι τὸ παρρησιάζεσθαι, καὶ λέλυκα τὸ στόμα, καὶ τοιαύτην τὴν ὑπόθεσιν ἐποιησάμην ὥστε μήτε καλὸν εἶναί μοι μήτε δυνατὸν παραλιπεῖν τὰς τοιαύτας πράξεις, ἐξ ὧν οἷόν τ’ ἐστὶν ἐπιδεικνύναι πλέονος ἀξίαν τὴν πόλιν ἡμῶν γεγενημένην περὶ τοὺς Ἕλληνας τῆς Λακεδαιμονίων, οὐ κατασιωπητέον οὐδὲ περὶ τῶν ἄλλων κακῶν τῶν οὔπω μὲν εἰρημένων ἐν δὲ τοῖς Ἕλλησι γεγενημένων, ἀλλ’ ἐπιδεικτέον τοὺς μὲν ἡμετέρους ὀψιμαθεῖς αὐτῶν γεγενημένους, Λακεδαιμονίους δὲ τὰ μὲν πρώτους τὰ δὲ μόνους ἐξαμαρτόντας.", "st": "12.96"}, {"sp": "N", "t": "πλεῖστοι μὲν οὖν κατηγοροῦσιν ἀμφοῖν τοῖν πολέοιν, ὅτι προσποιούμεναι κινδυνεῦσαι πρὸς τοὺς βαρβάρους ὑπὲρ τῶν Ἑλλήνων οὐκ εἴασαν τὰς πόλεις αὐτονόμους εἶναι καὶ διοικῆσαι τὰ σφέτερ’ αὐτῶν ὅπως ἑκάστῃ συνέφερεν, ἀλλ’ ὥσπερ αἰχμαλώτους εἰληφυῖαι διελόμεναι κατεδουλώσαντο πάσας αὐτάς, καὶ παραπλήσιον ἐποίησαν τοῖς παρὰ μὲν τῶν ἄλλων τοὺς οἰκέτας εἰς ἐλευθερίαν ἀφαιρουμένοις, σφίσι δ’ αὐτοῖς δουλεύειν ἀναγκάζουσιν.", "st": "12.97"}, {"sp": "N", "t": "τοῦ δὲ λέγεσθαι ταῦτα καὶ πολὺ πλείω καὶ πικρότερα τούτων οὐχ ἡμεῖς αἴτιοι γεγόναμεν, ἀλλ’ οἱ νῦν μὲν ἐν τοῖς λεγομένοις ἡμῖν ἀντιτεταγμένοι, τὸν δ’ ἄλλον χρόνον ἐν τοῖς πραττομένοις ἅπασιν. τοὺς μὲν γὰρ ἡμετέρους προγόνους οὐδεὶς ἂν ἐπιδείξειεν ἐν τοῖς ἐπέκεινα χρόνοις τοῖς ἀναριθμήτοις οὐδεμιᾶς πόλεως οὔτε μείζονος οὔτ’ ἐλάττονος ἄρχειν ἐπιχειρήσαντας· Λακεδαιμονίους δὲ πάντες ἴσασιν, ἀφ’ οὗ περ εἰς Πελοπόννησον εἰσῆλθον, οὐδὲν ἄλλο πράττοντας οὐδὲ βουλευομένους πλὴν ὅπως μάλιστα μὲν ἁπάντων ἄρξουσιν, εἰ δὲ μή, Πελοποννησίων.", "st": "12.98"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τὰς στάσεις καὶ τὰς σφαγὰς καὶ τὰς τῶν πολιτειῶν μεταβολάς, ἃς ἀμφοτέροις τινὲς ἡμῖν ἐπιφέρουσιν, ἐκεῖνοι μὲν ἂν φανεῖεν ἁπάσας τὰς πόλεις πλὴν ὀλίγων μεστὰς πεποιηκότες τῶν τοιούτων συμφορῶν καὶ νοσημάτων, τὴν δ’ ἡμετέραν πόλιν οὐδεὶς ἂν οὐδ’ εἰπεῖν τολμήσειε πρὸ τῆς ἀτυχίας τῆς ἐν Ἑλλησπόντῳ γενομένης ὡς τοιοῦτον ἐν τοῖς συμμάχοις τι διαπραξαμένην.", "st": "12.99"}, {"sp": "N", "t": "ἄλλ’ ἐπειδὴ Λακεδαιμόνιοι κύριοι καταστάντες τῶν Ἑλλήνων πάλιν ἐξέπιπτον ἐκ τῶν πραγμάτων, ἐν τούτοις τοῖς καιροῖς στασιαζουσῶν τῶν ἄλλων, πόλεων δύ’ ἢ τρεῖς τῶν στρατηγῶν τῶν ἡμετέρων, οὐ γὰρ ἀποκρύψομαι τἀληθές, ἐξήμαρτον περί τινας αὐτῶν ἐλπίζοντες, ἢν μιμήσωνται τὰς Σπαρτιατῶν πράξεις, μᾶλλον αὐτὰς δυνήσεσθαι κατασχεῖν.", "st": "12.100"}, {"sp": "N", "t": "ὥστε δικαίως ἂν ἐκείνοις μὲν ἅπαντες ἐγκαλέσειαν ὡς ἀρχηγοῖς γεγενημένοις καὶ διδασκάλοις τῶν τοιούτων ἔργων, τοῖς δ’ ἡμετέροις, ὥσπερ τῶν μαθητῶν τοῖς ὑπὸ τῶν ὑπισχνουμένων ἐξηπατημένοις καὶ διημαρτηκόσι τῶν ἐπίδων, εἰκότως ἂν συγγνώμην ἔχοιεν.", "st": "12.101"}, {"sp": "N", "t": "τὸ τοίνυν τελευταῖον, ὃ μόνοι καὶ καθ’ αὑτοὺς ἔπραξαν, τίς οὐκ οἶδεν ὅτι κοινῆς ἡμῖν τῆς ἔχθρας ὑπαρχούσης, τῆς πρὸς τοὺς βαρβάρους καὶ τοὺς βασιλέας αὐτῶν, ἡμεῖς μὲν ἐν πολέμοις πολλοῖς γιγνόμενοι καὶ μεγάλαις συμφοραῖς ἐνίοτε περιπίπτοντες καὶ τῆς χώρας ἡμῶν θαμὰ πορθουμένης καὶ τεμνομένης οὐδεπώποτ’ ἐβλέψαμεν πρὸς τὴν ἐκείνων φιλίαν καὶ συμμαχίαν, ἀλλ’ ὑπὲρ ὧν τοῖς Ἕλλησιν ἐπεβούλευσαν μισοῦντες αὐτοὺς διετελέσαμεν μᾶλλον ἢ τοὺς ἐν τῷ παρόντι κακῶς ἡμᾶς ποιοῦντας·", "st": "12.102"}, {"sp": "N", "t": "Λακεδαιμόνιοι δ’ οὔτε πάσχοντες κακὸν οὐδὲν οὔτε μέλλοντες οὔτε δεδιότες εἰς τοῦτ’ ἀπληστίας ἦλθον, ὥστ’ οὐκ ἐξήρκεσεν αὐτοῖς ἔχειν τὴν κατὰ γῆν ἀρχήν, ἀλλὰ καὶ τὴν κατὰ θάλατταν δύναμιν οὕτως ἐπεθύμησαν λαβεῖν, ὥστε κατὰ τοὺς αὐτοὺς χρόνους τούς τε συμμάχους τοὺς ἡμετέρους ἀφίστασαν, ἐλευθερώσειν αὐτοὺς ὑπισχνούμενοι, καὶ βασιλεῖ περὶ φιλίας διελέγοντο καὶ συμμαχίας, παραδώσειν αὐτῷ φάσκοντες ἅπαντας τοὺς ἐπὶ τῆς Ἀσίας κατοικοῦντας,", "st": "12.103"}, {"sp": "N", "t": "πίστεις δὲ δόντες τούτοις ἀμφοτέροις καὶ καταπολεμήσαντες ἡμᾶς, οὓς μὲν ἐλευθερώσειν ὤμοσαν, κατεδουλώσαντο μᾶλλον ἢ τοὺς Εἵλωτας, βασιλεῖ δὲ τοιαύτην χάριν ἀπέδοσαν ὥστ’ ἔπεισαν τὸν ἀδελφὸν αὐτοῦ Κῦρον ὄντα νεώτερον ἀμφισβητεῖν τῆς βασιλείας, καὶ στρατόπεδον αὐτῷ συναγαγόντες καὶ στρατηγὸν Κλέαρχον ἐπιστήσαντες ἀνέπεμψαν ἐπ’ ἐκεῖνον·", "st": "12.104"}, {"sp": "N", "t": "ἀτυχήσαντες δ’ ἐν τούτοις καὶ γνωσθέντες ὧν ἐπεθύμουν, καὶ μισηθέντες ὑπὸ πάντων, εἰς πόλεμον καὶ ταραχὰς τοσαύτας κατέστησαν ὅσας εἰκὸς τοὺς καὶ περὶ τοὺς Ἕλληνας καὶ τοὺς βαρβάρους ἐξημαρτηκότας. περὶ ὧν οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγοντα διατρίβειν, πλὴν ὅτι καταναυμαχηθέντες ὑπό τε τῆς βασιλέως δυνάμεως καὶ τῆς Κόνωνος στρατηγίας τοιαύτην ἐποιήσαντο τὴν εἰρήνην,", "st": "12.105"}, {"sp": "N", "t": "ἧς οὐδεὶς ἂν ἐπιδείξειεν οὔτ’ αἰσχίω πώποτε γενομένην οὔτ’ ἐπονειδιστοτέραν οὔτ’ ὀλιγωροτέραν τῶν Ἑλλήνων οὔτ’ ἐναντιωτέραν τοῖς λεγομένοις ὑπό τινων περὶ τῆς ἀρετῆς τῆς Λακεδαιμονίων· οἵ τινες, ὅτε μὲν αὐτοὺς ὁ βασιλεὺς δεσπότας τῶν Ἑλλήνων κατέστησεν, ἀφελέσθαι τὴν βασιλείαν αὐτοῦ καὶ τὴν εὐδαιμονίαν ἅπασαν ἐπεχείρησαν, ἐπειδὴ δὲ καταναυμαχήσας ταπεινοὺς ἐποίησεν, οὐ μικρὸν μέρος αὐτῷ τῶν Ἑλλήνων παρέδωκαν ἀλλὰ πάντας τοὺς τὴν Ἀσίαν οἰκοῦντας, διαρρήδην γράψαντες χρῆσθαι τοῦθ’ ὅ τι ἂν αὐτὸς βούληται,", "st": "12.106"}, {"sp": "N", "t": "καὶ οὐκ ᾐσχύνθησαν τοιαύτας ποιούμενοι τὰς ὁμολογίας περὶ ἀνδρῶν, οἷς χρώμενοι συμμάχοις ἡμῶν τε περιεγένοντο καὶ τῶν Ἑλλήνων κύριοι κατέστησαν καὶ τὴν Ἀσίαν ἅπασαν ἤλπισαν κατασχήσειν, ἀλλὰ τὰς τοιαύτας συνθήκας αὐτοί τ’ ἐν τοῖς ἱεροῖς τοῖς σφετέροις αὐτῶν ἀνέγραψαν καὶ τοὺς συμμάχους ἠνάγκασαν.", "st": "12.107"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους οὐκ οἴομαι πράξεων ἑτέρων ἐπιθυμήσειν ἀκούειν, ἀλλ’ ἐκ τῶν εἰρημένων ἱκανῶς μεμαθηκέναι νομιεῖν ὁποία τις τοῖν πολέοιν ἑκατέρα περὶ τοὺς Ἕλληνας γέγονεν· ἐγὼ δ’ οὐχ οὕτω τυγχάνω διακείμενος, ἀλλ’ ἡγοῦμαι τὴν ὑπόθεσιν ἣν ἐποιησάμην ἄλλων τε πολλῶν προσδεῖσθαι λόγων, καὶ μάλιστα τῶν ἐπιδειξόντων τὴν ἄνοιαν τῶν ἀντιλὲγειν τοῖς εἰρημένοις ἐπιχειρησόντων· οὓς οἴομαι ῥᾳδίως εὑρήσειν.", "st": "12.108"}, {"sp": "N", "t": "τῶν γὰρ ἀποδεχομένων ἁπάσας τὰς Λακεδαιμονίων πράξεις, τοὺς μὲν βελτίστους αὐτῶν ἡγοῦμαι καὶ πλεῖστον νοῦν ἔχοντας τὴν μὲν Σπαρτιατῶν πολιτείαν ἐπαινέσεσθαι καὶ τὴν αὐτὴν γνώμην ἕξειν περὶ αὐτῆς ἥνπερ πρότερον, περὶ δὲ τῶν εἰς τοὺς Ἕλληνας πεπραγμένων ὁμονοήσειν τοῖς ὑπ’ ἐμοῦ λεγομένοις,", "st": "12.109"}, {"sp": "N", "t": "τοὺς δὲ φαυλοτέρους οὐ μόνον τούτων ὄντας ἀλλὰ καὶ τῶν πολλῶν, καὶ περὶ ἄλλου πράγματος οὐδενὸς ἂν οἵους τε γενομένους ἀνεκτῶς εἰπεῖν, περὶ δὲ Λακεδαιμονίων οὐ δυναμένους σιωπᾶν, ἀλλὰ προσδοκῶντας, ἢν ὑπερβάλλοντας τοὺς ἐπαίνους περὶ ἐκείνων ποιῶνται, τὴν αὐτὴν λήψεσθαι δόξαν τοῖς ἁδροτέροις αὐτῶν καὶ πολὺ βελτίοσιν εἶναι δοκοῦσι· τοὺς δὴ τοιούτους,", "st": "12.110"}, {"sp": "N", "t": "ἐπειδὰν αἴσθωνται τοὺς τόπους ἅπαντας προκατειλημμένους καὶ μηδὲ πρὸς ἓν ἀντειπεῖν ἔχωσι τῶν εἰρημένων, ἐπὶ τὸν λόγον οἶμαι τρέψεσθαι τὸν περὶ τῶν πολιτειῶν, καὶ παραβάλλοντας τἀκεῖ καθεστῶτα τοῖς ἐνθάδε, καὶ μάλιστα τὴν σωφροσύνην καὶ πειθαρχίαν πρὸς τὰς παρ’ ἡμῖν ὀλιγωρίας, ἐκ τούτων ἐγκωμιάσειν τὴν Σπάρτην.", "st": "12.111"}, {"sp": "N", "t": "ἢν δὴ τοιοῦτον ἐπιχειρῶσί τι ποιεῖν, προσήκει τοὺς εὖ φρονοῦντας ληρεῖν νομίζειν αὐτούς. ἐγὼ γὰρ ὑπεθέμην οὐχ ὡς περὶ τῶν πολιτειῶν διαλεξόμενος, ἀλλ’ ὡς ἐπιδείξων τὴν πόλιν ἡμῶν πολὺ πλείονος ἀξίαν Λακεδαιμονίων περὶ τοὺς Ἕλληνας γεγενημένην. ἢν μὲν οὖν ἀναιρῶσί τι τούτων, ἢ πράξεις ἑτέρας κοινὰς λέγωσι περὶ ἃς ἐκεῖνοι βελτίους ἡμῶν γεγόνασιν, εἰκότως ἂν ἐπαίνου τυγχάνοιεν· ἢν δὲ λέγειν ἐπιχειρῶσι περὶ ὧν ἐγὼ μηδεμίαν μνείαν ποιησαίμην, δικαίως ἂν ἅπασιν ἀναισθήτως ἔχειν δοκοῖεν.", "st": "12.112"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐπειδή περ αὐτοὺς οἴομαι τὸν λόγον τὸν περὶ τῶν πολιτειῶν εἰς τὸ μέσον ἐμβαλεῖν, οὐκ ὀκνήσω διαλεχθῆναι περὶ αὐτῶν· οἶμαι γὰρ ἐν αὐτοῖς τούτοις τὴν πόλιν ἡμῶν ἐπιδείξειν πλέον διενεγκοῦσαν ἢ τοῖς ἤδη προειρημένοις.", "st": "12.113"}, {"sp": "N", "t": "καὶ μηδεὶς ὑπολάβῃ με ταῦτ’ εἰρηκέναι περὶ ταύτης, ἣν ἀναγκασθέντες μετελάβομεν, ἀλλὰ περὶ τῆς τῶν προγόνων, ἧς οὐ καταφρονήσαντες οἱ πατέρες ἡμῶν ἐπὶ τὴν νῦν καθεστῶσαν ὥρμησαν, ἀλλὰ περὶ μὲν τὰς ἄλλας πράξεις πολὺ σπουδαιοτέραν ἐκείνην προκρίναντες, περὶ δὲ τὴν δύναμιν τὴν κατὰ θάλατταν ταύτην χρησιμωτέραν εἶναι νομίζοντες, ἣν λαβόντες καὶ καλῶς ἐπιμεληθέντες οἷοί τ’ ἐγένοντο καὶ τὰς ἐπιβουλὰς τὰς Σπαρτιατῶν ἀμύνασθαι καὶ τὴν Πελοποννησίων ἁπάντων ῥώμην, ὧν κατήπειγε τὴν πόλιν περὶ ἐκεῖνον τὸν χρόνον μάλιστα περιγενέσθαι πολεμοῦσαν.", "st": "12.114"}, {"sp": "N", "t": "ὥστ’ οὐδεὶς ἂν δικαίως ἐπιτιμήσειε τοῖς ἑλομένοις αὐτήν· οὐ γὰρ διήμαρτον τῶν ἐλπίδων, οὐδ’ ἠγνόησαν οὐδὲν οὔτε τῶν ἀγαθῶν οὔτε τῶν κακῶν τῶν προσόντων ἑκατέρᾳ τῶν δυνάμεων, ἀλλ’ ἀκριβῶς ᾔδεσαν τὴν μὲν κατὰ γῆν ἡγεμονίαν ὑπ’ εὐταξίας καὶ σωφροσύνης καὶ πειθαρχίας καὶ τῶν ἄλλων τῶν τοιούτων μελετωμένην, τὴν δὲ κατὰ θάλατταν δύναμιν οὐκ ἐκ τούτων αὐξανομένην,", "st": "12.115"}, {"sp": "N", "t": "ἀλλ’ ἔκ τε τῶν τεχνῶν τῶν περὶ τὰς ναῦς καὶ τῶν ἐλαύνειν αὐτὰς δυναμένων καὶ τῶν τὰ σφέτερα μὲν αὐτῶν ἀπολωλεκότων, ἐκ δὲ τῶν ἀλλοτρίων πορίζεσθαι τὸν βίον εἰθισμένων· ὧν εἰσπεσόντων εἰς τὴν πόλιν οὐκ ἄδηλος ἦν ὅ τε κόσμος ὁ τῆς πολιτείας τῆς πρότερον ὑπαρχούσης λυθησόμενος, ἥ τε τῶν συμμάχων εὔνοια ταχέως ληψομένη μεταβολήν, ὅταν οἷς πρότερον χώρας ἐδίδοσαν καὶ πόλεις, τούτους ἀναγκάζωσι συντάξεις καὶ φόρους ὑποτελεῖν, ἵν’ ἔχωσι μισθὸν διδόναι τοῖς τοιούτοις οἵους ὀλίγῳ πρότερον εἶπον.", "st": "12.116"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐδὲν ἀγνοοῦντες τῶν προειρημένων ἐνόμιζον τῇ πόλει τῇ τηλικαύτῃ μὲν τὸ μέγεθος, τοιαύτην δ’ ἐχούσῃ δόξαν, λυσιτελεῖν καὶ πρέπειν ἁπάσας ὑπομεῖναι τὰς δυσχερείας μᾶλλον ἢ τὴν Λακεδαιμονίων ἀρχήν· δυοῖν γὰρ πραγμάτοιν προτεινομένοιν μὴ σπουδαίοιν, κρείττω τὴν αἵρεσιν εἶναι τοῦ δεινὰ ποιεῖν ἑτέρους ἢ πάσχειν αὐτοὺς καὶ τοῦ μὴ δικαίως τῶν ἄλλων ἄρχειν μᾶλλον ἢ φεύγοντας τὴν αἰτίαν ταύτην ἀδίκως Λακεδαιμονίοις δουλεύειν.", "st": "12.117"}, {"sp": "N", "t": "ἅπερ ἅπαντες μὲν ἂν οἱ νοῦν ἔχοντες ἕλοιντο καὶ βουληθεῖεν, ὀλίγοι δ’ ἄν τινες τῶν προσποιουμένων εἶναι σοφῶν ἐρωτηθέντες οὐκ ἂν φήσαιεν. αἱ μὲν οὖν αἰτίαι δι’ ἃς μετέλαβον τὴν πολιτείαν τὴν ὑπό τινων ψεγομένην ἀντὶ τῆς ὑπὸ πάντων ἐπαινουμένης, διὰ μακροτέρων μὲν αὐτὰς διῆλθον, αὗται δ’ οὖν ἦσαν.", "st": "12.118"}, {"sp": "N", "t": "ἤδη δὲ περὶ ἧς τε ὑπεθέμην καὶ τῶν προγόνων ποιήσομαι τοὺς λόγους, ἐκείνων τῶν χρόνων ἐπιλαβόμενος ὅτ’ οὐκ ἦν οὔτ’ ὀλιγαρχίας οὔτε δημοκρατίας ὄνομά πω λεγόμενον, ἀλλὰ μοναρχίαι καὶ τὰ γένη τὰ τῶν βαρβάρων καὶ τὰς πόλεις τὰς Ἑλληνίδας ἁπάσας διῴκουν.", "st": "12.119"}, {"sp": "N", "t": "διὰ τοῦτο δὲ προειλόμην πορρωτέρωθεν ποιήσασθαι τὴν ἀρχήν, πρῶτον μὲν ἡγούμενος προσήκειν τοῖς ἀμφισβητοῦσιν ἀρετῆς εὐθὺς ἀπὸ γενεᾶς διαφέροντας εἶναι τῶν ἄλλων, ἔπειτ’ αἰσχυνόμενος εἰ περὶ ἀνδρῶν ἀγαθῶν μὲν οὐδὲν δέ μοι προσηκόντων πλείω διαλεχθεὶς τῶν μετρίων περὶ τῶν προγόνων τῶν τὴν πόλιν κάλλιστα διοικησάντων μηδὲ μικρὰν ποιήσομαι μνείαν,", "st": "12.120"}, {"sp": "N", "t": "οἳ τοσοῦτον βελτίους ἐγένοντο τῶν τοιαύτας δυναστείας ἐχόντων, ὅσον περ ἄνδρες οἱ φρονιμώτατοι καὶ πραότατοι διενέγκοιεν ἂν θηρίων τῶν ἀγριωτάτων καὶ πλείστης ὠμότητος μεστῶν. τί γὰρ οὐκ ἂν εὕροιμεν τῶν ὑπερβαλλόντων ἀνοσιότητι καὶ δεινότητι πεπραγμένον ἐν ταῖς ἄλλαις πόλεσι, καὶ μάλιστ’ ἐν ταῖς μεγίσταις καὶ τότε νομιζομέναις καὶ νῦν εἶναι δοκούσαις; οὐ φόνους ἀδελφῶν καὶ πατέρων καὶ ξένων παμπληθεῖς γεγενημένους;", "st": "12.121"}, {"sp": "N", "t": "οὐ σφαγὰς μητέρων καὶ μίξεις καὶ παιδοποιίας ἐξ ὧν ἐτύγχανον αὐτοὶ πεφυκότες; οὐ παίδων βρῶσιν ὑπὸ τῶν οἰκειοτάτων ἐπιβεβουλευμένην; οὐκ ἐκβολὰς ὧν ἐγέννησαν, καὶ καταποντισμοὺς καὶ τυφλώσεις καὶ τοσαύτας τὸ πλῆθος κακοποιίας, ὥστε μηδένα πώποτε ἀπορῆσαι τῶν εἰθισμένων καθ’ ἕκαστον τὸν ἐνιαυτὸν εἰσφέρειν εἰς τὸ θέατρον τὰς τότε γεγενημένας συμφοράς;", "st": "12.122"}, {"sp": "N", "t": "ταῦτα δὲ διῆλθον οὐκ ἐκείνους λοιδορῆσαι βουλόμενος, ἀλλ’ ἐπιδεῖξαι παρὰ τοῖς ἡμετέροις οὐ μόνον οὐδὲν τοιοῦτον γεγενημένον· τοῦτο μὲν γὰρ ἂν σημεῖον ἦν οὐκ ἀρετῆς ἀλλ’ ὡς οὐχ ὅμοιοι τὰς φύσεις ἦσαν τοῖς ἀνοσιωτάτοις γεγενημένοις· δεῖ δὲ τοὺς ἐπιχειροῦντας καθ’ ὑπερβολήν τινας ἐπαινεῖν μὴ τοῦτο μόνον ἐπιδεικνύναι, μὴ πονηροὺς ὄντας αὐτούς, ἀλλ’ ὡς ἁπάσαις ταῖς ἀρεταῖς καὶ τῶν τότε καὶ τῶν νῦν διήνεγκαν. ἅπερ ἔχοι τις ἂν καὶ περὶ τῶν προγόνων τῶν ἡμετέρων εἰπεῖν.", "st": "12.123"}, {"sp": "N", "t": "οὕτω γὰρ ὁσίως καὶ καλῶς καὶ τὰ περὶ τὴν πόλιν καὶ τὰ περὶ σφᾶς αὐτοὺς διῴκησαν, ὥσπερ προσῆκον ἦν τοὺς ἀπὸ θεῶν μὲν γεγονότας, πρώτους δὲ καὶ πόλιν οἰκήσαντας καὶ νόμοις χρησαμένους, ἅπαντα δὲ τὸν χρόνον ἠσκηκότας εὐσέβειαν μὲν περὶ τοὺς θεοὺς δικαιοσύνην δὲ περὶ τοὺς ἀνθρώπους, ὄντας δὲ μήτε μιγάδας μήτ’ ἐπήλυδας, ἀλλὰ μόνους αὐτόχθονας τῶν Ἑλλήνων,", "st": "12.124"}, {"sp": "N", "t": "καὶ ταύτην ἔχοντας τὴν χώραν τροφὸν ἐξ ἧς περ ἔφυσαν, καὶ στέργοντας αὐτὴν ὁμοίως ὥσπερ οἱ βέλτιστοι τοὺς πατέρας καὶ τὰς μητέρας τὰς αὑτῶν, πρὸς δὲ τούτοις οὕτω θεοφιλεῖς ὄντας, ὥσθ’ ὃ δοκεῖ χαλεπώτατον εἶναι καὶ σπανιώτατον, εὑρεῖν τινας τῶν οἴκων τῶν τυραννικῶν καὶ βασιλικῶν ἐπὶ τέτταρας ἢ πέντε γενεὰς διαμείναντας,", "st": "12.125"}, {"sp": "N", "t": "καὶ τοῦτο συμβῆναι μόνοις ἐκείνοις. Ἐριχθόνιος μὲν γὰρ ὁ φὺς ἐξ Ἡφαίστου καὶ Γῆς παρὰ Κέκροπος ἄπαιδος ὄντος ἀρρένων παίδων τὸν οἶκον καὶ τὴν βασιλείαν παρέλαβεν· ἐντεῦθεν δ’ ἀρξάμενοι πάντες οἱ γενόμενοι μετ’ ἐκεῖνον, ὄντες οὐκ ὀλίγοι, τὰς κτήσεις τὰς αὑτῶν καὶ τὰς δυναστείας τοῖς αὑτῶν παισὶ παρέδοσαν μέχρι Θησέως. περὶ οὗ πρὸ πολλοῦ ἂν ἐποιησάμην μὴ διειλέχθαι πρότερον περὶ τῆς ἀρετῆς καὶ τῶν πεπραγμένων αὐτῷ· πολὺ γὰρ ἂν μᾶλλον ἥρμοσεν ἐν τῷ λόγῳ τῷ περὶ τῆς πόλεως διελθεῖν περὶ αὐτῶν. ἀλλὰ γὰρ χαλεπὸν ἦν,", "st": "12.126"}, {"sp": "N", "t": "μᾶλλον δ’ ἀδύνατον, τὰ κατ’ ἐκεῖνον ἐπελθόντα τὸν χρόνον εἰς τοῦτον ἀποθέσθαι τὸν καιρόν, ὃν οὐ προῄδειν ἐσόμενον. ἐκεῖνα μὲν οὖν ἐάσομεν, ἐπειδὴ πρὸς τὸ παρὸν αὐτοῖς κατεχρησάμην, μιᾶς δὲ μόνον μνησθήσομαι πράξεως, ᾗ συμβέβηκε μήτ’ εἰρῆσθαι πρότερον μήτε πεπρᾶχθαι μηδ’ ὑφ’ ἑνὸς ἄλλου πλὴν ὑπὸ Θησέως, σημεῖον δ’ εἶναι μέγιστον τῆς ἀρετῆς τῆς ἐκείνου καὶ φρονήσεως.", "st": "12.127"}, {"sp": "N", "t": "ἔχων γὰρ βασιλείαν ἀσφαλεστάτην καὶ μεγίστην, ἐν ᾗ πολλὰ καὶ καλὰ διαπεπραγμένος ἦν καὶ κατὰ πόλεμον καὶ περὶ διοίκησιν τῆς πόλεως, ἅπαντα ταῦθ’ ὑπερεῖδεν, καὶ μᾶλλον εἵλετο τὴν δόξαν τὴν ἀπὸ τῶν πόνων καὶ τῶν ἀγώνων εἰς ἅπαντα τὸν χρόνον μνημονευθησομένην ἢ τὴν ῥᾳθυμίαν καὶ τὴν εὐδαιμονίαν τὴν διὰ τὴν βασιλείαν ἐν τῷ παρόντι γιγνομένην.", "st": "12.128"}, {"sp": "N", "t": "καὶ ταῦτ’ ἔπραξεν οὐκ ἐπειδὴ πρεσβύτερος γενόμενος ἀπολελαυκὼς ἦν τῶν ἀγαθῶν τῶν παρόντων, ἀλλ’ ἀκμάζων, ὡς λέγεται, τὴν μὲν πόλιν διοικεῖν τῷ πλήθει παρέδωκεν, αὐτὸς δ’ ὑπὲρ ταύτης τε καὶ τῶν ἄλλων Ἑλλήνων διετέλει κινδυνεύων.", "st": "12.129"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς Θησέως ἀρετῆς νῦν μὲν ὡς οἷόν τ’ ἦν ἀνεμνήσαμεν, πρότερον δ’ ἁπάσας αὐτοῦ τὰς πράξεις οὐκ ἀμελῶς διήλθομεν· περὶ δὲ τῶν παραλαβόντων τὴν τῆς πόλεως διοίκησιν, ἣν ἐκεῖνος παρέδωκεν, οὐκ ἔχω τίνας ἐπαίνους εἰπὼν ἀξίους ἂν εἴην εἰρηκὼς τῆς ἐκείνων διανοίας. οἵτινες ἄπειροι πολιτειῶν ὄντες, οὐ διήμαρτον αἱρούμενοι τῆς ὑπὸ πάντων ἂν ὁμολογηθείσης οὐ μόνον εἶναι κοινοτάτης καὶ δικαιοτάτης, ἀλλὰ καὶ συμφορωτάτης ἅπασι καὶ τοῖς χρωμένοις ἡδίστης.", "st": "12.130"}, {"sp": "N", "t": "κατεστήσαντο γὰρ δημοκρατίαν οὐ τὴν εἰκῇ πολιτευομένην, καὶ νομίζουσαν τὴν μὲν ἀκολασίαν ἐλευθερίαν εἶναι, τὴν δ’ ἐξουσίαν ὅ τι βούλεταί τις ποιεῖν εὐδαιμονίαν, ἀλλὰ τὴν τοῖς τοιούτοις μὲν ἐπιτιμῶσαν, ἀριστοκρατίᾳ δὲ χρωμένην· ἣν οἱ μὲν πολλοὶ χρησιμωτάτην οὖσαν ὥσπερ τὴν ἀπὸ τῶν τιμημάτων ἐν ταῖς πολιτείαις ἀριθμοῦσιν, οὐ δι’ ἀμαθίαν ἀγνοοῦντες, ἀλλὰ διὰ τὸ μηδὲν πώποτ’ αὐτοῖς μελῆσαι τῶν δεόντων.", "st": "12.131"}, {"sp": "N", "t": "ἐγὼ δὲ φημὶ τὰς μὲν ἰδέας τῶν πολιτειῶν τρεῖς εἶναι μόνας, ὀλιγαρχίαν, δημοκρατίαν, μοναρχίαν, τῶν δ’ ἐν ταύταις οἰκούντων ὅσοι μὲν εἰώθασιν ἐπὶ τὰς ἀρχὰς καθιστάναι καὶ τὰς ἄλλας πράξεις τοὺς ἱκανωτάτους τῶν πολιτῶν καὶ τοὺς μέλλοντας ἄριστα καὶ δικαιότατα τῶν πραγμάτων ἐπιστατήσειν, τούτους μὲν ἐν ἁπάσαις ταῖς πολιτείαις καλῶς οἰκήσειν καὶ πρὸς σφᾶς αὐτοὺς καὶ πρὸς τοὺς ἄλλους·", "st": "12.132"}, {"sp": "N", "t": "τοὺς δὲ τοῖς θρασυτάτοις καὶ πονηροτάτοις ἐπὶ ταῦτα χρωμένους, καὶ τῶν μὲν τῇ πόλει συμφερόντων μηδὲν φροντίζουσιν, ὑπὲρ δὲ τῆς αὑτῶν πλεονεξίας ἑτοίμοις οὖσιν ὁτιοῦν πάσχειν, τὰς δὲ τούτων πόλεις ὁμοίως οἰκήσεσθαι ταῖς τῶν προεστώτων πονηρίαις· τοὺς δὲ μήθ’ οὕτω μήθ’ ὡς πρότερον εἶπον, ἀλλ’ ὅταν μὲν θαρρῶσι, τούτους μάλιστα τιμῶντας, τοὺς πρὸς χάριν λέγοντας, ὅταν δὲ δείσωσιν, ἐπὶ τοὺς βελτίστους καὶ φρονιμωτάτους καταφεύγοντας, τοὺς δὲ τοιούτους ἐναλλὰξ τοτὲ μὲν χεῖρον τοτὲ δὲ βέλτιον πράξειν.", "st": "12.133"}, {"sp": "N", "t": "αἱ μὲν οὖν φύσεις καὶ δυνάμεις τῶν πολιτειῶν οὕτως ἔχουσιν, ἡγοῦμαι δὲ ταῦτα μὲν ἑτέροις πολὺ πλείους λόγους παρέξειν τῶν νῦν εἰρημένων, ἐμοὶ δ’ οὐκέτι περὶ ἁπασῶν αὐτῶν εἶναι διαλεκτέον, ἀλλὰ περὶ μόνης τῆς τῶν προγόνων· ταύτην γὰρ ὑπεσχόμην ἐπιδείξειν σπουδαιοτέραν καὶ πλειόνων ἀγαθῶν αἰτίαν οὖσαν τῆς ἐν Σπάρτῃ καθεστηκυίας.", "st": "12.134"}, {"sp": "N", "t": "ἔσται δ’ ὁ λόγος τοῖς μὲν ἡδέως ἂν ἀκούσασι πολιτείαν χρηστὴν ἐμοῦ διεξιόντος οὔτ’ ὀχληρὸς οὔτ’ ἄκαιρος, ἀλλὰ σύμμετρος καὶ προσήκων τοῖς πρότερον εἰρημένοις, τοῖς δὲ μὴ χαίρουσι τοῖς μετὰ πολλῆς σπουδῆς εἰρημένοις, ἀλλὰ τοῖς ἐν ταῖς πανηγύρεσι μάλιστα μὲν λοιδορουμένοις, ἢν δ’ ἀπόσχωνται τῆς μανίας ταύτης, ἐγκωμιάζουσιν ἢ τὰ φαυλότατα τῶν ὄντων ἢ τοὺς παρανομωτάτους τῶν γεγενημένων, τούτοις δ’ αὐτὸν οἶμαι δόξειν πολὺ μακρότερον εἶναι τοῦ δέοντος.", "st": "12.135"}, {"sp": "N", "t": "ἐμοὶ δὲ τῶν μὲν τοιούτων ἀκροατῶν οὐδὲν πώποτ’ ἐμέλησεν, οὐδὲ τοῖς ἄλλοις τοῖς εὖ φρονοῦσιν, ἐκείνων δὲ τῶν ἅ τε προεῖπον πρὸ ἅπαντος τοῦ λόγου μνημονευσόντων, τῷ τε πλήθει τῶν λεγομένων οὐκ ἐπιτιμησόντων, οὐδ’ ἢν μυρίων ἐπῶν ᾖ τὸ μῆκος, ἀλλ’ ἐφ’ αὑτοῖς εἶναι νομιούντων τοσοῦτον ἀναγνῶναι μέρος καὶ διελθεῖν ὁπόσον ἂν αὐτοὶ βουληθῶσιν, πάντων δὲ μάλιστα τῶν οὐδενὸς ἂν ἥδιον ἀκουόντων ἢ λόγου διεξιόντος ἀνδρῶν ἀρετὰς καὶ πόλεως τρόπον καλῶς οἰκουμένης,", "st": "12.136"}, {"sp": "N", "t": "ἅπερ εἰ μιμήσασθαί τινες βουληθεῖεν καὶ δυνηθεῖεν, αὐτοί τ’ ἂν ἐν μεγάλῃ δόξῃ τὸν βίον διαγάγοιεν καὶ τὰς πόλεις τὰς αὑτῶν εὐδαίμονας ποιήσειαν. οἵους μὲν οὖν εὐξαίμην ἂν εἶναι τοὺς ἀκουσομένους τῶν ἐμῶν, εἴρηκα, δέδοικα δὲ μὴ τοιούτων γενομένων πολὺ καταδεέστερον εἴπω τῶν πραγμάτων περὶ ὧν μέλλω ποιεῖσθαι τοὺς λόγους. ὅμως δ’ οὕτως ὅπως ἂν οἷός τ’ ὦ πειράσομαι διαλεχθῆναι περὶ αὐτῶν.", "st": "12.137"}, {"sp": "N", "t": "τοῦ μὲν οὖν διαφερόντως τῶν ἄλλων οἰκεῖσθαι τὴν πόλιν ἡμῶν κατ’ ἐκεῖνον τὸν χρόνον δικαίως ἂν ἐπενέγκοιμεν τὴν αἰτίαν τοῖς βασιλεύσασιν αὐτῆς, περὶ ὧν ὀλίγῳ πρότερον διελέχθην. ἐκεῖνοι γὰρ ἦσαν οἱ παιδεύσαντες τὸ πλῆθος ἐν ἀρετῇ καὶ δικαιοσύνῃ καὶ πολλῇ σωφροσύνῃ, καὶ διδάξαντες ἐξ ὧν διῴκουν, ἅπερ ἐγὼ φανείην ἂν ὕστερον εἰρηκὼς ἢ κεῖνοι πράξαντες, ὅτι πᾶσα πολιτεία ψυχὴ πόλεώς ἐστι, τοσαύτην ἔχουσα δύναμιν ὅσην περ ἐν σώματι φρόνησις· αὕτη γάρ ἐστιν ἡ βουλευομένη περὶ ἁπάντων, καὶ τὰ μὲν ἀγαθὰ διαφυλάττουσα, τὰς δὲ συμφορὰς διαφεύγουσα, καὶ πάντων αἰτία τῶν ταῖς πόλεσι συμβαινόντων.", "st": "12.138"}, {"sp": "N", "t": "ἃ μαθὼν ὁ δῆμος οὐκ ἐπελάθετο διὰ τὴν μεταβολήν, ἀλλὰ μᾶλλον τούτῳ προσεῖχεν ἢ τοῖς ἄλλοις, ὅπως λήψεται τοὺς ἡγεμόνας δημοκρατίας μὲν ἐπιθυμοῦντας, τὸ δ’ ἦθος τοιοῦτον ἔχοντας οἷόν περ οἱ πρότερον ἐπιστατοῦντες αὐτῶν, καὶ μὴ λήσουσι σφᾶς αὐτοὺς κυρίους ἁπάντων τῶν κοινῶν καταστήσαντες οἷς οὐδεὶς ἂν οὐδὲν τῶν ἰδίων ἐπιτρέψειεν,", "st": "12.139"}, {"sp": "N", "t": "μηδὲ περιόψονται πρὸς τὰ τῆς πόλεως προσιόντας τοὺς ὁμολογουμένως ὄντας πονηρούς, μηδ’ ἀνέξονται τὴν φωνὴν τῶν τὰ μὲν σώματα τὰ σφέτερ’ αὐτῶν ἐπονειδίστως διατιθεμένων, συμβουλεύειν δὲ τοῖς ἄλλοις ἀξιούντων ὃν τρόπον τὴν πόλιν διοικοῦντες σωφρονοῖεν ἂν καὶ βέλτιον πράττομεν, μηδὲ τῶν ἃ μὲν παρὰ τῶν πατέρων παρέλαβον εἰς αἰσχρὰς ἡδονὰς ἀνηλωκότων, ἐκ δὲ τῶν κοινῶν ταῖς ἰδίαις ἀπορίαις βοηθεῖν ζητούντων, μηδὲ τῶν πρὸς χάριν μὲν ἀεὶ λέγειν γλιχομένων, εἰς πολλὰς δ’ ἀηδίας καὶ λύπας τοὺς πειθομένους ἐμβαλλόντων,", "st": "12.140"}, {"sp": "N", "t": "ἀλλὰ τούς τε τοιούτους ἅπαντας ἀπείργειν ἀπὸ τοῦ συμβουλεύειν ἕκαστος οἰήσεται δεῖν, καὶ πρὸς τούτοις ἐκείνους, τοὺς τὰ μὲν τῶν ἄλλων κτήματα τῆς πόλεως εἶναι φάσκοντας, τὰ δὲ ταύτης ἴδια κλέπτειν καὶ διαρπάζειν τολμῶντας, καὶ φιλεῖν μὲν τὸν δῆμον προσποιουμένους, ὑπὸ δὲ τῶν ἄλλων ἁπάντων αὐτὸν μισεῖσθαι ποιοῦντας, καὶ λόγῳ μὲν δεδιότας ὑπὲρ τῶν Ἑλλήνων,", "st": "12.141"}, {"sp": "N", "t": "ἔργῳ δὲ λυμαινομένους καὶ συκοφαντοῦντας καὶ διατιθέντας αὐτοὺς οὕτω πρὸς ἡμᾶς, ὥστε τῶν πόλεων τὰς εἰς τὸν πόλεμον καθισταμένας ἥδιον ἂν καὶ θᾶττον ἐνίας εἰσδέξασθαι τοὺς πολιορκοῦντας ἢ τὴν παρ’ ἡμῶν βοήθειαν. ἀπείποι δ’ ἄν τις γράφων, εἰ πάσας τὰς κακοηθείας καὶ πονηρίας ἐξαριθμεῖν ἐπιχειρήσειεν.", "st": "12.142"}, {"sp": "N", "t": "ἃς ἐκεῖνοι μισήσαντες καὶ τοὺς ἔχοντας αὐτάς, ἐποιοῦντο συμβούλους καὶ προστάτας οὐ τοὺς τυχόντας ἀλλὰ τοὺς βελτίστους καὶ φρονιμωτάτους καὶ κάλλιστα βεβιωκότας, καὶ τοὺς αὐτοὺς τούτους στρατηγοὺς ᾑροῦντο καὶ πρέσβεις, εἴ που δεήσειεν, ἔπεμπον, καὶ πάσας τὰς ἡγεμονίας τὰς τῆς πόλεως αὐτοῖς παρεδίδοσαν, νομίζοντες τοὺς ἐπὶ τοῦ βήματος βουλομένους καὶ δυναμένους τὰ βέλτιστα συμβουλεύειν, τούτους καὶ καθ’ αὑτοὺς γενομένους ἐν ἅπασι τοῖς τόποις καὶ περὶ ἁπάσας τὰς πράξεις τὴν αὐτὴν γνώμην ἕξειν· ἅπερ αὐτοῖς συνέβαινεν.", "st": "12.143"}, {"sp": "N", "t": "διὰ γὰρ τὸ ταῦτα γιγνώσκειν ἐν ὀλίγαις ἡμέραις ἑώρων τούς τε νόμους ἀναγεγραμμένους, οὐχ ὁμοίους τοῖς νῦν κειμένοις, οὐδὲ τοσαύτης ταραχῆς καὶ τοσούτων ἐναντιώσεων μεστοὺς ὥστε μηδέν ἂν δυνηθῆναι συνιδεῖν μήτε τοὺς χρησίμους μήτε τοὺς ἀχρήστους αὐτῶν, ἀλλὰ πρῶτον μὲν ὀλίγους, ἱκανοὺς δὲ τοῖς χρῆσθαι μέλλουσι καὶ ῥᾳδίους συνιδεῖν, ἔπειτα δικαίους καὶ συμφέροντας καὶ σφίσιν αὐτοῖς ὁμολογουμένους, καὶ μᾶλλον ἐσπουδασμένους τοὺς περὶ τῶν κοινῶν ἐπιτηδευμάτων ἢ τοὺς περὶ τῶν ἰδίων συμβολαίων, οἵους περ εἶναι χρὴ παρὰ τοῖς καλῶς πολιτευομένοις.", "st": "12.144"}, {"sp": "N", "t": "περὶ δὲ τοὺς αὐτοὺς χρόνους καθίστασαν ἐπὶ τὰς ἀρχὰς τοὺς προκριθέντας ὑπὸ τῶν φυλετῶν καὶ δημοτῶν, οὐ περιμαχήτους αὐτὰς ποιήσαντες οὐδ’ ἐπιθυμίας ἀξίας, ἀλλὰ πολὺ μᾶλλον λειτουργίαις ὁμοίας ταῖς ἐνοχλούσαις μὲν οἷς ἂν προσταχθῶσι, τιμὴν δέ τινα περιτιθείσαις αὐτοῖς· ἔδει γὰρ τοὺς ἄρχειν αἱρεθέντας τῶν τε κτημάτων τῶν ἰδίων ἀμελεῖν, καὶ τῶν λημμάτων τῶν εἰθισμένων δίδοσθαι ταῖς ἀρχαῖς ἀπέχεσθαι μηδὲν ἧττον ἢ τῶν ἱερῶν (ἃ τίς ἂν ἐν τοῖς νῦν καθεστῶσιν ὑπομείνειεν;),", "st": "12.145"}, {"sp": "N", "t": "καὶ τοὺς μὲν ἀκριβεῖς περὶ ταύτας γιγνομένους μετρίως ἐπαινεθέντας ἐφ’ ἑτέραν ἐπιμέλειαν τάττεσθαι τοιαύτην, τοὺς δὲ καὶ μικρὸν παραβάντας ταῖς ἐσχάταις αἰσχύναις καὶ μεγίσταις ζημίαις περιπίπτειν· ὥστε μηδένα τῶν πολιτῶν ὥσπερ νῦν διακεῖσθαι πρὸς τὰς ἀρχάς, ἀλλὰ μᾶλλον τότε ταύτας φεύγειν ἢ νῦν διώκειν,", "st": "12.146"}, {"sp": "N", "t": "καὶ πάντας νομίζειν μηδέποτ’ ἂν γενέσθαι δημοκρατίαν ἀληθεστέραν μηδὲ βεβαιοτέραν μηδὲ μᾶλλον τῷ πλήθει συμφέρουσαν τῆς τῶν μὲν τοιούτων πραγματειῶν ἀτέλειαν τῷ δήμῳ διδούσης, τοῦ δὲ τὰς ἀρχὰς καταστῆσαι καὶ λαβεῖν δίκην παρὰ τῶν ἐξαμαρτόντων κύριον ποιούσης, ἅπερ ὑπάρχει καὶ τῶν τυράννων τοῖς εὐδαιμονεστάτοις.", "st": "12.147"}, {"sp": "N", "t": "σημεῖον δὲ μέγιστον ὅτι ταῦτ’ ἠγάπων μᾶλλον ἢ ’γὼ λέγω· φαίνεται γὰρ ὁ δῆμος ταῖς μὲν ἄλλαις πολιτείαις ταῖς οὐκ ἀρεσκούσαις μαχόμενος καὶ καταλύων καὶ τοὺς προεστῶτας αὐτῶν ἀποκτείνων, ταύτῃ δὲ χρώμενος οὐκ ἐλάττω χιλίων ἐτῶν, ἀλλ’ ἐμμείνας ἀφ’ οὗ περ ἔλαβε μέχρι τῆς Σόλωνος μὲν ἡλικίας Πεισιστράτου δὲ δυναστείας, ὃς δημαγωγὸς γενόμενος καὶ πολλὰ τὴν πόλιν λυμηνάμενος καὶ τοὺς βελτίστους τῶν πολιτῶν ὡς ὀλιγαρχικοὺς ὄντας ἐκβαλών, τελευτῶν τόν τε δῆμον κατέλυσε καὶ τύραννον αὑτὸν κατέστησεν.", "st": "12.148"}, {"sp": "N", "t": "τάχ’ οὖν ἄν τινες ἄτοπον εἶναί με φήσειαν, οὐδὲν γὰρ κωλύει διαλαβεῖν τὸν λόγον, ὅτι τολμῶ λέγειν ὡς ἀκριβῶς εἰδὼς περὶ πραγμάτων οἷς οὐ παρῆν πραττομένοις. ἐγὼ δ’ οὐδὲν τούτων ἄλογον οἶμαι ποιεῖν. εἰ μὲν γὰρ μόνος ἐπίστευον τοῖς τε λεγομένοις περὶ τῶν παλαιῶν καὶ τοῖς γράμμασι τοῖς ἐξ ἐκείνου τοῦ χρόνου παραδεδομένοις ἡμῖν, εἰκότως ἂν ἐπιτιμῴμην· νῦν δὲ πολλοὶ καὶ νοῦν ἔχοντες ταὐτὸν ἐμοὶ φανεῖεν ἂν πεπονθότες. χωρὶς δὲ τούτων,", "st": "12.149"}, {"sp": "N", "t": "εἰ κατασταίην εἰς ἔλεγχον καὶ λόγον, δυνηθείην ἂν ἐπιδεῖξαι πάντας ἀνθρώπους πλείους ἐπιστήμας ἔχοντας διὰ τῆς ἀκοῆς ἢ τῆς ὄψεως, καὶ μείζους πράξεις καὶ καλλίους εἰδότας ἃς παρ’ ἑτέρων ἀκηκόασιν ἢ ’κείνας αἷς αὐτοὶ παραγεγενημένοι τυγχάνουσιν. ἀλλὰ γὰρ οὔτ’ ἀμελεῖν καλῶς ἔχει τῶν τοιούτων ὑπολήψεων, τυχὸν γὰρ μηδενὸς ἀντειπόντος λυμήναιντ’ ἂν τὴν ἀλήθειαν, οὔτ’ αὖ πολὺν χρόνον ἀντιλέγοντας διατρίβειν ἐν αὐταῖς, ἀλλ’ ὅσον ὑποδείξαντας μόνον τοῖς ἄλλοις ἐξ ὧν ληροῦντας ἂν αὐτοὺς ἐπιδείξαιεν, πάλιν ἐπανελθόντας περαίνειν καὶ λέγειν ὅθεν ἀπέλιπον· ὅπερ ἐγὼ ποιήσω.", "st": "12.150"}, {"sp": "N", "t": "τὸ μὲν οὖν σύνταγμα τῆς τότε πολιτείας, καὶ τὸν χρόνον ὅσον αὐτῇ χρώμενοι διετέλεσαν, ἐξαρκούντως δεδηλώκαμεν· λοιπὸν δ’ ἡμῖν τὰς πράξεις τὰς ἐκ τοῦ καλῶς πολιτεύεσθαι γεγενημένας διελθεῖν. ἐκ τούτων γὰρ ἔτι μᾶλλον ἔσται καταμαθεῖν ὅτι καὶ τὴν πολιτείαν εἶχον ἡμῶν οἱ πρόγονοι βελτίω τῶν ἄλλων καὶ σωφρονεστέραν, καὶ προστάταις καὶ συμβούλοις ἐχρῶντο τοιούτοις οἵοις χρὴ τοὺς εὖ φρονοῦντας.", "st": "12.151"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ ταῦτά μοι πρότερον λεκτέον ἐστί, πρὶν ἂν μικρὰ προείπω περὶ αὐτῶν. ἢν γὰρ ὑπεριδὼν τὰς ἐπιτιμήσεις τὰς τῶν οὐδὲν ἄλλο ποιεῖν ἢ τοῦτο δυναμένων ἐφεξῆς διηγῶμαι περί τε τῶν ἄλλων τῶν πεπραγμένων καὶ τῶν ἐπιτηδευμάτων τῶν περὶ τὸν πόλεμον, οἷς οἱ πρόγονοι χρώμενοι τῶν τε βαρβάρων περιεγένοντο καὶ παρὰ τοῖς Ἕλλησιν εὐδοκίμησαν, οὐκ ἔστιν ὅπως οὐ φήσουσί τινές με διεξιέναι τοὺς νόμους οὓς Λυκοῦργος μὲν ἔθηκε, Σπαρτιᾶται δ’ αὐτοῖς χρώμενοι τυγχάνουσιν.", "st": "12.152"}, {"sp": "N", "t": "ἐγὼ δ’ ὁμολογῶ μὲν ἐρεῖν πολλὰ τῶν ἐκεῖ καθεστώτων, οὐχ ὡς Λυκούργου τι τούτων εὑρόντος ἢ διανοηθέντος, ἀλλ’ ὡς μιμησαμένου τὴν διοίκησιν ὡς δυνατὸν ἄριστα τὴν τῶν προγόνων τῶν ἡμετέρων, καὶ τήν τε δημοκρατίαν καταστήσαντος παρ’ αὐτοῖς τὴν ἀριστοκρατίᾳ μεμιγμένην, ἥπερ ἦν παρ’ ἡμῖν, καὶ τὰς ἀρχὰς οὐ κληρωτὰς ἀλλ’ αἱρετὰς ποιήσαντος,", "st": "12.153"}, {"sp": "N", "t": "καὶ τῶν γερόντων αἵρεσιν τῶν ἐπιστατούντων ἅπασι τοῖς πράγμασι μετὰ τοσαύτης σπουδῆς ποιεῖσθαι νομοθετήσαντος, μεθ’ ὅσης πέρ φασι καὶ τοὺς ἡμετέρους περὶ τῶν εἰς Ἄρειον πάγον ἀναβήσεσθαι μελλόντων, ἔτι δὲ καὶ τὴν δύναμιν αὐτοῖς περιθέντος τὴν αὐτήν, ἥνπερ ᾔδει καὶ τὴν βουλὴν ἔχουσαν τὴν παρ’ ἡμῖν.", "st": "12.154"}, {"sp": "N", "t": "ὅτι μὲν οὖν τὸν αὐτὸν τρόπον τἀκεῖ καθέστηκεν ὥσπερ εἶχε τὸ παλαιὸν καὶ τὰ παρ’ ἡμῖν, παρὰ πολλῶν ἔσται πυθέσθαι τοῖς εἰδέναι βουλομένοις· ὡς δὲ καὶ τὴν ἐμπειρίαν τὴν περὶ τὸν πόλεμον οὐ πρότερον ἤσκησαν οὐδ’ ἄμεινον ἐχρήσαντο Σπαρτιᾶται τῶν ἡμετέρων, ἐκ τῶν ἀγώνων καὶ τῶν πολέμων τῶν ὁμολογουμένων γενέσθαι κατ’ ἐκεῖνοι τὸν χρόνον οὕτως οἶμαι σαφῶς ἐπιδείξειν, ὥστε μήτε τοὺς ἀνοήτως λακωνίζοντας ἀντειπεῖν δυνήσεσθαι τοῖς ῥηθεῖσι, μήτε τοὺς τὰ ἡμέτερα ἅμα τε θαυμάζοντας καὶ βασκαίνοντας καὶ μιμεῖσθαι γλιχομένους.", "st": "12.155"}, {"sp": "N", "t": "ποιήσομαι δὲ τὴν ἀρχὴν τῶν λεχθησομένων ἀκοῦσαι μὲν ἴσως τισὶν ἀηδῆ, ῥηθῆναι δ’ οὐκ ἀσύμφορον. εἰ γάρ τις φαίη τὼ πόλεε τούτω πλείστων ἀγαθῶν αἰτίας γεγενῆσθαι τοῖς Ἕλλησι καὶ μεγίστων κακῶν μετὰ τὴν Ξέρξου στρατείαν, οὐκ ἔστιν ὅπως οὐκ ἀληθῆ δόξειεν ἂν λέγειν τοῖς εἰδόσι τι περὶ τῶν τότε γεγενημένων.", "st": "12.156"}, {"sp": "N", "t": "ἠγωνίσαντό τε γὰρ ὡς δυνατὸν ἄριστα πρὸς τὴν ἐκείνου δύναμιν, ταῦτά τε πράξασαι, προσῆκον αὐταῖς καὶ περὶ τῶν ἐχομένων βουλεύσασθαι καλῶς, εἰς τοῦτ’ ἦλθον οὐκ ἀνοίας ἀλλὰ μανίας, ὥστε πρὸς μὲν τὸν ἐπιστρατεύσαντα καὶ βουληθέντα τὼ μὲν πόλεε τούτω παντάπασιν ἀνελεῖν, τοὺς δ’ ἄλλους Ἕλληνας καταδουλώσασθαι,", "st": "12.157"}, {"sp": "N", "t": "πρὸς μὲν τὸν τοιοῦτον, κρατήσασαι ῥᾳδίως ἂν αὐτοῦ καὶ κατὰ γῆν καὶ κατὰ θάλατταν, εἰρήνην εἰς ἅπαντα συνεγράψαντο τὸν χρόνον ὥσπερ πρὸς εὐεργέτην γεγενημένον, φθονήσασαι δὲ ταῖς ἀρεταῖς ταῖς αὑτῶν, εἰς πόλεμον καταστᾶσαι πρὸς ἀλλήλας καὶ φιλονεικίαν, οὐ πρότερον ἐπαύσαντο σφᾶς τε αὐτὰς ἀπολλύουσαι καὶ τοὺς ἄλλους Ἕλληνας, πρὶν κύριον ἐποίησαν τὸν κοινὸν ἐχθρὸν τὴν τε πόλιν τὴν ἡμετέραν εἰς τοὺς ἐσχάτους καταστῆσαι κινδύνους διὰ τῆς δυνάμεως τῆς Λακεδαιμονίων, καὶ πάλιν τὴν ἐκείνων διὰ τῆς πόλεως τῆς ἡμετέρας.", "st": "12.158"}, {"sp": "N", "t": "καὶ τοσοῦτον ἀπολειφθέντες τῆς τοῦ βαρβάρου φρονήσεως, οὔτ’ ἐν ἐκείνοις τοῖς χρόνοις ἤλγησαν ἀξίως ὧν ἔπαθον οὐδ’ ὡς προσῆκεν αὐτούς, οὔτε νῦν αἱ μέγισται τῶν Ἑλληνίδων πόλεων αἰσχύνονται διακολακευόμεναι πρὸς τὸν ἐκείνου πλοῦτον, ἀλλ’ ἡ μὲν Ἀργείων καὶ Θηβαίων Αἴγυπτον αὐτῷ συγκατεπολέμησεν, ἵν’ ὡς μεγίστην ἔχων δύναμιν ἐπιβουλεύῃ τοῖς Ἕλλησιν, ἡμεῖς δὲ καὶ Σπαρτιᾶται, συμμαχίας ἡμῖν ὑπαρχούσης, ἀλλοτριώτερον ἔχομεν πρὸς ἡμᾶς αὐτοὺς ἢ πρὸς οὓς ἑκάτεροι πολεμοῦντες τυγχάνομεν.", "st": "12.159"}, {"sp": "N", "t": "σημεῖον δ’ οὐ μικρόν· κοινῇ μὲν γὰρ οὐδὲ περὶ ἑνὸς πράγματος βουλευόμεθα, χωρὶς δ’ ἑκάτεροι πρέσβεις πέμπομεν ὡς ἐκεῖνον, ἐλπίζοντες, ὁποτέροις ἂν οἰκειότερον διατεθῇ, κυρίους τούτους γενήσεσθαι τῆς ἐν τοῖς Ἕλλησι πλεονεξίας, κακῶς εἰδότες ὡς τοὺς μὲν θεραπεύοντας αὑτὸν ὑβρίζειν εἴθισται, πρὸς δὲ τοὺς ἀντιταττομένους καὶ καταφρονοῦντας τῆς ἐκείνου δυνάμεως ἐκ παντὸς τρόπου διαλύεσθαι πειρᾶται τὰς διαφοράς.", "st": "12.160"}, {"sp": "N", "t": "ταῦτα δὲ διῆλθον οὐκ ἀγνοῶν ὅτι λέγειν τινὲς τολμήσουσιν ὡς ἔξω τῆς ὑποθέσεως τοῖς λόγοις τούτοις ἐχρησάμην. ἐγὼ δ’ οὐδέποτ’ ἂν οἶμαι τοῖς προειρημένοις οἰκειοτέρους λόγους ῥηθῆναι τούτων, οὐδ’ ἐξ ὧν ἄν τις σαφέστερον ἐπιδείξειε τοὺς προγόνους ἡμῶν φρονιμωτέρους ὄντας περὶ τὰ μέγιστα τῶν τήν τε πόλιν τὴν ἡμετέραν καὶ τὴν Σπαρτιατῶν μετὰ τὸν πόλεμον τὸν πρὸς Ξέρξην διοικησάντων.", "st": "12.161"}, {"sp": "N", "t": "αὗται μὲν γὰρ ἂν φανεῖεν ἐν ἐκείνοις τε τοῖς χρόνοις πρὸς μὲν τοὺς βαρβάρους εἰρήνην ποιησάμεναι, σφᾶς δ’ αὐτὰς καὶ τὰς ἄλλας πόλεις ἀπολλύουσαι νῦν τε τῶν μὲν Ἑλλήνων ἄρχειν ἀξιοῦσαι, πρὸς δὲ τὸν βασιλέα πρέσβεις πέμπουσαι περὶ φιλίας καὶ συμμαχίας· οἱ δὲ τότε τὴν πόλιν οἰκοῦντες οὐδὲν τούτων ἔπραττον,", "st": "12.162"}, {"sp": "N", "t": "ἀλλὰ πᾶν τοὐναντίον· τῶν μὲν γὰρ Ἑλληνίδων πόλεων οὕτως αὐτοῖς ἀπέχεσθαι σφόδρα δεδογμένον ἦν ὥσπερ τοῖς εὐσεβέσι τῶν ἐν τοῖς ἱεροῖς ἀνακειμένων, τῶν δὲ πολέμων ὑπελάμβανον ἀναγκαιότατον μὲν εἶναι καὶ δικαιότατον τὸν μετὰ πάντων ἀνθρώπων πρὸς τὴν ἀγριότητα τῶν θηρίων γιγνόμενον, δεύτερον δὲ τὸν μετὰ τῶν Ἑλλήνων πρὸς τοὺς βαρβάρους τοὺς καὶ φύσει πολεμίους ὄντας καὶ πάντα τὸν χρόνον ἐπιβουλεύοντας ἡμῖν.", "st": "12.163"}, {"sp": "N", "t": "τοῦτον δ’ εἴρηκα τὸν λόγον οὐκ αὐτὸς εὑρών, ἀλλ’ ἐκ τῶν ἐκείνοις πεπραγμένων συλλογισάμενος. ὁρῶντες γὰρ τὰς μὲν ἄλλας πόλεις ἐν πολλοῖς κακοῖς καὶ πολέμοις καὶ ταραχαῖς οὔσας, τὴν δ’ αὑτῶν μόνην καλῶς διοικουμένην, οὐχ ἡγήσαντο δεῖν τοὺς ἄμεινον τῶν ἄλλων φρονοῦντας καὶ πράττοντας ἀμελεῖν οὐδὲ περιορᾶν τὰς τῆς αὐτῆς συγγενείας μετεχούσας ἀπολλυμένας, ἀλλὰ σκεπτέον εἶναι καὶ πρακτέον ὅπως ἁπάσας ἀπαλλάξουσι τῶν κακῶν τῶν παρόντων.", "st": "12.164"}, {"sp": "N", "t": "ταῦτα δὲ διανοηθέντες τῶν μὲν ἧττον νοσουσῶν πρεσβείαις καὶ λόγοις ἐξαιρεῖν ἐπειρῶντο τὰς διαφοράς, εἰς δὲ τὰς μᾶλλον στασιαζούσας ἐξέπεμπον τῶν πολιτῶν τοὺς μεγίστην παρ’ αὐτοῖς δόξαν ἔχοντας, οἳ περί τε τῶν παρόντων πραγμάτων αὐταῖς συνεβούλευον καὶ συγγιγνόμενοι τοῖς τε μὴ δυναμένοις ἐν ταῖς αὑτῶν ζῆν καὶ τοῖς χεῖρον γεγονόσιν ὧν οἱ νόμοι προστάττουσιν, οἵπερ ὡς ἐπὶ τὸ πολὺ λυμαίνονται τὰς πόλεις, ἔπειθον μεθ’ αὑτῶν στρατεύεσθαι καὶ βίον ζητεῖν βελτίω τοῦ παρόντος.", "st": "12.165"}, {"sp": "N", "t": "πολλῶν δὲ γιγνομένων τῶν ταῦτα βουλομένων καὶ πειθομένων, στρατόπεδα συνιστάντες ἐξ αὐτῶν, τούς τε τὰς νήσους κατέχοντας τῶν βαρβάρων καὶ τοὺς ἐφ’ ἑκατέρας τῆς ἠπείρου τὴν παραλίαν κατοικοῦντας καταστρεφόμενοι, καὶ πάντας ἐκβαλόντες, τοὺς μάλιστα βίου δεομένους τῶν Ἑλλήνων κατῴκιζον. καὶ ταῦτα πράττοντες καὶ τοῖς ἄλλοις ὑποδεικνύοντες διετέλουν, ἕως ἤκουσαν Σπαρτιάτας τὰς πόλεις τὰς ἐν Πελοποννήσῳ κατοικούσας, ὥσπερ εἶπον, ὑφ’ αὑτοῖς πεποιημένους· μετὰ δὲ ταῦτα τοῖς ἰδίοις ἠναγκάζοντο προσέχειν τὸν νοῦν.", "st": "12.166"}, {"sp": "N", "t": "τί οὖν ἐστὶ τὸ συμβεβηκὸς ἀγαθὸν ἐκ τοῦ πολέμου τοῦ περὶ τὰς ἀποικίας καὶ πραγματείας; τοῦτο γὰρ οἶμαι μάλιστα ποθεῖν ἀκοῦσαι τοὺς πολλούς. τοῖς μὲν Ἕλλησιν εὐπορωτέροις γενέσθαι τὰ περὶ τὸν βίον καὶ μᾶλλον ὁμονοεῖν τοσούτων τὸ πλῆθος καὶ τοιούτων ἀνθρώπων ἀπαλλαγεῖσι, τοῖς δὲ βαρβάροις ἐκπίπτειν ἐκ τῆς αὑτῶν καὶ φρονεῖν ἔλαττον ἢ πρότερον, τοῖς δ’ αἰτίοις τούτων γεγενημένοις εὐδοκιμεῖν καὶ δοκεῖν διπλασίαν πεποιηκέναι τὴν Ἑλλάδα τῆς ἐξ ἀρχῆς συστάσης.", "st": "12.167"}, {"sp": "N", "t": "μεῖζον μὲν οὖν εὐεργέτημα τούτου καὶ κοινότερον τοῖς Ἕλλησι γεγενημένον παρὰ τῶν προγόνων τῶν ἡμετέρων οὐκ ἂν δυναίμην ἐξευρεῖν· οἰκειότερον δὲ τῇ περὶ τὸν πόλεμον ἐπιμελείᾳ καὶ δόξης οὐκ ἐλάττονος ἄξιον καὶ πᾶσι φανερώτερον ἴσως ἕξομεν εἰπεῖν. τίς γὰρ οὐκ οἶδεν, ἢ τίς οὐκ ἀκήκοε τῶν τραγῳδοδιδασκάλων Διονυσίοις, τὰς Ἀδράστῳ γενομένας ἐν Θήβαις συμφοράς,", "st": "12.168"}, {"sp": "N", "t": "ὅτι κατάγειν βουληθεὶς τὸν Οἰδίπου μὲν υἱὸν αὑτοῦ δὲ κηδεστὴν παμπληθεῖς μὲν Ἀργείων ἀπώλεσεν, ἅπαντας δὲ τοὺς λοχαγοὺς ἐπεῖδε διαφθαρέντας, αὐτὸς δ’ ἐπονειδίστως σωθείς, ἐπειδὴ σπονδῶν οὐχ οἷός τ’ ἦν τυχεῖν οὐδ’ ἀνελέσθαι τοὺς τετελευτηκότας, ἱκέτης γενόμενος τῆς πόλεως, ἔτι Θησέως αὐτὴν διοικοῦντος, ἐδεῖτο μὴ περιιδεῖν τοιούτους ἄνδρας ἀτάφους γενομένους μηδὲ παλαιὸν ἔθος καὶ πάτριον νόμον καταλυόμενον, ᾧ πάντες ἄνθρωποι χρώμενοι διατελοῦσιν οὐχ ὡς ὑπ’ ἀνθρωπίνης κειμένῳ φύσεως, ἀλλ’ ὡς ὑπὸ δαιμονίας προστεταγμένῳ δυνάμεως;", "st": "12.169"}, {"sp": "N", "t": "ὧν ἀκούσας οὐδένα χρόνον ἐπισχὼν ὁ δῆμος ἔπεμψε πρεσβείαν εἰς Θήβας, περί τε τῆς ἀναιρέσεως συμβουλεύσοντας αὐτοῖς ὁσιώτερον βουλεύσασθαι καὶ τὴν ἀπόκρισιν νομιμωτέραν ποιήσασθαι τῆς πρότερον γενομένης, κἀκεῖνο ὑποδείξοντας, ὡς ἡ πόλις αὐτοῖς οὐκ ἐπιτρέψει παραβαίνουσι τὸν νόμον τὸν κοινὸν ἁπάντων τῶν Ἑλλήνων.", "st": "12.170"}, {"sp": "N", "t": "ὧν ἀκούσαντες οἱ κύριοι τότε Θηβῶν ὄντες οὐχ ὁμοίως ἔγνωσαν οὔτε ταῖς δόξαις αἷς ἔχουσί τινες περὶ αὐτῶν, οὔθ’ οἷς ἐβουλεύσαντο πρότερον, ἀλλὰ μετρίως περὶ αὑτῶν τε διαλεχθέντες καὶ τῶν ἐπιστρατευσάντων κατηγορήσαντες ἔδοσαν τῇ πόλει τὴν ἀναίρεσιν.", "st": "12.171"}, {"sp": "N", "t": "καὶ μηδεὶς οἰέσθω με ἀγνοεῖν ὅτι τἀναντία τυγχάνω λέγων οἷς ἐν τῷ Πανηγυρικῷ λόγῳ φανείην ἂν περὶ τῶν αὐτῶν τούτων γεγραφώς· ἀλλὰ γὰρ οὐδένα νομίζω τῶν ταῦτα συνιδεῖν ἂν δυνηθέντων τοσαύτης ἀμαθίας εἶναι καὶ φθόνου μεστόν, ὅστις οὐκ ἂν ἐπαινέσειέ με καὶ σωφρονεῖν ἡγήσαιτο τότε μὲν ἐκείνως νῦν δ’ οὕτω διαλεχθέντα περὶ αὐτῶν.", "st": "12.172"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων οἶδ’ ὅτι καλῶς γέγραφα καὶ συμφερόντως· ὅσον δ’ ἡ πόλις ἡμῶν διέφερε τὰ περὶ τὸν πόλεμον κατ’ ἐκεῖνον τὸν χρόνον, τοῦτο γὰρ ἀποδεῖξαι βουλόμενος διῆλθον τὰ γενόμενα Θήβῃσιν, ἡγοῦμαι τὴν πρᾶξιν ἐκείνην ἅπασι σαφῶς δηλοῦν, τὴν τὸν μὲν βασιλέα τὸν Ἀργείων ἀναγκάσασαν ἱκέτην γενέσθαι τῆς πόλεως τῆς ἡμετέρας, τοὺς δὲ κυρίους ὄντας Θηβῶν οὕτω διαθεῖσαν,", "st": "12.173"}, {"sp": "N", "t": "ὥστε ἑλέσθαι μᾶλλον αὐτοὺς ἐμμεῖναι τοῖς λόγοις τοῖς ὑπὸ τῆς πόλεως πεμφθεῖσιν ἢ τοῖς νόμοις τοῖς ὑπὸ τοῦ δαιμονίου κατασταθεῖσιν· ὧν οὐδὲν ἂν οἵα τ’ ἐγένετο διοικῆσαι κατὰ τρόπον ἡ πόλις ἡμῶν, εἰ μὴ καὶ τῇ δόξῃ καὶ τῇ δυνάμει πολὺ διήνεγκε τῶν ἄλλων.", "st": "12.174"}, {"sp": "N", "t": "ἔχων δὲ πολλὰς καὶ καλὰς πράξεις περὶ τῶν προγόνων εἰπεῖν, σκοποῦμαι τίνα τρόπον διαλεχθῶ περὶ αὐτῶν. μέλει γάρ μοι τούτων μᾶλλον ἢ τῶν ἄλλων· τυγχάνω γὰρ ὢν περὶ τὴν ὑπόθεσιν ἣν ἐποιησάμην τελευταίαν, ἐν ᾗ προεῖπον ὡς ἐπιδείξω τοὺς προγόνους ἡμῶν ἐν τοῖς πολέμοις καὶ ταῖς μάχαις πλέον διενεγκόντας Σπαρτιατῶν ἢ τοῖς ἄλλοις ἅπασιν.", "st": "12.175"}, {"sp": "N", "t": "ἔσται δ’ ὁ λόγος παράδοξος μὲν τοῖς πολλοῖς, ὁμοίως δ’ ἀληθὴς τοῖς ἄλλοις. ἄρτι μὲν οὖν ἠπόρουν ποτέρων διεξίω πρότερον τοὺς κινδύνους καὶ τὰς μάχας, τὰς Σπαρτιατῶν ἢ τὰς τῶν ἡμετέρων· νῦν δὲ προαιροῦμαι λέγειν τὰς ἐκείνων, ἵν’ ἐν ταῖς καλλίοσι καὶ δικαιοτέραις καταλύω τὸν λόγον τὸν περὶ τούτων.", "st": "12.176"}, {"sp": "N", "t": "ἐπειδὴ γὰρ Δωριέων οἱ στρατεύσαντες εἰς Πελοπόννησον τρίχα διείλοντο τάς τε πόλεις καὶ τὰς χώρας ἃς ἀφείλοντο τοὺς δικαίως κεκτημένους, οἱ μὲν Ἄργος λαχόντες καὶ Μεσσήνην παραπλησίως διῴκουν τὰ σφέτερ’ αὐτῶν τοῖς ἄλλοις Ἕλλησι, τὸ δὲ τρίτον μέρος αὐτῶν, οὓς καλοῦμεν νῦν Λακεδαιμονίους, στασιάσαι μέν φασιν αὐτοὺς οἱ τἀκείνων ἀκριβοῦντες ὡς οὐδένας ἄλλους τῶν Ἑλλήνων, περιγενομένους δὲ τοὺς μεῖζον τοῦ πλήθους φρονοῦντας οὐδὲν τῶν αὐτῶν βουλεύσασθαι περὶ τῶν συμβεβηκότων τοῖς τοιαῦτα διαπεπραγμένοις·", "st": "12.177"}, {"sp": "N", "t": "τοὺς μὲν γὰρ ἄλλους συνοίκους ἔχειν ἐν τῇ πόλει τοὺς στασιάσαντας καὶ κοινωνοὺς ἁπάντων πλὴν τῶν ἀρχῶν καὶ τῶν τιμῶν· οὓς οὐκ εὖ φρονεῖν ἡγεῖσθαι Σπαρτιατῶν τοὺς νοῦν ἔχοντας, εἰ νομίζουσιν ἀσφαλῶς πολιτεύεσθαι μετὰ τούτων οἰκοῦντες, περὶ οὓς τὰ μέγιστα τυγχάνουσιν ἐξημαρτηκότες· αὐτοὺς δ’ οὐδὲν τούτων ποιεῖν, ἀλλὰ παρὰ σφίσι μὲν αὐτοῖς ἰσονομίαν καταστῆσαι καὶ δημοκρατίαν τοιαύτην, οἵαν περ χρὴ τοὺς μέλλοντας ἅπαντα τὸν χρόνον ὁμονοήσειν, τὸν δὲ δῆμον περιοίκους ποιήσασθαι, καταδουλωσαμένους αὐτῶν τὰς ψυχὰς οὐδὲν ἧττον ἢ τὰς τῶν οἰκετῶν·", "st": "12.178"}, {"sp": "N", "t": "ταῦτα δὲ πράξαντας τῆς χώρας, ἧς προσῆκεν ἴσον ἔχειν ἕκαστον, αὐτοὺς μὲν λαβεῖν ὀλίγους ὄντας οὐ μόνον τὴν ἀρίστην, ἀλλὰ καὶ τοσαύτην ὅσην οὐδένες τῶν Ἑλλήνων ἔχουσι, τῷ δὲ πλήθει τηλικοῦτον ἀπονεῖμαι μέρος τῆς χειρίστης ὥστ’ ἐπιπόνως ἐργαζομένους μόλις ἔχειν τὸ καθ’ ἡμέραν· μετὰ δὲ ταῦτα διελόντας τὸ πλῆθος αὐτῶν ὡς οἷόν τ’ ἦν εἰς ἐλαχίστους εἰς τόπους κατοικίσαι μικροὺς καὶ πολλούς, ὀνόμασι μὲν προσαγορευομένους ὡς πόλεις οἰκοῦντας, τὴν δὲ δύναμιν ἔχοντας ἐλάττω τῶν δήμων τῶν παρ’ ἡμῖν·", "st": "12.179"}, {"sp": "N", "t": "ἁπάντων δ’ ἀποστερήσαντας αὐτοὺς ὧν προσήκει μετέχειν τοὺς ἐλευθέρους, τοὺς πλείστους ἐπιθεῖναι τῶν κινδύνων αὐτοῖς· ἔν τε γὰρ ταῖς στρατείαις, αἷς ἡγεῖται βασιλεύς, κατ’ ἄνδρα συμπαρατάττεσθαι σφίσιν αὐτοῖς, ἐνίους δὲ καὶ τῆς πρώτης τάττειν, ἐάν τέ που δεῆσαν αὐτοὺς ἐκπέμψαι βοήθειαν φοβηθῶσιν ἢ τοὺς πόνους ἢ τοὺς κινδύνους ἢ τὸ πλῆθος τοῦ χρόνου, τούτους ἀποστέλλειν προκινδυνεύσοντας τῶν ἄλλων.", "st": "12.180"}, {"sp": "N", "t": "καὶ τί δεῖ μακρολογεῖν ἁπάσας διεξιόντα τὰς ὕβρεις τὰς περὶ τὸ πλῆθος γιγνομένας, ἀλλὰ μὴ τὸ μέγιστον εἰπόντα τῶν κακῶν ἀπαλλαγῆναι τῶν ἄλλων; τῶν γὰρ οὕτω μὲν ἐξ ἀρχῆς δεινὰ πεπονθότων, ἐν δὲ τοῖς παροῦσι καιροῖς χρησίμων ὄντων, ἔξεστι τοῖς ἐφόροις ἀκρίτους ἀποκτεῖναι τοσούτους ὁπόσους ἂν βουληθῶσιν· ἃ τοῖς ἄλλοις Ἕλλησιν οὐδὲ τοὺς πονηροτάτους τῶν οἰκετῶν ὅσιόν ἐστι μιαιφονεῖν.", "st": "12.181"}, {"sp": "N", "t": "τούτου δ’ ἕνεκα περὶ τῆς οἰκειότητος καὶ τῶν ἡμαρτημένων εἰς αὐτοὺς διὰ πλειόνων διῆλθον, ἵν’ ἔρωμαι τοὺς ἀποδεχομένους ἁπάσας τὰς Σπαρτιατῶν πράξεις, εἰ καὶ ταύτας ἀποδέχονται, καὶ τὰς μάχας εὐσεβεῖς εἶναι νομίζουσι καὶ καλὰς τὰς πρὸς τούτους γεγενημένας.", "st": "12.182"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ ἡγοῦμαι μεγάλας μὲν αὐτὰς γεγενῆσθαι καὶ δεινὰς καὶ πολλῶν αἰτίας τοῖς μὲν ἡττηθεῖσι κακῶν τοῖς δὲ κατορθώσασι λημμάτων, ὧνπερ ἕνεκα πολεμοῦντες ἅπαντα τὸν χρόνον διατελοῦσιν, οὐ μὴν ὁσίας οὐδὲ καλὰς οὐδὲ πρεπούσας τοῖς ἀρετῆς ἀντιποιουμένοις, μὴ τῆς ἐπὶ τῶν τεχνῶν ὀνομαζομένης καὶ πολλῶν ἄλλων, ἀλλὰ τῆς τοῖς καλοῖς κἀγαθοῖς τῶν ἀνδρῶν ἐν ταῖς ψυχαῖς μετ’ εὐσεβείας καὶ δικαιοσύνης ἐγγιγνομένης, περὶ ἧς ἅπας ὁ λόγος ἐστίν.", "st": "12.183"}, {"sp": "N", "t": "ἧς ὀλιγωροῦντές τινες ἐγκωμιάζουσι τοὺς πλείω τῶν ἄλλων ἡμαρτηκότας, καὶ οὐκ αἰσθάνονται τὰς διανοίας ἐπιδεικνύντες τὰς σφετέρας αὐτῶν, ὅτι κἀκείνους ἂν ἐπαινέσειαν, τοὺς πλείω μὲν κεκτημένους τῶν ἱκανῶν, ἀποκτεῖναι δ’ ἂν τολμήσαντας τοὺς ἀδελφοὺς τοὺς ἑαυτῶν καὶ τοὺς ἑταίρους καὶ τοὺς κοινωνοὺς ὥστε καὶ τἀκείνων λαβεῖν· ὅμοια γὰρ τὰ τοιαῦτα τῶν ἔργων ἐστὶ τοῖς ὑπὸ Σπαρτιατῶν πεπραγμένοις, ἃ τοὺς ἀποδεχομένους ἀναγκαῖόν ἐστι καὶ περὶ τῶν εἰρημένων ἄρτι τὴν αὐτὴν ἔχειν γνώμην.", "st": "12.184"}, {"sp": "N", "t": "θαυμάζω δ’ εἴ τινες τὰς μάχας καὶ τὰς νίκας τὰς παρὰ τὸ δίκαιον γιγνομένας μὴ νομίζουσιν αἰσχίους εἶναι καὶ πλειόνων ὀνειδῶν μεστὰς ἢ τὰς ἥττας τὰς ἄνευ κακίας συμβαινούσας, καὶ τοῦτ’ εἰδότες ὅτι μεγάλαι δυνάμεις πονηραὶ δὲ πολλάκις γίγνονται κρείττους ἀνδρῶν σπουδαίων καὶ κινδυνεύειν ὑπὲρ τῆς πατρίδος αἱρουμένων.", "st": "12.185"}, {"sp": "N", "t": "οὓς πολὺ ἂν δικαιότερον ἐπαινοῖμεν ἢ τοὺς περὶ τῶν ἀλλοτρίων ἑτοίμως ἀποθνήσκειν ἐθέλοντας καὶ τοῖς ξενικοῖς στρατεύμασιν ὁμοίους ὄντας· ταῦτα μὲν γάρ ἐστιν ἔργα πονηρῶν ἀνθρώπων, τὸ δὲ τοὺς χρηστοὺς ἐνίοτε χεῖρον ἀγωνίζεσθαι τῶν ἀδικεῖν βουλομένων θεῶν ἄν τις ἀμέλειαν εἶναι φήσειεν.", "st": "12.186"}, {"sp": "N", "t": "ἔχοιμι δ’ ἂν τῷ λόγῳ τούτῳ χρήσασθαι καὶ περὶ τῆς συμφορᾶς τῆς Σπαρτιάταις ἐν Θερμοπύλαις γενομένης, ἣν ἅπαντες ὅσοι περ ἀκηκόασιν ἐπαινοῦσι καὶ θαυμάζουσι μᾶλλον ἢ τὰς μάχας καὶ τὰς νίκας τὰς κρατησάσας μὲν τῶν ἐναντίων, πρὸς οὓς δ’ οὐκ ἐχρῆν γεγενημένας· ἃς εὐλογεῖν τινες τολμῶσι, κακῶς εἰδότες ὡς οὐδὲν οὔθ’ ὅσιον οὔτε καλόν ἐστι τῶν μὴ μετὰ δικαιοσύνης καὶ λεγομένων καὶ πραττομένων.", "st": "12.187"}, {"sp": "N", "t": "ὧν Σπαρτιάταις μὲν οὐδὲν πώποτ’ ἐμέλησεν· βλέπουσι γὰρ εἰς οὐδὲν ἄλλο πλὴν ὅπως ὡς πλεῖστα τῶν ἀλλοτρίων κατασχήσουσιν· οἱ δ’ ἡμέτεροι περὶ οὐδὲν οὕτω τῶν ὄντων ἐσπούδαζον ὡς τὸ παρὰ τοῖς Ἕλλησιν εὐδοκιμεῖν· ἡγοῦντο γὰρ οὐδεμίαν ἂν γενέσθαι κρίσιν οὔτ’ ἀληθεστέραν οὔτε δικαιοτέραν τῆς ὑπὸ παντὸς τοῦ γένους γνωσθείσης.", "st": "12.188"}, {"sp": "N", "t": "δῆλοι δ’ ἦσαν οὕτως ἔχοντες ἔν τε τοῖς ἄλλοις οἷς διῴκουν τὴν πόλιν, καὶ τοῖς μεγίστοις τῶν πραγμάτων. τριῶν γὰρ πολέμων γενομένων ἄνευ τοῦ Τρωικοῦ τοῖς Ἕλλησι πρὸς τοὺς βαρβάρους, ἐν ἅπασι τούτοις πρωτεύουσαν αὐτὴν παρέσχον. ὧν εἷς μὲν ἦν ὁ πρὸς Ξέρξην, ἐν ᾧ πλέον διήνεγκαν Λακεδαιμονίων ἐν ἅπασι τοῖς κινδύνοις ἢ ’κεῖνοι τῶν ἄλλων,", "st": "12.189"}, {"sp": "N", "t": "δεύτερος δ’ ὁ περὶ τὴν κτίσιν τῶν ἀποικιῶν, εἰς ὃν Δωριέων μὲν οὐδεὶς ἦλθε συμπολεμήσων, ἡ δὲ πόλις ἡμῶν ἡγεμὼν καταστᾶσα τῶν οὐκ εὐπορούντων καὶ τῶν ἄλλων τῶν βουλομένων τοσοῦτον τὰ πράγματα μετέστησεν, ὥστ’ εἰθισμένων τῶν βαρβάρων τὸν ἄλλον χρόνον τὰς μεγίστας πόλεις τῶν Ἑλληνίδων καταλαμβάνειν ἐποίησε τοὺς Ἕλληνας, ἃ πρότερον ἔπασχον, ταῦτα δύνασθαι ποιεῖν.", "st": "12.190"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῖν δυοῖν πολέμοιν ἐν τοῖς ἔμπροσθεν ἱκανῶς εἰρήκαμεν, περὶ δὲ τοῦ τρίτου ποιήσομαι τοὺς λόγους, ὃς ἐγένετο τῶν μὲν Ἑλληνίδων πόλεων ἄρτι κατῳκισμένων, τῆς δ’ ἡμετέρας ἔτι βασιλευομένης. ἐφ’ ὧν καὶ πόλεμοι πλεῖστοι καὶ κίνδυνοι μέγιστοι συνέπεσον, οὓς ἅπαντας μὲν οὔθ’ εὑρεῖν οὔτ’ εἰπεῖν ἂν δυνηθείην,", "st": "12.191"}, {"sp": "N", "t": "παραλιπὼν δὲ τὸν πλεῖστον ὄχλον τῶν ἐν ἐκείνῳ μὲν τῷ χρόνῳ πραχθέντων ῥηθῆναι δὲ νῦν οὐ κατεπειγόντων, ὡς ἂν δύνωμαι συντομώτατα πειράσομαι δηλῶσαι τούς τ’ ἐπιστρατεύσαντας τῇ πόλει καὶ τὰς μάχας τὰς ἀξίας μνημονευθῆναι καὶ ῥηθῆναι καὶ τοὺς ἡγεμόνας αὐτῶν, ἔτι δὲ τὰς προφάσεις ἃς ἔλεγον, καὶ τὴν δύναμιν τῶν γενῶν τῶν συνακολουθησάντων αὐτοῖς· ἱκανὰ γὰρ ἔσται ταῦτ’ εἰπεῖν πρὸς οἷς περὶ τῶν ἐναντίων εἰρήκαμεν.", "st": "12.192"}, {"sp": "N", "t": "Θρᾷκες μὲν γὰρ μετ’ Εὐμόλπου τοῦ Ποσειδῶνος εἰσέβαλον εἰς τὴν χώραν ἡμῶν, ὃς ἠμφισβήτησεν Ἐρεχθεῖ τῆς πόλεως, φάσκων Ποσειδῶ πρότερον Ἀθηνᾶς καταλαβεῖν αὐτήν· Σκύθαι δὲ μετ’ Ἀμαζόνων τῶν ἐξ Ἄρεως γενομένων, αἳ τὴν στρατείαν ἐφ’ Ἱππολύτην ἐποιήσαντο, τὴν τούς τε νόμους παραβᾶσαν τοὺς παρ’ αὐταῖς κειμένους, ἐρασθεῖσάν τε Θησέως καὶ συνακολουθήσασαν ἐκεῖθεν καὶ συνοικήσασαν αὐτῷ·", "st": "12.193"}, {"sp": "N", "t": "Πελοποννήσιοι δὲ μετ’ Εὐρυσθέως, ὃς Ἡρακλεῖ μὲν οὐκ ἔδωκε δίκην ὧν ἡμάρτανεν εἰς αὐτόν, στρατεύσας δ’ ἐπὶ τοὺς ἡμετέρους προγόνους ὡς ἐκληψόμενος βίᾳ τοὺς ἐκείνου παῖδας, παρ’ ἡμῖν γὰρ ἦσαν καταπεφευγότες, ἔπαθεν ἃ προσῆκεν αὐτόν. τοσούτου γὰρ ἐδέησε κύριος γενέσθαι τῶν ἱκετῶν, ὥστε ἡττηθεὶς μάχῃ καὶ ζωγρηθεὶς ὑπὸ τῶν ἡμετέρων, αὐτὸς ἱκέτης γενόμενος τούτων οὓς ἐξαιτῶν ἦλθε, τὸν βίον ἐτελεύτησεν.", "st": "12.194"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον οἱ πεμφθέντες ὑπὸ Δαρείου τὴν Ἑλλάδα πορθήσοντες, ἀποβάντες εἰς Μαραθῶνα, πλείοσι κακοῖς καὶ μείζοσι συμφοραῖς περιπεσόντες ὧν ἤλπισαν τὴν πόλιν ἡμῶν ποιήσειν, ᾤχοντο φεύγοντες ἐξ ἁπάσης τῆς Ἑλλάδος.", "st": "12.195"}, {"sp": "N", "t": "τούτους δ’ ἅπαντας οὓς διῆλθον, οὐ μετ’ ἀλλήλων εἰσβαλόντας οὐδὲ κατὰ τοὺς αὐτοὺς χρόνους, ἀλλ’ ὡς οἵ τε καιροὶ καὶ τὸ συμφέρον ἑκάστοις καὶ τὸ βούλεσθαι συνέπιπτε, μάχῃ νικήσαντες καὶ τῆς ὕβρεως παύσαντες, οὐκ ἐξέστησαν αὑτῶν τηλικαῦτα διαπραξάμενοι τὸ μέγεθος, οὐδ’ ἔπαθον ταὐτὸ τοῖς διὰ μὲν τὸ καλῶς καὶ φρονίμως βουλεύσασθαι καὶ πλούτους μεγάλους καὶ δόξας καλὰς κτησαμένοις, διὰ δὲ τὰς ὑπερβολὰς τὰς τούτων ὑπερηφάνοις γενομένοις καὶ τὴν φρόνησιν διαφθαρεῖσι καὶ κατενεχθεῖσιν εἰς χείρω πράγματα καὶ ταπεινότερα τῶν πρότερον αὐτοῖς ὑπαρχόντων,", "st": "12.196"}, {"sp": "N", "t": "ἀλλὰ πάντα τὰ τοιαῦτα διαφυγόντες ἐνέμειναν τοῖς ἤθεσιν οἷς εἶχον διὰ τὸ πολιτεύεσθαι καλῶς, μεῖζον φρονοῦντες ἐπὶ τῇ τῆς ψυχῆς ἕξει καὶ ταῖς διανοίαις ταῖς αὑτῶν ἢ ταῖς μάχαις ταῖς γεγενημέναις, καὶ μᾶλλον ὑπὸ τῶν ἄλλων θαυμαζόμενοι διὰ τὴν καρτερίαν ταύτην καὶ σωφροσύνην ἢ διὰ τὴν ἀνδρίαν τὴν ἐν τοῖς κινδύνοις αὐτοῖς παραγενομένην·", "st": "12.197"}, {"sp": "N", "t": "ἑώρων γὰρ πάντες τὴν μὲν εὐψυχίαν τὴν πολεμικὴν πολλοὺς ἔχοντας καὶ τῶν ταῖς κακουργίαις ὑπερβαλλόντων, τῆς δὲ χρησίμης ἐπὶ πᾶσι καὶ πάντας δυναμένης ὠφελεῖν οὐ κοινωνοῦντας τοὺς πονηρούς, ἀλλὰ μόνοις ἐγγιγνομένην τοῖς καλῶς γεγονόσι καὶ τεθραμμένοις καὶ πεπαιδευμένοις, ἅπερ προσῆν τοῖς τότε τὴν πόλιν διοικοῦσι καὶ τῶν εἰρημένων ἀγαθῶν ἁπάντων αἰτίοις καταστᾶσιν.", "st": "12.198"}, {"sp": "N", "t": "τοὺς μὲν οὖν ἄλλους ὁρῶ περὶ τὰ μέγιστα τῶν ἔργων καὶ μάλιστα μνημονευθησόμενα τοὺς λόγους καταλύοντας, ἐγὼ δὲ σωφρονεῖν μὲν νομίζω τοὺς ταῦτα γιγνώσκοντας καὶ πράττοντας, οὐ μὴν συμβαίνει μοι ταὐτὸ ποιεῖν ἐκείνοις, ἀλλ’ ἔτι λέγειν ἀναγκάζομαι. τὴν δ’ αἰτίαν δι’ ἥν, ὀλίγον ὕστερον ἐρῶ, μικρὰ πάνυ προδιαλεχθείς.", "st": "12.199"}, {"sp": "N", "t": "ἐπηνώρθουν μὲν γὰρ τὸν λόγον τὸν μέχρι τῶν ἀναγνωσθέντων γεγραμμένον μετὰ μειρακίων τριῶν ἢ τεττάρων τῶν εἰθισμένων μοι συνδιατρίβειν· ἐπειδὴ δὲ διεξιοῦσιν ἡμῖν ἐδόκει καλῶς ἔχειν καὶ προσδεῖσθαι τελευτῆς μόνον, ἔδοξέ μοι μεταπέμψασθαί τινα τῶν ἐμοὶ μὲν πεπλησιακότων, ἐν ὀλιγαρχίᾳ δὲ πεπολιτευμένον, προῃρημένον δὲ Λακεδαιμονίους ἐπαινεῖν, ἵν’ εἴ τι παρέλαθεν ἡμᾶς ψεῦδος εἰρημένον, ἐκεῖνος κατιδὼν δηλώσειεν ἡμῖν.", "st": "12.200"}, {"sp": "N", "t": "ἐλθὼν δ’ ὁ κληθεὶς καὶ διαναγνοὺς τὸν λόγον (τὰ γὰρ μεταξὺ τί δεῖ λέγοντα διατρίβειν;), ἐδυσχέρανε μὲν ἐπ’ οὐδενὶ τῶν γεγραμμένων, ἐπῄνεσε δ’ ὡς δυνατὸν μάλιστα, καὶ διελέχθη περὶ ἑκάστου τῶν μερῶν παραπλησίως οἷς ἡμεῖς ἐγιγνώσκομεν· οὐ μὴν ἀλλὰ φανερὸς ἦν οὐχ ἡδέως ἔχων ἐπὶ τοῖς περὶ Λακεδαιμονίων εἰρημένοις.", "st": "12.201"}, {"sp": "N", "t": "ἐδήλωσε δὲ διὰ ταχέων· ἐτόλμησε γὰρ εἰπεῖν ὡς εἰ καὶ μηδὲν ἄλλο πεποιήκασι τοὺς Ἕλληνας ἀγαθόν, ἀλλ’ οὖν ἐκεῖνό γε δικαίως ἂν αὐτοῖς ἅπαντες χάριν ἔχοιεν, ὅτι τὰ κάλλιστα τῶν ἐπιτηδευμάτων εὑρόντες αὐτοί τε χρῶνται καὶ τοῖς ἄλλοις κατέδειξαν.", "st": "12.202"}, {"sp": "N", "t": "τοῦτο δὲ ῥηθὲν οὕτω βραχὺ καὶ μικρὸν αἴτιον ἐγένετο τοῦ μήτε καταλῦσαί με τὸν λόγον ἐφ’ ὧν ἐβουλήθην, ὑπολαβεῖν θ’ ὡς αἰσχρὸν ποιήσω καὶ δεινόν, εἰ παρὼν περιόψομαί τινα τῶν ἐμοὶ πεπλησιακότων πονηροῖς λόγοις χρώμενον. ταῦτα δὲ διανοηθεὶς ἠρόμην αὐτὸν εἰ μηδὲν φροντίζει τῶν παρόντων, μηδ’ αἰσχύνεται λόγον εἰρηκὼς ἀσεβῆ καὶ ψευδῆ καὶ πολλῶν ἐναντιώσεων μεστόν.", "st": "12.203"}, {"sp": "N", "t": "“γνώσει δ’ ὡς ἔστι τοιοῦτος, ἢν ἐρωτήσῃς τινὰς τῶν εὖ φρονούντων ποῖα τῶν ἐπιτηδευμάτων κάλλιστα νομίζουσιν εἶναι, καὶ μετὰ ταῦτα πόσος χρόνος ἐστὶν ἐξ οὗ Σπαρτιᾶται τυγχάνουσιν ἐν Πελοποννήσῳ κατοικοῦντες. οὐδεὶς γὰρ ὅστις οὐ τῶν μὲν ἐπιτηδευμάτων προκρινεῖ τὴν εὐσέβειαν τὴν περὶ τοὺς θεοὺς καὶ τὴν δικαιοσύνην τὴν περὶ τοὺς ἀνθρώπους καὶ τὴν φρόνησιν τὴν περὶ τὰς ἄλλας πράξεις, Σπαρτιάτας δ’ ἐνταῦθα κατοικεῖν οὐ πλείω φήσουσιν ἐτῶν ἑκτακοσίων.", "st": "12.204"}, {"sp": "N", "t": "τούτων δ’ οὕτως ἐχόντων, εἰ μὲν τυγχάνεις ἀληθῆ λέγων τούτους φάσκων εὑρετὰς γεγενῆσθαι τῶν καλλίστων ἐπιτηδευμάτων, ἀναγκαῖόν ἐστι τοὺς πολλαῖς γενεαῖς πρότερον γεγονότας, πρὶν Σπαρτιάτας ἐνταῦθα κατοικῆσαι, μὴ μετέχειν αὐτῶν, μήτε τοὺς ἐπὶ Τροίαν στρατευσαμένους μήτε τοὺς περὶ Ἡρακλέα καὶ Θησέα γεγονότας μήτε Μίνω τὸν Διὸς μήτε Ῥαδάμανθυν μήτ’ Αἰακὸν μήτε τῶν ἄλλων μηδένα τῶν ὑμνουμένων ἐπὶ ταῖς ἀρεταῖς ταύταις, ἀλλὰ ψευδῆ τὴν δόξαν ταύτην ἅπαντας ἔχειν· εἰ δὲ σὺ μὲν φλυαρῶν τυγχάνεις,", "st": "12.205"}, {"sp": "N", "t": "προσήκει δὲ τοὺς ἀπὸ θεῶν γεγονότας καὶ χρῆσθαι ταύταις μᾶλλον τῶν ἄλλων καὶ καταδεῖξαι τοῖς ἐπιγιγνομένοις, οὐκ ἔστιν ὅπως οὐ μαίνεσθαι δόξεις ἅπασι τοῖς ἀκούσασιν, οὕτως εἰκῇ καὶ παρανόμως οὓς ἂν τύχῃς ἐπαινῶν. ἔπειτ’ εἰ μὲν εὐλόγεις αὐτοὺς οὐδὲν ἀκηκοὼς τῶν ἐμῶν, ἐλήρεις μὲν ἄν, οὐ μὴν ἐναντία γε λέγων ἐφαίνου σαυτῷ·", "st": "12.206"}, {"sp": "N", "t": "νῦν δ’ ἐπῃνεκότι σοι τὸν ἐμὸν λόγον, τὸν ἐπιδεικνύντα πολλὰ καὶ δεινὰ Δακεδαιμονίους περὶ τε τοὺς συγγενεῖς τοὺς αὑτῶν καὶ περὶ τοὺς ἄλλους Ἕλληνας διαπεπραγμένους, πῶς οἷόν τ’ ἦν ἔτι σοὶ λέγειν τοὺς ἐνόχους ὄντας τούτοις, ὡς τῶν καλλίστων ἐπιτηδευμάτων ἡγεμόνες γεγόνασιν;", "st": "12.207"}, {"sp": "N", "t": "πρὸς δὲ τούτοις κἀκεῖνό σε λέληθεν, ὅτι τὰ παραλελειμμένα τῶν ἐπιτηδευμάτων καὶ τῶν τεχνῶν καὶ τῶν ἄλλων ἁπάντων οὐχ οἱ τυχόντες εὑρίσκουσιν, ἀλλ’ οἱ τάς τε φύσεις διαφέροντες καὶ μαθεῖν πλεῖστα τῶν πρότερον εὑρημένων δυνηθέντες καὶ προσέχειν τὸν νοῦν τῷ ζητεῖν μᾶλλον τῶν ἄλλων ἐθελήσαντες.", "st": "12.208"}, {"sp": "N", "t": "ὧν Λακεδαιμόνιοι πλέον ἀπέχουσι τῶν βαρβάρων· οἱ μὲν γὰρ ἂν φανεῖεν πολλῶν εὑρημάτων καὶ μαθηταὶ καὶ διδάσκαλοι γεγονότες, οὗτοι δὲ τοσοῦτον ἀπολελειμμένοι τῆς κοινῆς παιδείας καὶ φιλοσοφίας εἰσὶν ὥστ’ οὐδὲ γράμματα μανθάνουσιν, ἃ τηλικαύτην ἔχει δύναμιν ὥστε τοὺς ἐπισταμένους καὶ χρωμένους αὐτοῖς μὴ μόνον ἐμπείρους γίγνεσθαι τῶν ἐπὶ τῆς ἡλικίας τῆς αὑτῶν πραχθέντων ἀλλὰ καὶ τῶν πώποτε γενομένων.", "st": "12.209"}, {"sp": "N", "t": "ἀλλ’ ὅμως σὺ καὶ τοὺς τῶν τοιούτων ἀμαθεῖς ὄντας ἐτόλμησας εἰπεῖν ὡς εὑρεταὶ τῶν καλλίστων ἐπιτηδευμάτων γεγόνασι, καὶ ταῦτ’ εἰδὼς ὅτι τοὺς παῖδας τοὺς ἑαυτῶν ἐθίζουσι περὶ τοιαύτας πραγματείας διατρίβειν, ἐξ ὧν ἐλπίζουσιν αὐτοὺς οὐκ εὐεργέτας γενήσεσθαι τῶν ἄλλων, ἀλλὰ κακῶς ποιεῖν μάλιστα δυνήσεσθαι τοὺς Ἕλληνας.", "st": "12.210"}, {"sp": "N", "t": "ἃς πάσας μὲν διεξιὼν πολὺν ὄχλον ἐμαυτῷ τ’ ἂν παράσχοιμι καὶ τοῖς ἀκούουσιν, μίαν δὲ μόνον εἰπών, ἣν ἀγαπῶσι καὶ περὶ ἣν μάλιστα σπουδάζουσιν, οἶμαι δηλώσειν ἅπαντα τὸν τρόπον αὐτῶν. ἐκεῖνοι γὰρ καθ’ ἑκάστην τὴν ἡμέραν εὐθὺς ἐξ εὐνῆς ἐκπέμπουσι τοὺς παῖδας, μεθ’ ὧν ἂν ἕκαστοι βουληθῶσι, λόγῳ μὲν ἐπὶ θήραν, ἔργῳ δ’ ἐπὶ κλωπείαν τῶν ἐν τοῖς ἀγροῖς κατοικούντων·", "st": "12.211"}, {"sp": "N", "t": "ἐν ᾗ συμβαίνει τοὺς μὲν ληφθέντας ἀργύριον ἀποτίνειν καὶ πληγὰς λαμβάνειν, τοὺς δὲ πλεῖστα κακουργήσαντας καὶ λαθεῖν δυνηθέντας ἔν τε τοῖς παισὶν εὐδοκιμεῖν μᾶλλον τῶν ἄλλων, ἐπειδὰν δ’ εἰς ἄνδρας συντελῶσιν, ἢν ἐμμείνωσι τοῖς ἤθεσιν οἷς παῖδες ὄντες ἐμελέτησαν, ἐγγὺς εἶναι τῶν μεγίστων ἀρχῶν.", "st": "12.212"}, {"sp": "N", "t": "καὶ ταύτης ἤν τις ἐπιδείξῃ παιδείαν μᾶλλον ἀγαπωμένην ἢ σπουδαιοτέραν παρ’ αὐτοῖς εἶναι νομιζομένην, ὁμολογῶ μηδὲν ἀληθὲς εἰρηκέναι μηδὲ περὶ ἑνὸς πώποτε πράγματος. καίτοι τί τῶν τοιούτων ἔργων καλόν ἐστιν ἢ σεμνόν, ἀλλ’ οὐκ αἰσχύνης ἄξιον; πῶς δ’ οὐκ ἀνοήτους χρὴ νομίζειν τοὺς ἐπαινοῦντας τοὺς τοσοῦτον τῶν νόμων τῶν κοινῶν ἐξεστηκότας καὶ μηδὲν τῶν αὐτῶν μήτε τοῖς Ἕλλησι μήτε τοῖς βαρβάροις γιγνώσκοντας;", "st": "12.213"}, {"sp": "N", "t": "οἱ μὲν γὰρ ἄλλοι τοὺς κακουργοῦντας καὶ κλέπτοντας πονηροτέρους τῶν οἰκετῶν νομίζουσιν, ἐκεῖνοι δὲ τοὺς ἐν τοῖς τοιούτοις τῶν ἔργων πρωτεύοντας βελτίστους εἶναι τῶν παίδων ὑπολαμβάνουσι καὶ μάλιστα τιμῶσιν. καίτοι τίς ἂν τῶν εὖ φρονούντων οὐκ ἂν τρὶς ἀποθανεῖν ἕλοιτο μᾶλλον, ἢ διὰ τοιούτων ἐπιτηδευμάτων γνωσθῆναι τὴν ἄσκησιν τῆς ἀρετῆς ποιούμενος;”", "st": "12.214"}, {"sp": "N", "t": "ταῦτ’ ἀκούσας θρασέως μὲν οὐδὲ πρὸς ἓν ἀντεῖπε τῶν εἰρημένων, οὐδ’ αὖ παντάπασιν ἀπεσιώπησεν, ἀλλ’ ἔλεγεν ὅτι “οὐ μὲν πεποίησαι τοὺς λόγουσ” ἐμὲ λέγων “ὡς ἅπαντ’ ἀποδεχομένου μου τἀκεῖ καὶ καλῶς ἔχειν νομίζοντος· ἐμοὶ δὲ δοκεῖς περὶ μὲν τῆς τῶν παίδων αὐτονομίας καὶ περὶ ἄλλων πολλῶν εἰκότως ἐπιτιμᾶν ἐκείνοις,", "st": "12.215"}, {"sp": "N", "t": "ἐμοῦ δ’ οὐ δικαίως κατηγορεῖν. ἐγὼ γὰρ ἐλυπήθην μὲν τὸν λόγον ἀναγιγνώσκων ἐπὶ τοῖς περὶ Λακεδαιμονίων εἰρημένοις, οὐ μὴν οὕτως ὡς ἐπὶ τῷ μηδὲν ἀντειπεῖν ὑπὲρ αὐτῶν δύνασθαι τοῖς γεγραμμένοις, εἰθισμένος τὸν ἄλλον χρόνον ἐπαινεῖν. εἰς τοιαύτην δ’ ἀπορίαν καταστὰς εἶπον ὅπερ ἦν λοιπόν, ὡς εἰ καὶ μηδὲν δι’ ἄλλο, διά γ’ ἐκεῖνο δικαίως ἂν αὐτοῖς ἅπαντες χάριν ἔχοιμεν, ὅτι τοῖς καλλίστοις τῶν ἐπιτηδευμάτων χρώμενοι τυγχάνουσιν.", "st": "12.216"}, {"sp": "N", "t": "ταῦτα δ’ εἶπον οὐ πρὸς τὴν εὐσέβειαν οὐδὲ πρὸς τὴν δικαιοσύνην οὐδὲ πρὸς τὴν φρόνησιν ἀποβλέψας, ἃ σὺ διῆθες, ἀλλὰ πρὸς τὰ γυμνάσια τἀκεῖ καθεστηκότα καὶ πρὸς τὴν ἄσκησιν τῆς ἀνδρίας καὶ τὴν ὁμόνοιαν καὶ συνόλως τὴν περὶ τὸν πόλεμον ἐπιμέλειαν, ἅπερ ἅπαντες ἂν ἐπαινοῖεν, καὶ μάλιστ’ ἂν αὐτοῖς ἐκείνους χρῆσθαι φήσειαν.”", "st": "12.217"}, {"sp": "N", "t": "ταῦτα δ’ αὐτοῦ διαλεχθέντος ἀπεδεξάμην μέν, οὐχ ὡς διαλυόμενόν τι τῶν κατηγορημένων, ἀλλ’ ὡς ἀποκρυπτόμενον τὸ πικρότατον τῶν τότε ῥηθέντων οὐκ ἀπαιδεύτως ἀλλὰ νοῦν ἐχόντως, καὶ περὶ τῶν ἄλλων ἀπολελογημένον σωφρονέστερον ἢ τότε παρρησιασάμενον· οὐ μὴν ἀλλ’ ἐκεῖν’ ἐάσας περὶ αὐτῶν τούτων ἔφασκον κατηγορίαν ἔχειν πολὺ δεινοτέραν ἢ περὶ τῆς τῶν παίδων κλωπείας.", "st": "12.218"}, {"sp": "N", "t": "“ἐκείνοις μὲν γὰρ τοῖς ἐπιτηδεύμασιν ἐλυμαίνοντο τοὺς αὑτῶν παῖδας, οἷς δ’ ὀλίγῳ πρότερον σὺ διῆλθες, τοὺς Ἕλληνας ἀπώλλυσαν. ῥᾴδιον δ’, ὡς οὕτως εἶχε ταῦτα, συνιδεῖν. οἶμαι γὰρ ἅπαντας ἂν ὁμολογῆσαι κακίστους ἄνδρας εἶναι καὶ μεγίστης ζημίας ἀξίους, ὅσοι τοῖς πράγμασι τοῖς εὑρημένοις ἐπ’ ὠφελίᾳ, τούτοις ἐπὶ βλάβῃ χρώμενοι τυγχάνουσι,", "st": "12.219"}, {"sp": "N", "t": "μὴ πρὸς τοὺς βαρβάρους μηδὲ πρὸς τοὺς ἁμαρτάνοντας μηδὲ πρὸς τοὺς εἰς τὴν αὑτῶν χώραν εἰσβάλλοντας, ἀλλὰ πρὸς τοὺς οἰκειοτάτους καὶ τῆς αὐτῆς συγγενείας μετέχοντας· ἅπερ ἐποίουν Ξπαρτιᾶται. καίτοι πῶς ὅσιόν ἐστι φάσκειν καλῶς χρῆσθαι τοῖς περὶ τὸν πόλεμον ἐπιτηδεύμασιν, οἵτινες οὓς προσῆκε σώζειν, τούτους ἀπολλύοντες ἅπαντα τὸν χρόνον διετέλεσαν;", "st": "12.220"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐ σὺ μόνος ἀγνοεῖς τοὺς καλῶς χρωμένους τοῖς πράγμασιν, ἀλλὰ σχεδὸν οἱ πλεῖστοι τῶν Ἑλλήνων. ἐπειδὰν γάρ τινας ἴδωσιν ἢ πύθωνται παρά τινων ἐπιμελῶς διατρίβοντας περὶ τὰ δοκοῦντ’ εἶναι καλὰ τῶν ἐπιτηδευμάτων, ἐπαινοῦσι καὶ πολλοὺς λόγους ποιοῦνται περὶ αὐτῶν, οὐκ εἰδότες τὸ συμβησόμενον.", "st": "12.221"}, {"sp": "N", "t": "χρὴ δὲ τοὺς ὀρθῶς δοκιμάζειν βουλομένους περὶ τῶν τοιούτων ἐν ἀρχῇ μὲν ἡσυχίαν ἄγειν καὶ μηδεμίαν δόξαν ἔχειν περὶ αὐτῶν, ἐπειδὰν δ’ εἰς τὸν χρόνον ἐκεῖνον ἔλθωσιν, ἐν ᾧ καὶ λέγοντας καὶ πράττοντας αὐτοὺς ὄψονται καὶ περὶ τῶν ἰδίων καὶ περὶ τῶν κοινῶν, τότε θεωρεῖν ἀκριβῶς ἕκαστον αὐτῶν,", "st": "12.222"}, {"sp": "N", "t": "καὶ τοὺς μὲν νομίμως καὶ καλῶς χρωμένους οἷς ἐμελέτησαν ἐπαινεῖν καὶ τιμᾶν, τοὺς δὲ πλημμελοῦντας καὶ κακουργοῦντας ψέγειν καὶ μισεῖν καὶ φυλάττεσθαι τὸν τρόπον αὐτῶν, ἐνθυμουμένους ὡς οὐχ αἱ φύσεις αἱ τῶν πραγμάτων οὔτ’ ὠφελοῦσιν οὔτε βλάπτουσιν ἡμᾶς, ἀλλ’ ὡς αἱ τῶν ἀνθρώπων χρήσεις καὶ πράξεις ἁπάντων ἡμῖν αἴτιαι τῶν συμβαινόντων εἰσίν.", "st": "12.223"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις ἐκεῖθεν· τὰ γὰρ αὐτὰ πανταχῇ καὶ μηδαμῇ διαφέροντα τοῖς μὲν ὠφέλιμα τοῖς δὲ βλαβερὰ γίγνεται. καίτοι τὴν μὲν φύσιν ἕκαστον τῶν ὄντων τὴν ἐναντίαν αὐτὴν αὑτῇ καὶ μὴ αὐτὴν οὐκ εὔκολόν ἐστιν· τὸ δὲ μηδὲν τῶν αὐτῶν συμβαίνειν τοῖς ὀρθῶς καὶ δικαίως πράττουσι καὶ τοῖς ἀσελγῶς τε καὶ κακῶς, τίνι τῶν ὀρθῶς λογιζομένων οὐκ ἂν εἰκότως ταῦτα γίγνεσθαι δόξειεν;", "st": "12.224"}, {"sp": "N", "t": "ὁ δ’ αὐτὸς οὗτος λόγος καὶ περὶ τὰς ὁμονοίας ἂν ἁρμόσειεν· καὶ γὰρ ἐκεῖναι τὴν φύσιν εἰσὶν οὐκ ἀνόμοιαι τοῖς εἰρημένοις, ἀλλὰ τὰς μὲν αὐτῶν εὕροιμεν ἂν πλείστων ἀγαθῶν αἰτίας γιγνομένας, τὰς δὲ τῶν μεγίστων κακῶν καὶ συμφορῶν. ὧν μίαν εἶναί φημι καὶ τὴν Σπαρτιατῶν· εἰρήσεται γὰρ τἀληθές, εἰ καί τισι δόξω λίαν παράδοξα λέγειν.", "st": "12.225"}, {"sp": "N", "t": "οὗτοι γὰρ τῷ ταὐτὰ γιγνώσκειν περὶ τῶν ἔξω πραγμάτων ἀλλήλοις στασιάζειν τοὺς Ἕλληνας ὥσπερ τέχνην ἔχοντες, ἐποίουν, καὶ τὸ χαλεπώτατον ταῖς ἄλλαις πόλεσι τῶν κακῶν γιγνόμενον, τοῦθ’ αὑτοῖς ἁπάντων συμφορώτατον ἐνόμιζον εἶναι· τὰς γὰρ οὕτω διακειμένας ἐξῆν αὐτοῖς, ὅπως ἠβούλοντο, διοικεῖν. ὥστ’ οὐδεὶς ἂν αὐτοὺς διά γε τὴν ὁμόνοιαν δικαίως ἐπαινέσειεν, οὐδὲν μᾶλλον ἢ τοὺς καταποντιστὰς καὶ λῃστὰς καὶ τοὺς περὶ τὰς ἄλλας ἀδικίας ὄντας· καὶ γὰρ ἐκεῖνοι σφίσιν αὐτοῖς ὁμονοοῦντες τοὺς ἄλλους ἀπολλύουσιν.", "st": "12.226"}, {"sp": "N", "t": "εἰ δέ τισι δοκῶ τὴν παραβολὴν ἀπρεπῆ πεποιῆσθαι πρὸς τὴν ἐκείνων δόξαν, ταύτην μὲν ἐῶ, λέγω δὲ Τριβαλλούς, οὓς ἅπαντές φασιν ὁμονοεῖν μὲν ὡς οὐδένας ἄλλους ἀνθρώπους, ἀπολλύναι δ’ οὐ μόνον τοὺς ὁμόρους καὶ τοὺς πλησίον οἰκοῦντας, ἀλλὰ καὶ τοὺς ἄλλους ὅσων ἂν ἐφικέσθαι δυνηθῶσιν.", "st": "12.227"}, {"sp": "N", "t": "οὓς οὐ χρὴ μιμεῖσθαι τοὺς ἀρετῆς ἀντιποιουμένους, ἀλλὰ πολὺ μᾶλλον τὴν τῆς σοφίας καὶ τῆς δικαιοσύνης καὶ τῶν ἄλλων ἀρετῶν δύναμιν. αὗται μὲν γὰρ οὐ τὰς σφετέρας αὐτῶν φύσεις εὐεργετοῦσιν, ἀλλ’ οἷς ἂν παραγενόμεναι παραμείνωσιν, εὐδαίμονας καὶ μακαρίους ποιοῦσιν· Λακεδαιμόνιοι δὲ τοὐναντίον, οἷς μὲν ἂν πλησιάσωσιν, ἀπολλύουσι, τὰ δὲ τῶν ἄλλων ἀγαθὰ πάντα περὶ σφᾶς αὐτοὺς ποιοῦνται.”", "st": "12.228"}, {"sp": "N", "t": "ταῦτ’ εἰπὼν κατέσχον πρὸς ὃν τοὺς λόγους ἐποιούμην, ἄνδρα δεινὸν καὶ πολλῶν ἔμπειρον καὶ περὶ τὸ λέγειν γεγυμνασμένον οὐδενὸς ἧττον τῶν ἐμοὶ πεπλησιακότων. οὐ μὴν τὰ μειράκια τὰ πᾶσι παραγεγενημένα τούτοις τὴν αὐτὴν ἐμοὶ γνώμην ἔσχεν, ἀλλ’ ἐμὲ μὲν ἐπῄνεσαν ὡς διειλεγμένον τε νεαρωτέρως ἢ προσεδόκησαν ἠγωνισμένον τε καλῶς, ἐκείνου δὲ κατεφρόνησαν, οὐκ ὀρθῶς γιγνώσκοντες,", "st": "12.229"}, {"sp": "N", "t": "ἀλλὰ διημαρτηκότες ἀμφοτέρων ἡμῶν. ὁ μὲν γὰρ ἀπῄει φρονιμώτερος γεγενημένος καὶ συνεσταλμένην ἔχων τὴν διάνοιαν, ὥσπερ χρὴ τοὺς εὖ φρονοῦντας, καὶ πεπονθὼς τὸ γεγραμμένον ἐν Δελφοῖς, αὑτόν τ’ ἐγνωκὼς καὶ τὴν Λακεδαιμονίων φύσιν μᾶλλον ἢ πρότερον· ἐγὼ δ’ ὑπελειπόμην ἐπιτυχῶς μὲν ἴσως διειλεγμένος, ἀνοητότερος δὲ δι’ αὐτὸ τοῦτο γεγενημένος, καὶ φρονῶν μεῖζον ἢ προσῆκε τοὺς τηλικούτους, καὶ ταραχῆς μειρακιώδους μεστὸς ὤν.", "st": "12.230"}, {"sp": "N", "t": "δῆλος δ’ ἦν οὕτω διακείμενος· ἐπειδὴ γὰρ ἡσυχίας ἐπελαβόμην, οὐ πρότερον ἐπαυσάμην πρὶν ὑπέβαλον τῷ παιδὶ τὸν λόγον, ὃν ὀλίγῳ μὲν πρότερον μεθ’ ἡδονῆς διῆλθον, μικρῷ δ’ ὕστερον ἤμελλέ με λυπήσειν. τριῶν γὰρ ἢ τεττάρων ἡμερῶν διαλειφθεισῶν ἀναγιγνώσκων αὐτὰ καὶ διεξιών, ἐπὶ μὲν οἷς περὶ τῆς πόλεως ἦν εἰρηκώς, οὐκ ἠχθόμην, καλῶς γὰρ καὶ δικαίως ἦν ἅπαντα περὶ αὐτῆς γεγραφώς,", "st": "12.231"}, {"sp": "N", "t": "ἐπὶ δὲ τοῖς περὶ Λακεδαιμονίων ἐλυπήθην καὶ βαρέως ἔφερον· οὐ γὰρ μετρίως ἐδόκουν μοι διειλέχθαι περὶ αὐτῶν οὐδ’ ὁμοίως τοῖς ἄλλοις, ἀλλ’ ὀλιγώρως καὶ λίαν πικρῶς καὶ παντάπασιν ἀνοήτως· ὥστε πολλάκις ὁρμήσας ἐξαλείφειν αὐτὸν ἢ κατακάειν μετεγίγνωσκον, ἐλεῶν τὸ γῆρας τοὐμαυτοῦ καὶ τὸν πόνον τὸν περὶ τὸν λόγον γεγενημένον.", "st": "12.232"}, {"sp": "N", "t": "ἐν τοιαύτῃ δὲ μοι ταραχῇ καθεστηκότι καὶ μεταβολὰς ποιουμένῳ πολλὰς ἔδοξε κράτιστον εἶναι παρακαλέσαντι τῶν πεπλησιακότων τοὺς ἐπιδημοῦντας βουλεύσασθαι μετ’ αὐτῶν, πότεροι ἀφανιστέος παντάπασίν ἐστιν ἢ διαδοτέος τοῖς βουλομένοις λαμβάνειν, ὁπότερα δ’ ἂν ἐκείνοις δόξῃ, ταῦτα ποιεῖν. τούτων γνωσθέντων οὐδεμίαν διατριβὴν ἐποιησάμην, ἀλλ’ εὐθὺς παρεκέκληντο μὲν οὓς εἶπον, προειρηκὼς δ’ ἦν αὐτοῖς ἐφ’ ἃ συνεληλυθότες ἦσαν, ἀνέγνωστο δ’ ὁ λόγος, ἐπῃνημένος δ’ ἦν καὶ τεθορυβημένος καὶ τετυχηκὼς ὧνπερ οἱ κατορθοῦντες ἐν ταῖς ἐπιδείξεσιν.", "st": "12.233"}, {"sp": "N", "t": "ἁπάντων δὲ τούτων ἐπιτετελεσμένων οἱ μὲν ἄλλοι διελέγοντο πρὸς σφᾶς αὐτούς, δῆλον ὅτι περὶ τῶν ἀναγνωσθέντων· ὃν δ’ ἐξ ἀρχῆς μετεπεμψάμεθα σύμβουλον, τὸν Λακεδαιμονίων ἐπαινέτην, πρὸς ὃν πλείω διελέχθην τοῦ δέοντος, σιωπὴν ποιησάμενος καὶ πρὸς ἐμὲ βλέψας ἀπορεῖν ἔφασκεν ὅ τι χρήσηται τοῖς παροῦσιν· οὔτε γὰρ ἀπιστεῖν βούλεσθαι τοῖς ὑπ’ ἐμοῦ λεγομένοις, οὔτε πιστεύειν δύνασθαι παντάπασιν αὐτοῖς.", "st": "12.234"}, {"sp": "N", "t": "“θαυμάζω γὰρ εἴθ’ οὕτως ἐλυπήθης καὶ βαρέως ἔσχες, ὥσπερ φῄς, ἐπὶ τοῖς περὶ Λακεδαιμονίων εἰρημένοις, οὐδὲν γὰρ ἐν αὐτοῖς ὁρῶ τοιοῦτον γεγραμμένον, εἴτε συμβούλοις περὶ τοῦ λόγου χρήσασθαι βουλόμενος ἡμᾶς συνήγαγες, οὓς οἶσθ’ ἀκριβῶς ἅπαν ὅ τι ἂν σὺ λέγῃς ἢ πράττῃς ἐπαινοῦντας. εἰθισμένοι δ’ εἰσὶν οἱ νοῦν ἔχοντες ἀνακοινοῦσθαι, περὶ ὧν ἂν σπουδάζωσι, μάλιστα μὲν τοῖς ἄμεινον αὑτῶν φρονοῦσιν, εἰ δὲ μή, τοῖς μέλλουσιν ἀποφαίνεσθαι τὴν αὑτῶν γνώμην· ὧν τἀναντία σὺ πεποίηκας.", "st": "12.235"}, {"sp": "N", "t": "τούτων μὲν οὖν οὐδέτερον ἀποδέχομαι τῶν λόγων, δοκεῖς δέ μοι ποιήσασθαι τήν τε παράκλησιν τὴν ἡμετέραν καὶ τὸν ἔπαινον τὸν τῆς πόλεως οὐχ ἁπλῶς, οὐδ’ ὡς διείλεξαι πρὸς ἡμᾶς, ἀλλ’ ἡμῶν μὲν πεῖραν λαβεῖν βουλόμενος, εἰ φιλοσοφοῦμεν καὶ μεμνήμεθα τῶν ἐν ταῖς διατριβαῖς λεγομένων καὶ συνιδεῖν δυνηθεῖμεν ἂν ὃν τρόπον ὁ λόγος τυγχάνει γεγραμμένος,", "st": "12.236"}, {"sp": "N", "t": "τὴν δὲ πόλιν ἐπαινεῖν προελέσθαι τὴν σαυτοῦ σωφρονῶν, ἵνα τῷ τε πλήθει τῷ τῶν πολιτῶν χαρίσῃ καὶ παρὰ τοῖς εὖνοι· κῶς πρὸς ὑμᾶς διακειμένοις εὐδοκιμήσῃς. ταῦτα δὲ γνοὺς ὑπέλαβες ὡς εἰ μὲν περὶ μόνης αὐτῆς ποιήσει τοὺς λόγους καὶ τὰ μυθώδη περὶ αὐτῆς ἐρεῖς ἃ πάντες θρυλοῦσιν, ὅμοια φανεῖται τὰ λεγόμενα τοῖς ὑπὸ τῶν ἄλλων γεγραμμένοις, ἐφ’ ᾧ σὺ μάλιστ’ ἂν αἰσχυνθείης καὶ λυπηθείης·", "st": "12.237"}, {"sp": "N", "t": "ἐὰν δ’ ἐάσας ἐκεῖνα λέγῃς τὰς πράξεις τὰς ὁμολογουμένας καὶ πολλῶν ἀγαθῶν αἰτίας τοῖς Ἕλλησι γεγενημένας, καὶ παραβάλλῃς αὐτὰς πρὸς τὰς Λακεδαιμονίων, καὶ τὰς μὲν τῶν προγόνων ἐπαινῇς, τῶν δ’ ἐκείνοις πεπραγμένων κατηγορῇς, ὅ τε λόγος ἐναργέστερος εἶναι δόξει τοῖς ἀκούουσι καὶ σὺ μενεῖς ἐν τοῖς αὐτοῖς, ὃ μᾶλλον ἄν τινες θαυμάσειαν τῶν τοῖς ἄλλοις γεγραμμένων.", "st": "12.238"}, {"sp": "N", "t": "ἐν ἀρχῇ μὲν οὖν οὕτω μοι φαίνει τάξαι καὶ βουλεύσασθαι περὶ αὐτῶν, εἰδὼς δὲ σαυτὸν ἐπῃνεκότα τὴν Σπαρτιατῶν διοίκησιν ὡς οὐδεὶς ἄλλος, φοβεῖσθαι τοὺς ἀκηκοότας, μὴ δόξῃς ὅμοιος εἶναι τοῖς λέγουσιν ὅ τι ἂν τύχωσι καὶ τούτους νῦν ψέγειν οὓς πρότερον ἐπῄνεις μᾶλλον τῶν ἄλλων· ταῦτ’ ἐνθυμηθεὶς σκοπεῖσθαι ποίους τινὰς ἂν ἑκατέρους εἶναι φήσας ἀληθῆ τε λέγειν δόξειας περὶ ἀμφοτέρων, ἔχοις τ’ ἂν τοὺς μὲν προγόνους ἐπαινεῖν, οὕσπερ βούλει, Σπαρτιατῶν δὲ δοκεῖν μὲν κατηγορεῖν τοῖς ἀηδῶς πρὸς αὐτοὺς διακειμένοις, μηδὲν δὲ ποιεῖν τοιοῦτον ἀλλὰ λανθάνειν ἐπαινῶν αὐτούς·", "st": "12.239"}, {"sp": "N", "t": "ζητῶν δὲ τὰ τοιαῦτα ῥᾳδίως εὑρεῖν λόγους ἀμφιβόλους καὶ μηδὲν μᾶλλον μετὰ τῶν ἐπαινούντων ἢ τῶν ψεγόντων ὄντας, ἀλλ’ ἐπαμφοτερίζειν δυναμένους καὶ πολλὰς ἀμφισβητήσεις ἔχοντας, οἷς χρῆσθαι περὶ μὲν συμβολαίων καὶ περὶ πλεονεξίας ἀγωνιζόμενον αἰσχρὸν καὶ πονηρίας οὐ μικρὸν σημεῖον, περὶ δὲ φύσεως ἀνθρώπων διαλεγόμενον καὶ πραγμάτων καλὸν καὶ φιλόσοφον.", "st": "12.240"}, {"sp": "N", "t": "οἷός περ ὁ λόγος ὁ διαναγνωσθείς ἐστιν, ἐν ᾧ πεποίηκας τοὺς μὲν σοὺς προγόνους εἰρηνικοὺς καὶ φιλέλληνας καὶ τῆς ἰσότητος τῆς ἐν ταῖς πολιτείαις ἡγεμόνας, Σπαρτιάτας δ’ ὑπεροπτικοὺς καὶ πολεμικοὺς καὶ πλεονέκτας, οἵους περ αὐτοὺς εἶναι πάντες ὑπειλήφασιν. τοιαύτην δ’ ἑκατέρων ἐχόντων τὴν φύσιν, τοὺς μὲν ὑπὸ πάντων ἐπαινεῖσθαι καὶ δοκεῖν εὔνους εἶναι τῷ πλήθει, τοῖς δὲ τοὺς μὲν πολλοὺς φθονεῖν καὶ δυσμενῶς ἔχειν,", "st": "12.241"}, {"sp": "N", "t": "ἔστι δ’ οὓς καὶ ἐπαινεῖν αὐτοὺς καὶ θαυμάζειν, καὶ τολμᾶν λέγειν ὡς ἀγαθὰ μείζω τυγχάνουσιν ἔχοντες τῶν τοῖς προγόνοις τοῖς σοῖς προσόντων· τήν τε γὰρ ὑπεροψίαν σεμνότητος μετέχειν, εὐδοκίμου πράγματος, καὶ δοκεῖν ἅπασι μεγαλοφρονεστέρους εἶναι τοὺς τοιούτους ἢ τοὺς τῆς ἰσότητος προεστῶτας, τούς τε πολεμικοὺς πολὺ διαφέρειν τῶν εἰρηνικῶν· τοὺς μὲν γὰρ οὔτε κτητικοὺς εἶναι τῶν οὐκ ὄντων οὔτε φύλακας δεινοὺς τῶν ὑπαρχόντων, τοὺς δ’ ἀμφότερα δύνασθαι, καὶ λαμβάνειν ὧν ἂν ἐπιθυμῶσι καὶ σώζειν ἅπερ ἂν ἅπαξ κατάσχωσιν· ἃ ποιοῦσιν οἱ τέλειοι δοκοῦντες εἶναι τῶν ἀνδρῶν.", "st": "12.242"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ περὶ τῆς πλεονεξίας καλλίους ἔχειν οἴονται λόγους τῶν εἰρημένων· τοὺς μὲν γὰρ ἀποστεροῦντας τὰ συμβόλαια καὶ τοὺς παρακρουομένους καὶ παραλογιζομένους οὐχ ἡγοῦνται δικαίως καλεῖσθαι πλεονεκτικούς, διὰ γὰρ τὸ πονηρὰν ἔχειν τὴν δόξαν ἐν ἅπασιν αὐτοὺς ἐλαττοῦσθαι τοῖς πράγμασι, τὰς δὲ Σπαρτιατῶν πλεονεξίας καὶ τὰς τῶν βασιλέων καὶ τὰς τῶν τυράννων εὐκτὰς μὲν εἶναι, καὶ ἅπαντας αὐτῶν ἐπιθυμεῖν,", "st": "12.243"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ λοιδορεῖσθαι καὶ καταρᾶσθαι τοῖς τὰς τηλικαύτας ἔχουσι δυναστείας· οὐδένα δὲ τοιοῦτον εἶναι τὴν φύσιν ὅστις οὐκ ἂν εὔξαιτο τοῖς θεοῖς μάλιστα μὲν αὐτὸς τυχεῖν τῆς ἐξουσίας ταύτης, εἰ δὲ μή, τοὺς οἰκειοτάτους· ᾧ καὶ φανερόν ἐστιν ὅτι μέγιστον τῶν ἀγαθῶν ἅπαντες εἶναι νομίζομεν τὸ πλέον ἔχειν τῶν ἄλλων. τὴν μὲν οὖν περιβολὴν τοῦ λόγου δοκεῖς μοι ποιήσασθαι μετὰ τοιαύτης διανοίας.", "st": "12.244"}, {"sp": "N", "t": "εἰ μὲν οὖν ἡγούμην ἀφέξεσθαι σε τῶν εἰρημένων καὶ παραλείψειν ἀνεπιτίμητον τὸν λόγον τοῦτον, οὐδ’ ἂν αὐτὸς ἔτι λέγειν ἐπεχείρουν· νῦν δ’ ὅτι μὲν οὐκ ἀπεφηνάμην περὶ ὧν παρεκλήθην σύμβουλος, οὐδὲν οἶμαί σοι μελήσειν, οὐδὲ γὰρ ὅτε συνῆγες ἡμᾶς, ἐδόκεις μοι σπουδάζειν περὶ αὐτῶν,", "st": "12.245"}, {"sp": "N", "t": "προελόμενον δέ σε συνθεῖναι λόγον μηδὲν ὅμοιον τοῖς ἄλλοις, ἀλλὰ τοῖς μὲν ῥᾳθύμως ἀναγιγνώσκουσιν ἁπλοῦν εἶναι δόξοντα καὶ ῥᾴδιον καταμαθεῖν, τοῖς δ’ ἀκριβῶς διεξιοῦσιν αὐτόν, καὶ πειρωμένοις κατιδεῖν ὃ τοὺς ἄλλους λέληθεν, χαλεπὸν φανούμενον καὶ δυσκαταμάθητον καὶ πολλῆς μὲν ἱστορίας γέμοντα καὶ φιλοσοφίας, παντοδαπῆς δὲ μεστὸν ποικιλίας καὶ ψευδολογίας, οὐ τῆς εἰθισμένης μετὰ κακίας βλάπτειν τοὺς συμπολιτευομένους, ἀλλὰ τῆς δυναμένης μετὰ παιδιᾶς ὠφελεῖν ἢ τέρπειν τοὺς ἀκούοντας,", "st": "12.246"}, {"sp": "N", "t": "—ὧν οὐδὲν ἐάσαντά με φήσειν τὸν τρόπον τοῦτον ἔχειν ὡς ἐβουλεύσω σὺ περὶ αὐτῶν, ἀλλὰ τήν τε δύναμιν τῶν λεγομένων διδάσκοντα καὶ τὴν σὴν διάνοιαν ἐξηγούμενον οὐκ αἰσθάνεσθαι τοσούτῳ τὸν λόγον ἀδοξότερον δι’ ἐμὲ γιγνόμενον, ὅσῳ περ αὐτὸν φανερώτερον ἐποίουν καὶ γνωριμώτερον τοῖς ἀναγιγνώσκουσιν· ἐπιστήμην γὰρ τοῖς οὐκ εἰδόσιν ἐνεργαζόμενον ἔρημον τὸν λόγον με ποιεῖν καὶ τῆς τιμῆς ἀποστερεῖν τῆς γιγνομένης ἂν αὐτῷ διὰ τοὺς πονοῦντας καὶ πράγματα σφίσιν αὐτοῖς παρέχοντας.", "st": "12.247"}, {"sp": "N", "t": "ἐγὼ δ’ ὁμολογῶ μὲν ἀπολελεῖφθαι τὴν ἐμὴν φρόνησιν τῆς σῆς ὡς δυνατὸν πλεῖστον, οὐ μὴν ἀλλ’ ὥσπερ τοῦτ’ οἶδα, κἀκεῖνο τυγχάνω γιγνώσκων, ὅτι τῆς πόλεως τῆς ὑμετέρας βουλευομένης περὶ τῶν μεγίστων οἱ μὲν ἄριστα φρονεῖν δοκοῦντες ἐνίοτε διαμαρτάνουσι τοῦ συμφέροντος, τῶν δὲ φαύλων νομιζομένων εἶναι καὶ καταφρονουμένων ἔστιν ὅτε κατώρθωσεν ὁ τυχὼν καὶ βέλτιστα λέγειν ἔδοξεν·", "st": "12.248"}, {"sp": "N", "t": "ὥστ’ οὐδὲν θαυμαστὸν εἰ καὶ περὶ τοῦ νῦν ἐνεστῶτος τοιοῦτόν τι συμβέβηκεν, ὅπου σὺ μὲν οἴει μάλιστ’ εὐδοκιμήσειν, ἢν ὡς πλεῖστον χρόνον διαλάθῃς ἣν ἔχων γνώμην τὰ περὶ τὸν λόγον ἐπραγματεύθης, ἐγὼ δ’ ἡγοῦμαι βέλτιστά σε πράξειν, ἢν δυνηθῇς τὴν διάνοιαν, ᾗ χρώμενος αὐτὸν συνέθηκας, ὡς τάχιστα φανερὰν ποιῆσαι τοῖς τ’ ἄλλοις ἅπασι καὶ Λακεδαιμονίοις, περὶ ὧν πεποίησαι πολλοὺς λόγους, τοὺς μὲν δικαίους καὶ σεμνούς, τοὺς δ’ ἀσελγεῖς καὶ λίαν φιλαπεχθήμονας.", "st": "12.249"}, {"sp": "N", "t": "οὓς εἴ τις ἐπέδειξεν αὐτοῖς πρὶν ἐμὲ διαλεχθῆναι περὶ αὐτῶν, οὐκ ἔστιν ὅπως οὐκ ἂν ἐμίσησαν καὶ δυσκόλως πρὸς σὲ διετέθησαν ὡς κατηγορίαν γεγραφότα καθ’ αὑτῶν. νῦν δ’ οἴομαι τοὺς μὲν πλείστους Σπαρτιατῶν ἐμμενεῖν τοῖς ἤθεσιν οἷσπερ καὶ τὸν ἄλλον χρόνον, τοῖς δὲ λόγοις τοῖς ἐνθάδε γραφομένοις οὐδὲν μᾶλλον προσέξειν τὸν νοῦν ἢ τοῖς ἔξω τῶν Ἡρακλέους στηλῶν λεγομένοις,", "st": "12.250"}, {"sp": "N", "t": "τοὺς δὲ φρονιμωτάτους αὐτῶν καὶ τῶν λόγων τινὰς ἔχοντας τῶν σῶν καὶ θαυμάζοντας, τούτους, ἢν λάβωσι τὸν ἀναγνωσόμενον καὶ χρόνον ὥστε συνδιατρῖψαι σφίσιν αὐτοῖς, οὐδὲν ἀγνοήσειν τῶν μετ’ ἀποδείξεως εἰρημένων περὶ τῆς πόλεως τῆς ἑαυτῶν, καὶ τῶν λοιδοριῶν καταφρονήσειν τῶν εἰκῇ μὲν τοῖς πράγμασι λεγομένων πικρῶς δὲ τοῖς ὀνόμασι κεχρημένων, καὶ νομιεῖν τὰς μὲν βλασφημίας τὰς ἐνούσας ἐν τῷ βιβλίῳ τὸν φθόνον ὑποβαλεῖν,", "st": "12.251"}, {"sp": "N", "t": "τὰς δὲ πράξεις καὶ τὰς μάχας, ἐφ’ αἷς αὐτοί τε μέγα φρονοῦσι καὶ παρὰ τοῖς ἄλλοις εὐδοκιμοῦσι, σὲ γεγραφέναι καὶ μνημονεύεσθαι πεποιηκέναι, συναγαγόντα πάσας αὐτὰς καὶ θέντα παρ’ ἀλλήλας, αἴτιον δ’ εἶναι καὶ τοῦ πολλοὺς ποθεῖν ἀναγνῶναι καὶ διελθεῖν αὐτάς, οὐ τὰς ἐκείνων ἐπιθυμοῦντας ἀκοῦσαι πράξεις,", "st": "12.252"}, {"sp": "N", "t": "ἀλλὰ πῶς σὺ διείλεξαι περὶ αὐτῶν μαθεῖν βουλομένους. ταῦτ’ ἐνθυμουμένους καὶ διεξιόντας οὐδὲ τῶν παλαιῶν ἔργων ἀμνημονήσειν, δι’ ὧν ἐγκεκωμίακας τοὺς προγόνους αὐτῶν, ἀλλὰ καὶ πολλάκις διαλέξεσθαι πρὸς σφᾶς αὐτούς, πρῶτον μὲν ὅτι Δωριεῖς ὄντες, ἐπειδὴ κατεῖδον τὰς πόλεις τὰς ἑαυτῶν ἀδόξους καὶ μικρὰς καὶ πολλῶν ἐνδεεῖς οὔσας, ὑπεριδόντες ταύτας ἐστράτευσαν ἐπὶ τὰς ἐν Πελοποννήσῳ πρωτευούσας, ἐπ’ Ἄργος καὶ Λακεδαίμονα καὶ Μεσσήνην,", "st": "12.253"}, {"sp": "N", "t": "μάχῃ δὲ νικήσαντες τοὺς μὲν ἡττηθέντας ἔκ τε τῶν πόλεων καὶ τῆς χώρας ἐξέβαλον, αὐτοὶ δὲ τὰς κτήσεις ἁπάσας τὰς ἐκείνων τότε κατασχόντες ἔτι καὶ νῦν ἔχουσιν, οὗ μεῖζον ἔργον καὶ θαυμαστότερον οὐδεὶς ἐπιδείξει κατ’ ἐκεῖνον τὸν χρόνον γενόμενον, οὐδὲ πρᾶξιν εὐτυχεστέραν καὶ θεοφιλεστέραν τῆς τοὺς χρησαμένους τῆς μὲν οἰκείας ἀπορίας ἀπαλλαξάσης, τῆς δ’ ἀλλοτρίας εὐδαιμονίας κυρίους ποιησάσης.", "st": "12.254"}, {"sp": "N", "t": "καὶ ταῦτα μὲν μετὰ πάντων συστρατευσαμένων ἔπραξαν· ἐπειδὴ δὲ πρὸς Ἀργείους καὶ Μεσσηνίους τὴν χώραν διείλοντο καὶ καθ’ αὑτοὺς ἐν Σπάρτῃ κατῴκησαν, ἐν τούτοις τοῖς καιροῖς τοσοῦτον φρονῆσαι φῂς αὐτούς, ὥστε ὄντας οὐ πλείους τότε δισχιλίων οὐχ ἡγήσασθαι σφᾶς αὐτοὺς ἀξίους εἶναι ζῆν, εἰ μὴ δεσπόται πασῶν τῶν ἐν Πελοποννήσῳ πόλεων γενέσθαι δυνηθεῖεν,", "st": "12.255"}, {"sp": "N", "t": "ταῦτα δὲ διανοηθέντας καὶ πολεμεῖν ἐπιχειρήσαντας οὐκ ἀπειπεῖν, ἐν πολλοῖς κακοῖς καὶ κινδύνοις γιγνομένους, πρὶν ἁπάσας ταύτας ὑφ’ αὑτοῖς ἐποιήσαντο πλὴν τῆς Ἀργείων πόλεως, ἔχοντας δ’ ἤδη καὶ χώραν πλείστην καὶ δύναμιν μεγίστην καὶ δόξαν τοσαύτην ὅσην προσήκει τοὺς τηλικαῦτα διαπεπραγμένους οὐχ ἧττον διακεῖσθαι φιλοτίμως, ὅτι λόγος ὑπῆρχεν αὐτοῖς ἴδιος καὶ καλὸς μόνοις τῶν Ἑλλήνων·", "st": "12.256"}, {"sp": "N", "t": "ἐξεῖναι γὰρ εἰπεῖν αὐτοῖς ὅτι σφεῖς μὲν ὄντες οὕτως ὀλίγοι τὸν ἀριθμὸν οὐδεμιᾷ πώποτε τῶν μυριάνδρων πόλεων ἠκολούθησαν οὐδ’ ἐποίησαν τὸ προσταττόμενον, ἀλλ’ αὐτόνομοι διετέλεσαν ὄντες, αὐτοὶ δ’ ἐν τῶ πολέμῳ τῷ πρὸς τοὺς βαρβάρους πάντων τῶν Ἑλλήνων ἡγεμόνες κατέστησαν, καὶ τῆς τιμῆς ταύτης ἔτυχον οὐκ ἀλόγως, ἀλλὰ διὰ τὸ μάχας ποιησάμενοι πλείστας ἀνθρώπων κατ’ ἐκεῖνον τὸν χρόνον μηδεμίαν ἡττηθῆναι τούτων ἡγουμένου βασιλέως,", "st": "12.257"}, {"sp": "N", "t": "ἀλλὰ νενικηκέναι πάσας, οὗ τεκμήριον οὐδεὶς ἂν δύναιτο μεῖζον εἰπεῖν ἀνδρίας καὶ καρτερίας καὶ τῆς πρὸς ἀλλήλους ὁμονοίας, πλὴν ἢ τὸ ῥηθήσεσθαι μέλλον· τοσούτων γὰρ τὸ πλῆθος τῶν πόλεων τῶν Ἑλληνίδων οὐσῶν, τῶν μὲν ἄλλων οὐδεμίαν οὐδέν’ εἰπεῖν οὐδ’ εὑρεῖν, ἥτις οὐ περιπέπτωκε ταῖς συμφοραῖς ταῖς εἰθισμέναις γίγνεσθαι ταῖς πόλεσιν,", "st": "12.258"}, {"sp": "N", "t": "ἐν δὲ τῇ Σπαρτιατῶν οὐδεὶς ἂν ἐπιδείξειεν οὔτε στάσιν οὔτε σφαγὰς οὔτε φυγὰς ἀνόμους γεγενημένας, οὐδ’ ἁρπαγὰς χρημάτων οὐδ’ αἰσχύνας γυναικῶν καὶ παίδων, ἀλλ’ οὐδὲ πολιτείας μεταβολὴν οὐδὲ χρεῶν ἀποκοπὰς οὐδὲ γῆς ἀναδασμὸν οὐδ’ ἄλλ’ οὐδὲν τῶν ἀνηκέστων κακῶν. περὶ ὧν διεξιόντας οὐκ ἔστιν ὅπως οὐ καὶ σοῦ, τοῦ τ’ ἀθροίσαντος καὶ διαλεχθέντος οὕτω καλῶς περὶ αὐτῶν, μεμνήσεσθαι καὶ πολλὴν χάριν ἕξειν.", "st": "12.259"}, {"sp": "N", "t": "οὐ τὴν αὐτὴν δὲ γνώμην ἔχω περὶ σοῦ νῦν καὶ πρότερον. ἐν μὲν γὰρ τοῖς παρελθοῦσι χρόνοις ἐθαύμαζόν σου τήν τε φύσιν καὶ τὴν τοῦ βίου τάξιν καὶ τὴν φιλοπονίαν καὶ μάλιστα τὴν ἀλήθειαν τῆς φιλοσοφίας, νῦν δὲ ζηλῶ σε καὶ μακαρίζω τῆς εὐδαιμονίας· δοκεῖς γάρ μοι ζῶν μὲν λήψεσθαι δόξαν οὐ μείζω μὲν ἧς ἄξιος εἶ, χαλεπὸν γάρ, παρὰ πλείοσι δὲ καὶ μᾶλλον ὁμολογουμένην τῆς νῦν ὑπαρχούσης, τελευτήσας δὲ τὸν βίον μεθέξειν ἀθανασίας, οὐ τῆς τοῖς θεοῖς παρούσης, ἀλλὰ τῆς τοῖς ἐπιγιγνομένοις περὶ τῶν διενεγκόντων ἐπί τινι τῶν καλῶν ἔργων μνήμην ἐμποιούσης.", "st": "12.260"}, {"sp": "N", "t": "καὶ δικαίως τεύξει τούτων· ἐπῄνεκας γὰρ τὰς πόλεις ἀμφοτέρας καλῶς καὶ προσηκόντως, τὴν μὲν κατὰ τὴν δόξαν τὴν τῶν πολλῶν, ἧς οὐδεὶς τῶν ὀνομαστῶν ἀνδρῶν καταπεφρόνηκεν, ἀλλ’ ἐπιθυμοῦντες τυχεῖν αὐτῆς οὐκ ἔστιν ὅντινα κίνδυνον οὐχ ὑπομένουσι, τὴν δὲ κατὰ τὸν λογισμὸν τῶν πειρωμένων στοχάζεσθαι τῆς ἀληθείας, παρ’ οἷς εὐδοκιμεῖν ἄν τινες ἕλοιντο μᾶλλον ἢ παρὰ τοῖς ἄλλοις διπλασίοις γενομένοις ἢ νῦν εἰσιν.", "st": "12.261"}, {"sp": "N", "t": "ἀπλήστως δὲ διακείμενος ἐν τῷ παρόντι πρὸς τὸ λέγειν, καὶ πόλλ’ ἂν εἰπεῖν ἔχων ἔτι καὶ περὶ σοῦ καὶ περὶ τοῖν πολέοιν καὶ περὶ τοῦ λόγου, ταῦτα μὲν ἐάσω, περὶ ὧν δὲ παρακληθῆναί με σὺ φῄς, περὶ τούτων ἀποφανοῦμαι. συμβουλεύω γάρ σοι μήτε κατακάειν τὸν λόγον μήτ’ ἀφανίζειν, ἀλλ’ εἴ τινος ἐνδεής ἐστι, διορθώσαντα καὶ προσγράψαντα πάσας τὰς διατριβὰς τὰς περὶ αὐτὸν γεγενημένας διδόναι τοῖς βουλομένοις λαμβάνειν,", "st": "12.262"}, {"sp": "N", "t": "εἴπερ βούλει χαρίσασθαι μὲν τοῖς ἐπιεικεστάτοις τῶν Ἑλλήνων καὶ τοῖς ὡς ἀληθῶς φιλοσοφοῦσιν ἀλλὰ μὴ προσποιουμένοις, λυπῆσαι δὲ τοὺς θαυμάζοντας μὲν τὰ σὰ μᾶλλον τῶν ἄλλων, λοιδορουμένους δὲ τοῖς λόγοις τοῖς σοῖς ἐν τοῖς ὄχλοις τοῖς πανηγυρικοῖς, ἐν οἷς πλείους εἰσὶν οἱ καθεύδοντες τῶν ἀκροωμένων, καὶ προσδοκῶντας, ἢν παρακρούσωνται τοὺς τοιούτους, ἐναμίλλους τοὺς αὑτῶν γενήσεσθαι τοῖς ὑπὸ σοῦ γεγραμμένοις, κακῶς εἰδότας ὅτι πλέον ἀπολελειμμένοι τῶν σῶν εἰσιν ἢ τῆς Ὁμήρου δόξης οἱ περὶ τὴν αὐτὴν ἐκείνῳ ποίησιν γεγονότες.”", "st": "12.263"}, {"sp": "N", "t": "ταῦτ’ εἰπόντος αὐτοῦ καὶ τοὺς παρόντας ἀξιώσαντος ἀποφήνασθαι περὶ ὧν παρεκλήθησαν, οὐκ ἐθορύβησαν, ὃ ποιεῖν εἰώθασιν ἐπὶ τοῖς χαριέντως διειλεγμένοις, ἀλλ’ ἀνεβόησαν ὡς ὑπερβαλλόντως εἰρηκότος, καὶ περιστάντες αὐτὸν ἐπῄνουν, ἐζήλουν, ἐμακάριζον, καὶ προσθεῖναι μὲν οὐδὲν εἶχον τοῖς εἰρημένοις οὐδ’ ἀφελεῖν, συναπεφαίνοντο δὲ καὶ συνεβούλευόν μοι ποιεῖν ἅπερ ἐκεῖνος παρῄνεσεν.", "st": "12.264"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ ἐγὼ παρεστὼς ἐσιώπων, ἀλλ’ ἐπῄνεσα τήν τε φύσιν αὐτοῦ καὶ τὴν ἐπιμέλειαν, περὶ δὲ τῶν ἄλλων οὐδὲν ἐφθεγξάμην ὧν εἶπεν, οὔθ’ ὡς ἔτυχε ταῖς ὑπονοίαις τῆς ἐμῆς διανοίας οὔθ’ ὡς διήμαρτεν, ἀλλ’ εἴων αὐτὸν οὕτως ἔχειν ὥσπερ αὐτὸς αὑτὸν διέθηκεν.", "st": "12.265"}, {"sp": "N", "t": "περὶ μὲν οὖν ὧν ὑπεθέμην ἱκανῶς εἰρῆσθαι νομίζω· τὸ γὰρ ἀναμιμνήσκειν καθ’ ἕκαστον τῶν εἰρημένων οὐ πρέπει τοῖς λόγοις τοῖς τοιούτοις· βούλομαι δὲ διαλεχθῆναι περὶ τῶν ἰδίᾳ μοι περὶ τὸν λόγον συμβεβηκότων. ἐγὼ γὰρ ἐνεστησάμην μὲν αὐτὸν ἔτη γεγονὼς ὅσα περ ἐν ἀρχῇ προεῖπον·", "st": "12.266"}, {"sp": "N", "t": "ἤδη δὲ τῶν ἡμισέων γεγραμμένων ἐπιγενομένου μοι νοσήματος ῥηθῆναι μὲν οὐκ εὐπρεποῦς, δυναμένου δ’ ἀναιρεῖν οὐ μόνον τοὺς πρεσβυτέρους ἐν τρισὶν ἢ τέτταρσιν ἡμέραις ἀλλὰ καὶ τῶν ἀκμαζόντων πολλούς, τούτῳ διατελῶ τρί’ ἔτη μαχόμενος, οὕτω φιλοπόνως ἑκάστην τὴν ἡμέραν διάγων, ὥστε τοὺς εἰδότας καὶ τοὺς παρὰ τούτων πυνθανομένους μᾶλλόν με θαυμάζειν διὰ τὴν καρτερίαν ταύτην ἢ δι’ ἃ πρότερον ἐπῃνούμην.", "st": "12.267"}, {"sp": "N", "t": "ἤδη δ’ ἀπειρηκότος καὶ διὰ τὴν νόσον καὶ διὰ τὸ γῆρας, τῶν ἐπισκοπούντων τινές με καὶ πολλάκις ἀνεγνωκότων τὸ μέρος τοῦ λόγου τὸ γεγραμμένον, ἐδέοντό μου καὶ συνεβούλευον μὴ καταλιπεῖν αὐτὸν ἡμιτελῆ μηδ’ ἀδιέργαστον, ἀλλὰ πονῆσαι μικρὸν χρόνον καὶ προσέχειν τοῖς λοιποῖς τὸν νοῦν.", "st": "12.268"}, {"sp": "N", "t": "οὐχ ὁμοίως δὲ διελέγοντο περὶ τούτων τοῖς ἀφοσιουμένοις, ἀλλ’ ὑπερεπαινοῦντες μὲν τὰ γεγραμμένα, τοιαῦτα δὲ λέγοντες, ὧν εἴ τινες ἤκουον μήτε συνήθεις ἡμῖν ὄντες μήτ’ εὔνοιαν μηδεμίαν ἔχοντες, οὐκ ἔστιν ὅπως οὐκ ἂν ὑπέλαβον τοὺς μὲν φενακίζειν, ἐμὲ δὲ διεφθάρθαι καὶ παντάπασιν εἶναι μωρόν,", "st": "12.269"}, {"sp": "N", "t": "εἰ πείσομαι τοῖς λεγομένοις. οὕτω δ’ ἔχων ἐφ’ οἷς εἰπεῖν ἐτόλμησαν ἐπείσθην (τί γὰρ δεῖ μακρολογεῖν;) γενέσθαι πρὸς τῇ τῶν λοιπῶν πραγματείᾳ γεγονὼς μὲν ἔτη τρία μόνον ἀπολείποντα τῶν ἑκατόν, οὕτω δὲ διακείμενος ὡς ἕτερος ἔχων οὐχ ὅπως γράφειν ἂν λόγον ἐπεχείρησεν, ἀλλ’ οὐδ’ ἄλλου δεικνύοντος καὶ πονήσαντος ἠθέλησεν ἀκροατὴς γενέσθαι.", "st": "12.270"}, {"sp": "N", "t": "τίνος οὖν ἕνεκα ταῦτα διῆλθον; οὐ συγγνώμης τυχεῖν ἀξιῶν ὑπὲρ τῶν εἰρημένων, οὐ γὰρ οὕτως οἴομαι διειλέχθαι περὶ αὐτῶν, ἀλλὰ δηλῶσαι βουλόμενος τά τε περὶ ἐμὲ γεγενημένα, καὶ τῶν ἀκροατῶν ἐπαινέσαι μὲν τοὺς τόν τε λόγον ἀποδεχομένους τοῦτον καὶ τῶν ἄλλων σπουδαιοτέρους καὶ φιλοσοφωτέρους εἶναι νομίζοντας τούς τε διδασκαλικοὺς καὶ τεχνικοὺς τῶν πρὸς τὰς ἐπιδείξεις καὶ τοὺς ἀγῶνας γεγραμμένων, καὶ τοὺς τῆς ἀληθείας στοχαζομένους τῶν τὰς δόξας τῶν ἀκροωμένων παρακρούεσθαι ζητούντων, καὶ τοὺς ἐπιπλήττοντας τοῖς ἁμαρτανομένοις καὶ νουθετοῦντας τῶν πρὸς ἡδονὴν καὶ χάριν λεγομένων,", "st": "12.271"}, {"sp": "N", "t": "συμβουλεῦσαι δὲ τοῖς τἀναντία τούτων γιγνώσκουσι πρῶτον μὲν μὴ πιστεύειν ταῖς αὑτῶν γνώμαις, μηδὲ νομίζειν ἀληθεῖς εἶναι τὰς κρίσεις τὰς ὑπὸ τῶν ῥᾳθυμούντων γιγνομένας, ἔπειτα μὴ προπετῶς ἀποφαίνεσθαι περὶ ὧν οὐκ ἴσασιν, ἀλλὰ περιμένειν ἕως ἂν ὁμονοῆσαι δυνηθῶσι τοῖς τῶν ἐπιδεικνυμένων πολλὴν ἐμπειρίαν ἔχουσιν· τῶν γὰρ οὕτω διοικούντων τὰς ἑαυτῶν διανοίας οὐκ ἔστιν ὅστις ἂν τοὺς τοιούτους ἀνοήτους εἶναι νομίσειεν.", "st": "12.272"}], []);})();
